"#define PRISMIO_PLATFORM_H\n"
"\n"
"// Platform includes plus the few macros that paper over the differences between\n"
"// the Win32 and POSIX APIs the toolchain uses.\n"
"//\n"
"// Shared by both halves of the former driver.c -- program_support.c (linked into\n"
"// every compiled Prismio program) and build_driver.c (linked only into the\n"
"// compiler) -- so the two translation units cannot drift apart on things like the\n"
"// path separator.\n"
"\n"
"// <stdint.h> is here for the uint32_t that _NSGetExecutablePath() takes on macOS.\n"
"// Windows headers drag it in transitively, which is why its absence went unnoticed;\n"
"// on Apple platforms nothing else includes it and program_support.c fails to build.\n"
"#include <stdint.h>\n"
"#include <stdio.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"#ifdef _WIN32\n"
"#include <direct.h>\n"
"#include <process.h>\n"
"#include <windows.h>\n"
"#define PRISMIO_GETPID _getpid\n"
"#define PRISMIO_MKDIR(path) _mkdir(path)\n"
"#define PRISMIO_RMDIR(path) _rmdir(path)\n"
"#define PRISMIO_PATH_SEP '\\\\'\n"
"#else\n"
"#include <dirent.h>\n"
"#include <sys/stat.h>\n"
"#include <unistd.h>\n"
"#ifdef __APPLE__\n"
"#include <mach-o/dyld.h>\n"
"#endif\n"
"#define PRISMIO_GETPID getpid\n"
"#define PRISMIO_MKDIR(path) mkdir(path, 0777)\n"
"#define PRISMIO_RMDIR(path) rmdir(path)\n"
"#define PRISMIO_PATH_SEP '/'\n"
"#endif\n"
"\n"
"#endif\n"
;

static const char prismio_embedded_prismio_runtime_h[] =
"#ifndef PRISMIO_RUNTIME_H\n"
"#define PRISMIO_RUNTIME_H\n"
"\n"
"// Program support: the half of the old driver.c that a *compiled Prismio program*\n"
"// can legitimately call at its own runtime. Implemented in program_support.c and\n"
"// destined for runtime.lib / runtime.a.\n"
"//\n"
"// The dividing line is \"would a user's program ever call this?\". Command-line\n"
"// access and plain file/path helpers: yes -- tests/test_19_runtime_split.psm\n"
"// already externs executable_directory, join_path, command_quote_arg and\n"
"// file_exists, and src/main.psm externs read_file, get_directory and delete_file.\n"
"// Driving llc/clang to produce an executable: no, that is the compiler's job and\n"
"// lives in build_driver.c (backend.lib).\n"
"//\n"
"// build_driver.c includes this header because the build orchestration reuses these\n"
"// helpers; the dependency runs backend -> runtime and never the other way.\n"
"\n"
"// --- file and path helpers ---\n"
"int file_exists(const char* path);\n"
"char* read_file(const char* path);\n"
"char* get_directory(const char* path);\n"
"char* join_path(const char* directory, const char* filename);\n"
"char* current_directory(void);\n"
"int delete_file(const char* path);\n"
"char* list_modules(const char* directory);\n"
"\n"
"// Directory containing the running executable. executable_directory() falls back\n"
"// to \".\" so callers always get a usable string; prismio_executable_directory()\n"
"// returns NULL when the location genuinely cannot be determined, which the\n"
"// toolchain-source search in build_driver.c needs in order to try its next\n"
"// candidate. Both return malloc'd memory.\n"
"char* executable_directory(void);\n"
"char* prismio_executable_directory(void);\n"
"\n"
"// --- command helpers ---\n"
"char* command_quote_arg(const char* arg);\n"
"int execute_command(const char* command);\n"
"\n"
"// --- command line, as seen by the compiled program ---\n"
"// Backed by the prismio_argc / prismio_argv globals that generated code defines\n"
"// and fills from main's real argc/argv (see generate_module / generate_function in\n"
"// src/ir.psm), which is what makes these work identically on every platform.\n"
"int cli_arg_count(void);\n"
"char* cli_arg(int index);\n"
"\n"
"// --- REQUIREMENTS 15: tasks and channels ---\n"
"// prismio_task_* are compiler-emitted: `spawn f(x)` and `join t` lower to them,\n"
"// so no program declares them by hand. The chan_* set is ordinary FFI surface a\n"
"// program externs for itself, because a channel is a library, not syntax.\n"
"//\n"
"// SPEC 11 item 10 is what shapes the split: a task *owns* its arguments and a\n"
"// channel *moves* its messages, so nothing the solver tiers is ever reachable\n"
"// from two tasks at once -- which is what keeps T3's count non-atomic.\n"
"void* prismio_task_spawn(void* fn, int rkind, int nargs, void* a0, void* a1, void* a2);\n"
"int   prismio_task_join(void* handle);\n"
"void* prismio_task_join_p(void* handle);\n"
"void  prismio_task_join_v(void* handle);\n"
"void  prismio_task_release(void* handle);\n"
"\n"
"void* chan_new(int capacity);\n"
"int   chan_send(void* handle, void* msg);\n"
"void* chan_recv(void* handle);\n"
"void* chan_share(void* handle);\n"
"void  chan_close(void* handle);\n"
"int   chan_len(void* handle);\n"
"void  chan_free(void* handle);\n"
"\n"
"// --- LAYOUT 2/3: the measured access profile ---\n"
"// Present in every binary and called only from a workload driver, which is an\n"
"// instrumented build the compiler produces, runs and discards. A shipped program\n"
"// contains no call to any of these -- see the block comment in lang_runtime.c for\n"
"// why that, rather than a -D, is what keeps W4 true.\n"
"void rt_profile_begin(void);\n"
"void rt_profile_end(void);\n"
"void rt_profile_field(const char* type, const char* field, int is_write);\n"
"void rt_profile_range(const char* type, const char* field, long long value);\n"
"void rt_profile_alloc(const char* type);\n"
"void rt_profile_release(const char* type);\n"
"int  rt_profile_dump(const char* path, const char* workload, int runs);\n"
"\n"
"// W3: the body every extern the sandbox cannot provide is given instead of a\n"
"// link to whatever libc exports. Warns once per symbol and returns 0.\n"
"long long rt_workload_stub(const char* name);\n"
"\n"
"#endif\n"
;

static const char prismio_embedded_lang_runtime_c[] =
"// AIF Level 4. Strings and lists are affine now, so codegen emits a release for\n"
"// them -- and the allocation at the other end of that pairing is in *this* file,\n"
"// not behind ir_alloc_object. Both ends have to swap together or a verify build\n"
"// reports every string release as a pointer that was never live.\n"
"//\n"
"// The build driver compiles this file with -DPRISMIO_AIF_VERIFY for `--verify`,\n"
"// which is why verify mode still changes no codegen: the swap happens when the\n"
"// runtime is compiled, not when the program is generated.\n"
"#ifdef PRISMIO_AIF_VERIFY\n"
"#include <stddef.h>\n"
"void* aif_verify_alloc(size_t size);\n"
"void  aif_verify_release(void* p);\n"
"void  aif_verify_arm(void);\n"
"#define rt_base_alloc(n) aif_verify_alloc(n)\n"
"#define rt_free(p)       aif_verify_release(p)\n"
"#else\n"
"#define rt_base_alloc(n) malloc(n)\n"
"#define rt_free(p)       free(p)\n"
"#endif\n"
"\n"
"#include <stdio.h>\n"
"#include <stdint.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"// AIF Level 4, second half: `region` absorbs collections too.\n"
"//\n"
"// COMPILER-AUDIT scheduled Level 4 after Level 3 so that regions would already\n"
"// exist to take the string traffic -- but the arena is reached through\n"
"// ir_alloc_region, and only a struct literal goes through that. A string is\n"
"// allocated in this file, by str_concat, which has no idea where it is being\n"
"// called from.\n"
"//\n"
"// So the *call site* says. Codegen brackets a producing runtime call whose value\n"
"// aif_arena_at_node accepted with rt_arena_hint_push/pop, and the allocation\n"
"// inside bumps from the arena instead of the heap. The bracket goes around the\n"
"// call only -- arguments are already evaluated by then -- so a nested allocation\n"
"// that was not accepted does not inherit the hint.\n"
"//\n"
"// The hint is a depth, not a flag, because a producing call can be an argument\n"
"// to another one. It is never pushed outside a region: aif_arena_at_node needs an\n"
"// enclosing one before it says yes.\n"
"void* arena_alloc(size_t size);\n"
"void* arena_alloc_at(int slot, size_t size);\n"
"int arena_current_slot(void);\n"
"\n"
"static int rt_arena_hint = 0;\n"
"\n"
"void rt_arena_hint_push(void) { rt_arena_hint++; }\n"
"void rt_arena_hint_pop(void)  { if (rt_arena_hint > 0) rt_arena_hint--; }\n"
"\n"
"static void* rt_alloc(size_t size) {\n"
"    if (rt_arena_hint > 0) return arena_alloc(size);\n"
"    return rt_base_alloc(size);\n"
"}\n"
"\n"
"// Which arena an allocation made right now would come from, 1-based, or 0 for\n"
"// \"the heap\". A container is handed this at construction so that a *later*\n"
"// reallocation can go back to the same arena rather than to whichever one is on\n"
"// top at the time -- see list_push. A flag would not do: a nested `region`\n"
"// inside the one that owns the list would take the new element block and free it\n"
"// at its own exit, with the list still pointing at it.\n"
"static int rt_arena_slot(void) { return rt_arena_hint > 0 ? arena_current_slot() : 0; }\n"
"\n"
"// Println function - prints a string and adds a newline\n"
"void println(const char* str) {\n"
"    printf(\"%s\\n\", str);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print function - prints a string without newline\n"
"void print(const char* str) {\n"
"    printf(\"%s\", str);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print integer\n"
"void print_int(int value) {\n"
"    printf(\"%d\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print integer with newline\n"
"void println_int(int value) {\n"
"    printf(\"%d\\n\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print float\n"
"void print_float(double value) {\n"
"    printf(\"%g\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print float with newline\n"
"void println_float(double value) {\n"
"    printf(\"%g\\n\", value);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Private ABI used by std/io.psm. See the WASM branch for why the old symbols\n"
"// remain available even though new Prismio programs do not declare them.\n"
"void prismio_rt_print(const char* str) {\n"
"    print(str);\n"
"}\n"
"\n"
"void prismio_rt_println(const char* str) {\n"
"    println(str);\n"
"}\n"
"\n"
"void prismio_rt_print_float(double value) {\n"
"    print_float(value);\n"
"}\n"
"\n"
"void prismio_rt_println_float(double value) {\n"
"    println_float(value);\n"
"}\n"
"\n"
"// Print boolean\n"
"void print_bool(int value) {\n"
"    printf(\"%s\", value ? \"true\" : \"false\");\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print boolean with newline\n"
"void println_bool(int value) {\n"
"    printf(\"%s\\n\", value ? \"true\" : \"false\");\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print character\n"
"void print_char(char c) {\n"
"    printf(\"%c\", c);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// Print character with newline\n"
"void println_char(char c) {\n"
"    printf(\"%c\\n\", c);\n"
"    fflush(stdout);\n"
"}\n"
"\n"
"// ============================================\n"
"// String Comparison\n"
"// ============================================\n"
"\n"
"int str_equals(const char* s1, const char* s2) {\n"
"    return strcmp(s1, s2) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"int str_compare(const char* s1, const char* s2) {\n"
"    return strcmp(s1, s2);\n"
"}\n"
"\n"
"// ============================================\n"
"// String Length\n"
"// ============================================\n"
"\n"
"int str_length(const char* s) {\n"
"    return strlen(s);\n"
"}\n"
"\n"
"// ============================================\n"
"// String Concatenation\n"
"// ============================================\n"
"\n"
"char* str_concat(const char* s1, const char* s2) {\n"
"    int len1 = strlen(s1);\n"
"    int len2 = strlen(s2);\n"
"    char* result = (char*)rt_alloc(len1 + len2 + 1);\n"
"\n"
"    strcpy(result, s1);\n"
"    strcat(result, s2);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Substring\n"
"// ============================================\n"
"\n"
"char* str_substring(const char* s, int start, int length) {\n"
"    int str_len = strlen(s);\n"
"\n"
"    // The out-of-range answer is an empty string the caller *owns*. It used to be\n"
"    // the literal \"\", which was fine while nothing freed a string and is a free\n"
"    // of a .rodata pointer now that they are affine (AIF Level 4). Anything\n"
"    // declared to return String hands back something a release can take.\n"
"    if (start < 0 || start >= str_len) {\n"
"        start = str_len;\n"
"        length = 0;\n"
"    }\n"
"\n"
"    if (start + length > str_len) {\n"
"        length = str_len - start;\n"
"    }\n"
"\n"
"    char* result = (char*)rt_alloc(length + 1);\n"
"    strncpy(result, s + start, length);\n"
"    result[length] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// The length-carrying slice, and the reason it has to exist.\n"
"//\n"
"// `str_substring` above cannot be made linear. A String here is a\n"
"// NUL-terminated `char*`, so the only way it can bound `start` or clamp\n"
"// `length` is to strlen the whole buffer -- once per call, over the entire\n"
"// source. A lexer calls it once per token, which makes scanning a file\n"
"// O(n x tokens). Measured on a 21 KB buffer: 1.808 ms against 0.031 ms for the\n"
"// identical scan with the call removed, i.e. **98% of the work**, and doubling\n"
"// the input multiplies the time by ~2.9 rather than by 2.\n"
"//\n"
"// This is the same defect `str_char_at` had, fixed the same way. createLexer\n"
"// already measures the input once and holds it in `Lexer.length` precisely\n"
"// because a per-character strlen made scanning quadratic; the comment there\n"
"// says so. That fix stopped at the character reads and never reached the\n"
"// slices, which is where the tokens are actually cut.\n"
"//\n"
"// The caller passes the base's length, which it already knows, and the bounds\n"
"// become constant time. This is SPEC 8.4's `(handle, offset, length)` reduced\n"
"// to what today's String can carry -- and it is only half of a view, because it\n"
"// still allocates and copies. Deleting that half needs the value to *be*\n"
"// (base, offset, length) rather than a fresh NUL-terminated buffer, which is\n"
"// the representation work. Priced in Rust on the same workload, the copy is\n"
"// worth a further 5.57x.\n"
"//\n"
"// Clamping rather than rejecting, exactly as str_substring does, so a caller\n"
"// that passes a stale or wrong `base_len` gets a short string and never a read\n"
"// past the end.\n"
"char* str_slice(const char* s, int start, int length, int base_len) {\n"
"    if (base_len < 0) base_len = 0;\n"
"    if (start < 0 || start >= base_len) {\n"
"        start = base_len;\n"
"        length = 0;\n"
"    }\n"
"    if (length < 0) length = 0;\n"
"    if (start + length > base_len) {\n"
"        length = base_len - start;\n"
"    }\n"
"\n"
"    char* result = (char*)rt_alloc(length + 1);\n"
"    strncpy(result, s + start, length);\n"
"    result[length] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Character At\n"
"// ============================================\n"
"\n"
"char str_char_at(const char* s, int index) {\n"
"    int len = strlen(s);\n"
"\n"
"    if (index < 0 || index >= len) {\n"
"        return '\\0';\n"
"    }\n"
"\n"
"    return s[index];\n"
"}\n"
"\n"
"// See the native definition for why this exists.\n"
"char str_byte_at(const char* s, int index) {\n"
"    if (index < 0) return '\\0';\n"
"    return s[index];\n"
"}\n"
"\n"
"// ============================================\n"
"// String Contains\n"
"// ============================================\n"
"\n"
"int str_contains(const char* haystack, const char* needle) {\n"
"    return strstr(haystack, needle) != NULL ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Starts With\n"
"// ============================================\n"
"\n"
"int str_starts_with(const char* s, const char* prefix) {\n"
"    int s_len = strlen(s);\n"
"    int prefix_len = strlen(prefix);\n"
"\n"
"    if (prefix_len > s_len) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    return strncmp(s, prefix, prefix_len) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Ends With\n"
"// ============================================\n"
"\n"
"int str_ends_with(const char* s, const char* suffix) {\n"
"    int s_len = strlen(s);\n"
"    int suffix_len = strlen(suffix);\n"
"\n"
"    if (suffix_len > s_len) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    return strcmp(s + (s_len - suffix_len), suffix) == 0 ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Index Of\n"
"// ============================================\n"
"\n"
"int str_index_of(const char* haystack, const char* needle) {\n"
"    const char* pos = strstr(haystack, needle);\n"
"\n"
"    if (pos == NULL) {\n"
"        return -1;\n"
"    }\n"
"\n"
"    return pos - haystack;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Replace (first occurrence)\n"
"// ============================================\n"
"\n"
"char* str_replace(const char* s, const char* old_str, const char* new_str) {\n"
"    const char* pos = strstr(s, old_str);\n"
"\n"
"    if (pos == NULL) {\n"
"        // No match, return copy\n"
"        char* result = (char*)rt_alloc(strlen(s) + 1);\n"
"        strcpy(result, s);\n"
"        return result;\n"
"    }\n"
"\n"
"    int old_len = strlen(old_str);\n"
"    int new_len = strlen(new_str);\n"
"    int prefix_len = pos - s;\n"
"    int suffix_len = strlen(pos + old_len);\n"
"\n"
"    char* result = (char*)rt_alloc(prefix_len + new_len + suffix_len + 1);\n"
"\n"
"    // Copy prefix\n"
"    strncpy(result, s, prefix_len);\n"
"    result[prefix_len] = '\\0';\n"
"\n"
"    // Copy new string\n"
"    strcat(result, new_str);\n"
"\n"
"    // Copy suffix\n"
"    strcat(result, pos + old_len);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String To Integer\n"
"// ============================================\n"
"\n"
"int str_to_int(const char* s) {\n"
"    return atoi(s);\n"
"}\n"
"\n"
"// ============================================\n"
"// Integer To String\n"
"// ============================================\n"
"\n"
"char* int_to_str(int n) {\n"
"    char* result = (char*)rt_alloc(32);  // enough for any int\n"
"    sprintf(result, \"%d\", n);\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Clone/Copy\n"
"// ============================================\n"
"\n"
"char* str_clone(const char* s) {\n"
"    int len = strlen(s);\n"
"    char* result = (char*)rt_alloc(len + 1);\n"
"    strcpy(result, s);\n"
"    return result;\n"
"}\n"
"\n"
"// One-character string. The lexer assembles a decoded string literal a character\n"
"// at a time and there is no other way to turn a Char into a String -- the\n"
"// language has no string builder and no char-to-string conversion.\n"
"char* str_from_char(char c) {\n"
"    char* result = (char*)rt_alloc(2);\n"
"    result[0] = c;\n"
"    result[1] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Trim (whitespace)\n"
"// ============================================\n"
"\n"
"char* str_trim(const char* s) {\n"
"    // Find start (skip leading whitespace)\n"
"    while (*s == ' ' || *s == '\\t' || *s == '\\n' || *s == '\\r') {\n"
"        s++;\n"
"    }\n"
"\n"
"    // An all-whitespace input falls through to a one-byte allocation rather than\n"
"    // returning the literal \"\" -- see str_substring for why a String return is\n"
"    // always something the caller can release.\n"
"\n"
"    // Find end (skip trailing whitespace)\n"
"    const char* end = s + strlen(s) - 1;\n"
"    while (end > s && (*end == ' ' || *end == '\\t' || *end == '\\n' || *end == '\\r')) {\n"
"        end--;\n"
"    }\n"
"\n"
"    int len = end - s + 1;\n"
"    char* result = (char*)rt_alloc(len + 1);\n"
"    strncpy(result, s, len);\n"
"    result[len] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// String Split (simplified - single delimiter)\n"
"// ============================================\n"
"\n"
"typedef struct {\n"
"    char** parts;\n"
"    int count;\n"
"} StringArray;\n"
"\n"
"StringArray* str_split(const char* s, char delimiter) {\n"
"    // Count delimiters\n"
"    int count = 1;\n"
"    for (const char* p = s; *p; p++) {\n"
"        if (*p == delimiter) count++;\n"
"    }\n"
"\n"
"    StringArray* result = (StringArray*)malloc(sizeof(StringArray));\n"
"    result->parts = (char**)malloc(count * sizeof(char*));\n"
"    result->count = count;\n"
"\n"
"    int part_index = 0;\n"
"    const char* start = s;\n"
"    const char* p = s;\n"
"\n"
"    while (1) {\n"
"        if (*p == delimiter || *p == '\\0') {\n"
"            int len = p - start;\n"
"            result->parts[part_index] = (char*)malloc(len + 1);\n"
"            strncpy(result->parts[part_index], start, len);\n"
"            result->parts[part_index][len] = '\\0';\n"
"            part_index++;\n"
"\n"
"            if (*p == '\\0') break;\n"
"            start = p + 1;\n"
"        }\n"
"        p++;\n"
"    }\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"void str_split_free(StringArray* arr) {\n"
"    for (int i = 0; i < arr->count; i++) {\n"
"        free(arr->parts[i]);\n"
"    }\n"
"    free(arr->parts);\n"
"    free(arr);\n"
"}\n"
"\n"
"// Helpers for type punning ASTNode pointers in Prismio\n"
"void* ptr_to_node(void* ptr) { return ptr; }\n"
"void* node_to_ptr(void* ptr) { return ptr; }\n"
"void* ptr_to_token(void* ptr) { return ptr; }\n"
"void* token_to_ptr(void* ptr) { return ptr; }\n"
"void* ptr_to_type(void* ptr) { return ptr; }\n"
"void* type_to_ptr(void* ptr) { return ptr; }\n"
"\n"
"// A note on how the frontend spells \"this slot is empty\", because it is not\n"
"// what it looks like and getting it wrong is a segfault rather than a warning.\n"
"//\n"
"// An absent child is the **empty string**, not a null pointer -- create_node()\n"
"// initialises every pointer slot to \"\". So `str_equals(p, \"\")` is the right\n"
"// question and a null test is not: a null test says \"present\" for an empty slot\n"
"// and the caller then dereferences it.\n"
"//\n"
"// What makes `str_equals(p, \"\")` fragile is the other direction. A punned\n"
"// pointer is a `char*`, so strcmp reads the *bytes of the pointed-to struct*,\n"
"// and a struct beginning with a zero-valued enum begins with a NUL byte -- so\n"
"// it compares equal to \"\" and a live node reads as an empty slot. src/ast.psm\n"
"// states the invariant that keeps this from firing and enforces it at the two\n"
"// enums that matter.\n"
"\n"
"// Native builds use libc malloc; the per-frame arena reset is a no-op here.\n"
"void heap_reset(void) { }\n"
"\n"
"// ============================================================================\n"
"// Arenas (AIF Level 3, SPEC 5.2)\n"
"//\n"
"// A stack of bump allocators. `region r { ... }` pushes one on entry and pops it\n"
"// on every exit; an allocation the analysis proved cannot outlive that region\n"
"// comes from the top of the stack, and the whole block goes back at once.\n"
"//\n"
"// COMPILER-AUDIT 3 expected the arena handle to be *threaded* to each allocation\n"
"// site as a second argument. It is dynamically scoped instead, which keeps\n"
"// ir_alloc_region a `fn(size) -> ptr` like the other two hooks and needs no new\n"
"// frontend plumbing. The cost of that choice is that a callee cannot be given a\n"
"// different arena from its caller's -- which does not arise, because only sites\n"
"// lexically inside the block are routed here (SPEC 5.2's own wording), and the\n"
"// analysis has already proved each of those dies no later than this region.\n"
"//\n"
"// Chunks are a linked list so a region that outgrows its first block keeps\n"
"// going rather than falling back to the heap; pointers already handed out stay\n"
"// valid because earlier chunks are not moved.\n"
"// ============================================================================\n"
"\n"
"#define ARENA_CHUNK_MIN 8192\n"
"#define ARENA_MAX_DEPTH 64\n"
"\n"
"typedef struct ArenaChunk {\n"
"    struct ArenaChunk* next;\n"
"    size_t used, cap;\n"
"    unsigned char* base;\n"
"} ArenaChunk;\n"
"\n"
"static ArenaChunk* arena_stack[ARENA_MAX_DEPTH];\n"
"static int arena_depth = 0;\n"
"\n"
"// Reported by arena_stats so a test can assert an allocation came from a region\n"
"// rather than from malloc -- the two are indistinguishable from the value.\n"
"static long arena_bytes_served, arena_objects_served, arena_regions_entered;\n"
"\n"
"// Chunks are pooled rather than returned to libc, and that is what makes\n"
"// LAYOUT 4's `arenaSetupCost` of ~40 cycles a real number instead of an\n"
"// aspiration. Without the pool a region that serves one allocation pays a malloc\n"
"// for its chunk and a free at the pop -- 180 cycles, more than the 87 an arena\n"
"// saves per allocation -- so the cost model would have to decline every small\n"
"// scope and automatic placement (LAYOUT 7.1) could never fire. With it, entering\n"
"// a region is a depth increment and a pointer swap.\n"
"//\n"
"// Only default-sized chunks are pooled. An oversized one was cut for a single\n"
"// large allocation and holding it would keep an arbitrary amount of memory live\n"
"// for the rest of the program.\n"
"//\n"
"// The pool is capped, and the cap is the difference between \"pooled\" and\n"
"// \"never returned to the OS\". Uncapped, a program's peak arena footprint stays\n"
"// resident for the rest of its life: one pass that nests deeply or chains many\n"
"// chunks sets a high-water mark nothing ever gives back, and peak RSS carries it\n"
"// to exit. Trimming rather than removing, because removing the pool is what the\n"
"// note above says would stop automatic placement firing at all.\n"
"//\n"
"// ARENA_POOL_MAX * ARENA_CHUNK_MIN is the resident ceiling: 64 KB. The cap has\n"
"// to clear ordinary *nesting* -- chunks held by live regions are on the stack,\n"
"// not in the pool, so it only has to cover what a single pop hands back plus\n"
"// reuse across iterations, and a loop entering one region reuses one chunk.\n"
"#define ARENA_POOL_MAX 8\n"
"static ArenaChunk* arena_pool;\n"
"static int arena_pool_count;\n"
"\n"
"static ArenaChunk* arena_chunk_new(size_t need) {\n"
"    if (need <= ARENA_CHUNK_MIN && arena_pool) {\n"
"        ArenaChunk* c = arena_pool;\n"
"        arena_pool = c->next;\n"
"        arena_pool_count--;\n"
"        c->used = 0;\n"
"        c->next = NULL;\n"
"        return c;\n"
"    }\n"
"\n"
"    size_t cap = need > ARENA_CHUNK_MIN ? need : ARENA_CHUNK_MIN;\n"
"    ArenaChunk* c = (ArenaChunk*)malloc(sizeof(ArenaChunk));\n"
"    if (!c) return NULL;\n"
"    c->base = (unsigned char*)malloc(cap);\n"
"    if (!c->base) { free(c); return NULL; }\n"
"    c->used = 0;\n"
"    c->cap = cap;\n"
"    c->next = NULL;\n"
"    return c;\n"
"}\n"
"\n"
"void arena_push(void) {\n"
"#ifdef PRISMIO_AIF_VERIFY\n"
"    aif_verify_arm();\n"
"#endif\n"
"    if (arena_depth >= ARENA_MAX_DEPTH) {\n"
"        fprintf(stderr, \"internal error: regions nested more than %d deep\\n\", ARENA_MAX_DEPTH);\n"
"        exit(1);\n"
"    }\n"
"    arena_stack[arena_depth++] = NULL;   // chunks are taken on first use\n"
"    arena_regions_entered++;\n"
"}\n"
"\n"
"void arena_pop(void) {\n"
"    if (arena_depth <= 0) return;\n"
"    ArenaChunk* c = arena_stack[--arena_depth];\n"
"    while (c) {\n"
"        ArenaChunk* next = c->next;\n"
"        if (c->cap == ARENA_CHUNK_MIN && arena_pool_count < ARENA_POOL_MAX) {\n"
"            c->next = arena_pool;\n"
"            arena_pool = c;\n"
"            arena_pool_count++;\n"
"        } else {\n"
"            free(c->base);\n"
"            free(c);\n"
"        }\n"
"        c = next;\n"
"    }\n"
"    arena_stack[arena_depth] = NULL;\n"
"}\n"
"\n"
"static void* arena_alloc_slot(int index, size_t size) {\n"
"    size_t need = (size + 15u) & ~(size_t)15u;   // 16-byte aligned, as malloc is\n"
"    ArenaChunk* c = arena_stack[index];\n"
"    if (!c || c->used + need > c->cap) {\n"
"        ArenaChunk* fresh = arena_chunk_new(need);\n"
"        if (!fresh) return rt_base_alloc(size);\n"
"        fresh->next = c;\n"
"        arena_stack[index] = fresh;\n"
"        c = fresh;\n"
"    }\n"
"\n"
"    void* p = c->base + c->used;\n"
"    c->used += need;\n"
"    arena_bytes_served += (long)need;\n"
"    arena_objects_served++;\n"
"    return p;\n"
"}\n"
"\n"
"void* arena_alloc(size_t size) {\n"
"    // No region active. Codegen only routes a site here when one is, so this is\n"
"    // a corrupted arena stack rather than an ordinary case -- but falling back\n"
"    // to the ordinary allocator keeps SPEC 1's invariant (never wrong, only\n"
"    // slower) instead of returning NULL into code that will not check it. Through\n"
"    // rt_base_alloc rather than malloc so a verify build still accounts for it.\n"
"    if (arena_depth <= 0) return rt_base_alloc(size);\n"
"    return arena_alloc_slot(arena_depth - 1, size);\n"
"}\n"
"\n"
"int arena_current_slot(void) { return arena_depth; }\n"
"\n"
"// SPEC 5.2.1.1. Allocate from a *named* arena rather than from the innermost\n"
"// one, so a container can grow back into the region that owns it after an inner\n"
"// region has been entered. `slot` is 1-based, as arena_current_slot returns it.\n"
"//\n"
"// A slot past the current depth is a region that has already exited, which\n"
"// obligation 3 rules out -- the container is dead by then. Falling back to the\n"
"// heap rather than trusting it keeps SPEC 1's invariant, and it is the direction\n"
"// that leaks rather than the one that corrupts.\n"
"void* arena_alloc_at(int slot, size_t size) {\n"
"    if (slot <= 0 || slot > arena_depth) return rt_base_alloc(size);\n"
"    return arena_alloc_slot(slot - 1, size);\n"
"}\n"
"\n"
"long arena_objects(void) { return arena_objects_served; }\n"
"long arena_bytes(void)   { return arena_bytes_served; }\n"
"long arena_regions(void) { return arena_regions_entered; }\n"
"\n"
"// ============================================================================\n"
"// AIF `verify` mode (SPEC 7.3)\n"
"//\n"
"// A verify build swaps the allocator and deallocator names through\n"
"// ir_set_alloc_function / ir_set_free_function and changes nothing else -- the\n"
"// same seam COMPILER-AUDIT 3 describes for T2, used here for its first real\n"
"// purpose. Codegen is identical to a release build.\n"
"//\n"
"// What this covers, of SPEC 7.3's table:\n"
"//\n"
"//   Tier T0/T1, \"no access after frame or region exit\" -- partially. Released\n"
"//   memory is poisoned before it goes back to the allocator, so a read that\n"
"//   should not have happened returns a recognisable pattern rather than data\n"
"//   that is merely stale-but-plausible. Reads are not instrumented, so this\n"
"//   makes such a bug loud rather than impossible.\n"
"//\n"
"//   The balance itself, which is not in the table and should be: every object\n"
"//   released exactly once, and none left over. That is what catches a missed\n"
"//   drop path (leak) and a doubled one (release of something not live), which\n"
"//   are the two ways Level 2 can be wrong.\n"
"//\n"
"// What it does not cover, and why:\n"
"//\n"
"//   A = Unique / A <= Borrowed  need a count word in the object header, which\n"
"//                               is the same layout change T3 needs.\n"
"//   E = Region(r)               needs arenas; Level 3.\n"
"//   E <= Caller                 needs static-root reachability at return.\n"
"//   T = Isolated / Transferred  vacuous -- the language has no tasks.\n"
"//   C = Acyclic                 needs a periodic heap walk.\n"
"// ============================================================================\n"
"\n"
"#define AIF_VERIFY_BUCKETS 4096\n"
"#define AIF_VERIFY_POISON  0xDD\n"
"\n"
"typedef struct AifLive {\n"
"    struct AifLive* next;\n"
"    void* p;\n"
"    size_t size;\n"
"    long serial;        // allocation order, so a leak report names something\n"
"} AifLive;\n"
"\n"
"static AifLive* aif_live[AIF_VERIFY_BUCKETS];\n"
"static long aif_allocs, aif_releases, aif_violations;\n"
"static int aif_report_armed;\n"
"\n"
"static unsigned aif_live_hash(const void* p) {\n"
"    uintptr_t v = (uintptr_t)p;\n"
"    v ^= v >> 33;\n"
"    v *= 0xff51afd7ed558ccdull;\n"
"    v ^= v >> 29;\n"
"    return (unsigned)v & (AIF_VERIFY_BUCKETS - 1);\n"
"}\n"
"\n"
"void aif_verify_report(void) {\n"
"    long leaked = 0;\n"
"    for (int i = 0; i < AIF_VERIFY_BUCKETS; i++) {\n"
"        for (AifLive* n = aif_live[i]; n; n = n->next) {\n"
"            // The serial is the allocation's order in the run, which is the only\n"
"            // handle a leak report can offer without debug info: \"the 116th\n"
"            // object\" is enough to find the site by counting sites.\n"
"            if (leaked < 20) {\n"
"                fprintf(stderr, \"aif-verify: leaked #%ld (%lu bytes)\\n\",\n"
"                        n->serial, (unsigned long)n->size);\n"
"            }\n"
"            leaked++;\n"
"        }\n"
"    }\n"
"    fprintf(stderr, \"aif-verify: %ld allocated, %ld released, %ld leaked, %ld violation(s)\\n\",\n"
"            aif_allocs, aif_releases, leaked, aif_violations);\n"
"    if (leaked || aif_violations) {\n"
"        fprintf(stderr, \"aif-verify: FAILED -- an inferred fact did not hold at run time\\n\");\n"
"    }\n"
"}\n"
"\n"
"// Armed by the first allocation *or* the first region entry. Once LAYOUT 7.1\n"
"// places arenas automatically, a program can run to completion without a single\n"
"// call through the seam -- every allocation served from a bump block -- and\n"
"// arming only there would print no report at all, which reads as \"the seam was\n"
"// not redirected\" rather than as \"nothing needed accounting\".\n"
"void aif_verify_arm(void) {\n"
"    if (!aif_report_armed) {\n"
"        aif_report_armed = 1;\n"
"        atexit(aif_verify_report);\n"
"    }\n"
"}\n"
"\n"
"void* aif_verify_alloc(size_t size) {\n"
"    aif_verify_arm();\n"
"    void* p = malloc(size);\n"
"    if (!p) return NULL;\n"
"\n"
"    aif_allocs++;\n"
"    AifLive* n = (AifLive*)malloc(sizeof(AifLive));\n"
"    if (n) {\n"
"        n->p = p;\n"
"        n->size = size;\n"
"        n->serial = aif_allocs;\n"
"        unsigned b = aif_live_hash(p);\n"
"        n->next = aif_live[b];\n"
"        aif_live[b] = n;\n"
"    }\n"
"    return p;\n"
"}\n"
"\n"
"void aif_verify_release(void* p) {\n"
"    if (!p) return;\n"
"\n"
"    unsigned b = aif_live_hash(p);\n"
"    AifLive** link = &aif_live[b];\n"
"    while (*link && (*link)->p != p) link = &(*link)->next;\n"
"\n"
"    if (!*link) {\n"
"        // Either released twice, or never came from here. Both mean a fact was\n"
"        // wrong: the value was freed on a path the analysis did not account for.\n"
"        fprintf(stderr, \"aif-verify: release of a pointer that is not live (%p)\\n\", p);\n"
"        aif_violations++;\n"
"        return;\n"
"    }\n"
"\n"
"    AifLive* n = *link;\n"
"    *link = n->next;\n"
"    memset(p, AIF_VERIFY_POISON, n->size);\n"
"    free(n);\n"
"    free(p);\n"
"    aif_releases++;\n"
"}\n"
"\n"
"// ============================================\n"
"// Growable list (List<T> for reference elements) \342\200\224 backs Prismio's List<T>.\n"
"// Stores pointer-sized elements.\n"
"// ============================================\n"
"// ============================================\n"
"// AIF Level 5 -- T3, non-atomic reference counting (SPEC 3, T3).\n"
"//\n"
"// The count lives in a **prefix header**: rc_alloc returns base + RC_HDR, and the\n"
"// count is the word immediately in front of the pointer the program holds. That\n"
"// choice is what keeps the seam a fourth allocator name and nothing else.\n"
"// COMPILER-AUDIT 3's table says T3 is only \"partly\" expressible because \"the\n"
"// header word changes struct layout, which named_struct and every\n"
"// ir_struct_field_ptr index would have to account for\" -- true of a header word\n"
"// inside the object, and avoided entirely by putting it in front. The struct type\n"
"// LLVM sees is unchanged and every field index still means what it meant.\n"
"//\n"
"// **The count starts at zero, not one**, and that is the whole design rather than\n"
"// an off-by-one. What is counted here is *container edges*, because they are the\n"
"// only holder class this compiler both tracks and releases: a T3 value's escape is\n"
"// Caller or Global by definition of the tier, so aif_frees_at_scope_node can never\n"
"// admit its binding, and a struct field has no teardown yet. A value in no\n"
"// container is therefore held by nothing that will ever release, and counting the\n"
"// creating expression would put every such value permanently at one. At zero it\n"
"// simply leaks, which is exactly what it did before this existed.\n"
"//\n"
"// So: one container is one count, the teardown decrements, and the value dies with\n"
"// the last container that held it. A release without a matching retain cannot\n"
"// happen -- only a container retains, and only the same container releases.\n"
"//\n"
"// **An OPAQUE site is never refcounted.** The pointer came back from a function\n"
"// this compilation cannot see, so there is no header in front of it and reading\n"
"// one is reading whatever the allocator put there. That excludes all 37 of the\n"
"// compiler's own T3 sites, which is why the self-host exercises none of this.\n"
"// ============================================\n"
"\n"
"#define RC_HDR 16       // >= sizeof(size_t), and keeps the payload 16-byte aligned\n"
"\n"
"static size_t* rc_slot(void* p) {\n"
"    return &((size_t*)p)[-1];\n"
"}\n"
"\n"
"// LAYOUT 6's hot/cold split, the T3 half.\n"
"//\n"
"// `rc_release` frees one block and cannot name the type -- a counted value's last\n"
"// holder is a container's teardown, which arrives holding a bare pointer. That is\n"
"// the one release path the generated `__aif_release_T` does not cover, and it is\n"
"// where a split would leak its cold block.\n"
"//\n"
"// **RC_HDR is 16 bytes with 8 in use, so the fix is already paid for.** The\n"
"// second word holds the *byte offset* of the link within the payload, stamped at\n"
"// construction exactly as `cyc_set_type` stamps a descriptor, and `rc_release`\n"
"// reads the cold pointer from there. No function pointer, no per-type table, and\n"
"// no extra call on the release path.\n"
"//\n"
"// Offset 0 means \"not split\", and it is sound rather than convenient: field 0 is\n"
"// pinned hot and placed first, so no hot record can carry its link at byte 0.\n"
"static size_t* rc_cold_slot(void* p) {\n"
"    return &((size_t*)p)[-2];\n"
"}\n"
"\n"
"void* rc_alloc(size_t size) {\n"
"    unsigned char* base = (unsigned char*)rt_base_alloc(size + RC_HDR);\n"
"    if (!base) return 0;\n"
"    void* payload = base + RC_HDR;\n"
"    *rc_slot(payload) = 0;\n"
"    *rc_cold_slot(payload) = 0;\n"
"    return payload;\n"
"}\n"
"\n"
"// Allocates the cold half of a split T3 object, links it, and records where the\n"
"// link is. Emitted by ir_alloc_rc immediately after rc_alloc, so the object is\n"
"// whole before any field initialiser runs.\n"
"//\n"
"// Through rt_base_alloc, like rc_alloc itself, so a verify build accounts for\n"
"// both halves in one ledger and rc_release's rt_free pairs with it.\n"
"void rc_attach_cold(void* p, size_t cold_size, size_t link_offset) {\n"
"    if (!p || link_offset == 0) return;\n"
"    void* cold = rt_base_alloc(cold_size);\n"
"    *(void**)((unsigned char*)p + link_offset) = cold;\n"
"    *rc_cold_slot(p) = link_offset;\n"
"}\n"
"\n"
"void rc_retain(void* p) {\n"
"    if (p) (*rc_slot(p))++;\n"
"}\n"
"\n"
"// AIF T4a (SPEC 3, REQUIREMENTS 15). The same count, touched atomically.\n"
"//\n"
"// **A separate entry point, chosen at compile time, and that is the whole\n"
"// design.** The obvious alternative is one `rc_release` that branches on a bit\n"
"// in the header -- and it puts a load and a branch on the path SPEC 11 item 10\n"
"// exists to keep clear. The point of inferring thread affinity at all is that\n"
"// the answer is known statically, so a value that never crosses a thread\n"
"// boundary should not pay even a predictable branch to find that out. The\n"
"// compiler picks the symbol; there is nothing to test at run time.\n"
"//\n"
"// Relaxed on the increment, acq_rel on the decrement, which is the standard\n"
"// pairing and not an optimisation: a retain only needs the count to be right,\n"
"// while the decrement that reaches zero must see every write any other thread\n"
"// made through its own reference before the free runs.\n"
"//\n"
"// Built from __atomic rather than <stdatomic.h> because the count is an\n"
"// ordinary `size_t` in a header this file shares with the non-atomic path --\n"
"// declaring it _Atomic would change rc_slot's type for both. The generic\n"
"// builtins are the supported way to do exactly that, and clang is the compiler\n"
"// on all three CI platforms.\n"
"#if defined(_MSC_VER) && !defined(__clang__)\n"
"#include <intrin.h>\n"
"#define PRISMIO_ATOMIC_INC(p) ((size_t)_InterlockedIncrement64((volatile __int64*)(p)))\n"
"#define PRISMIO_ATOMIC_DEC(p) ((size_t)_InterlockedDecrement64((volatile __int64*)(p)))\n"
"#else\n"
"#define PRISMIO_ATOMIC_INC(p) __atomic_add_fetch((p), 1, __ATOMIC_RELAXED)\n"
"#define PRISMIO_ATOMIC_DEC(p) __atomic_sub_fetch((p), 1, __ATOMIC_ACQ_REL)\n"
"#endif\n"
"\n"
"void rc_retain_atomic(void* p) {\n"
"    if (p) PRISMIO_ATOMIC_INC(rc_slot(p));\n"
"}\n"
"\n"
"void rc_release_atomic(void* p) {\n"
"    if (!p) return;\n"
"    size_t* c = rc_slot(p);\n"
"    // The zero test is not a race the atomics have to cover. A count of zero\n"
"    // means nothing ever retained the value, so no second reference exists to\n"
"    // be decrementing concurrently -- the same reasoning rc_release relies on,\n"
"    // and the reason this reads the slot plainly first.\n"
"    if (*c == 0) return;\n"
"    if (PRISMIO_ATOMIC_DEC(c) == 0) {\n"
"        size_t off = *rc_cold_slot(p);\n"
"        if (off) rt_free(*(void**)((unsigned char*)p + off));\n"
"        rt_free((unsigned char*)p - RC_HDR);\n"
"    }\n"
"}\n"
"\n"
"void rc_release(void* p) {\n"
"    if (!p) return;\n"
"    size_t* c = rc_slot(p);\n"
"    if (*c == 0) return;            // never retained: nothing holds it, nothing frees it\n"
"    if (--(*c) == 0) {\n"
"        // The cold block first: its pointer lives *inside* the payload, so reading\n"
"        // it after the base has gone is a use-after-free -- and in a verify build,\n"
"        // a read of poisoned bytes handed straight to the deallocator.\n"
"        size_t off = *rc_cold_slot(p);\n"
"        if (off) rt_free(*(void**)((unsigned char*)p + off));\n"
"        rt_free((unsigned char*)p - RC_HDR);\n"
"    }\n"
"}\n"
"\n"
"// ============================================\n"
"// AIF T4b -- the cycle collector (CYCLES 3)\n"
"//\n"
"// Trial deletion (Bacon-Rajan), scoped to the T4b residue, traversing **only\n"
"// cyclic edges** (CYCLES 4). That restriction is the design's own contribution\n"
"// and it is available because the compiler owns the type graph: every edge of a\n"
"// value-level cycle connects two types in one SCC, so traversing only fields\n"
"// whose type is in the owner's SCC finds every cycle and never leaves the\n"
"// skeleton. A Node with two child pointers and six fields of strings and spans\n"
"// is walked through two edges, not eight, and the collector never descends into\n"
"// the string graph at all.\n"
"//\n"
"// **A T4b object is told what its cyclic children are.** `cyc_set_type` stamps a\n"
"// per-type function generated by codegen, for the same reason `list_set_elem_owner`\n"
"// exists: reading a header in front of a pointer to find out would be reading\n"
"// memory this compilation did not allocate.\n"
"//\n"
"// The count is container edges, exactly as at Level 5 -- a T4b value's escape is\n"
"// Caller or Global by the tier's definition, so no binding ever releases it.\n"
"// What T4b adds over T3 is the case Level 5 cannot handle: a decrement that does\n"
"// *not* reach zero is the only way a cycle can become garbage, so that is when a\n"
"// candidate root is buffered.\n"
"// ============================================\n"
"\n"
"#define CYC_BLACK  0\n"
"#define CYC_GREY   1\n"
"#define CYC_WHITE  2\n"
"#define CYC_PURPLE 3\n"
"\n"
"typedef void (*CycVisitor)(void*);\n"
"\n"
"typedef struct {\n"
"    size_t rc;\n"
"    unsigned char colour;\n"
"    unsigned char buffered;\n"
"    void (*children)(void*, CycVisitor);\n"
"    void (*release)(void*);\n"
"} CycHeader;\n"
"\n"
"// Rounded so the payload stays 16-byte aligned, like RC_HDR above.\n"
"#define CYC_HDR ((sizeof(CycHeader) + 15u) & ~(size_t)15u)\n"
"\n"
"static CycHeader* cyc_hdr(void* p) {\n"
"    return (CycHeader*)((unsigned char*)p - CYC_HDR);\n"
"}\n"
"\n"
"// CYCLES 6.1: collection is triggered by candidate-buffer occupancy, never by a\n"
"// timer -- a timer would make a program's pause profile a function of how fast\n"
"// the machine is, which is exactly the unpredictability SPEC's latency claim\n"
"// rejects. CYCLES 10 lists both of these as tuning constants needing\n"
"// measurement; they are the document's defaults and are not measured here.\n"
"#define CYC_THETA_BUFFER 4096\n"
"#define CYC_K_ROOTS      256\n"
"\n"
"static void** cyc_candidates;\n"
"static int cyc_cand_count, cyc_cand_cap;\n"
"\n"
"// The traversal's child window. Recursion uses a slice of this rather than a\n"
"// local array, so a wide object does not put its whole fan-out on the C stack.\n"
"static void** cyc_walk;\n"
"static int cyc_walk_len, cyc_walk_cap;\n"
"\n"
"static long long cyc_allocated, cyc_collected, cyc_collections;\n"
"\n"
"static void cyc_walk_push(void* p) {\n"
"    if (cyc_walk_len == cyc_walk_cap) {\n"
"        int grow = cyc_walk_cap ? cyc_walk_cap * 2 : 64;\n"
"        cyc_walk = (void**)realloc(cyc_walk, (size_t)grow * sizeof(void*));\n"
"        cyc_walk_cap = grow;\n"
"    }\n"
"    cyc_walk[cyc_walk_len++] = p;\n"
"}\n"
"\n"
"static void cyc_buffer(void* p) {\n"
"    if (cyc_cand_count == cyc_cand_cap) {\n"
"        int grow = cyc_cand_cap ? cyc_cand_cap * 2 : 256;\n"
"        cyc_candidates = (void**)realloc(cyc_candidates, (size_t)grow * sizeof(void*));\n"
"        cyc_cand_cap = grow;\n"
"    }\n"
"    cyc_candidates[cyc_cand_count++] = p;\n"
"}\n"
"\n"
"static void cyc_free_object(void* p) {\n"
"    CycHeader* h = cyc_hdr(p);\n"
"    cyc_collected++;\n"
"    // The generated release reclaims the object's *non*-cyclic owned fields and\n"
"    // the storage. Struct-field ownership declines a cyclic field precisely so\n"
"    // that it is the collector, not a recursive release, that follows it.\n"
"    if (h->release) {\n"
"        h->release(p);\n"
"    } else {\n"
"        rt_free((unsigned char*)p - CYC_HDR);\n"
"    }\n"
"}\n"
"\n"
"static void cyc_mark_grey(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    if (h->colour == CYC_GREY) return;\n"
"    h->colour = CYC_GREY;\n"
"    if (!h->children) return;\n"
"\n"
"    int base = cyc_walk_len;\n"
"    h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"    for (int i = base; i < end; i++) {\n"
"        void* y = cyc_walk[i];\n"
"        if (!y) continue;\n"
"        // Trial deletion of an internal reference. What survives with a non-zero\n"
"        // count is what something outside the candidate subgraph still holds.\n"
"        CycHeader* yh = cyc_hdr(y);\n"
"        if (yh->rc > 0) yh->rc--;\n"
"        cyc_mark_grey(y);\n"
"    }\n"
"    cyc_walk_len = base;\n"
"}\n"
"\n"
"static void cyc_scan_black(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    h->colour = CYC_BLACK;\n"
"    if (!h->children) return;\n"
"\n"
"    int base = cyc_walk_len;\n"
"    h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"    for (int i = base; i < end; i++) {\n"
"        void* y = cyc_walk[i];\n"
"        if (!y) continue;\n"
"        cyc_hdr(y)->rc++;\n"
"        if (cyc_hdr(y)->colour != CYC_BLACK) cyc_scan_black(y);\n"
"    }\n"
"    cyc_walk_len = base;\n"
"}\n"
"\n"
"static void cyc_scan(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    if (h->colour != CYC_GREY) return;\n"
"    if (h->rc > 0) {\n"
"        cyc_scan_black(x);         // reachable from outside; the cycle is live\n"
"        return;\n"
"    }\n"
"    h->colour = CYC_WHITE;\n"
"    if (!h->children) return;\n"
"\n"
"    int base = cyc_walk_len;\n"
"    h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"    for (int i = base; i < end; i++) {\n"
"        if (cyc_walk[i]) cyc_scan(cyc_walk[i]);\n"
"    }\n"
"    cyc_walk_len = base;\n"
"}\n"
"\n"
"static void cyc_collect_white(void* x) {\n"
"    CycHeader* h = cyc_hdr(x);\n"
"    if (h->colour != CYC_WHITE || h->buffered) return;\n"
"    h->colour = CYC_BLACK;\n"
"\n"
"    // Children are gathered *before* the object is freed: cyc_free_object hands\n"
"    // the storage back, and reading the field afterwards is a use-after-free.\n"
"    int base = cyc_walk_len;\n"
"    if (h->children) h->children(x, cyc_walk_push);\n"
"    int end = cyc_walk_len;\n"
"\n"
"    int n = end - base;\n"
"    void** kids = NULL;\n"
"    if (n > 0) {\n"
"        kids = (void**)malloc((size_t)n * sizeof(void*));\n"
"        for (int i = 0; i < n; i++) kids[i] = cyc_walk[base + i];\n"
"    }\n"
"    cyc_walk_len = base;\n"
"\n"
"    cyc_free_object(x);\n"
"\n"
"    for (int i = 0; i < n; i++) {\n"
"        if (kids[i]) cyc_collect_white(kids[i]);\n"
"    }\n"
"    free(kids);\n"
"}\n"
"\n"
"// CYCLES 6.2: at most K roots per collection, and the rest stay buffered.\n"
"// Bounding by roots rather than by traversal steps is what removes the need for\n"
"// an abort path in the common case -- the walk from K roots through cyclic edges\n"
"// only is bounded by the cyclic skeleton reachable from them.\n"
"static void cyc_collect(int all) {\n"
"    int take = all ? cyc_cand_count : (cyc_cand_count < CYC_K_ROOTS ? cyc_cand_count : CYC_K_ROOTS);\n"
"    if (take <= 0) return;\n"
"    cyc_collections++;\n"
"\n"
"    void** roots = (void**)malloc((size_t)take * sizeof(void*));\n"
"    for (int i = 0; i < take; i++) roots[i] = cyc_candidates[i];\n"
"    for (int i = take; i < cyc_cand_count; i++) cyc_candidates[i - take] = cyc_candidates[i];\n"
"    cyc_cand_count -= take;\n"
"\n"
"    // Unbuffered before the walk, so CollectWhite is allowed to reclaim a root:\n"
"    // its own `buffered` flag is what would otherwise stop it.\n"
"    for (int i = 0; i < take; i++) cyc_hdr(roots[i])->buffered = 0;\n"
"\n"
"    for (int i = 0; i < take; i++) cyc_mark_grey(roots[i]);\n"
"    for (int i = 0; i < take; i++) cyc_scan(roots[i]);\n"
"    for (int i = 0; i < take; i++) cyc_collect_white(roots[i]);\n"
"\n"
"    free(roots);\n"
"}\n"
"\n"
"// A final pass at exit, which is CYCLES 6.1's \"explicit request\". Without it a\n"
"// short program never reaches Theta_buffer and the collector never runs, so a\n"
"// fixture could not tell an implemented collector from an absent one.\n"
"static int cyc_exit_registered;\n"
"\n"
"static void cyc_final(void) {\n"
"    while (cyc_cand_count > 0) cyc_collect(1);\n"
"}\n"
"\n"
"void* cyc_alloc(size_t size) {\n"
"    if (!cyc_exit_registered) {\n"
"        cyc_exit_registered = 1;\n"
"        atexit(cyc_final);\n"
"    }\n"
"    unsigned char* base = (unsigned char*)rt_base_alloc(size + CYC_HDR);\n"
"    if (!base) return 0;\n"
"    void* payload = base + CYC_HDR;\n"
"    CycHeader* h = cyc_hdr(payload);\n"
"    h->rc = 0;\n"
"    h->colour = CYC_BLACK;\n"
"    h->buffered = 0;\n"
"    h->children = 0;\n"
"    h->release = 0;\n"
"    cyc_allocated++;\n"
"    return payload;\n"
"}\n"
"\n"
"void cyc_set_type(void* p, void (*children)(void*, CycVisitor), void (*release)(void*)) {\n"
"    if (!p) return;\n"
"    CycHeader* h = cyc_hdr(p);\n"
"    h->children = children;\n"
"    h->release = release;\n"
"}\n"
"\n"
"void cyc_retain(void* p) {\n"
"    if (p) cyc_hdr(p)->rc++;\n"
"}\n"
"\n"
"void cyc_release(void* p) {\n"
"    if (!p) return;\n"
"    CycHeader* h = cyc_hdr(p);\n"
"    if (h->rc == 0) return;         // never retained: nothing holds it, nothing frees it\n"
"    if (--h->rc == 0) {\n"
"        cyc_free_object(p);\n"
"        return;\n"
"    }\n"
"    // CYCLES 3.2. A count that dropped without reaching zero is the only way a\n"
"    // cycle can become garbage, so this is the one place a candidate is born.\n"
"    if (!h->buffered) {\n"
"        h->colour = CYC_PURPLE;\n"
"        h->buffered = 1;\n"
"        cyc_buffer(p);\n"
"        if (cyc_cand_count >= CYC_THETA_BUFFER) cyc_collect(0);\n"
"    }\n"
"}\n"
"\n"
"// CYCLES 6.1's third trigger, \"or on explicit request\". Exposed because the\n"
"// other two -- buffer occupancy and allocation failure -- are both unreachable\n"
"// in a fixture small enough to reason about, and a collector that only ever runs\n"
"// at exit cannot be shown to restore counts on a *live* cycle.\n"
"void cyc_collect_now(void) { cyc_collect(1); }\n"
"\n"
"long long cyc_objects(void)     { return cyc_allocated; }\n"
"long long cyc_reclaimed(void)   { return cyc_collected; }\n"
"long long cyc_collections_run(void) { return cyc_collections; }\n"
"\n"
"// AIF item 3. `elem_own` is what the container was told about its elements at\n"
"// construction, and being told is the only way it can know: the elements are\n"
"// plain pointers, and reading a header in front of one to find out would be\n"
"// reading memory this program may not have allocated.\n"
"//\n"
"// Set once, by codegen, from aif_elem_owner_at_node -- which answers NONE unless\n"
"// every element site agrees, so a list that reaches here with a mode is a list\n"
"// whose elements are uniformly reclaimable.\n"
"#define XEFY_ELEM_NONE   0\n"
"#define XEFY_ELEM_OBJECT 1\n"
"#define XEFY_ELEM_LIST   2\n"
"#define XEFY_ELEM_RC     3   // Level 5: a decrement, and the last holder frees\n"
"#define XEFY_ELEM_TYPED  4   // struct-field ownership: the element type's own release\n"
"#define XEFY_ELEM_CYCLE  5   // T4b: a decrement, and a non-zero result is a candidate root\n"
"// REQUIREMENTS 15. The two above, one tier up: T4a is a count two threads can\n"
"// touch, so the same decrement has to be atomic. Two constants rather than one\n"
"// plus a flag, because SPEC 3 requires an implementation to \"distinguish the\n"
"// sub-classes\" and specifically forbids charging collector participation to a\n"
"// T4a value that is provably acyclic -- which is exactly the difference here.\n"
"#define XEFY_ELEM_RC_ATOMIC    6\n"
"#define XEFY_ELEM_CYCLE_ATOMIC 7\n"
"\n"
"typedef struct {\n"
"    void** data;\n"
"    int len;\n"
"    int cap;\n"
"    int elem_own;\n"
"    // Struct-field ownership. Under XEFY_ELEM_TYPED the release differs per\n"
"    // element *type*, and an int cannot name a type -- so the container is told\n"
"    // the function. Same rule as elem_own, one step less abstract: the container\n"
"    // is told what to do because it has no way to ask.\n"
"    void (*elem_release)(void*);\n"
"    // SPEC 5.2.1.1. The arena this list came from, 1-based, or 0 for the heap.\n"
"    //\n"
"    // A list is two allocations and one of them is *rewritten* long after the\n"
"    // site that made it: list_push doubles the element block and frees the old\n"
"    // one. That is the whole of the `is_list` clause the placement gate used to\n"
"    // reject an arena-served list with -- and the reason it can be lifted for a\n"
"    // bracketed extent is that the answer is recorded here rather than guessed\n"
"    // at from the arena depth that happens to be current. Without it, a list\n"
"    // whose handle is a bump pointer would hand its old element block to free().\n"
"    int arena;\n"
"} XefyList;\n"
"\n"
"static void* list_new_cap(int cap) {\n"
"    XefyList* l = (XefyList*)rt_alloc(sizeof(XefyList));\n"
"    l->len = 0;\n"
"    l->cap = cap;\n"
"    l->elem_own = XEFY_ELEM_NONE;\n"
"    l->elem_release = 0;\n"
"    l->arena = rt_arena_slot();\n"
"    l->data = (void**)rt_alloc(sizeof(void*) * (size_t)cap);\n"
"    return l;\n"
"}\n"
"\n"
"void* list_new(void) { return list_new_cap(4); }\n"
"\n"
"// Vec::with_capacity. A hint about size, not a bound: the list still grows by\n"
"// doubling past `n`, so a wrong hint costs memory or a realloc and never\n"
"// correctness. That is what keeps it outside SPEC 5's annotation budget -- it is\n"
"// a library call whose argument is a value, not a fact the analysis has to trust.\n"
"//\n"
"// Worth 0.926x on g2 (aif/evidence/xlang/prismio/g2.psm, 9 interleaved runs),\n"
"// where `cull` builds a fresh ~501-element list every frame for 20 000 frames and\n"
"// paid seven reallocations and 508 pointer copies each time. Measured before this\n"
"// was written, by raising the default capacity to 512 and timing the frame loop --\n"
"// which is the upper bound this API can reach, since it removes exactly the same\n"
"// reallocations.\n"
"//\n"
"// A non-positive hint is clamped rather than rejected: `list_new_with_capacity(0)`\n"
"// is the natural thing to write when the count is computed and comes out empty,\n"
"// and a zero-length data block would make the first push read cap 0 and double it\n"
"// to 0 forever.\n"
"void* list_new_with_capacity(int n) {\n"
"    return list_new_cap(n > 0 ? n : 4);\n"
"}\n"
"\n"
"void list_set_elem_owner(void* lp, int mode) {\n"
"    if (lp) ((XefyList*)lp)->elem_own = mode;\n"
"}\n"
"\n"
"void list_set_elem_releaser(void* lp, void (*fn)(void*)) {\n"
"    if (lp) ((XefyList*)lp)->elem_release = fn;\n"
"}\n"
"\n"
"// REQUIREMENTS 4. The checked unwrap behind `expect(x)`.\n"
"//\n"
"// A function rather than a branch in codegen, and returning its argument rather\n"
"// than being void, so the whole thing is one ordinary call expression -- no new\n"
"// blocks, no new backend surface, and the failure is loud instead of a null\n"
"// dereference somewhere downstream.\n"
"void* prismio_expect(void* p) {\n"
"    if (!p) {\n"
"        fprintf(stderr, \"runtime error: expect() called on a `none` value\\n\");\n"
"        exit(1);\n"
"    }\n"
"    return p;\n"
"}\n"
"\n"
"// The growth half of list_push, outlined so the other half can be inlined.\n"
"//\n"
"// M1.1 makes the hot container ops available to the inliner as\n"
"// `available_externally` bodies. `list_push` was the one that never took: the\n"
"// inliner priced it at **cost=675 against a threshold of 225** and declined at\n"
"// every site, because the realloc-and-copy below is 159 of its 227 IR lines and\n"
"// runs once per doubling rather than once per push. Measured: with it outlined,\n"
"// `list_push` drops to 69 IR lines, every `bl _list_push` in the corpus\n"
"// disappears, and g5 -- fifteen push sites -- runs **1.87x** faster than with\n"
"// the seven-op curated set.\n"
"//\n"
"// It takes `void*` rather than `XefyList*` so the exported surface stays the\n"
"// same shape as every other op here and the struct stays private to this file.\n"
"//\n"
"// **It has to be exported.** A curated body may only reference symbols the\n"
"// runtime object actually defines; `static` here would put an undefined\n"
"// `_list_push_grow` in every program that inlined the fast path.\n"
"// run_curated_closure_test is what enforces that, and it is why the three\n"
"// `static`s this function still touches -- rt_arena_hint, arena_depth,\n"
"// arena_alloc_slot, all reached through rt_alloc -- stay on this side of the\n"
"// split and out of the inlined half.\n"
"void list_push_grow(void* lp) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    int nc = l->cap * 2;\n"
"    // Back into the arena that owns this list, not into whatever the hint\n"
"    // says right now: the push is usually outside the bracket that created\n"
"    // the list, so rt_alloc here would take the heap and the block below\n"
"    // would be an arena pointer handed to free().\n"
"    void** nd = l->arena ? (void**)arena_alloc_at(l->arena, sizeof(void*) * (size_t)nc)\n"
"                         : (void**)rt_alloc(sizeof(void*) * (size_t)nc);\n"
"    for (int i = 0; i < l->len; i++) nd[i] = l->data[i];\n"
"    if (!l->arena) rt_free(l->data);\n"
"    l->data = nd;\n"
"    l->cap = nc;\n"
"}\n"
"\n"
"void list_push(void* lp, void* value) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    // AIF Level 5. The retain and the release are the same container's, driven by\n"
"    // the same stamped mode, so they cannot disagree about whether an element is\n"
"    // counted -- which is the failure a per-element answer would invite.\n"
"    if (l->elem_own == XEFY_ELEM_RC) rc_retain(value);\n"
"    if (l->elem_own == XEFY_ELEM_CYCLE) cyc_retain(value);\n"
"    if (l->elem_own == XEFY_ELEM_RC_ATOMIC) rc_retain_atomic(value);\n"
"    if (l->elem_own == XEFY_ELEM_CYCLE_ATOMIC) { rc_retain_atomic(value); cyc_retain(value); }\n"
"    if (l->len >= l->cap) list_push_grow(lp);\n"
"    l->data[l->len] = value;\n"
"    l->len = l->len + 1;\n"
"}\n"
"\n"
"// AIF Level 4. A list is two allocations -- the handle and the element block --\n"
"// so the deallocator seam, which takes one pointer and frees it, cannot reclaim\n"
"// it: `free(list)` leaks the block. Codegen calls this instead for a droppable\n"
"// List binding, which is why the drop list carries a kind and not just a slot.\n"
"//\n"
"// AIF item 3: the elements go too, when the container was told it owns them.\n"
"// That reverses Level 4's rule, and the reason the old one was right then is the\n"
"// reason it is wrong now. It read `list_push` as `retain_in(0)` -- the element's\n"
"// escape becomes the list's -- and concluded that whoever owns the element owns\n"
"// it at its own binding. Nobody does: an element's escape is the container's, so\n"
"// aif_frees_at_scope_node declines the binding, and until something released\n"
"// here every element of every list leaked. One owner, and it is this one.\n"
"//\n"
"// Reverse order, as everywhere else a scope unwinds: an element may hold a\n"
"// reference to one pushed before it, never after.\n"
"void list_release(void* lp) {\n"
"    if (!lp) return;\n"
"    XefyList* l = (XefyList*)lp;\n"
"    // SPEC 5.2.1.1. An arena reclaims in bulk when its region exits, so there is\n"
"    // nothing here to do and every free below would be a pointer into the middle\n"
"    // of a chunk. Codegen should not emit this call at all for such a list --\n"
"    // aif_frees_at_scope_node and aif_owns_call_result_at_node both decline once\n"
"    // the site is arena-served -- so this is the second line of defence, not the\n"
"    // mechanism. It is here because the failure it guards is heap corruption and\n"
"    // the cost of the guard is one predictable branch.\n"
"    if (l->arena) return;\n"
"    if (l->elem_own != XEFY_ELEM_NONE) {\n"
"        for (int i = l->len - 1; i >= 0; i--) {\n"
"            void* e = l->data[i];\n"
"            if (!e) continue;\n"
"            if (l->elem_own == XEFY_ELEM_LIST)    list_release(e);\n"
"            else if (l->elem_own == XEFY_ELEM_RC) rc_release(e);\n"
"            else if (l->elem_own == XEFY_ELEM_CYCLE) cyc_release(e);\n"
"            else if (l->elem_own == XEFY_ELEM_RC_ATOMIC) rc_release_atomic(e);\n"
"            // SPEC 3's \"a value meeting both conditions pays both\", and the\n"
"            // order is forced: cyc_release is what buffers a candidate root, so\n"
"            // it has to see the count *after* this thread's decrement.\n"
"            else if (l->elem_own == XEFY_ELEM_CYCLE_ATOMIC) { rc_release_atomic(e); cyc_release(e); }\n"
"            else if (l->elem_own == XEFY_ELEM_TYPED) {\n"
"                // Struct-field ownership. The element owns fields of its own, so\n"
"                // rt_free(e) here would reclaim the object and leak everything\n"
"                // hanging off it -- which is exactly what g3_scene_graph did with\n"
"                // 1365 Nodes and three owned fields each.\n"
"                if (l->elem_release) l->elem_release(e);\n"
"            }\n"
"            else                                  rt_free(e);\n"
"        }\n"
"    }\n"
"    rt_free(l->data);\n"
"    rt_free(l);\n"
"}\n"
"\n"
"void* list_get(void* lp, int index) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    if (index < 0 || index >= l->len) return 0;\n"
"    return l->data[index];\n"
"}\n"
"\n"
"// The overwritten element is released only under RC, where the container's own\n"
"// count says whether anything else still holds it. Under OBJECT it leaks: the\n"
"// container owns it, but so might the binding the value came from, and a free\n"
"// here would be the double free the whole ownership rule exists to prevent.\n"
"void list_set(void* lp, int index, void* value) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    if (index < 0 || index >= l->len) return;\n"
"    if (l->elem_own == XEFY_ELEM_RC) {\n"
"        rc_retain(value);\n"
"        rc_release(l->data[index]);\n"
"    } else if (l->elem_own == XEFY_ELEM_RC_ATOMIC\n"
"               || l->elem_own == XEFY_ELEM_CYCLE_ATOMIC) {\n"
"        // Retain before release, as above: if the incoming value is the one\n"
"        // already in the slot, releasing first can take the count to zero and\n"
"        // free what is about to be stored.\n"
"        rc_retain_atomic(value);\n"
"        rc_release_atomic(l->data[index]);\n"
"    }\n"
"    l->data[index] = value;\n"
"}\n"
"\n"
"int list_len(void* lp) {\n"
"    XefyList* l = (XefyList*)lp;\n"
"    return l->len;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// LAYOUT 2 -- the measured access profile\n"
"//\n"
"// These counters exist only in a workload driver: an instrumented build the\n"
"// compiler produces, runs and throws away (LAYOUT 3.2). A shipped program never\n"
"// calls any of them, which is why they are compiled unconditionally rather than\n"
"// behind a -D like PRISMIO_AIF_VERIFY. That define was needed because verify\n"
"// changes allocation *pairing* and both ends have to swap together; profiling\n"
"// changes nothing at all, it only counts, so a second runtime compile mode would\n"
"// buy nothing and would be one more thing that can be half-applied.\n"
"//\n"
"// **W4 is what this arrangement is for.** \"Two builds with different profiles\n"
"// SHALL produce behaviourally identical programs\" is not enforced here by\n"
"// checking anything -- it holds because the profile reaches codegen only through\n"
"// the layout search, and the shipped binary contains no call to any function\n"
"// below. The instrumented binary is a different artifact with a different main.\n"
"//\n"
"// The counters are deliberately unsynchronised. A workload runs single-threaded\n"
"// by construction (the driver is generated, and the corpus is single-threaded);\n"
"// if that stops being true this is the line that breaks, and it should become a\n"
"// per-task table merged at the end rather than a lock, so the measurement does\n"
"// not serialise the thing it is measuring.\n"
"// ============================================================================\n"
"\n"
"#define RT_PROF_SLOTS 8192\n"
"\n"
"typedef struct {\n"
"    const char* type;\n"
"    const char* field;\n"
"    long long   reads;\n"
"    long long   writes;\n"
"    long long   lo;\n"
"    long long   hi;\n"
"    int         has_range;\n"
"    int         used;\n"
"} RtProfField;\n"
"\n"
"typedef struct {\n"
"    const char* type;\n"
"    long long   allocs;\n"
"    long long   live;\n"
"    long long   peak_live;\n"
"    int         used;\n"
"} RtProfType;\n"
"\n"
"static RtProfField g_prof_fields[RT_PROF_SLOTS];\n"
"static RtProfType  g_prof_types[RT_PROF_SLOTS];\n"
"\n"
"// `setup` runs with this at 0 and `measure` with it at 1, which is the whole of\n"
"// LAYOUT 3.1's \"setup is excluded\". It is a counter rather than a flag so a\n"
"// nested measure region -- which the grammar does not have today -- could not\n"
"// switch it off early.\n"
"static int g_prof_depth = 0;\n"
"\n"
"static unsigned rt_prof_hash(const char* a, const char* b) {\n"
"    unsigned h = 2166136261u;\n"
"    for (const char* p = a; p && *p; p++) { h ^= (unsigned char)*p; h *= 16777619u; }\n"
"    h ^= '.'; h *= 16777619u;\n"
"    for (const char* p = b; p && *p; p++) { h ^= (unsigned char)*p; h *= 16777619u; }\n"
"    return h;\n"
"}\n"
"\n"
"// Linear probing, and a full table drops counts rather than growing. Dropping is\n"
"// the right failure here: a profile is an estimate consumed by a cost model, and\n"
"// a rehash in the middle of a measured region would cost more than the sample is\n"
"// worth. RT_PROF_SLOTS is 8192 against a corpus whose largest program has 34\n"
"// (type, field) pairs, so the table is three orders of magnitude oversized; if it\n"
"// ever fills, the dropped counts make the profile wrong in the *conservative*\n"
"// direction -- a field that looks colder than it is stays where the source put it.\n"
"static RtProfField* rt_prof_slot(const char* type, const char* field) {\n"
"    unsigned h = rt_prof_hash(type, field) & (RT_PROF_SLOTS - 1);\n"
"    for (int probe = 0; probe < RT_PROF_SLOTS; probe++) {\n"
"        RtProfField* s = &g_prof_fields[(h + probe) & (RT_PROF_SLOTS - 1)];\n"
"        if (!s->used) {\n"
"            s->used = 1;\n"
"            s->type = type;\n"
"            s->field = field;\n"
"            return s;\n"
"        }\n"
"        if (strcmp(s->type, type) == 0 && strcmp(s->field, field) == 0) return s;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"static RtProfType* rt_prof_type_slot(const char* type) {\n"
"    unsigned h = rt_prof_hash(type, \"\") & (RT_PROF_SLOTS - 1);\n"
"    for (int probe = 0; probe < RT_PROF_SLOTS; probe++) {\n"
"        RtProfType* s = &g_prof_types[(h + probe) & (RT_PROF_SLOTS - 1)];\n"
"        if (!s->used) {\n"
"            s->used = 1;\n"
"            s->type = type;\n"
"            return s;\n"
"        }\n"
"        if (strcmp(s->type, type) == 0) return s;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"void rt_profile_begin(void) { g_prof_depth++; }\n"
"void rt_profile_end(void)   { if (g_prof_depth > 0) g_prof_depth--; }\n"
"\n"
"void rt_profile_field(const char* type, const char* field, int is_write) {\n"
"    if (!g_prof_depth) return;\n"
"    RtProfField* s = rt_prof_slot(type, field);\n"
"    if (!s) return;\n"
"    if (is_write) s->writes++; else s->reads++;\n"
"}\n"
"\n"
"// LAYOUT 2.1 marks `range` **dynamic only**, and this is why: it is the observed\n"
"// value range, which no amount of reading the source supplies. It is also the\n"
"// only input bit-packing has -- without a workload there is nothing to pack\n"
"// against, which is why the packing dimension could not be searched before now.\n"
"//\n"
"// Recorded on writes only. A read observes a value some write already put there,\n"
"// so counting reads would weight the range by how often a field is looked at\n"
"// rather than by what it can hold.\n"
"void rt_profile_range(const char* type, const char* field, long long value) {\n"
"    if (!g_prof_depth) return;\n"
"    RtProfField* s = rt_prof_slot(type, field);\n"
"    if (!s) return;\n"
"    if (!s->has_range) {\n"
"        s->has_range = 1;\n"
"        s->lo = value;\n"
"        s->hi = value;\n"
"        return;\n"
"    }\n"
"    if (value < s->lo) s->lo = value;\n"
"    if (value > s->hi) s->hi = value;\n"
"}\n"
"\n"
"void rt_profile_alloc(const char* type) {\n"
"    if (!g_prof_depth) return;\n"
"    RtProfType* s = rt_prof_type_slot(type);\n"
"    if (!s) return;\n"
"    s->allocs++;\n"
"    s->live++;\n"
"    if (s->live > s->peak_live) s->peak_live = s->live;\n"
"}\n"
"\n"
"// `live` is decremented wherever the object is released. It is best-effort by\n"
"// construction: a value reclaimed with its arena is never individually freed, so\n"
"// peak_live reads as the high-water of *allocations* for arena-served types\n"
"// rather than of live instances. LAYOUT 2.1 wants peak live instances; this\n"
"// over-reports it, which biases mu_for toward a larger footprint and therefore\n"
"// toward the layout that touches fewer bytes. Conservative in the direction that\n"
"// matters, and recorded here rather than presented as exact.\n"
"void rt_profile_release(const char* type) {\n"
"    if (!g_prof_depth) return;\n"
"    RtProfType* s = rt_prof_type_slot(type);\n"
"    if (!s) return;\n"
"    if (s->live > 0) s->live--;\n"
"}\n"
"\n"
"// LAYOUT 2.2's format, sorted, so two runs of the same workload produce\n"
"// byte-identical files and the profile can be diffed and checked in.\n"
"static int rt_prof_field_cmp(const void* a, const void* b) {\n"
"    const RtProfField* x = *(const RtProfField* const*)a;\n"
"    const RtProfField* y = *(const RtProfField* const*)b;\n"
"    int c = strcmp(x->type, y->type);\n"
"    return c ? c : strcmp(x->field, y->field);\n"
"}\n"
"\n"
"static int rt_prof_type_cmp(const void* a, const void* b) {\n"
"    const RtProfType* x = *(const RtProfType* const*)a;\n"
"    const RtProfType* y = *(const RtProfType* const*)b;\n"
"    return strcmp(x->type, y->type);\n"
"}\n"
"\n"
"int rt_profile_dump(const char* path, const char* workload, int runs) {\n"
"    FILE* f = fopen(path, \"w\");\n"
"    if (!f) return 1;\n"
"\n"
"    fprintf(f, \"aif-profile 1\\n\");\n"
"    fprintf(f, \"source      workload:%s\\n\", workload ? workload : \"?\");\n"
"    fprintf(f, \"runs        %d\\n\", runs);\n"
"    fprintf(f, \"#\\n# type              allocs      live\\n\");\n"
"\n"
"    RtProfType* types[RT_PROF_SLOTS];\n"
"    int ntypes = 0;\n"
"    for (int i = 0; i < RT_PROF_SLOTS; i++) {\n"
"        if (g_prof_types[i].used) types[ntypes++] = &g_prof_types[i];\n"
"    }\n"
"    qsort(types, (size_t)ntypes, sizeof(types[0]), rt_prof_type_cmp);\n"
"    for (int i = 0; i < ntypes; i++) {\n"
"        fprintf(f, \"type  %-16s %10lld %9lld\\n\",\n"
"                types[i]->type, types[i]->allocs, types[i]->peak_live);\n"
"    }\n"
"\n"
"    fprintf(f, \"#\\n# type.field         reads       writes    range\\n\");\n"
"    RtProfField* fields[RT_PROF_SLOTS];\n"
"    int nfields = 0;\n"
"    for (int i = 0; i < RT_PROF_SLOTS; i++) {\n"
"        if (g_prof_fields[i].used) fields[nfields++] = &g_prof_fields[i];\n"
"    }\n"
"    qsort(fields, (size_t)nfields, sizeof(fields[0]), rt_prof_field_cmp);\n"
"    for (int i = 0; i < nfields; i++) {\n"
"        RtProfField* s = fields[i];\n"
"        if (s->has_range) {\n"
"            fprintf(f, \"field %s.%-14s %10lld %10lld %lld..%lld\\n\",\n"
"                    s->type, s->field, s->reads, s->writes, s->lo, s->hi);\n"
"        } else {\n"
"            fprintf(f, \"field %s.%-14s %10lld %10lld -\\n\",\n"
"                    s->type, s->field, s->reads, s->writes);\n"
"        }\n"
"    }\n"
"\n"
"    fclose(f);\n"
"    return 0;\n"
"}\n"
"\n"
"// W3. Every extern the workload's module declares that the Prismio runtime does\n"
"// not itself define is replaced by a stub with this body, rather than linked\n"
"// against whatever libc happens to export. A workload that calls `system` or\n"
"// `fopen` is not reproducible, so it is not a workload -- but refusing to build\n"
"// it would fail the build, which W2 forbids. Warning and returning zero is the\n"
"// third option and the one the clause asks for.\n"
"//\n"
"// Warns once per symbol. A stubbed call inside the measured loop would otherwise\n"
"// print millions of lines and turn a diagnostic into the dominant cost of the\n"
"// run.\n"
"#define RT_STUB_WARNED_MAX 64\n"
"static const char* g_stub_warned[RT_STUB_WARNED_MAX];\n"
"static int g_stub_warned_n = 0;\n"
"\n"
"long long rt_workload_stub(const char* name) {\n"
"    for (int i = 0; i < g_stub_warned_n; i++) {\n"
"        if (strcmp(g_stub_warned[i], name) == 0) return 0;\n"
"    }\n"
"    if (g_stub_warned_n < RT_STUB_WARNED_MAX) {\n"
"        g_stub_warned[g_stub_warned_n++] = name;\n"
"    }\n"
"    fprintf(stderr,\n"
"            \"warning: workload called `%s`, which the build sandbox does not provide; \"\n"
"            \"it returned 0\\n\", name);\n"
"    return 0;\n"
"}\n"
;

static const char prismio_embedded_program_support_c[] =
"// Program support -- the runtime half of the former driver.c.\n"
"//\n"
"// Everything here is callable by a compiled Prismio program and belongs in\n"
"// runtime.lib / runtime.a. It must not depend on llc, clang, or anything else to\n"
"// do with *producing* a program; that all lives in build_driver.c (backend.lib).\n"
"\n"
"#include \"prismio_platform.h\"\n"
"#include \"prismio_runtime.h\"\n"
"\n"
"// Defined by generated code, not by this file: generate_module() in src/ir.psm\n"
"// emits them as module-level globals and generate_function() stores main's real\n"
"// argc/argv into them in the entry prologue. Reading them here is what makes\n"
"// cli_arg()/cli_arg_count() behave the same on Windows, Linux and macOS -- the\n"
"// previous version read the Windows-only CRT globals __argc/__argv and returned\n"
"// nothing at all anywhere else.\n"
"extern int prismio_argc;\n"
"extern char** prismio_argv;\n"
"\n"
"// ============================================\n"
"// File I/O\n"
"// ============================================\n"
"\n"
"int file_exists(const char* path) {\n"
"    FILE* file = fopen(path, \"r\");\n"
"    if (file) {\n"
"        fclose(file);\n"
"        return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// Returns an empty string on failure, never NULL. Prismio has no null String, so\n"
"// every caller checks the result with str_equals(content, \"\") -- and handing them a\n"
"// NULL turned \"file not found\" into strcmp(NULL, \"\") and an access violation. That\n"
"// made `prismio build missing.psm`, and any `import` naming a file that is not\n"
"// there, crash silently instead of reporting the error the code already had ready.\n"
"char* read_file(const char* path) {\n"
"    FILE* file = fopen(path, \"rb\");\n"
"    if (!file) {\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    fseek(file, 0, SEEK_END);\n"
"    long size = ftell(file);\n"
"    fseek(file, 0, SEEK_SET);\n"
"\n"
"    char* buffer = (char*)malloc(size + 1);\n"
"    if (!buffer) {\n"
"        fclose(file);\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    size_t read = fread(buffer, 1, size, file);\n"
"    buffer[read] = '\\0';\n"
"\n"
"    fclose(file);\n"
"    return buffer;\n"
"}\n"
"\n"
"int delete_file(const char* path) {\n"
"    if (!path || path[0] == '\\0') return 0;\n"
"    return remove(path) == 0 ? 0 : 1;\n"
"}\n"
"\n"
"// ============================================\n"
"// Paths\n"
"// ============================================\n"
"\n"
"char* get_directory(const char* path) {\n"
"    const char* last_slash = strrchr(path, '/');\n"
"    const char* last_backslash = strrchr(path, '\\\\');\n"
"\n"
"    const char* separator = last_slash > last_backslash ? last_slash : last_backslash;\n"
"\n"
"    if (!separator) {\n"
"        char* result = (char*)malloc(2);\n"
"        strcpy(result, \".\");\n"
"        return result;\n"
"    }\n"
"\n"
"    int len = separator - path;\n"
"    char* result = (char*)malloc(len + 1);\n"
"    strncpy(result, path, len);\n"
"    result[len] = '\\0';\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// Separators in the result are normalised to the host's, including any the\n"
"// caller had already embedded in `filename`. That matters for module paths: a\n"
"// dotted import (`import ir.expr`) becomes \"ir/expr.psm\" in the frontend, which\n"
"// knows nothing about the host, and the joined path is then what every\n"
"// diagnostic about that module prints. Both separators open a file on Windows,\n"
"// so this is about how the path reads, not whether it resolves.\n"
"char* join_path(const char* directory, const char* filename) {\n"
"    int len = (int)strlen(directory) + 1 + (int)strlen(filename) + 1;\n"
"    char* result = (char*)malloc(len);\n"
"    sprintf(result, \"%s%c%s\", directory, PRISMIO_PATH_SEP, filename);\n"
"\n"
"    for (char* c = result; *c; c++) {\n"
"        if (*c == '/' || *c == '\\\\') *c = PRISMIO_PATH_SEP;\n"
"    }\n"
"    return result;\n"
"}\n"
"\n"
"// The OS owns the working directory; exposing it as an allocated String keeps\n"
"// manifest discovery in native Prismio while limiting this runtime seam to the\n"
"// one capability the language cannot implement itself.\n"
"char* current_directory(void) {\n"
"#ifdef _WIN32\n"
"    char* path = _getcwd(NULL, 0);\n"
"#else\n"
"    char* path = getcwd(NULL, 0);\n"
"#endif\n"
"    if (path) return path;\n"
"\n"
"    char* fallback = (char*)malloc(2);\n"
"    strcpy(fallback, \".\");\n"
"    return fallback;\n"
"}\n"
"\n"
"// ============================================\n"
"// Listing a module directory\n"
"// ============================================\n"
"\n"
"static int compare_names(const void* a, const void* b) {\n"
"    return strcmp(*(const char* const*)a, *(const char* const*)b);\n"
"}\n"
"\n"
"// Records `filename` as a module name, minus its .psm suffix; ignores anything\n"
"// else. The suffix is re-checked here rather than trusted to the Win32 search\n"
"// pattern, which also matches 8.3 short names and would let through a file whose\n"
"// real extension is longer.\n"
"static void append_module_name(char*** names, int* count, int* capacity,\n"
"                               const char* filename) {\n"
"    size_t len = strlen(filename);\n"
"    if (len <= 4 || strcmp(filename + len - 4, \".psm\") != 0) return;\n"
"\n"
"    if (*count == *capacity) {\n"
"        *capacity = *capacity ? *capacity * 2 : 16;\n"
"        *names = (char**)realloc(*names, (size_t)*capacity * sizeof(char*));\n"
"        if (!*names) {\n"
"            fprintf(stderr, \"prismio: out of memory listing modules\\n\");\n"
"            exit(1);\n"
"        }\n"
"    }\n"
"\n"
"    char* stem = (char*)malloc(len - 3);\n"
"    memcpy(stem, filename, len - 4);\n"
"    stem[len - 4] = '\\0';\n"
"    (*names)[(*count)++] = stem;\n"
"}\n"
"\n"
"// The module names in `directory`, newline-separated, without the .psm suffix.\n"
"// Empty string when the directory does not exist or holds no modules -- the\n"
"// frontend reports that, because only it knows which `import` asked.\n"
"//\n"
"// **Sorted, and that is load-bearing.** This backs `import pkg.*`, so the order\n"
"// here becomes the order those modules are merged into the AST, which becomes\n"
"// the order their functions are emitted into the IR. Readdir order is a\n"
"// filesystem artefact that differs between machines and between a fresh checkout\n"
"// and a rebuilt one; taking it raw would mean two hosts building byte-different\n"
"// compilers from identical sources, breaking the fixpoint check and the seed.\n"
"char* list_modules(const char* directory) {\n"
"    char** names = NULL;\n"
"    int count = 0;\n"
"    int capacity = 0;\n"
"\n"
"#ifdef _WIN32\n"
"    char pattern[1024];\n"
"    snprintf(pattern, sizeof(pattern), \"%s%c*.psm\", directory, PRISMIO_PATH_SEP);\n"
"\n"
"    WIN32_FIND_DATAA entry;\n"
"    HANDLE search = FindFirstFileA(pattern, &entry);\n"
"    if (search != INVALID_HANDLE_VALUE) {\n"
"        do {\n"
"            if (entry.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) continue;\n"
"            append_module_name(&names, &count, &capacity, entry.cFileName);\n"
"        } while (FindNextFileA(search, &entry));\n"
"        FindClose(search);\n"
"    }\n"
"#else\n"
"    DIR* dir = opendir(directory);\n"
"    if (dir) {\n"
"        struct dirent* entry;\n"
"        while ((entry = readdir(dir)) != NULL) {\n"
"            append_module_name(&names, &count, &capacity, entry->d_name);\n"
"        }\n"
"        closedir(dir);\n"
"    }\n"
"#endif\n"
"\n"
"    if (count > 1) qsort(names, count, sizeof(char*), compare_names);\n"
"\n"
"    size_t total = 1;\n"
"    for (int i = 0; i < count; i++) total += strlen(names[i]) + 1;\n"
"\n"
"    char* result = (char*)malloc(total);\n"
"    result[0] = '\\0';\n"
"    for (int i = 0; i < count; i++) {\n"
"        if (i > 0) strcat(result, \"\\n\");\n"
"        strcat(result, names[i]);\n"
"        free(names[i]);\n"
"    }\n"
"    free(names);\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// Locating the running executable\n"
"// ============================================\n"
"\n"
"char* prismio_executable_directory(void) {\n"
"#ifdef _WIN32\n"
"    char exe_path[1024];\n"
"    DWORD len = GetModuleFileNameA(NULL, exe_path, sizeof(exe_path));\n"
"    if (len > 0 && len < sizeof(exe_path)) {\n"
"        return get_directory(exe_path);\n"
"    }\n"
"\n"
"    if (__argc > 0 && __argv[0] && __argv[0][0] != '\\0') {\n"
"        return get_directory(__argv[0]);\n"
"    }\n"
"#elif defined(__APPLE__)\n"
"    // macOS has no /proc, so the Linux branch below silently fails there.\n"
"    char raw_path[1024];\n"
"    uint32_t size = sizeof(raw_path);\n"
"    if (_NSGetExecutablePath(raw_path, &size) == 0) {\n"
"        char resolved_path[1024];\n"
"        if (realpath(raw_path, resolved_path) != NULL) {\n"
"            return get_directory(resolved_path);\n"
"        }\n"
"        return get_directory(raw_path);\n"
"    }\n"
"#else\n"
"    char exe_path[1024];\n"
"    ssize_t len = readlink(\"/proc/self/exe\", exe_path, sizeof(exe_path) - 1);\n"
"    if (len > 0) {\n"
"        exe_path[len] = '\\0';\n"
"        return get_directory(exe_path);\n"
"    }\n"
"#endif\n"
"    return NULL;\n"
"}\n"
"\n"
"char* executable_directory(void) {\n"
"    char* directory = prismio_executable_directory();\n"
"    if (directory) {\n"
"        return directory;\n"
"    }\n"
"\n"
"    char* fallback = (char*)malloc(2);\n"
"    strcpy(fallback, \".\");\n"
"    return fallback;\n"
"}\n"
"\n"
"// ============================================\n"
"// Commands\n"
"// ============================================\n"
"\n"
"char* command_quote_arg(const char* arg) {\n"
"    int len = strlen(arg);\n"
"    char* result = (char*)malloc((len * 2) + 3);\n"
"    int out = 0;\n"
"    result[out++] = '\"';\n"
"    for (int i = 0; i < len; i++) {\n"
"        if (arg[i] == '\"') {\n"
"            result[out++] = '\\\\';\n"
"        }\n"
"        result[out++] = arg[i];\n"
"    }\n"
"    result[out++] = '\"';\n"
"    result[out] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"int execute_command(const char* command) {\n"
"#ifdef _WIN32\n"
"    int command_len = (int)strlen(command) + 16;\n"
"    char* wrapped = (char*)malloc(command_len);\n"
"    snprintf(wrapped, command_len, \"cmd /S /C \\\"%s\\\"\", command);\n"
"    int result = system(wrapped);\n"
"    free(wrapped);\n"
"    return result == 0 ? 0 : 1;\n"
"#else\n"
"    return system(command) == 0 ? 0 : 1;\n"
"#endif\n"
"}\n"
"\n"
"// ============================================\n"
"// Command line\n"
"// ============================================\n"
"\n"
"int cli_arg_count(void) {\n"
"    return prismio_argc;\n"
"}\n"
"\n"
"char* cli_arg(int index) {\n"
"    if (index < 0 || index >= prismio_argc || prismio_argv == NULL) {\n"
"        return \"\";\n"
"    }\n"
"    return prismio_argv[index];\n"
"}\n"
"\n"
"// ============================================\n"
"// Tasks and channels\n"
"// ============================================\n"
"//\n"
"// REQUIREMENTS 15, and the shape is fixed by SPEC 11 item 10: *isolation*\n"
"// concurrency, no shared mutable heap, no atomic counts on the common path.\n"
"// Everything here exists to make that sentence enforceable rather than\n"
"// aspirational -- and to give AIF's `T` domain (INFERENCE 2.3) something to\n"
"// attach to, which it has never had.\n"
"//\n"
"// Two primitives, and the split between them is the whole design:\n"
"//\n"
"//   * A **task** takes ownership of its arguments. `spawn f(x)` moves `x` in;\n"
"//     the move checker makes the parent's binding dead, so no second owning\n"
"//     reference exists and INFERENCE's T-SPAWN-MOVE lands the value at\n"
"//     `Transferred` rather than `CrossThread`. Transferred is the tier\n"
"//     isolation exists to produce: the spawn is itself a synchronisation edge,\n"
"//     so a release/acquire pair there is sufficient and the *count stays\n"
"//     non-atomic*. That is the sentence SPEC 11 item 10 is protecting.\n"
"//   * A **channel** carries messages between tasks. The message is moved, not\n"
"//     shared -- send hands the pointer over and the sender must not keep it.\n"
"//     The channel is the one object both tasks hold at once, which is exactly\n"
"//     why it is a runtime object with its own lock rather than a Prismio heap\n"
"//     value: nothing the solver tiers is shared, so nothing the solver tiers\n"
"//     needs an atomic count.\n"
"//\n"
"// The arity ceiling is three, and it is a real ceiling rather than a variadic\n"
"// call through a mistyped pointer. Calling a one-argument function through a\n"
"// three-argument function pointer happens to work on every ABI anyone ships and\n"
"// is still undefined; the switch below costs four lines and is defined.\n"
"\n"
"#ifdef _WIN32\n"
"#define PRISMIO_THREAD_T           HANDLE\n"
"#define PRISMIO_MUTEX_T            CRITICAL_SECTION\n"
"#define PRISMIO_COND_T             CONDITION_VARIABLE\n"
"#define PRISMIO_MUTEX_INIT(m)      InitializeCriticalSection(m)\n"
"#define PRISMIO_MUTEX_DESTROY(m)   DeleteCriticalSection(m)\n"
"#define PRISMIO_MUTEX_LOCK(m)      EnterCriticalSection(m)\n"
"#define PRISMIO_MUTEX_UNLOCK(m)    LeaveCriticalSection(m)\n"
"#define PRISMIO_COND_INIT(c)       InitializeConditionVariable(c)\n"
"#define PRISMIO_COND_DESTROY(c)    ((void)(c))\n"
"#define PRISMIO_COND_WAIT(c, m)    SleepConditionVariableCS(c, m, INFINITE)\n"
"#define PRISMIO_COND_SIGNAL(c)     WakeConditionVariable(c)\n"
"#define PRISMIO_COND_BROADCAST(c)  WakeAllConditionVariable(c)\n"
"#else\n"
"#include <pthread.h>\n"
"#define PRISMIO_THREAD_T           pthread_t\n"
"#define PRISMIO_MUTEX_T            pthread_mutex_t\n"
"#define PRISMIO_COND_T             pthread_cond_t\n"
"#define PRISMIO_MUTEX_INIT(m)      pthread_mutex_init(m, NULL)\n"
"#define PRISMIO_MUTEX_DESTROY(m)   pthread_mutex_destroy(m)\n"
"#define PRISMIO_MUTEX_LOCK(m)      pthread_mutex_lock(m)\n"
"#define PRISMIO_MUTEX_UNLOCK(m)    pthread_mutex_unlock(m)\n"
"#define PRISMIO_COND_INIT(c)       pthread_cond_init(c, NULL)\n"
"#define PRISMIO_COND_DESTROY(c)    pthread_cond_destroy(c)\n"
"#define PRISMIO_COND_WAIT(c, m)    pthread_cond_wait(c, m)\n"
"#define PRISMIO_COND_SIGNAL(c)     pthread_cond_signal(c)\n"
"#define PRISMIO_COND_BROADCAST(c)  pthread_cond_broadcast(c)\n"
"#endif\n"
"\n"
"// A task's result comes back through `join`, so the runtime has to call the\n"
"// spawned function through a pointer of its *real* type. Twelve typedefs --\n"
"// three return kinds by four arities -- rather than one signature and a cast.\n"
"//\n"
"// The cast would work on every ABI anyone ships and is still undefined, and\n"
"// with return values it stops being merely formal: an i32-returning function\n"
"// called through a pointer declared to return void* leaves the upper half of\n"
"// the register undefined on exactly the 64-bit targets this compiles for.\n"
"#define PRISMIO_RK_INT  0\n"
"#define PRISMIO_RK_PTR  1\n"
"#define PRISMIO_RK_VOID 2\n"
"\n"
"typedef int   (*PrismioFnI0)(void);\n"
"typedef int   (*PrismioFnI1)(void*);\n"
"typedef int   (*PrismioFnI2)(void*, void*);\n"
"typedef int   (*PrismioFnI3)(void*, void*, void*);\n"
"typedef void* (*PrismioFnP0)(void);\n"
"typedef void* (*PrismioFnP1)(void*);\n"
"typedef void* (*PrismioFnP2)(void*, void*);\n"
"typedef void* (*PrismioFnP3)(void*, void*, void*);\n"
"typedef void  (*PrismioFnV0)(void);\n"
"typedef void  (*PrismioFnV1)(void*);\n"
"typedef void  (*PrismioFnV2)(void*, void*);\n"
"typedef void  (*PrismioFnV3)(void*, void*, void*);\n"
"\n"
"typedef struct {\n"
"    PRISMIO_THREAD_T thread;\n"
"    void* fn;\n"
"    int rkind;\n"
"    int nargs;\n"
"    void* a[3];\n"
"    int result_i;\n"
"    void* result_p;\n"
"    int joined;\n"
"    int started;\n"
"} PrismioTask;\n"
"\n"
"static void prismio_task_invoke(PrismioTask* t) {\n"
"    void** a = t->a;\n"
"    if (t->rkind == PRISMIO_RK_PTR) {\n"
"        switch (t->nargs) {\n"
"            case 0:  t->result_p = ((PrismioFnP0)t->fn)(); return;\n"
"            case 1:  t->result_p = ((PrismioFnP1)t->fn)(a[0]); return;\n"
"            case 2:  t->result_p = ((PrismioFnP2)t->fn)(a[0], a[1]); return;\n"
"            default: t->result_p = ((PrismioFnP3)t->fn)(a[0], a[1], a[2]); return;\n"
"        }\n"
"    }\n"
"    if (t->rkind == PRISMIO_RK_VOID) {\n"
"        switch (t->nargs) {\n"
"            case 0:  ((PrismioFnV0)t->fn)(); return;\n"
"            case 1:  ((PrismioFnV1)t->fn)(a[0]); return;\n"
"            case 2:  ((PrismioFnV2)t->fn)(a[0], a[1]); return;\n"
"            default: ((PrismioFnV3)t->fn)(a[0], a[1], a[2]); return;\n"
"        }\n"
"    }\n"
"    switch (t->nargs) {\n"
"        case 0:  t->result_i = ((PrismioFnI0)t->fn)(); return;\n"
"        case 1:  t->result_i = ((PrismioFnI1)t->fn)(a[0]); return;\n"
"        case 2:  t->result_i = ((PrismioFnI2)t->fn)(a[0], a[1]); return;\n"
"        default: t->result_i = ((PrismioFnI3)t->fn)(a[0], a[1], a[2]); return;\n"
"    }\n"
"}\n"
"\n"
"#ifdef _WIN32\n"
"static DWORD WINAPI prismio_task_entry(LPVOID arg) {\n"
"    prismio_task_invoke((PrismioTask*)arg);\n"
"    return 0;\n"
"}\n"
"#else\n"
"static void* prismio_task_entry(void* arg) {\n"
"    prismio_task_invoke((PrismioTask*)arg);\n"
"    return NULL;\n"
"}\n"
"#endif\n"
"\n"
"// Emitted by generate_expression for a SPAWN_EXPR. Returns an opaque handle;\n"
"// the language types it `Task<R>`, where R is what `join` yields.\n"
"//\n"
"// A task that cannot be started runs **inline** rather than failing. SPEC 1's\n"
"// invariant is about inference, but the same principle applies with more force\n"
"// here: a program that silently does not run its work is worse than one that\n"
"// runs it on the calling thread. The result is identical either way, because\n"
"// isolation means the task shares nothing with its parent -- which is the one\n"
"// property that makes a serial fallback observationally equivalent.\n"
"void* prismio_task_spawn(void* fn, int rkind, int nargs, void* a0, void* a1, void* a2) {\n"
"    PrismioTask* t = (PrismioTask*)calloc(1, sizeof(PrismioTask));\n"
"    if (!t) return NULL;\n"
"    t->fn = fn;\n"
"    t->rkind = rkind;\n"
"    t->nargs = (nargs < 0) ? 0 : (nargs > 3 ? 3 : nargs);\n"
"    t->a[0] = a0;\n"
"    t->a[1] = a1;\n"
"    t->a[2] = a2;\n"
"\n"
"#ifdef _WIN32\n"
"    t->thread = CreateThread(NULL, 0, prismio_task_entry, t, 0, NULL);\n"
"    t->started = (t->thread != NULL);\n"
"#else\n"
"    t->started = (pthread_create(&t->thread, NULL, prismio_task_entry, t) == 0);\n"
"#endif\n"
"\n"
"    if (!t->started) {\n"
"        prismio_task_invoke(t);\n"
"    }\n"
"    return t;\n"
"}\n"
"\n"
"// The wait itself, shared by the three typed accessors below. Split out because\n"
"// joining twice must not wait on a dead thread: the language does not stop a\n"
"// program from doing it -- a handle is copyable -- so the runtime has to.\n"
"static PrismioTask* prismio_task_await(void* handle) {\n"
"    PrismioTask* t = (PrismioTask*)handle;\n"
"    if (!t) return NULL;\n"
"    if (!t->joined) {\n"
"        if (t->started) {\n"
"#ifdef _WIN32\n"
"            WaitForSingleObject(t->thread, INFINITE);\n"
"            CloseHandle(t->thread);\n"
"#else\n"
"            pthread_join(t->thread, NULL);\n"
"#endif\n"
"        }\n"
"        t->joined = 1;\n"
"    }\n"
"    return t;\n"
"}\n"
"\n"
"// Three accessors rather than one returning a word the caller reinterprets.\n"
"// Which one is emitted is decided by the callee's declared return type, which\n"
"// the compiler knows statically -- so the type the task produced and the type\n"
"// read back out are the same by construction rather than by convention.\n"
"int prismio_task_join(void* handle) {\n"
"    PrismioTask* t = prismio_task_await(handle);\n"
"    return t ? t->result_i : 0;\n"
"}\n"
"\n"
"void* prismio_task_join_p(void* handle) {\n"
"    PrismioTask* t = prismio_task_await(handle);\n"
"    return t ? t->result_p : NULL;\n"
"}\n"
"\n"
"void prismio_task_join_v(void* handle) {\n"
"    prismio_task_await(handle);\n"
"}\n"
"\n"
"// The join is the synchronisation edge, so the handle is dead the moment it\n"
"// returns and the caller has nothing left to free by hand.\n"
"void prismio_task_release(void* handle) {\n"
"    if (handle) free(handle);\n"
"}\n"
"\n"
"typedef struct {\n"
"    PRISMIO_MUTEX_T lock;\n"
"    PRISMIO_COND_T not_empty;\n"
"    PRISMIO_COND_T not_full;\n"
"    void** slots;\n"
"    int cap, head, len;\n"
"    int closed;\n"
"} PrismioChan;\n"
"\n"
"void* chan_new(int capacity) {\n"
"    if (capacity < 1) capacity = 1;\n"
"    PrismioChan* c = (PrismioChan*)calloc(1, sizeof(PrismioChan));\n"
"    if (!c) return NULL;\n"
"    c->slots = (void**)calloc((size_t)capacity, sizeof(void*));\n"
"    if (!c->slots) { free(c); return NULL; }\n"
"    c->cap = capacity;\n"
"    PRISMIO_MUTEX_INIT(&c->lock);\n"
"    PRISMIO_COND_INIT(&c->not_empty);\n"
"    PRISMIO_COND_INIT(&c->not_full);\n"
"    return c;\n"
"}\n"
"\n"
"// Blocks while the channel is full. Sending on a closed channel drops the\n"
"// message and reports 0; the alternative is aborting the program, and a closed\n"
"// channel is a race the receiver won rather than a defect in the sender.\n"
"int chan_send(void* handle, void* msg) {\n"
"    PrismioChan* c = (PrismioChan*)handle;\n"
"    if (!c) return 0;\n"
"    PRISMIO_MUTEX_LOCK(&c->lock);\n"
"    while (c->len == c->cap && !c->closed) {\n"
"        PRISMIO_COND_WAIT(&c->not_full, &c->lock);\n"
"    }\n"
"    if (c->closed) {\n"
"        PRISMIO_MUTEX_UNLOCK(&c->lock);\n"
"        return 0;\n"
"    }\n"
"    c->slots[(c->head + c->len) % c->cap] = msg;\n"
"    c->len++;\n"
"    PRISMIO_COND_SIGNAL(&c->not_empty);\n"
"    PRISMIO_MUTEX_UNLOCK(&c->lock);\n"
"    return 1;\n"
"}\n"
"\n"
"// Blocks until a message arrives. Returns NULL once the channel is closed and\n"
"// drained, which is how a receiving loop terminates without a sentinel value.\n"
"void* chan_recv(void* handle) {\n"
"    PrismioChan* c = (PrismioChan*)handle;\n"
"    if (!c) return NULL;\n"
"    PRISMIO_MUTEX_LOCK(&c->lock);\n"
"    while (c->len == 0 && !c->closed) {\n"
"        PRISMIO_COND_WAIT(&c->not_empty, &c->lock);\n"
"    }\n"
"    if (c->len == 0) {\n"
"        PRISMIO_MUTEX_UNLOCK(&c->lock);\n"
"        return NULL;\n"
"    }\n"
"    void* msg = c->slots[c->head];\n"
"    c->head = (c->head + 1) % c->cap;\n"
"    c->len--;\n"
"    PRISMIO_COND_SIGNAL(&c->not_full);\n"
"    PRISMIO_MUTEX_UNLOCK(&c->lock);\n"
"    return msg;\n"
"}\n"
"\n"
"// Wakes every blocked party. Both waits above re-test `closed`, so a broadcast\n"
"// is enough and no waiter can be left holding the old predicate.\n"
"void chan_close(void* handle) {\n"
"    PrismioChan* c = (PrismioChan*)handle;\n"
"    if (!c) return;\n"
"    PRISMIO_MUTEX_LOCK(&c->lock);\n"
"    c->closed = 1;\n"
"    PRISMIO_COND_BROADCAST(&c->not_empty);\n"
"    PRISMIO_COND_BROADCAST(&c->not_full);\n"
"    PRISMIO_MUTEX_UNLOCK(&c->lock);\n"
"}\n"
"\n"
"// SPEC 11 item 10, and this function exists *because* of its second sentence:\n"
"// \"creating a second owning reference SHALL be a syntactically identifiable\n"
"// event.\" A channel is the one object two tasks are supposed to hold at once,\n"
"// and every handle the language can name is affine -- so without an explicit\n"
"// duplication there is no way to get one into a task and keep one in the\n"
"// parent, and `spawn producer(c)` simply moves the channel away.\n"
"//\n"
"// So the duplication is spelled out loud. `chan_share` is the event, it is\n"
"// visible at the call site, and it is what AIF's aliasing module sees when it\n"
"// decides the endpoint is `Shared` rather than `Unique` -- which is what puts\n"
"// anything reachable from it at CrossThread, and therefore on an atomic count.\n"
"// The alternative, making channel handles quietly copyable, would have bought\n"
"// the same programs and lost the only place the analysis could have noticed.\n"
"//\n"
"// The pointer is returned as-is rather than reference-counted. The contract is\n"
"// the one the corpus already follows and the one the join edge makes checkable:\n"
"// the creator closes, joins every task it shared with, then frees. A count here\n"
"// would have to be atomic, which is the tax this whole design exists to avoid\n"
"// paying on anything but the shared object itself.\n"
"void* chan_share(void* handle) {\n"
"    return handle;\n"
"}\n"
"\n"
"int chan_len(void* handle) {\n"
"    PrismioChan* c = (PrismioChan*)handle;\n"
"    if (!c) return 0;\n"
"    PRISMIO_MUTEX_LOCK(&c->lock);\n"
"    int n = c->len;\n"
"    PRISMIO_MUTEX_UNLOCK(&c->lock);\n"
"    return n;\n"
"}\n"
"\n"
"// Freeing a channel someone is still blocked on is a program defect this cannot\n"
"// detect. Every caller in the corpus closes, joins, then frees -- the join is\n"
"// what makes the free safe, and it is the same edge that makes the counts\n"
"// non-atomic.\n"
"void chan_free(void* handle) {\n"
"    PrismioChan* c = (PrismioChan*)handle;\n"
"    if (!c) return;\n"
"    PRISMIO_MUTEX_DESTROY(&c->lock);\n"
"    PRISMIO_COND_DESTROY(&c->not_empty);\n"
"    PRISMIO_COND_DESTROY(&c->not_full);\n"
"    free(c->slots);\n"
"    free(c);\n"
"}\n"
;

static const char prismio_embedded_build_driver_c[] =
"// Build orchestration -- the compiler half of the former driver.c.\n"
"//\n"
"// Everything here exists to *produce* an executable: locating the toolchain\n"
"// sources, naming temporary files, and driving llc and clang. A compiled Prismio\n"
"// program never calls any of it, so this translation unit belongs in\n"
"// backend.lib / backend.a alongside llvm-api-backend.c, and never in runtime.lib.\n"
"//\n"
"// It does depend on the runtime half (prismio_runtime.h) for plain file and path\n"
"// helpers. That direction is deliberate and one-way: backend -> runtime.\n"
"\n"
"#include \"prismio_platform.h\"\n"
"#include \"prismio_runtime.h\"\n"
"\n"
"#ifndef PRISMIO_EMBEDDED_SOURCES_HEADER\n"
"#define PRISMIO_EMBEDDED_SOURCES_HEADER \"embedded_sources.h\"\n"
"#endif\n"
"#include PRISMIO_EMBEDDED_SOURCES_HEADER\n"
"\n"
"// ============================================\n"
"// The toolchain source set\n"
"// ============================================\n"
"\n"
"// The C sources a compiled program is linked against, plus the headers they need\n"
"// available beside them when they are unpacked from the embedded copies. Keeping\n"
"// this as one table means the filesystem search, the embedded unpacking and the\n"
"// compile/link steps can never disagree about which files make up the toolchain.\n"
"typedef struct {\n"
"    const char* name;\n"
"    int compiled;  // 1 = compile to an object and link it; 0 = header, unpack only\n"
"    const char* role;\n"
"    // 1 = part of runtime.lib, needed by every compiled program.\n"
"    // 0 = part of backend.lib, needed only when building the compiler itself.\n"
"    int runtime;\n"
"} PrismioToolchainFile;\n"
"\n"
"// From llvm-api-backend.c: the target the frontend selected. Read rather than\n"
"// copied, so this file and the backend cannot disagree about what is being\n"
"// built. See the \"Targets\" section there.\n"
"const char* ir_target_triple(void);\n"
"int ir_target_is_explicit(void);\n"
"\n"
"// M1.1's two LLVM operations. They live in llvm-api-backend.c because that is\n"
"// where the C API dependency lives; this file drives clang and does not link\n"
"// LLVM itself.\n"
"int ir_curate_module(const char* runtime_ir, const char* const* names, int count,\n"
"                     const char* out_path);\n"
"int ir_link_modules(const char* dest_ir, const char* src_ir, const char* out_path);\n"
"\n"
"static const PrismioToolchainFile prismio_toolchain_files[] = {\n"
"    { \"prismio_platform.h\", 0, NULL,              1 },\n"
"    { \"prismio_runtime.h\",  0, NULL,              1 },\n"
"    { \"lang_runtime.c\",     1, \"lang_runtime\",    1 },\n"
"    { \"program_support.c\",  1, \"program_support\", 1 },\n"
"    { \"build_driver.c\",     1, \"build_driver\",    0 },\n"
"    { \"ir_symbols.c\",       1, \"ir_symbols\",      0 },\n"
"    { \"aif_support.c\",      1, \"aif_support\",     0 },\n"
"    { \"diagnostics.c\",      1, \"diagnostics\",     0 },\n"
"    { \"llvm-api-backend.c\", 1, \"backend\",         0 },\n"
"};\n"
"\n"
"#define PRISMIO_TOOLCHAIN_FILE_COUNT \\\n"
"    ((int)(sizeof(prismio_toolchain_files) / sizeof(prismio_toolchain_files[0])))\n"
"\n"
"#ifdef PRISMIO_EMBEDDED_SOURCE_AVAILABLE\n"
"// Same order as prismio_toolchain_files. Generated by\n"
"// runtime/generate_embedded_sources.py, and checked against this table by\n"
"// tools/check_source_lists.py.\n"
"static const char* prismio_embedded_text(int index) {\n"
"    switch (index) {\n"
"        case 0: return prismio_embedded_prismio_platform_h;\n"
"        case 1: return prismio_embedded_prismio_runtime_h;\n"
"        case 2: return prismio_embedded_lang_runtime_c;\n"
"        case 3: return prismio_embedded_program_support_c;\n"
"        case 4: return prismio_embedded_build_driver_c;\n"
"        case 5: return prismio_embedded_ir_symbols_c;\n"
"        case 6: return prismio_embedded_aif_support_c;\n"
"        case 7: return prismio_embedded_diagnostics_c;\n"
"        case 8: return prismio_embedded_llvm_api_backend_c;\n"
"        default: return NULL;\n"
"    }\n"
"}\n"
"#endif\n"
"\n"
"// ============================================\n"
"// Path helpers (compiler-side only)\n"
"// ============================================\n"
"\n"
"static const char* path_file_name(const char* path) {\n"
"    const char* last_slash = strrchr(path, '/');\n"
"    const char* last_backslash = strrchr(path, '\\\\');\n"
"    const char* separator = last_slash > last_backslash ? last_slash : last_backslash;\n"
"    return separator ? separator + 1 : path;\n"
"}\n"
"\n"
"static char* path_without_extension(const char* path) {\n"
"    const char* filename = path_file_name(path);\n"
"    const char* dot = strrchr(filename, '.');\n"
"    int len = dot ? (int)(dot - path) : (int)strlen(path);\n"
"    char* result = (char*)malloc(len + 1);\n"
"    strncpy(result, path, len);\n"
"    result[len] = '\\0';\n"
"    return result;\n"
"}\n"
"\n"
"char* compiler_default_exe_path(const char* source_path) {\n"
"    char* stem = path_without_extension(source_path);\n"
"#ifdef _WIN32\n"
"    char* result = (char*)malloc(strlen(stem) + 5);\n"
"    sprintf(result, \"%s.exe\", stem);\n"
"#else\n"
"    char* result = (char*)malloc(strlen(stem) + 1);\n"
"    sprintf(result, \"%s\", stem);\n"
"#endif\n"
"    free(stem);\n"
"    return result;\n"
"}\n"
"\n"
"// Builds \"<dir><sep>.prismio-<stem>-<suffix>\", or the same without the directory\n"
"// prefix when the path has none. Shared by the temporary .ll, .obj and unpacked\n"
"// source directory names, which previously repeated this logic three times.\n"
"static char* compiler_temp_path(const char* base_path, const char* suffix) {\n"
"    char* directory = get_directory(base_path);\n"
"    const char* filename = path_file_name(base_path);\n"
"    const char* dot = strrchr(filename, '.');\n"
"    int stem_len = dot ? (int)(dot - filename) : (int)strlen(filename);\n"
"\n"
"    int has_directory = strcmp(directory, \".\") != 0;\n"
"    int result_len = (has_directory ? (int)strlen(directory) + 1 : 0) +\n"
"                     (int)strlen(\".prismio-\") + stem_len + 1 +\n"
"                     (int)strlen(suffix) + 1;\n"
"    char* result = (char*)malloc(result_len);\n"
"\n"
"    if (has_directory) {\n"
"        sprintf(result, \"%s%c.prismio-%.*s-%s\", directory, PRISMIO_PATH_SEP,\n"
"                stem_len, filename, suffix);\n"
"    } else {\n"
"        sprintf(result, \".prismio-%.*s-%s\", stem_len, filename, suffix);\n"
"    }\n"
"\n"
"    free(directory);\n"
"    return result;\n"
"}\n"
"\n"
"// LAYOUT 3.2. The workload runner needs three temporaries beside the source --\n"
"// driver IR, driver executable, and the profile itself -- and they follow the\n"
"// same \".prismio-<stem>-<suffix>\" convention as every other build temporary so a\n"
"// failed build leaves recognisable litter rather than anonymous files.\n"
"//\n"
"// Unlike compiler_temp_ir_path this does *not* stamp the pid into the name. The\n"
"// profile is the one build temporary a user may want to keep and check in\n"
"// (LAYOUT 2.2: \"checked in beside the manifest\"), and a pid in the name would\n"
"// make that impossible to predict.\n"
"char* compiler_temp_path_for(const char* source_path, const char* suffix) {\n"
"    return compiler_temp_path(source_path, suffix);\n"
"}\n"
"\n"
"// The same name with the pid in it, for a temporary that must not be shared\n"
"// between concurrent builds of one source.\n"
"//\n"
"// RESULTS-layout \302\2477: the three paths the workload runner used were the only ones\n"
"// here without a pid, so two compiles of the same program shared one\n"
"// profile.txt. A build that read another process's profile chose a different\n"
"// field order, and -- unlike a profile that fails to load -- neither fell back\n"
"// nor warned. It made the IR differential, which is this project's definition of\n"
"// a safe change, report a false difference under any concurrent load.\n"
"//\n"
"// LAYOUT \302\2472.2's predictable path is kept: the profile is *published* to it after\n"
"// the run (compiler_publish_file), so the artifact a user may check in beside\n"
"// the manifest still appears at the name it always had. What changed is that\n"
"// nothing reads it.\n"
"char* compiler_temp_private_path(const char* source_path, const char* suffix) {\n"
"    char stamped[128];\n"
"    snprintf(stamped, sizeof(stamped), \"%d-%s\", PRISMIO_GETPID(), suffix);\n"
"    return compiler_temp_path(source_path, stamped);\n"
"}\n"
"\n"
"static int write_text_file(const char* path, const char* content);\n"
"\n"
"// Copies `from` onto `to` through a pid-qualified temporary beside it, so a\n"
"// concurrent reader of `to` sees either the old file or the new one and never a\n"
"// half-written one. Returns 0 on success.\n"
"int compiler_publish_file(const char* from, const char* to) {\n"
"    char* text = read_file(from);\n"
"    if (!text) return 1;\n"
"\n"
"    size_t len = strlen(to) + 32;\n"
"    char* tmp = (char*)malloc(len);\n"
"    snprintf(tmp, len, \"%s.%d.tmp\", to, PRISMIO_GETPID());\n"
"\n"
"    int result = write_text_file(tmp, text);\n"
"    if (result == 0 && rename(tmp, to) != 0) {\n"
"        // Same filesystem by construction -- the temporary is a sibling -- so a\n"
"        // failure here is a permission or a disk problem, not EXDEV. Publishing\n"
"        // is best-effort either way: the build has its own copy.\n"
"        delete_file(tmp);\n"
"        result = 1;\n"
"    }\n"
"\n"
"    free(tmp);\n"
"    free(text);\n"
"    return result;\n"
"}\n"
"\n"
"char* compiler_temp_ir_path(const char* source_path) {\n"
"    char suffix[32];\n"
"    snprintf(suffix, sizeof(suffix), \"%d.ll\", PRISMIO_GETPID());\n"
"    return compiler_temp_path(source_path, suffix);\n"
"}\n"
"\n"
"static char* compiler_temp_obj_path(const char* exe_file, const char* role) {\n"
"    char suffix[96];\n"
"    snprintf(suffix, sizeof(suffix), \"%s-%d.obj\", role, PRISMIO_GETPID());\n"
"    return compiler_temp_path(exe_file, suffix);\n"
"}\n"
"\n"
"static char* compiler_temp_source_dir(const char* exe_file) {\n"
"    char suffix[64];\n"
"    snprintf(suffix, sizeof(suffix), \"sources-%d\", PRISMIO_GETPID());\n"
"    return compiler_temp_path(exe_file, suffix);\n"
"}\n"
"\n"
"// ============================================\n"
"// Directories\n"
"// ============================================\n"
"\n"
"static int ensure_directory_exists(const char* directory) {\n"
"    if (!directory || directory[0] == '\\0' || strcmp(directory, \".\") == 0) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    char* path = (char*)malloc(strlen(directory) + 1);\n"
"    strcpy(path, directory);\n"
"\n"
"    int start = 0;\n"
"#ifdef _WIN32\n"
"    if (strlen(path) > 2 && path[1] == ':') {\n"
"        start = 3;\n"
"    }\n"
"#endif\n"
"\n"
"    for (int i = start; path[i] != '\\0'; i++) {\n"
"        if (path[i] == '/' || path[i] == '\\\\') {\n"
"            char saved = path[i];\n"
"            path[i] = '\\0';\n"
"            if (strlen(path) > 0) {\n"
"                PRISMIO_MKDIR(path);\n"
"            }\n"
"            path[i] = saved;\n"
"        }\n"
"    }\n"
"\n"
"    PRISMIO_MKDIR(path);\n"
"    free(path);\n"
"    return 0;\n"
"}\n"
"\n"
"int compiler_prepare_output_path(const char* output_path) {\n"
"    char* directory = get_directory(output_path);\n"
"    int result = ensure_directory_exists(directory);\n"
"    free(directory);\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// Locating toolchain sources on disk\n"
"// ============================================\n"
"\n"
"static int accept_if_exists(char* out, int out_size, const char* candidate) {\n"
"    if (!file_exists(candidate)) {\n"
"        return 0;\n"
"    }\n"
"    strncpy(out, candidate, out_size - 1);\n"
"    out[out_size - 1] = '\\0';\n"
"    return 1;\n"
"}\n"
"\n"
"// Looks for runtime/<filename>, first relative to the compiler executable (so an\n"
"// installed toolchain works from any working directory) and then relative to the\n"
"// current directory (so an in-repo build works).\n"
"static int find_toolchain_source(char* out, int out_size, const char* filename) {\n"
"    char candidate[1024];\n"
"\n"
"    char* compiler_dir = prismio_executable_directory();\n"
"    if (compiler_dir) {\n"
"        snprintf(candidate, sizeof(candidate), \"%s%c..%cruntime%c%s\",\n"
"                 compiler_dir, PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            free(compiler_dir);\n"
"            return 1;\n"
"        }\n"
"\n"
"        snprintf(candidate, sizeof(candidate), \"%s%cruntime%c%s\",\n"
"                 compiler_dir, PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            free(compiler_dir);\n"
"            return 1;\n"
"        }\n"
"\n"
"        free(compiler_dir);\n"
"    }\n"
"\n"
"    static const char* prefixes[] = {\n"
"        \"runtime\\\\\", \"runtime/\",\n"
"        \"..\\\\runtime\\\\\", \"../runtime/\",\n"
"        \"..\\\\..\\\\runtime\\\\\", \"../../runtime/\",\n"
"        NULL\n"
"    };\n"
"    for (int i = 0; prefixes[i] != NULL; i++) {\n"
"        snprintf(candidate, sizeof(candidate), \"%s%s\", prefixes[i], filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            return 1;\n"
"        }\n"
"    }\n"
"\n"
"    return 0;\n"
"}\n"
"\n"
"// ============================================\n"
"// Locating the LLVM C API\n"
"//\n"
"// The backend is built on it, so a build that includes the backend needs LLVM's\n"
"// headers to compile and its C API library to link. The two places to look are\n"
"// the same two the bootstrap scripts read, in the same order and with the same\n"
"// names: PRISMIO_LLVM_DIR overrides, otherwise third_party/llvm-paths.json,\n"
"// which tools/setup_llvm.py writes. A third answer would be a third thing to\n"
"// keep in step.\n"
"// ============================================\n"
"\n"
"// The value of a top-level \"key\": \"value\" pair. Not a JSON parser and does not\n"
"// pretend to be one: this reads a file this toolchain generated, whose shape is\n"
"// fixed by setup_llvm.py. The one escape a Windows path actually produces --\n"
"// a doubled backslash -- is undone; anything else is copied through, and a file\n"
"// that does not match returns 0 rather than a wrong answer.\n"
"static int json_string_field(const char* text, const char* key, char* out, int out_size) {\n"
"    char pattern[64];\n"
"    snprintf(pattern, sizeof(pattern), \"\\\"%s\\\"\", key);\n"
"\n"
"    const char* at = strstr(text, pattern);\n"
"    if (!at) return 0;\n"
"    at = strchr(at + strlen(pattern), ':');\n"
"    if (!at) return 0;\n"
"    at = strchr(at, '\"');\n"
"    if (!at) return 0;\n"
"    at++;\n"
"\n"
"    int n = 0;\n"
"    while (*at && *at != '\"' && n < out_size - 1) {\n"
"        if (at[0] == '\\\\' && (at[1] == '\\\\' || at[1] == '/')) at++;\n"
"        out[n++] = *at++;\n"
"    }\n"
"    if (*at != '\"') return 0; // ran off the end: an incomplete value is not a value\n"
"    out[n] = '\\0';\n"
"    return n > 0;\n"
"}\n"
"\n"
"static int find_llvm_paths(char* include_out, int include_size, char* lib_out, int lib_size) {\n"
"    const char* root = getenv(\"PRISMIO_LLVM_DIR\");\n"
"    if (root && root[0]) {\n"
"        snprintf(include_out, include_size, \"%s%cinclude\", root, PRISMIO_PATH_SEP);\n"
"        snprintf(lib_out, lib_size, \"%s%clib\", root, PRISMIO_PATH_SEP);\n"
"        return 1;\n"
"    }\n"
"\n"
"    // Beside the compiler and then beside the working directory, matching\n"
"    // find_toolchain_source: a bootstrap runs from a checkout either way.\n"
"    static const char* relative[] = {\n"
"        \"..\", \".\", NULL\n"
"    };\n"
"    char candidate[1024];\n"
"    char* compiler_dir = prismio_executable_directory();\n"
"    char* text = NULL;\n"
"\n"
"    for (int i = 0; relative[i] && !text; i++) {\n"
"        if (!compiler_dir) break;\n"
"        snprintf(candidate, sizeof(candidate), \"%s%c%s%cthird_party%cllvm-paths.json\",\n"
"                 compiler_dir, PRISMIO_PATH_SEP, relative[i],\n"
"                 PRISMIO_PATH_SEP, PRISMIO_PATH_SEP);\n"
"        if (file_exists(candidate)) text = read_file(candidate);\n"
"    }\n"
"    if (compiler_dir) free(compiler_dir);\n"
"\n"
"    static const char* prefixes[] = {\n"
"        \"third_party/llvm-paths.json\", \"third_party\\\\llvm-paths.json\",\n"
"        \"../third_party/llvm-paths.json\", \"..\\\\third_party\\\\llvm-paths.json\",\n"
"        NULL\n"
"    };\n"
"    for (int i = 0; prefixes[i] && !text; i++) {\n"
"        if (file_exists(prefixes[i])) text = read_file(prefixes[i]);\n"
"    }\n"
"\n"
"    if (!text) return 0;\n"
"\n"
"    int ok = json_string_field(text, \"include\", include_out, include_size)\n"
"          && json_string_field(text, \"lib\", lib_out, lib_size);\n"
"    free(text);\n"
"    return ok;\n"
"}\n"
"\n"
"// ============================================\n"
"// Embedded source unpacking\n"
"// ============================================\n"
"\n"
"static int write_text_file(const char* path, const char* content) {\n"
"    FILE* file = fopen(path, \"wb\");\n"
"    if (!file) {\n"
"        return 1;\n"
"    }\n"
"    fputs(content, file);\n"
"    fclose(file);\n"
"    return 0;\n"
"}\n"
"\n"
"#ifdef PRISMIO_EMBEDDED_SOURCE_AVAILABLE\n"
"static void write_c_string_literal(FILE* file, const char* name, const char* value) {\n"
"    fprintf(file, \"static const char %s[] =\\n\\\"\", name);\n"
"    int column = 0;\n"
"\n"
"    for (const unsigned char* p = (const unsigned char*)value; *p; p++) {\n"
"        unsigned char c = *p;\n"
"\n"
"        if (c == '\\n') {\n"
"            fputs(\"\\\\n\\\"\\n\\\"\", file);\n"
"            column = 0;\n"
"            continue;\n"
"        }\n"
"\n"
"        if (column > 96) {\n"
"            fputs(\"\\\"\\n\\\"\", file);\n"
"            column = 0;\n"
"        }\n"
"\n"
"        if (c == '\\\\') {\n"
"            fputs(\"\\\\\\\\\", file);\n"
"            column += 2;\n"
"        } else if (c == '\"') {\n"
"            fputs(\"\\\\\\\"\", file);\n"
"            column += 2;\n"
"        } else if (c == '\\r') {\n"
"            fputs(\"\\\\r\", file);\n"
"            column += 2;\n"
"        } else if (c == '\\t') {\n"
"            fputs(\"\\\\t\", file);\n"
"            column += 2;\n"
"        } else if (c < 32 || c > 126) {\n"
"            // Octal, because that is what C's \\nnn escape means.\n"
"            fprintf(file, \"\\\\%03o\", c);\n"
"            column += 4;\n"
"        } else {\n"
"            fputc(c, file);\n"
"            column += 1;\n"
"        }\n"
"    }\n"
"\n"
"    fputs(\"\\\";\\n\\n\", file);\n"
"}\n"
"\n"
"// The unpacked build_driver.c includes embedded_sources.h, so the temp directory\n"
"// needs its own copy carrying the same payload.\n"
"static int write_embedded_sources_header(const char* path) {\n"
"    FILE* file = fopen(path, \"wb\");\n"
"    if (!file) {\n"
"        return 1;\n"
"    }\n"
"\n"
"    fputs(\"#ifndef PRISMIO_EMBEDDED_SOURCES_H\\n\", file);\n"
"    fputs(\"#define PRISMIO_EMBEDDED_SOURCES_H\\n\\n\", file);\n"
"    fputs(\"#define PRISMIO_EMBEDDED_SOURCE_AVAILABLE 1\\n\\n\", file);\n"
"    write_c_string_literal(file, \"prismio_embedded_prismio_platform_h\", prismio_embedded_prismio_platform_h);\n"
"    write_c_string_literal(file, \"prismio_embedded_prismio_runtime_h\", prismio_embedded_prismio_runtime_h);\n"
"    write_c_string_literal(file, \"prismio_embedded_lang_runtime_c\", prismio_embedded_lang_runtime_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_program_support_c\", prismio_embedded_program_support_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_build_driver_c\", prismio_embedded_build_driver_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_ir_symbols_c\", prismio_embedded_ir_symbols_c);\n"
"    write_c_string_literal(file, \"prismio_embedded_llvm_api_backend_c\", prismio_embedded_llvm_api_backend_c);\n"
"    fputs(\"#endif\\n\", file);\n"
"\n"
"    fclose(file);\n"
"    return 0;\n"
"}\n"
"#endif\n"
"\n"
"// ============================================\n"
"// Installed toolchain discovery\n"
"// ============================================\n"
"\n"
"// An installed toolchain looks like\n"
"//\n"
"//     <prefix>/bin/prismio(.exe)\n"
"//     <prefix>/lib/runtime.{lib,a}     linked into every compiled program\n"
"//     <prefix>/lib/backend.{lib,a}     linked into the compiler only\n"
"//     <prefix>/stdlib/\n"
"//\n"
"// and is located purely relative to the running executable: no hardcoded prefixes,\n"
"// no environment variables, no runtime sources shipped, nothing extracted from the\n"
"// binary. Also accepts lib/ sitting directly beside the executable, which is what a\n"
"// plain unpacked build tree looks like.\n"
"static int find_in_lib_dir(char* out, int out_size, const char* filename) {\n"
"    static const char* relative_dirs[] = { \"..\", \".\", NULL };\n"
"\n"
"    char* compiler_dir = prismio_executable_directory();\n"
"    if (!compiler_dir) {\n"
"        return 0;\n"
"    }\n"
"\n"
"    char candidate[1024];\n"
"    for (int d = 0; relative_dirs[d] != NULL; d++) {\n"
"        snprintf(candidate, sizeof(candidate), \"%s%c%s%clib%c%s\",\n"
"                 compiler_dir, PRISMIO_PATH_SEP, relative_dirs[d],\n"
"                 PRISMIO_PATH_SEP, PRISMIO_PATH_SEP, filename);\n"
"        if (accept_if_exists(out, out_size, candidate)) {\n"
"            free(compiler_dir);\n"
"            return 1;\n"
"        }\n"
"    }\n"
"\n"
"    free(compiler_dir);\n"
"    return 0;\n"
"}\n"
"\n"
"// Accepts either archive flavour, preferring the platform-native one, so a\n"
"// toolchain packaged on one platform still resolves if copied to another.\n"
"static int find_toolchain_library(char* out, int out_size, const char* stem) {\n"
"    static const char* extensions[] = {\n"
"#ifdef _WIN32\n"
"        \".lib\", \".a\",\n"
"#else\n"
"        \".a\", \".lib\",\n"
"#endif\n"
"        NULL\n"
"    };\n"
"\n"
"    char filename[256];\n"
"    for (int e = 0; extensions[e] != NULL; e++) {\n"
"        snprintf(filename, sizeof(filename), \"%s%s\", stem, extensions[e]);\n"
"        if (find_in_lib_dir(out, out_size, filename)) {\n"
"            return 1;\n"
"        }\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// The runtime archive for the target in force. `runtime.a` is the host's;\n"
"// anything else is `runtime-<triple>.a`.\n"
"//\n"
"// **This is the seam.** The compiler does not build a runtime for a foreign\n"
"// target and does not know what host functions that target has -- which module\n"
"// `print` is imported from on the web is an embedder's decision, not a\n"
"// compiler's. A framework ships runtime-wasm32-unknown-unknown.a, defines the\n"
"// host-import ABI it expects, and the compiler links whatever it is pointed at.\n"
"// Nothing is found, the build falls back to compiling the runtime sources with\n"
"// the same --target and --sysroot, which is what makes an SDK-based target like\n"
"// x86_64-apple-macos work with no archive shipped at all.\n"
"static int find_runtime_library(char* out, int out_size) {\n"
"    if (!ir_target_is_explicit()) return find_toolchain_library(out, out_size, \"runtime\");\n"
"\n"
"    char stem[320];\n"
"    snprintf(stem, sizeof(stem), \"runtime-%s\", ir_target_triple());\n"
"    return find_toolchain_library(out, out_size, stem);\n"
"}\n"
"\n"
"// ============================================\n"
"// Runtime freshness (FNV-1a over the runtime sources)\n"
"// ============================================\n"
"\n"
"// Content hashing, not timestamps: a checkout, a copy or a touch all move mtimes\n"
"// without changing code, and mtime comparison across machines is unreliable.\n"
"// FNV-1a is implemented here rather than shelling out to shasum/certutil so the\n"
"// check has no external dependency and gives identical results on every platform.\n"
"#define PRISMIO_FNV_OFFSET 1469598103934665603ULL\n"
"#define PRISMIO_FNV_PRIME  1099511628211ULL\n"
"\n"
"static unsigned long long fnv1a_bytes(unsigned long long hash, const unsigned char* data) {\n"
"    for (const unsigned char* p = data; *p; p++) {\n"
"        // Normalize line endings so a CRLF checkout hashes the same as an LF one.\n"
"        if (*p == '\\r') continue;\n"
"        hash ^= (unsigned long long)(*p);\n"
"        hash *= PRISMIO_FNV_PRIME;\n"
"    }\n"
"    return hash;\n"
"}\n"
"\n"
"// Hash of the sources that make up runtime.lib, in table order. Returns a malloc'd\n"
"// 16-digit hex string, or an empty string when the sources are not on disk (a\n"
"// normal installed toolchain, where there is nothing to compare against).\n"
"char* compiler_runtime_source_hash(void) {\n"
"    unsigned long long hash = PRISMIO_FNV_OFFSET;\n"
"    char path[1024];\n"
"    int hashed = 0;\n"
"\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        if (!prismio_toolchain_files[i].runtime) continue;\n"
"\n"
"        if (!find_toolchain_source(path, sizeof(path), prismio_toolchain_files[i].name)) {\n"
"            char* empty = (char*)malloc(1);\n"
"            empty[0] = '\\0';\n"
"            return empty;\n"
"        }\n"
"\n"
"        char* text = read_file(path);\n"
"        if (!text) {\n"
"            char* empty = (char*)malloc(1);\n"
"            empty[0] = '\\0';\n"
"            return empty;\n"
"        }\n"
"\n"
"        // Fold the file name in too, so moving code between files is detected.\n"
"        hash = fnv1a_bytes(hash, (const unsigned char*)prismio_toolchain_files[i].name);\n"
"        hash = fnv1a_bytes(hash, (const unsigned char*)text);\n"
"        free(text);\n"
"        hashed++;\n"
"    }\n"
"\n"
"    char* result = (char*)malloc(32);\n"
"    if (hashed == 0) {\n"
"        result[0] = '\\0';\n"
"    } else {\n"
"        snprintf(result, 32, \"%016llx\", hash);\n"
"    }\n"
"    return result;\n"
"}\n"
"\n"
"// The hash recorded beside the installed libraries when they were packaged.\n"
"// Empty when there is no installed toolchain or it predates hash recording.\n"
"char* compiler_installed_runtime_hash(void) {\n"
"    char path[1024];\n"
"    if (!find_in_lib_dir(path, sizeof(path), \"runtime.hash\")) {\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    char* text = read_file(path);\n"
"    if (!text) {\n"
"        char* empty = (char*)malloc(1);\n"
"        empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    // Trim trailing whitespace the sidecar may have picked up.\n"
"    for (int i = (int)strlen(text) - 1; i >= 0; i--) {\n"
"        if (text[i] == '\\n' || text[i] == '\\r' || text[i] == ' ' || text[i] == '\\t') {\n"
"            text[i] = '\\0';\n"
"        } else {\n"
"            break;\n"
"        }\n"
"    }\n"
"    return text;\n"
"}\n"
"\n"
"// ============================================\n"
"// Build orchestration\n"
"// ============================================\n"
"\n"
"static int run_build_command(const char* command) {\n"
"    int result = system(command);\n"
"    return result == 0 ? 0 : 1;\n"
"}\n"
"\n"
"// SPEC 7.3's `--verify`, as seen from the build.\n"
"//\n"
"// Codegen swaps the allocator and deallocator *names* and changes nothing else.\n"
"// That covers everything ir_alloc_object handed out and nothing else -- but AIF\n"
"// Level 4 made strings and lists affine, and those are allocated inside\n"
"// lang_runtime.c, past the seam. Their release would then be a pointer the\n"
"// accounting never saw, which reads as a violation on every string a program\n"
"// drops.\n"
"//\n"
"// So a verify build compiles the runtime from source with PRISMIO_AIF_VERIFY\n"
"// defined, which points its own allocator at the same shims. That keeps both\n"
"// ends of every pairing on the same side of the swap, and it keeps the property\n"
"// worth having: the *generated code* is byte-identical either way.\n"
"static int g_verify_mode = 0;\n"
"\n"
"void compiler_set_verify_mode(int on) { g_verify_mode = on ? 1 : 0; }\n"
"\n"
"// `-g`, as seen from the build. The DWARF itself is built by the backend and\n"
"// travels inside the .ll; this flag is the two things the *driver* has to do\n"
"// differently once it is there.\n"
"//\n"
"// **-O0 for the program object.** The rest of this file argues for -O2 and the\n"
"// measurements behind it stand, but they are measurements of speed, and -g is a\n"
"// request for a different thing. At -O2 a Prismio local is promoted out of its\n"
"// stack slot in the first hundred milliseconds of the pipeline, and every\n"
"// question a debugger can then answer about it is \"optimized out\". LLVM does not\n"
"// lie in that state -- it drops locations rather than keeping stale ones -- so\n"
"// the result is not wrong, it is empty, and an empty debugger is what a user\n"
"// would report as \"-g does not work\". Someone who wants both can still ask:\n"
"// `prismio build x.psm -O2 -g` runs the IR pipeline inside the compiler and the\n"
"// compile unit records isOptimized, so the debugger says so.\n"
"//\n"
"// **dsymutil on Darwin.** Mach-O keeps DWARF in the object file and puts only a\n"
"// debug map in the executable, so `delete_file(program_obj)` below -- which has\n"
"// always run -- would take the debug info with it. dsymutil walks the map and\n"
"// copies the DWARF into a .dSYM bundle beside the binary, which is where lldb\n"
"// looks. On ELF the linker copies the sections into the executable itself and\n"
"// there is nothing to do. This is why -g on macOS was not simply \"emit the\n"
"// metadata\": everything downstream of the metadata was already deleting it.\n"
"static int g_debug_info = 0;\n"
"\n"
"void compiler_set_debug_info(int on) { g_debug_info = on ? 1 : 0; }\n"
"\n"
"// ============================================\n"
"// Cross-compilation\n"
"//\n"
"// The triple is not stored here: llvm-api-backend.c already holds it, because\n"
"// that is where LLVM answered the question, and a second copy is a second thing\n"
"// that can be stale. This file asks.\n"
"//\n"
"// The sysroot is stored here, and is not part of the target record, because it\n"
"// is not a property of the triple -- it is where *this machine* keeps the SDK\n"
"// for it. Two hosts building the same target legitimately pass different paths,\n"
"// and the compiler has no business guessing either one: an SDK it picked itself\n"
"// is exactly the kind of \"helpfully wrong\" that produces a link error someone\n"
"// spends an afternoon on.\n"
"// ============================================\n"
"\n"
"static char g_sysroot[1024] = \"\";\n"
"\n"
"void compiler_set_sysroot(const char* path) {\n"
"    snprintf(g_sysroot, sizeof(g_sysroot), \"%s\", path ? path : \"\");\n"
"}\n"
"\n"
"// The clang flags that name the target: either \"\" or a string ending in a\n"
"// space, so a caller can always paste it straight in front of the rest of the\n"
"// command. \"\" is the host case, where clang goes on defaulting exactly as it\n"
"// always has and every existing build is byte-for-byte unaffected.\n"
"//\n"
"// Returned in a caller-owned buffer rather than a static one: it goes into the\n"
"// object cache key, and a key built from a buffer a later call can rewrite is a\n"
"// key that describes the wrong compile.\n"
"static char* target_clang_flags(void) {\n"
"    const char* triple = ir_target_is_explicit() ? ir_target_triple() : \"\";\n"
"    int has_sysroot = g_sysroot[0] != '\\0';\n"
"    if (!triple[0] && !has_sysroot) {\n"
"        char* empty = (char*)malloc(1);\n"
"        if (empty) empty[0] = '\\0';\n"
"        return empty;\n"
"    }\n"
"\n"
"    char* q_sysroot = has_sysroot ? command_quote_arg(g_sysroot) : NULL;\n"
"    int len = (int)strlen(triple) + (q_sysroot ? (int)strlen(q_sysroot) : 0) + 64;\n"
"    char* out = (char*)malloc(len);\n"
"    snprintf(out, len, \"%s%s%s%s%s%s\",\n"
"             triple[0] ? \"--target=\" : \"\", triple, triple[0] ? \" \" : \"\",\n"
"             has_sysroot ? \"-isysroot \" : \"\", q_sysroot ? q_sysroot : \"\",\n"
"             has_sysroot ? \" \" : \"\");\n"
"    if (q_sysroot) free(q_sysroot);\n"
"    return out;\n"
"}\n"
"\n"
"// Whether the thing being produced is Mach-O. dsymutil is asked only of a build\n"
"// that will have a debug map to walk, and after cross-compilation that is a\n"
"// question about the *target*, not about the host this compiler is running on.\n"
"static int target_is_mach_o(void) {\n"
"    if (!ir_target_is_explicit()) {\n"
"#ifdef __APPLE__\n"
"        return 1;\n"
"#else\n"
"        return 0;\n"
"#endif\n"
"    }\n"
"    const char* t = ir_target_triple();\n"
"    return strstr(t, \"apple\") != NULL || strstr(t, \"darwin\") != NULL;\n"
"}\n"
"\n"
"// LAYOUT 3.2. A workload driver calls rt_profile_*, and an *installed*\n"
"// runtime.lib may predate them -- it is a binary someone built at some point,\n"
"// and this feature is newer than some of those points. The link then fails on\n"
"// six symbols and W2 turns it into a fallback, so the effect is a workload that\n"
"// silently never runs on exactly the machines where the toolchain was installed\n"
"// rather than built.\n"
"//\n"
"// This is the same shape as the verify flag above and is here for the same\n"
"// reason: a build mode whose object code needs something the installed library\n"
"// cannot be assumed to contain must compile the runtime itself. It differs in\n"
"// one way worth stating -- verify compiles from source to change the runtime's\n"
"// *behaviour*, this one only to guarantee its *vintage*. Nothing is defined and\n"
"// the generated code is unaffected.\n"
"//\n"
"// build_from_toolchain_sources falls back to the sources embedded in the\n"
"// compiler binary when the repository is not on disk, so this costs an installed\n"
"// toolchain nothing but compile time.\n"
"static int g_workload_mode = 0;\n"
"\n"
"void compiler_set_workload_mode(int on) { g_workload_mode = on ? 1 : 0; }\n"
"\n"
"// IR -> object.\n"
"//\n"
"// This was `llc <ir> -filetype=obj` for a long time, and that ran the *codegen*\n"
"// pipeline only -- isel, scheduling, register allocation. llc does not run the\n"
"// IR pipeline, so mem2reg, SROA, GVN, LICM, inlining and vectorisation never\n"
"// touched a user program: every local stayed a stack slot and every field read\n"
"// was reloaded. Measured at 1.4x-3.0x across aif/corpus (RESULTS-xlang 3.1).\n"
"//\n"
"// clang runs both pipelines in one process, is already required for the link,\n"
"// and takes .ll directly -- which is why compiler_temp_ir_path spells the\n"
"// suffix `.ll`. It also drops llc from the user-build path entirely.\n"
"//\n"
"// -O2 rather than -O3: measured across the corpus, -O3 lands between 0.98x and\n"
"// 1.03x of -O2, which is noise, and costs the same compile time\n"
"// (aif/evidence/xlang/optlevel.py). -flto is speed-neutral too and worth ~15%\n"
"// of binary size, but needs linker plugin support that is not portable enough\n"
"// to make a default.\n"
"// Both live in the object-cache section below and are used here: the curated\n"
"// module is cached on the same key shape and in the same directory as the\n"
"// toolchain objects, because it is the same kind of thing -- a build product of\n"
"// the runtime sources that no program-specific input can change.\n"
"static char* object_cache_dir(void);\n"
"static char* object_cache_temp_path(const char* entry);\n"
"static int object_cache_disabled(void);\n"
"static int object_cache_trace(void);\n"
"\n"
"// ============================================\n"
"// M1.1 -- the curated inlinable module\n"
"//\n"
"// Every container access in a Prismio loop is a `bl` into the separately\n"
"// compiled C runtime, and the optimiser cannot see through it. Measured, that\n"
"// seam is worth 1.03x-2.31x across the corpus and 2.00x on g2_tuned\n"
"// (aif/evidence/RESULTS-M1-lto.md).\n"
"//\n"
"// The fix is Swift's `@inlinable` spelled at IR level: take the hot container\n"
"// ops out of the runtime's own IR, rewrite their linkage to\n"
"// `available_externally` -- the body is visible to the inliner but emits no\n"
"// code -- and link that module into the program's before -O2. Calls that do not\n"
"// get inlined still resolve to the runtime archive's copy, so nothing is\n"
"// defined twice and the ordinary native link is unchanged.\n"
"//\n"
"// **Why not -flto.** It was measured and it does not work here without more\n"
"// machinery, for a reason worth recording: the backend emits program functions\n"
"// carrying no target attributes at all, while clang stamps `target-cpu` and a\n"
"// 33-entry `target-features` on every runtime function, so the LTO inliner\n"
"// answers `cost=never: conflicting attributes` before it ever prices the call.\n"
"// Making that match needs the *exact* string clang used -- a superset fails, a\n"
"// newer CPU fails, and LLVMGetHostCPUName() answers a different chip than clang\n"
"// picks on this host. Merging sidesteps all of it, because `clang -O2` on the\n"
"// merged module fills its own defaults into the attribute-less functions, and\n"
"// does so self-consistently under --target since one invocation supplies both\n"
"// halves. The merge is also faster to compile (1.18x against -flto's 1.21x and\n"
"// a whole-runtime merge's 1.88x) and needs no linker plugin.\n"
"//\n"
"// **The curated set is not a list of whatever looked hot.** A function may be\n"
"// curated only if every symbol its body references is *exported* by the runtime\n"
"// object. A `static` in lang_runtime.c is absent from that object's symbol\n"
"// table, so inlining a body that reads one produces a program referencing a\n"
"// symbol nothing defines, and the link fails with \"Undefined symbols ...\n"
"// _arena_alloc_slot\". That is a reproduced failure, not a worry.\n"
"// `run_curated_closure_test` asserts the property rather than trusting it.\n"
"//\n"
"// `list_push` is the case worth knowing about, because it failed the rule twice\n"
"// over and both halves had to be fixed:\n"
"//\n"
"//   1. *It referenced three `static`s* -- rt_arena_hint, arena_depth and\n"
"//      arena_alloc_slot, all reached through rt_alloc on the growth path.\n"
"//   2. *It was too big to inline anyway.* The inliner priced it at cost=675\n"
"//      against a threshold of 225 and declined at every site, so adding it to\n"
"//      this list changed nothing at all: the emitted call counts were identical\n"
"//      with and without it, and the timing differences between those two builds\n"
"//      were pure measurement noise.\n"
"//\n"
"// Outlining the growth half into `list_push_grow` fixes both at once -- it takes\n"
"// the three statics with it, and it drops the remaining fast path from 227 IR\n"
"// lines to 69. See the comment on list_push_grow in lang_runtime.c.\n"
"static const char* const PRISMIO_CURATED_OPS[] = {\n"
"    \"list_get\", \"list_set\", \"list_len\",\n"
"    \"list_set_elem_owner\", \"list_set_elem_releaser\",\n"
"    \"rc_retain\", \"rc_release\", \"list_push\",\n"
"};\n"
"#define PRISMIO_CURATED_OP_COUNT \\\n"
"    ((int)(sizeof(PRISMIO_CURATED_OPS) / sizeof(PRISMIO_CURATED_OPS[0])))\n"
"\n"
"// Opt-in while it is measured. Default-off means the gate can run old against\n"
"// new on one tree, and a bad result is a variable away rather than a revert.\n"
"static int inline_runtime_enabled(void) {\n"
"    const char* v = getenv(\"PRISMIO_INLINE_RUNTIME\");\n"
"    return v && v[0] && !(v[0] == '0' && v[1] == '\\0');\n"
"}\n"
"\n"
"// Produce the curated module, or NULL if it cannot be produced for any reason.\n"
"//\n"
"// NULL is always safe: the caller compiles exactly as it did before. That is the\n"
"// same contract object_cache_path has, and for the same reason -- an\n"
"// optimisation that can fail a build is worse than no optimisation.\n"
"//\n"
"// Cached on the content of lang_runtime.c plus the compile flags, because the\n"
"// module is a function of both and of nothing else in the program being built.\n"
"// It is therefore produced once per toolchain per target and reused by every\n"
"// subsequent build, which is what keeps the steady-state cost at one in-process module merge.\n"
"static char* build_curated_module(const char* target_flags) {\n"
"    char lr_source[1024];\n"
"    if (!find_toolchain_source(lr_source, sizeof(lr_source), \"lang_runtime.c\")) return NULL;\n"
"\n"
"    char* text = read_file(lr_source);\n"
"    if (!text) return NULL;\n"
"\n"
"    // --verify compiles the runtime with -DPRISMIO_AIF_VERIFY, so its IR\n"
"    // differs and a module built for one mode must not serve the other. Same\n"
"    // hazard the object cache guards, same fix.\n"
"    const char* verify = g_verify_mode ? \"-DPRISMIO_AIF_VERIFY \" : \"\";\n"
"\n"
"    unsigned long long hash = PRISMIO_FNV_OFFSET;\n"
"    hash = fnv1a_bytes(hash, (const unsigned char*)\"curated\");\n"
"    hash = fnv1a_bytes(hash, (const unsigned char*)target_flags);\n"
"    hash = fnv1a_bytes(hash, (const unsigned char*)verify);\n"
"    hash = fnv1a_bytes(hash, (const unsigned char*)text);\n"
"    for (int i = 0; i < PRISMIO_CURATED_OP_COUNT; i++) {\n"
"        hash = fnv1a_bytes(hash, (const unsigned char*)PRISMIO_CURATED_OPS[i]);\n"
"    }\n"
"    free(text);\n"
"\n"
"    char* dir = object_cache_dir();\n"
"    if (!dir) return NULL;\n"
"    if (ensure_directory_exists(dir) != 0) { free(dir); return NULL; }\n"
"\n"
"    char name[128];\n"
"    snprintf(name, sizeof(name), \"curated-%016llx.ll\", hash);\n"
"    char* entry = join_path(dir, name);\n"
"    free(dir);\n"
"    if (!entry) return NULL;\n"
"\n"
"    // PRISMIO_OBJ_CACHE=0 has to reach this cache too, and for the same reason\n"
"    // it exists for the objects: the key covers the source and the flags but\n"
"    // *not* the clang that turned one into the other, so an in-place toolchain\n"
"    // upgrade leaves a stale entry that nothing notices. A bypass that skipped\n"
"    // only half the build products would be a bypass that does not bypass.\n"
"    //\n"
"    // It also makes \"cold build\" mean the same thing here as everywhere else,\n"
"    // which is what the compile-time measurement depends on.\n"
"    int bypass = object_cache_disabled();\n"
"    if (bypass) {\n"
"        if (object_cache_trace()) fprintf(stderr, \"[objcache off] curated\\n\");\n"
"    } else if (file_exists(entry)) {\n"
"        if (object_cache_trace()) fprintf(stderr, \"[objcache hit] curated\\n\");\n"
"        return entry;\n"
"    } else if (object_cache_trace()) {\n"
"        fprintf(stderr, \"[objcache miss] curated\\n\");\n"
"    }\n"
"\n"
"    // Built to a pid-qualified sibling and renamed into place, never written at\n"
"    // the cache path directly -- two builds racing on one entry would otherwise\n"
"    // link a half-written module. See object_cache_temp_path.\n"
"    char* tmp_ll = object_cache_temp_path(entry);\n"
"    char* tmp_raw = NULL;\n"
"    int failed = 0;\n"
"\n"
"    {\n"
"        size_t n = strlen(tmp_ll) + 16;\n"
"        tmp_raw = (char*)malloc(n);\n"
"        if (!tmp_raw) { failed = 1; }\n"
"        else snprintf(tmp_raw, n, \"%s.raw\", tmp_ll);\n"
"    }\n"
"\n"
"    char* q_src = failed ? NULL : command_quote_arg(lr_source);\n"
"    char* q_tmp = failed ? NULL : command_quote_arg(tmp_ll);\n"
"    char* q_raw = failed ? NULL : command_quote_arg(tmp_raw);\n"
"\n"
"    if (!failed) {\n"
"        int len = (int)(strlen(q_src) + strlen(q_tmp) + strlen(q_raw)\n"
"                        + strlen(target_flags) + 256\n"
"                        + PRISMIO_CURATED_OP_COUNT * 64);\n"
"        char* command = (char*)malloc(len);\n"
"        if (!command) failed = 1;\n"
"\n"
"        // 1. the runtime's own IR, at the same -O2 the runtime object is built\n"
"        //    with, so the bodies being inlined are the bodies that would have\n"
"        //    been called.\n"
"        if (!failed) {\n"
"            snprintf(command, len, \"clang %s%s-O2 -Wno-deprecated-declarations -S -emit-llvm %s -o %s\",\n"
"                     target_flags, verify, q_src, q_raw);\n"
"            if (run_build_command(command) != 0) failed = 1;\n"
"        }\n"
"\n"
"        free(command);\n"
"    }\n"
"\n"
"    // 2. the curated ops out of it, in process. Everything else is reduced to a\n"
"    //    declaration and then dropped, which is what makes the module small\n"
"    //    enough that the merge costs 1.18x rather than the whole runtime's\n"
"    //    1.88x. Byte-identical to what `llvm-extract` produced when this was a\n"
"    //    shell-out, which is how the port was checked.\n"
"    if (!failed && ir_curate_module(tmp_raw, PRISMIO_CURATED_OPS,\n"
"                                    PRISMIO_CURATED_OP_COUNT, tmp_ll) != 0) {\n"
"        failed = 1;\n"
"    }\n"
"\n"
"    // A bypassed cache builds to the temporary and uses it in place; installing\n"
"    // it would repopulate the very entry the caller asked to skip.\n"
"    if (!failed && bypass) {\n"
"        free(q_src); free(q_tmp); free(q_raw);\n"
"        if (tmp_raw) { delete_file(tmp_raw); free(tmp_raw); }\n"
"        free(entry);\n"
"        return tmp_ll;\n"
"    }\n"
"\n"
"    if (!failed && rename(tmp_ll, entry) != 0) {\n"
"        // A failed install is not a failed build: use the temporary this once\n"
"        // and pay for it again next time.\n"
"        free(q_src); free(q_tmp); free(q_raw);\n"
"        if (tmp_raw) { delete_file(tmp_raw); free(tmp_raw); }\n"
"        free(entry);\n"
"        return tmp_ll;\n"
"    }\n"
"\n"
"    if (tmp_raw) { delete_file(tmp_raw); free(tmp_raw); }\n"
"    free(q_src); free(q_tmp); free(q_raw);\n"
"\n"
"    if (failed) {\n"
"        delete_file(tmp_ll);\n"
"        free(tmp_ll);\n"
"        free(entry);\n"
"        return NULL;\n"
"    }\n"
"\n"
"    free(tmp_ll);\n"
"    return entry;\n"
"}\n"
"\n"
"// Merge the curated module into the program's, returning a path to the merged\n"
"// IR, or NULL to compile the program's IR unchanged.\n"
"static char* merge_curated_into_program(const char* ir_file, const char* target_flags) {\n"
"    char* curated = build_curated_module(target_flags);\n"
"    if (!curated) return NULL;\n"
"\n"
"    size_t n = strlen(ir_file) + 32;\n"
"    char* merged = (char*)malloc(n);\n"
"    if (!merged) { free(curated); return NULL; }\n"
"    snprintf(merged, n, \"%s.merged.ll\", ir_file);\n"
"\n"
"    int ok = ir_link_modules(ir_file, curated, merged) == 0;\n"
"    free(curated);\n"
"\n"
"    if (!ok) {\n"
"        delete_file(merged);\n"
"        free(merged);\n"
"        return NULL;\n"
"    }\n"
"    return merged;\n"
"}\n"
"\n"
"static int compile_ir_to_object(const char* ir_file, const char* program_obj) {\n"
"    char* target = target_clang_flags();\n"
"\n"
"    // M1.1. Merge the curated inlinable module in before -O2, so the container\n"
"    // ops are ordinary local calls the inliner can price rather than a `bl` into\n"
"    // another translation unit.\n"
"    //\n"
"    // **Declined under -g, deliberately.** The object step drops to -O0 there,\n"
"    // and at -O0 nothing is inlined, so the merge would cost a clang invocation\n"
"    // and an llvm-link to produce identical code. Worse, it would put the\n"
"    // runtime's bodies into the module a debugger walks, which is a change to\n"
"    // what `-g` builds -- and \"the merge must not silently change what -g\n"
"    // builds\" is the risk this milestone was told to watch.\n"
"    char* merged = NULL;\n"
"    if (inline_runtime_enabled() && !g_debug_info) {\n"
"        merged = merge_curated_into_program(ir_file, target);\n"
"    }\n"
"\n"
"    char* q_ir = command_quote_arg(merged ? merged : ir_file);\n"
"    char* q_obj = command_quote_arg(program_obj);\n"
"    int len = (int)(strlen(q_ir) + strlen(q_obj) + strlen(target) + 96);\n"
"    char* command = (char*)malloc(len);\n"
"\n"
"    // --target as well as the triple already written on the module: clang needs\n"
"    // the flag to pick the right assembler and object format.\n"
"    //\n"
"    // **-Wno-override-module, and the reason it is not a papered-over bug.**\n"
"    // The clang *driver* always compiles for the SDK's deployment target --\n"
"    // arm64-apple-macosx26.0.0 here -- while a module carries at most what\n"
"    // LLVMGetDefaultTargetTriple() gives, arm64-apple-darwin25.5.0. Those never\n"
"    // match, so clang always overrides and always warns. Measured: it warns\n"
"    // identically against a module with **no triple at all**, which a plain host\n"
"    // build emits, so this was never about what we stamp and could not be fixed\n"
"    // by stamping better or by stamping nothing.\n"
"    //\n"
"    // What the warning could in principle have caught is a real ABI\n"
"    // disagreement between the triple we describe `-g` offsets against and the\n"
"    // one clang codegens for. That is worth keeping, so it is now an assertion\n"
"    // instead of a warning: run_target_test requires the data layout we stamp to\n"
"    // equal the one clang computes for the same target, for the host and for\n"
"    // wasm32. A warning on every build that everyone learns to scroll past is\n"
"    // worth less than one test that fails.\n"
"    snprintf(command, len, \"clang %s-Wno-override-module %s -c %s -o %s\",\n"
"             target, g_debug_info ? \"-O0\" : \"-O2\", q_ir, q_obj);\n"
"    int result = run_build_command(command);\n"
"\n"
"    if (merged) {\n"
"        delete_file(merged);\n"
"        free(merged);\n"
"    }\n"
"    free(command);\n"
"    free(target);\n"
"    free(q_ir);\n"
"    free(q_obj);\n"
"    return result;\n"
"}\n"
"\n"
"// Normal user mode: link the program against the runtime library and nothing else.\n"
"// backend.lib -- the LLVM C API backend, the symbol tables, the diagnostics\n"
"// engine and this file -- exists only so the compiler can\n"
"// generate code and must never end up in a user's binary.\n"
"static int link_against_runtime_library(const char* program_obj,\n"
"                                        const char* runtime_lib,\n"
"                                        const char* exe_file) {\n"
"    char* q_obj = command_quote_arg(program_obj);\n"
"    char* q_lib = command_quote_arg(runtime_lib);\n"
"    char* q_exe = command_quote_arg(exe_file);\n"
"    char* target = target_clang_flags();\n"
"    int len = (int)(strlen(q_obj) + strlen(q_lib) + strlen(q_exe) + strlen(target) + 64);\n"
"    char* command = (char*)malloc(len);\n"
"\n"
"    snprintf(command, len, \"clang %s%s %s -o %s\", target, q_obj, q_lib, q_exe);\n"
"    int result = run_build_command(command);\n"
"\n"
"    free(command);\n"
"    free(target);\n"
"    free(q_obj);\n"
"    free(q_lib);\n"
"    free(q_exe);\n"
"    return result;\n"
"}\n"
"\n"
"// ============================================\n"
"// Toolchain object cache\n"
"//\n"
"// Every build compiles the toolchain sources from scratch and deletes the\n"
"// objects afterwards. Measured on this host: lang_runtime.c and\n"
"// program_support.c cost 203 ms of a 411 ms build of a 34-line program, so\n"
"// **half of every small build is recompiling code that did not change**. It is\n"
"// the same object every time -- the runtime does not depend on the program.\n"
"//\n"
"// The key is the content of the source plus the exact compile command, hashed\n"
"// with the same FNV-1a used for the staleness check above, for the reason given\n"
"// there: mtimes move on a checkout or a copy and content does not. Flags are in\n"
"// the key because `--verify` compiles the same file to a different object\n"
"// (-DPRISMIO_AIF_VERIFY), and an object built for one mode linked into the other\n"
"// is exactly the \"half the allocations are outside the accounting\" failure the\n"
"// verify path already guards against.\n"
"//\n"
"// **What the key does not cover: an in-place upgrade of clang itself.** The same\n"
"// source and the same flags through a different compiler produce a different\n"
"// object, and nothing here notices. Set `PRISMIO_OBJ_CACHE=0` to bypass the\n"
"// cache after a toolchain upgrade, or delete the directory. Spawning\n"
"// `clang --version` to fold into the key was measured at 28 ms -- 14% of what\n"
"// the cache saves -- and was not worth paying on every build.\n"
"// ============================================\n"
"\n"
"static int object_cache_disabled(void) {\n"
"    const char* v = getenv(\"PRISMIO_OBJ_CACHE\");\n"
"    return v && v[0] == '0' && v[1] == '\\0';\n"
"}\n"
"\n"
"// Prints one line per toolchain object saying whether it came from the cache.\n"
"// The test that this cache works asks for exactly this, because \"the build was\n"
"// faster\" is not an observation a test can make reliably on a shared host.\n"
"static int object_cache_trace(void) {\n"
"    const char* v = getenv(\"PRISMIO_OBJ_CACHE_TRACE\");\n"
"    return v && v[0] != '\\0' && !(v[0] == '0' && v[1] == '\\0');\n"
"}\n"
"\n"
"// PRISMIO_OBJ_CACHE_DIR *is* the directory when it is set, rather than a parent\n"
"// to append a name to. The bootstrap scripts read the same variable and use it\n"
"// directly, and two readings of one variable is how the two caches would end up\n"
"// in two places while both reporting hits.\n"
"static char* object_cache_dir(void) {\n"
"    const char* override = getenv(\"PRISMIO_OBJ_CACHE_DIR\");\n"
"    if (override && override[0]) {\n"
"        char* copy = (char*)malloc(strlen(override) + 1);\n"
"        strcpy(copy, override);\n"
"        return copy;\n"
"    }\n"
"\n"
"    const char* base;\n"
"#ifdef _WIN32\n"
"    base = getenv(\"TEMP\");\n"
"    if (!base || !base[0]) base = getenv(\"TMP\");\n"
"    if (!base || !base[0]) base = \".\";\n"
"#else\n"
"    base = getenv(\"TMPDIR\");\n"
"    if (!base || !base[0]) base = \"/tmp\";\n"
"#endif\n"
"    // Shared across every build on the host, which is the point: a test suite\n"
"    // building 119 programs compiles the runtime once rather than 119 times.\n"
"    return join_path(base, \"prismio-objcache\");\n"
"}\n"
"\n"
"// The cache entry for one toolchain source, or NULL when the source cannot be\n"
"// read or the cache directory cannot be made. A NULL is always safe: the caller\n"
"// compiles as it did before.\n"
"static char* object_cache_path(const char* role, const char* source_path,\n"
"                               const char* command_flags,\n"
"                               const char source_paths[][1024]) {\n"
"    char* text = read_file(source_path);\n"
"    if (!text) return NULL;\n"
"\n"
"    unsigned long long hash = PRISMIO_FNV_OFFSET;\n"
"    hash = fnv1a_bytes(hash, (const unsigned char*)role);\n"
"    hash = fnv1a_bytes(hash, (const unsigned char*)command_flags);\n"
"    hash = fnv1a_bytes(hash, (const unsigned char*)text);\n"
"    free(text);\n"
"\n"
"    // Every header in the table, into every entry. A header changes what a .c\n"
"    // compiles to without changing a byte of it, so keying on the .c alone\n"
"    // serves an object built against the *previous* prismio_runtime.h -- and the\n"
"    // way that happens is a runtime session regenerating embedded_sources.h,\n"
"    // which is a thing this project does routinely. Over-invalidating (an edit\n"
"    // to one header rebuilds all of them) is the right side to be wrong on: the\n"
"    // headers are three files and they change rarely.\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        if (prismio_toolchain_files[i].compiled) continue;\n"
"        if (!source_paths[i][0]) continue;\n"
"        char* header = read_file(source_paths[i]);\n"
"        if (!header) {\n"
"            // A header that cannot be read makes the key incomplete, and an\n"
"            // incomplete key is worse than no cache.\n"
"            return NULL;\n"
"        }\n"
"        hash = fnv1a_bytes(hash, (const unsigned char*)prismio_toolchain_files[i].name);\n"
"        hash = fnv1a_bytes(hash, (const unsigned char*)header);\n"
"        free(header);\n"
"    }\n"
"\n"
"    // embedded_sources.h is not in the table -- it is generated, and only\n"
"    // build_driver.c includes it -- but it is a header like any other and a\n"
"    // bootstrap build compiles against it. Absent on an installed toolchain,\n"
"    // where nothing includes it either, so missing is not an incomplete key.\n"
"    char embedded[1024];\n"
"    if (find_toolchain_source(embedded, sizeof(embedded), \"embedded_sources.h\")) {\n"
"        char* text_h = read_file(embedded);\n"
"        if (text_h) {\n"
"            hash = fnv1a_bytes(hash, (const unsigned char*)\"embedded_sources.h\");\n"
"            hash = fnv1a_bytes(hash, (const unsigned char*)text_h);\n"
"            free(text_h);\n"
"        }\n"
"    }\n"
"\n"
"    char* dir = object_cache_dir();\n"
"    if (ensure_directory_exists(dir) != 0) {\n"
"        free(dir);\n"
"        return NULL;\n"
"    }\n"
"\n"
"    char name[128];\n"
"    snprintf(name, sizeof(name), \"%s-%016llx.obj\", role, hash);\n"
"    char* path = join_path(dir, name);\n"
"    free(dir);\n"
"    return path;\n"
"}\n"
"\n"
"// A sibling of `entry` in the cache directory, which is where the compiler is\n"
"// told to write the object before it is renamed into place.\n"
"//\n"
"// **It has to be a sibling.** The first version compiled next to the *output\n"
"// executable* and renamed into $TMPDIR, and `rename()` cannot cross a\n"
"// filesystem: on any host where the two differ -- /tmp as tmpfs on Linux, a\n"
"// build directory on a second volume -- every install fails with EXDEV, the\n"
"// build still succeeds, and the cache silently never populates. Nothing local\n"
"// would ever have shown it, because this Mac has one volume.\n"
"static char* object_cache_temp_path(const char* entry) {\n"
"    const char* file = entry;\n"
"    for (const char* p = entry; *p; p++) {\n"
"        if (*p == '/' || *p == '\\\\') file = p + 1;\n"
"    }\n"
"    size_t dir_len = (size_t)(file - entry);\n"
"    size_t len = dir_len + strlen(file) + 32;\n"
"    char* tmp = (char*)malloc(len);\n"
"    snprintf(tmp, len, \"%.*s.tmp-%d-%s\", (int)dir_len, entry, PRISMIO_GETPID(), file);\n"
"    return tmp;\n"
"}\n"
"\n"
"// Compile the toolchain from source and link it with the program.\n"
"//\n"
"// `include_backend` selects the build mode:\n"
"//   0 -- normal user build with no installed libraries beside the compiler. Only\n"
"//        the runtime half is compiled, so the result matches what linking\n"
"//        runtime.lib would have produced and the backend still cannot leak in.\n"
"//   1 -- bootstrap. The program being built *is* the compiler, so it needs the\n"
"//        backend's ir_* functions and the build orchestration in this file.\n"
"//\n"
"// `force_filesystem` refuses the copies embedded in this binary and insists on\n"
"// runtime/ on disk. Bootstrap requires it: the embedded copies were frozen when the\n"
"// *bootstrapping* compiler was built, so using them would silently link the previous\n"
"// generation's runtime into the new one and make edits to runtime/*.c invisible --\n"
"// the exact staleness chain this refactor exists to break.\n"
"static int build_from_toolchain_sources(const char* program_obj, const char* exe_file,\n"
"                                        int include_backend, int force_filesystem) {\n"
"    char source_paths[PRISMIO_TOOLCHAIN_FILE_COUNT][1024];\n"
"    char* unpacked_paths[PRISMIO_TOOLCHAIN_FILE_COUNT];\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        source_paths[i][0] = '\\0';\n"
"        unpacked_paths[i] = NULL;\n"
"    }\n"
"\n"
"    int using_embedded_sources = 0;\n"
"    char* embedded_dir = NULL;\n"
"    char* embedded_header = NULL;\n"
"\n"
"#ifdef PRISMIO_EMBEDDED_SOURCE_AVAILABLE\n"
"    if (!force_filesystem) {\n"
"    embedded_dir = compiler_temp_source_dir(exe_file);\n"
"    if (ensure_directory_exists(embedded_dir) == 0) {\n"
"        using_embedded_sources = 1;\n"
"\n"
"        for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT && using_embedded_sources; i++) {\n"
"            if (!prismio_toolchain_files[i].runtime && !include_backend) continue;\n"
"\n"
"            unpacked_paths[i] = join_path(embedded_dir, prismio_toolchain_files[i].name);\n"
"            if (write_text_file(unpacked_paths[i], prismio_embedded_text(i)) != 0) {\n"
"                using_embedded_sources = 0;\n"
"                break;\n"
"            }\n"
"            strncpy(source_paths[i], unpacked_paths[i], sizeof(source_paths[i]) - 1);\n"
"            source_paths[i][sizeof(source_paths[i]) - 1] = '\\0';\n"
"        }\n"
"\n"
"        // Only build_driver.c includes embedded_sources.h, so the unpacked copy is\n"
"        // needed only when the backend is part of this build.\n"
"        if (using_embedded_sources && include_backend) {\n"
"            embedded_header = join_path(embedded_dir, \"embedded_sources.h\");\n"
"            if (write_embedded_sources_header(embedded_header) != 0) {\n"
"                using_embedded_sources = 0;\n"
"            }\n"
"        }\n"
"    }\n"
"    }\n"
"#endif\n"
"\n"
"    if (!using_embedded_sources) {\n"
"        for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"            if (!prismio_toolchain_files[i].runtime && !include_backend) continue;\n"
"\n"
"            if (!find_toolchain_source(source_paths[i], sizeof(source_paths[i]),\n"
"                                       prismio_toolchain_files[i].name)) {\n"
"                fprintf(stderr, \"ERROR: could not find runtime/%s\\n\",\n"
"                        prismio_toolchain_files[i].name);\n"
"                return 1;\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    // The IR is already an object by this point; compile each toolchain source and\n"
"    // link the lot together with it.\n"
"    char* q_program_obj = command_quote_arg(program_obj);\n"
"    char* q_exe = command_quote_arg(exe_file);\n"
"\n"
"    char* objs[PRISMIO_TOOLCHAIN_FILE_COUNT];\n"
"    char* q_objs[PRISMIO_TOOLCHAIN_FILE_COUNT];\n"
"    // A cached object outlives this build and must not be deleted with the\n"
"    // temporaries below.\n"
"    int cached[PRISMIO_TOOLCHAIN_FILE_COUNT];\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        objs[i] = NULL;\n"
"        q_objs[i] = NULL;\n"
"        cached[i] = 0;\n"
"    }\n"
"\n"
"    // The backend half needs LLVM's headers to compile and its C API library to\n"
"    // link. Resolved once, and a failure here is fatal rather than a fallback:\n"
"    // compiling the backend against the stub declarations in prismio_llvm.h and\n"
"    // then linking without -lLLVM-C is exactly what used to happen, and it ends\n"
"    // in several hundred undefined _LLVM* symbols after a full compile.\n"
"    char llvm_include[1024] = \"\";\n"
"    char llvm_lib[1024] = \"\";\n"
"    if (include_backend && !find_llvm_paths(llvm_include, sizeof(llvm_include),\n"
"                                            llvm_lib, sizeof(llvm_lib))) {\n"
"        fprintf(stderr,\n"
"                \"ERROR: no LLVM toolchain configured, and the compiler backend needs one.\\n\"\n"
"                \"       Run: python3 tools/setup_llvm.py\\n\"\n"
"                \"       (or set PRISMIO_LLVM_DIR to an LLVM install with include/llvm-c/Core.h)\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    int command_len = 4096;\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        command_len += (int)strlen(source_paths[i]) * 2 + 64;\n"
"    }\n"
"    command_len += (int)(strlen(q_exe) + strlen(q_program_obj));\n"
"    command_len += (int)(strlen(llvm_include) + strlen(llvm_lib)) * 2 + 256;\n"
"    char* command = (char*)malloc(command_len);\n"
"    int result = 0;\n"
"\n"
"    // One flag string for every source in this build, so the cache key and the\n"
"    // command cannot disagree about what an object was compiled with.\n"
"    char* compile_flags = (char*)malloc(command_len);\n"
"    {\n"
"        char* q_include = command_quote_arg(llvm_include);\n"
"        // The unpacked or in-tree sources include each other by bare name, so\n"
"        // the directory holding them is on the include path too. `-I` on a\n"
"        // quoted path: clang takes `-I <path>` as two arguments.\n"
"        char* source_dir = get_directory(source_paths[include_backend ? 4 : 2]);\n"
"        char* q_source_dir = command_quote_arg(source_dir);\n"
"        // The target flags go in *first*, and into `compile_flags` rather than\n"
"        // into the command, so that they reach the object cache key: two\n"
"        // targets share one source and one set of -D flags, and an object built\n"
"        // for one linked into the other is a silent, genuinely nasty failure.\n"
"        char* target = target_clang_flags();\n"
"        // -g reaches the toolchain's C sources as well, so a backtrace that\n"
"        // leaves generated code does not stop at `str_concat` with no file or\n"
"        // line. Deliberately *not* paired with -O0 the way the program object is\n"
"        // (compile_ir_to_object): there, -O0 exists because a Prismio local\n"
"        // folded into a register is a local the debugger cannot print, and that\n"
"        // is the whole feature. Here what is wanted is a named frame with a\n"
"        // source line in a trace, which -O2 -g gives; building the runtime at\n"
"        // -O0 would slow every `-g` build's execution to improve inspection of\n"
"        // code nobody is stepping through. It costs compile time, not run time.\n"
"        //\n"
"        // In `compile_flags` rather than in the command, so the object cache\n"
"        // keys on it: a -g and a non-g object must not share an entry.\n"
"        snprintf(compile_flags, command_len, \"%s%s-O2 -Wno-deprecated-declarations %s%s%s%s%s%s\",\n"
"                 target,\n"
"                 g_debug_info ? \"-g \" : \"\",\n"
"                 g_verify_mode ? \"-DPRISMIO_AIF_VERIFY \" : \"\",\n"
"                 include_backend ? \"-DPRISMIO_LLVM_REAL_HEADERS -I \" : \"\",\n"
"                 include_backend ? q_include : \"\",\n"
"                 include_backend ? \" -I \" : \"\",\n"
"                 include_backend ? q_source_dir : \"\",\n"
"                 include_backend ? \" \" : \"\");\n"
"        free(target);\n"
"        free(q_include);\n"
"        free(q_source_dir);\n"
"        free(source_dir);\n"
"    }\n"
"\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT && result == 0; i++) {\n"
"        if (!prismio_toolchain_files[i].compiled) continue;\n"
"        if (!prismio_toolchain_files[i].runtime && !include_backend) continue;\n"
"\n"
"        const char* role = prismio_toolchain_files[i].role;\n"
"        char* entry = NULL;\n"
"        if (object_cache_disabled()) {\n"
"            // Said separately from a miss: \"the cache was not consulted\" and\n"
"            // \"the cache was consulted and had nothing\" are different facts, and\n"
"            // a bypass that reported a miss would be indistinguishable from a\n"
"            // bypass that did not bypass.\n"
"            if (object_cache_trace()) fprintf(stderr, \"[objcache off] %s\\n\", role);\n"
"        } else {\n"
"            entry = object_cache_path(role, source_paths[i], compile_flags, source_paths);\n"
"\n"
"            if (entry && file_exists(entry)) {\n"
"                if (object_cache_trace()) fprintf(stderr, \"[objcache hit] %s\\n\", role);\n"
"                objs[i] = entry;\n"
"                q_objs[i] = command_quote_arg(entry);\n"
"                cached[i] = 1;\n"
"                continue;\n"
"            }\n"
"            if (object_cache_trace()) fprintf(stderr, \"[objcache miss] %s\\n\", role);\n"
"        }\n"
"\n"
"        // Compiled to a pid-qualified temporary *in the cache directory* and\n"
"        // moved into place, never written at the cache path directly: two builds\n"
"        // racing on one entry would otherwise link a half-written object. (The\n"
"        // profile race in runWorkloadProfile is the same mistake made the other\n"
"        // way round.) See object_cache_temp_path for why the temporary has to be\n"
"        // a sibling rather than a file beside the output.\n"
"        objs[i] = entry ? object_cache_temp_path(entry)\n"
"                        : compiler_temp_obj_path(exe_file, role);\n"
"        q_objs[i] = command_quote_arg(objs[i]);\n"
"        char* q_src = command_quote_arg(source_paths[i]);\n"
"        // -O2 here matters more than it does on the program's own IR: this is\n"
"        // where list_get, list_push and the allocator live, and a user program\n"
"        // calls them millions of times. Compiling them at -O0 was worth more of\n"
"        // the corpus gap than the missing IR pipeline was (RESULTS-xlang 3.1).\n"
"        snprintf(command, command_len, \"clang %s-c %s -o %s\",\n"
"                 compile_flags, q_src, q_objs[i]);\n"
"        if (run_build_command(command) != 0) result = 1;\n"
"        free(q_src);\n"
"\n"
"        if (result == 0 && entry) {\n"
"            // A failed install is not a failed build: link the temporary and\n"
"            // pay for the compile again next time.\n"
"            if (rename(objs[i], entry) == 0) {\n"
"                free(objs[i]);\n"
"                free(q_objs[i]);\n"
"                objs[i] = entry;\n"
"                q_objs[i] = command_quote_arg(entry);\n"
"                cached[i] = 1;\n"
"                entry = NULL;\n"
"            }\n"
"        }\n"
"        if (entry) free(entry);\n"
"    }\n"
"\n"
"    if (result == 0) {\n"
"        char* link_target = target_clang_flags();\n"
"        int written = snprintf(command, command_len, \"clang %s%s\", link_target, q_program_obj);\n"
"        free(link_target);\n"
"        for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"            if (!q_objs[i]) continue;\n"
"            written += snprintf(command + written, command_len - written, \" %s\", q_objs[i]);\n"
"        }\n"
"        written += snprintf(command + written, command_len - written, \" -o %s\", q_exe);\n"
"        if (include_backend) {\n"
"            // The half that was missing. Without it the backend's several\n"
"            // hundred LLVM calls are undefined symbols, after every object has\n"
"            // already been compiled.\n"
"            char* q_lib = command_quote_arg(llvm_lib);\n"
"            snprintf(command + written, command_len - written, \" -L %s -lLLVM-C\", q_lib);\n"
"            free(q_lib);\n"
"        }\n"
"        if (run_build_command(command) != 0) result = 1;\n"
"    }\n"
"\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        if (objs[i] && !cached[i]) delete_file(objs[i]);\n"
"        if (unpacked_paths[i]) delete_file(unpacked_paths[i]);\n"
"    }\n"
"    if (embedded_header) delete_file(embedded_header);\n"
"    if (embedded_dir) PRISMIO_RMDIR(embedded_dir);\n"
"\n"
"    free(compile_flags);\n"
"    free(command);\n"
"    free(q_exe);\n"
"    free(q_program_obj);\n"
"    for (int i = 0; i < PRISMIO_TOOLCHAIN_FILE_COUNT; i++) {\n"
"        if (q_objs[i]) free(q_objs[i]);\n"
"        if (objs[i]) free(objs[i]);\n"
"        if (unpacked_paths[i]) free(unpacked_paths[i]);\n"
"    }\n"
"    if (embedded_header) free(embedded_header);\n"
"    if (embedded_dir) free(embedded_dir);\n"
"\n"
"    return result;\n"
"}\n"
"\n"
"// Mach-O only, and a warning rather than a failure if it does not work.\n"
"//\n"
"// A .dSYM is a copy of debug info that already exists somewhere else, so a\n"
"// program that built and linked is a program that runs. Failing the build\n"
"// because the bundle could not be written would turn a degraded -g into no\n"
"// binary at all. The warning names the tool so the cause is not a mystery.\n"
"static void write_dsym(const char* exe_file) {\n"
"#ifdef __APPLE__\n"
"    char* q_exe = command_quote_arg(exe_file);\n"
"    int len = (int)strlen(q_exe) + 64;\n"
"    char* command = (char*)malloc(len);\n"
"    snprintf(command, len, \"dsymutil %s\", q_exe);\n"
"    if (run_build_command(command) != 0) {\n"
"        fprintf(stderr,\n"
"                \"warning: dsymutil failed; the binary has a debug map but no .dSYM,\\n\"\n"
"                \"         so a debugger will find no source lines for it.\\n\");\n"
"    }\n"
"    free(command);\n"
"    free(q_exe);\n"
"#else\n"
"    (void)exe_file; // ELF: the linker copied the debug sections into the binary\n"
"#endif\n"
"}\n"
"\n"
"// Normal user mode. The program links against the runtime only, so a link failure\n"
"// here is most often someone trying to build the compiler itself -- src/main.psm\n"
"// calls the backend's ir_* functions, which deliberately are not in runtime.lib.\n"
"int compiler_build_executable(const char* ir_file, const char* exe_file) {\n"
"    if (compiler_prepare_output_path(exe_file) != 0) {\n"
"        fprintf(stderr, \"ERROR: could not create output directory\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    char* program_obj = compiler_temp_obj_path(exe_file, \"program\");\n"
"    int result = compile_ir_to_object(ir_file, program_obj);\n"
"\n"
"    if (result == 0) {\n"
"        char runtime_lib[1024];\n"
"        // An installed runtime.lib was compiled without PRISMIO_AIF_VERIFY, so a\n"
"        // verify build cannot use it: half the allocations would be outside the\n"
"        // accounting. Compiling from source is slower and this is a debug mode.\n"
"        // A workload driver skips it too, for the vintage reason at g_workload_mode.\n"
"        int have_runtime_lib = !g_verify_mode && !g_workload_mode\n"
"                               && find_runtime_library(runtime_lib, sizeof(runtime_lib));\n"
"        if (have_runtime_lib) {\n"
"            result = link_against_runtime_library(program_obj, runtime_lib, exe_file);\n"
"        } else {\n"
"            result = build_from_toolchain_sources(program_obj, exe_file, 0, 0);\n"
"        }\n"
"\n"
"        if (result != 0) {\n"
"            // Two different failures, and the note that fits one is actively\n"
"            // misleading for the other.\n"
"            //\n"
"            // A *cross* build with no shipped archive fell back to compiling the\n"
"            // runtime for the named target, which needs a C library for it. With a\n"
"            // --sysroot that provides one -- an Apple SDK, say -- that works, and\n"
"            // it is how x86_64-apple-macos is built here today. With a target that\n"
"            // has no C library at all, wasm32-unknown-unknown being the case that\n"
"            // matters, it cannot: the sources stop at `#include <stdio.h>`. Telling\n"
"            // that user to run `prismio bootstrap` is nonsense -- bootstrap builds\n"
"            // a compiler for the host -- so say what was actually looked for and\n"
"            // where, by the exact name a framework has to ship it under.\n"
"            if (ir_target_is_explicit() && !have_runtime_lib) {\n"
"                fprintf(stderr,\n"
"                        \"\\nNOTE: no runtime library was found for --target %s, so the\\n\"\n"
"                        \"      runtime was compiled from source for that target instead.\\n\"\n"
"                        \"      Ship lib/runtime-%s.a beside the compiler, or pass\\n\"\n"
"                        \"      --sysroot pointing at an SDK that provides a C library for it.\\n\"\n"
"                        \"      A target with no C library of its own cannot be built the\\n\"\n"
"                        \"      second way.\\n\",\n"
"                        ir_target_triple(), ir_target_triple());\n"
"            } else {\n"
"                fprintf(stderr,\n"
"                        \"\\nNOTE: a normal build links against the Prismio runtime only.\\n\"\n"
"                        \"      If you are building the Prismio compiler itself, use:\\n\"\n"
"                        \"          prismio bootstrap %s\\n\"\n"
"                        \"      which also links the compiler backend (the ir_* functions)\\n\"\n"
"                        \"      and the LLVM C API they call.\\n\",\n"
"                        \"src/main.psm\");\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    // Before the object goes away, and only while it is still there to walk. See\n"
"    // g_debug_info: on Mach-O the executable carries a debug map, not DWARF, and\n"
"    // the DWARF it points at is in the object file the next line deletes.\n"
"    if (result == 0 && g_debug_info && target_is_mach_o()) write_dsym(exe_file);\n"
"\n"
"    delete_file(program_obj);\n"
"    free(program_obj);\n"
"    return result;\n"
"}\n"
"\n"
"// Bootstrap / compiler-development mode.\n"
"//\n"
"// Always builds against the repository sources and never against an installed\n"
"// toolchain, so an edit to runtime/*.c shows up in the very next compiler\n"
"// generation. That guarantee is what the mode exists for, and it is why this is a\n"
"// separate entry point selected by the `bootstrap` command rather than a flag or an\n"
"// environment variable read somewhere inside the build.\n"
"//\n"
"// **This could not link a compiler between the move to the LLVM C API and\n"
"// 2026-08-17**, and nothing noticed because nothing in the tree runs it: CI and\n"
"// every session use tools/bootstrap.sh. The link line was `clang <objects> -o\n"
"// <exe>` with no `-L` and no `-lLLVM-C`, so a full compile ended in several\n"
"// hundred undefined `_LLVM*` symbols \342\200\224 and `compiler_build_executable` printed a\n"
"// NOTE recommending this command, which made it a signpost pointing at a trap.\n"
"//\n"
"// It resolves LLVM the same way and from the same two places the scripts do\n"
"// (find_llvm_paths), so there is one answer to \"where is LLVM\" rather than two\n"
"// that can drift. `run_bootstrap_command_test` builds a compiler through this\n"
"// path and requires its IR to match the one that built it, which is what stops\n"
"// the drift being silent next time.\n"
"int compiler_bootstrap_executable(const char* ir_file, const char* exe_file) {\n"
"    if (compiler_prepare_output_path(exe_file) != 0) {\n"
"        fprintf(stderr, \"ERROR: could not create output directory\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    char probe[1024];\n"
"    if (!find_toolchain_source(probe, sizeof(probe), \"lang_runtime.c\")) {\n"
"        fprintf(stderr,\n"
"                \"ERROR: bootstrap needs the Prismio repository sources.\\n\"\n"
"                \"       Could not find runtime/lang_runtime.c relative to the compiler\\n\"\n"
"                \"       or the current directory. Run this from a Prismio checkout.\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    char* program_obj = compiler_temp_obj_path(exe_file, \"program\");\n"
"    int result = compile_ir_to_object(ir_file, program_obj);\n"
"\n"
"    if (result == 0) {\n"
"        // include_backend = 1: the artifact being produced is a compiler.\n"
"        result = build_from_toolchain_sources(program_obj, exe_file, 1, 1);\n"
"    }\n"
"\n"
"    // The same reason as in compiler_build_executable, and it was missing here:\n"
"    // on Mach-O the executable carries a debug map rather than DWARF, and the\n"
"    // DWARF it points at lives in the object file the next line deletes. Without\n"
"    // this, `prismio bootstrap -g` emitted every byte of the metadata and then\n"
"    // threw away the half describing the compiler's own code -- the runtime's C\n"
"    // frames would still resolve, because their objects are in the object cache\n"
"    // and outlive the build, and a Prismio frame would not.\n"
"    if (result == 0 && g_debug_info && target_is_mach_o()) write_dsym(exe_file);\n"
"\n"
"    delete_file(program_obj);\n"
"    free(program_obj);\n"
"    return result;\n"
"}\n"
"\n"
"// The path in the *command* position needs more care than one in an argument\n"
"// position, which is why this does not just quote and go.\n"
"//\n"
"// On Windows, `prismio run app.psm -o build/app.exe` failed outright: cmd.exe\n"
"// reads `build/app.exe` as the command `build` with the switch `/app.exe`, even\n"
"// quoted. It then reported \"Program exited with failure\" -- blaming the compiled\n"
"// program for a mistake the compiler made invoking it. A forward slash in `-o`\n"
"// is a completely ordinary thing to write, so normalise instead of rejecting.\n"
"//\n"
"// Everywhere else the separator is left alone: llc and clang take forward\n"
"// slashes happily, and only the command position is parsed by the shell this way.\n"
"static char* run_command_path(const char* exe_file) {\n"
"    size_t len = strlen(exe_file);\n"
"    // Room for a leading \"./\" (or \".\\\") if the path has no directory part.\n"
"    char* path = (char*)malloc(len + 3);\n"
"    if (!path) return NULL;\n"
"\n"
"    int has_separator = 0;\n"
"    for (size_t i = 0; i < len; i++) {\n"
"        if (exe_file[i] == '/' || exe_file[i] == '\\\\') has_separator = 1;\n"
"    }\n"
"\n"
"    size_t out = 0;\n"
"    // A bare name would otherwise be looked up on PATH first, which can run a\n"
"    // different program with the same name than the one just built.\n"
"    if (!has_separator) {\n"
"        path[out++] = '.';\n"
"        path[out++] = PRISMIO_PATH_SEP;\n"
"    }\n"
"\n"
"    for (size_t i = 0; i < len; i++) {\n"
"        char c = exe_file[i];\n"
"        path[out++] = (c == '/' || c == '\\\\') ? PRISMIO_PATH_SEP : c;\n"
"    }\n"
"    path[out] = '\\0';\n"
"    return path;\n"
"}\n"
"\n"
"// ============================================\n"
"// LAYOUT 3.2 -- running a workload at build time\n"
"//\n"
"// The whole of the sandbox, and it is smaller than the clause makes it sound\n"
"// because this language's surface is small. W3 names three effects to stub:\n"
"// network, absolute filesystem paths, and environment access. Prismio's runtime\n"
"// exposes none of them -- str_*, list_*, print and the allocators, and that is\n"
"// the list. What a program *can* do is declare an `extern fn` for any symbol the\n"
"// C library happens to export, which is the real hole, and it is closed on the\n"
"// other side: codegen gives every extern the runtime does not define a body of\n"
"// rt_workload_stub instead of a link (see generateWorkloadStubs). So by the time\n"
"// a driver runs, the only foreign code it can reach is the Prismio runtime.\n"
"//\n"
"// That leaves what this function owns: argv, the working directory, and time.\n"
"//\n"
"//  - **argv is empty.** cli_arg() reads the prismio_argv global, which a driver\n"
"//    never fills, so a workload cannot branch on the compiler's own command line\n"
"//    and produce a profile that depends on how the build was invoked.\n"
"//  - **The working directory is the output directory**, not the user's. A\n"
"//    relative path a workload opens through a stubbed extern goes nowhere, and\n"
"//    the profile lands beside the other build temporaries.\n"
"//  - **Time is bounded.** W2 lists \"times out\" as a fallback case, so it has to\n"
"//    be a case that can happen: a workload with an unbounded loop must warn and\n"
"//    fall back rather than hang the build forever.\n"
"//\n"
"// The timeout is enforced with the platform's own tool rather than by forking:\n"
"// `timeout` on Linux, and on macOS the same via a subshell watchdog, because\n"
"// coreutils' timeout is not installed by default there. A missing watchdog is\n"
"// not fatal -- the run simply is not bounded, which is the pre-existing\n"
"// behaviour of every other build command this file issues.\n"
"int compiler_run_workload(const char* exe_file, int timeout_seconds) {\n"
"    char* normalized = run_command_path(exe_file);\n"
"    if (!normalized) return 1;\n"
"\n"
"    char* q_exe = command_quote_arg(normalized);\n"
"    int command_len = (int)strlen(q_exe) + 128;\n"
"    char* command = (char*)malloc(command_len);\n"
"\n"
"#if defined(_WIN32)\n"
"    // No portable watchdog in cmd.exe. Recorded rather than faked: on Windows a\n"
"    // workload that hangs hangs the build, and the fix is a job object, which is\n"
"    // more platform code than this feature has earned until someone hits it.\n"
"    (void)timeout_seconds;\n"
"    snprintf(command, command_len, \"%s\", q_exe);\n"
"#else\n"
"    // `sh -c 'cmd & p=$!; (sleep N; kill $p) & wait $p'` is the portable form.\n"
"    // Using it unconditionally rather than probing for coreutils keeps one code\n"
"    // path on both Unixes.\n"
"    //\n"
"    // **The watchdog's redirections are load-bearing and were not obvious.** The\n"
"    // subshell inherits this process's stdout and stderr, which for any caller\n"
"    // that captures our output is a pipe. A reader waits for EOF, and EOF needs\n"
"    // *every* writer to close -- so a driver that finished in 40 ms still left\n"
"    // the reader blocked until the `sleep` expired, turning the timeout into a\n"
"    // floor on every workload build instead of a ceiling. It surfaced as the\n"
"    // test suite hanging with no process using any CPU.\n"
"    snprintf(command, command_len,\n"
"             \"sh -c '%s & p=$!; { sleep %d; kill $p; } >/dev/null 2>&1 </dev/null & w=$!; \"\n"
"             \"wait $p; s=$?; kill $w 2>/dev/null; exit $s'\",\n"
"             q_exe, timeout_seconds > 0 ? timeout_seconds : 60);\n"
"#endif\n"
"\n"
"    int result = run_build_command(command);\n"
"\n"
"    free(command);\n"
"    free(q_exe);\n"
"    free(normalized);\n"
"    return result;\n"
"}\n"
"\n"
"int compiler_run_executable(const char* exe_file) {\n"
"    char* normalized = run_command_path(exe_file);\n"
"    if (!normalized) return 1;\n"
"\n"
"    char* q_exe = command_quote_arg(normalized);\n"
"    int command_len = (int)strlen(q_exe) + 8;\n"
"    char* command = (char*)malloc(command_len);\n"
"\n"
"    snprintf(command, command_len, \"%s\", q_exe);\n"
"    int result = run_build_command(command);\n"
"\n"
"    free(command);\n"
"    free(q_exe);\n"
"    free(normalized);\n"
"    return result;\n"
"}\n"
;

static const char prismio_embedded_ir_symbols_c[] =
"// ============================================================================\n"
"// Compiler symbol tables and ownership bookkeeping.\n"
"//\n"
"// These are the frontend's own data structures -- what a struct's fields are,\n"
"// which names are globals, what type each binding has, which values have been\n"
"// moved from or borrowed, and where break/continue jump to. None of it is\n"
"// backend state: it describes the program being compiled, not the IR being\n"
"// produced.\n"
"//\n"
"// It used to live in llvm-bridge.c purely because that was the only C file the\n"
"// frontend already talked to. That became a problem the moment a second backend\n"
"// existed: linking the LLVM C API backend left every one of these undefined,\n"
"// even though none of them have anything to do with emitting IR. They are\n"
"// shared here so both backends link against the same copy and neither owns it.\n"
"//\n"
"// Every table was previously a fixed array of char[64] that truncated names at\n"
"// 63 characters and silently stopped recording once full. Both were latent\n"
"// silent-wrong-answer bugs rather than theoretical ones: mangled overload\n"
"// symbols in this compiler's own source already reach 77 characters, so two\n"
"// overloads sharing a long prefix would have been recorded as the same symbol\n"
"// and one would have been given the other's return type -- with no diagnostic,\n"
"// at any point. Names are now interned at full length and every table grows,\n"
"// so neither failure mode exists.\n"
"// ============================================================================\n"
"\n"
"#include <stdio.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"// The compiler cannot continue meaningfully past an allocation failure, and\n"
"// pretending otherwise is how the old silent truncation happened. Say what\n"
"// broke and stop.\n"
"static void symbols_oom(const char* what) {\n"
"    fprintf(stderr, \"internal error: out of memory growing %s\\n\", what);\n"
"    fflush(stderr);\n"
"    exit(1);\n"
"}\n"
"\n"
"static void* xmalloc(size_t n, const char* what) {\n"
"    void* p = malloc(n);\n"
"    if (!p) symbols_oom(what);\n"
"    return p;\n"
"}\n"
"\n"
"static void* xrealloc(void* p, size_t n, const char* what) {\n"
"    void* q = realloc(p, n);\n"
"    if (!q) symbols_oom(what);\n"
"    return q;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Name interning\n"
"//\n"
"// Every name the tables hold is stored once, at full length, and referred to by\n"
"// a canonical pointer. Two benefits: nothing is ever truncated, and a lookup\n"
"// compares pointers instead of running strcmp against every entry -- which\n"
"// matters because find_binding() is called once per identifier in the program\n"
"// and scans backwards over the whole binding table.\n"
"//\n"
"// Interned strings live for the life of the process. There is nothing to free:\n"
"// a compiler run ends when compilation does.\n"
"// ============================================================================\n"
"\n"
"#define INTERN_BUCKETS 4096\n"
"\n"
"typedef struct InternNode {\n"
"    struct InternNode* next;\n"
"    unsigned hash;\n"
"    char text[1]; // over-allocated to hold the whole name\n"
"} InternNode;\n"
"\n"
"static InternNode* intern_buckets[INTERN_BUCKETS];\n"
"\n"
"static unsigned hash_str(const char* s) {\n"
"    // FNV-1a. Cheap, and good enough for identifiers.\n"
"    unsigned h = 2166136261u;\n"
"    while (*s) {\n"
"        h ^= (unsigned char)*s++;\n"
"        h *= 16777619u;\n"
"    }\n"
"    return h;\n"
"}\n"
"\n"
"const char* ir_intern(const char* name) {\n"
"    if (!name) name = \"\";\n"
"\n"
"    unsigned h = hash_str(name);\n"
"    unsigned bucket = h & (INTERN_BUCKETS - 1);\n"
"\n"
"    for (InternNode* n = intern_buckets[bucket]; n; n = n->next) {\n"
"        if (n->hash == h && strcmp(n->text, name) == 0) return n->text;\n"
"    }\n"
"\n"
"    size_t len = strlen(name);\n"
"    InternNode* n = (InternNode*)xmalloc(sizeof(InternNode) + len, \"the name table\");\n"
"    n->hash = h;\n"
"    memcpy(n->text, name, len + 1);\n"
"    n->next = intern_buckets[bucket];\n"
"    intern_buckets[bucket] = n;\n"
"    return n->text;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Loop context stack -- break/continue targets, supports nesting\n"
"// ============================================================================\n"
"\n"
"#define MAX_LOOP_DEPTH 256\n"
"\n"
"static int loop_continue_stack[MAX_LOOP_DEPTH];\n"
"static int loop_break_stack[MAX_LOOP_DEPTH];\n"
"static int loop_depth = 0;\n"
"\n"
"void ir_loop_push(int continue_label, int break_label) {\n"
"    if (loop_depth >= MAX_LOOP_DEPTH) {\n"
"        fprintf(stderr, \"internal error: loops nested more than %d deep\\n\", MAX_LOOP_DEPTH);\n"
"        exit(1);\n"
"    }\n"
"    loop_continue_stack[loop_depth] = continue_label;\n"
"    loop_break_stack[loop_depth] = break_label;\n"
"    loop_depth++;\n"
"}\n"
"\n"
"void ir_loop_pop(void) {\n"
"    if (loop_depth > 0) loop_depth--;\n"
"}\n"
"\n"
"int ir_loop_continue_label(void) {\n"
"    return loop_depth > 0 ? loop_continue_stack[loop_depth - 1] : -1;\n"
"}\n"
"\n"
"int ir_loop_break_label(void) {\n"
"    return loop_depth > 0 ? loop_break_stack[loop_depth - 1] : -1;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// A growable list of interned names, shared by the several tables that are\n"
"// exactly that (globals, moved-from values, borrowed values).\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    const char** items;\n"
"    int count;\n"
"    int capacity;\n"
"    const char* what; // named in the message if growing it fails\n"
"} NameList;\n"
"\n"
"static void namelist_add(NameList* list, const char* name) {\n"
"    if (list->count == list->capacity) {\n"
"        int next = list->capacity ? list->capacity * 2 : 64;\n"
"        list->items = (const char**)xrealloc(list->items, (size_t)next * sizeof(char*), list->what);\n"
"        list->capacity = next;\n"
"    }\n"
"    list->items[list->count++] = ir_intern(name);\n"
"}\n"
"\n"
"static int namelist_contains(const NameList* list, const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < list->count; i++) {\n"
"        if (list->items[i] == interned) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Global variable name registry\n"
"// ============================================================================\n"
"\n"
"static NameList global_names = { NULL, 0, 0, \"the global name table\" };\n"
"\n"
"void ir_register_global_name(const char* name) {\n"
"    if (namelist_contains(&global_names, name)) return;\n"
"    namelist_add(&global_names, name);\n"
"}\n"
"\n"
"int ir_is_global_name(const char* name) {\n"
"    return namelist_contains(&global_names, name);\n"
"}\n"
"\n"
"void ir_reset_globals(void) {\n"
"    global_names.count = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Named type registry -- \"is this identifier a struct, an enum, or neither?\"\n"
"//\n"
"// Separate from the struct registry below, which holds field layouts and is\n"
"// populated by codegen. This one is filled by sema before checking begins and\n"
"// answers only the question a type annotation asks.\n"
"//\n"
"// It exists for speed. sema_annotation_type() used to answer by walking the\n"
"// whole module looking for a matching declaration, once per annotation -- and\n"
"// annotations are read for every parameter of every function, inside a loop over\n"
"// every function. On a 1600-function module that was the difference between\n"
"// quadratic and cubic.\n"
"// ============================================================================\n"
"\n"
"static NameList struct_type_names = { NULL, 0, 0, \"the struct name table\" };\n"
"static NameList enum_type_names = { NULL, 0, 0, \"the enum name table\" };\n"
"\n"
"// kind: 1 = struct, 2 = enum.\n"
"void ir_declare_named_type(const char* name, int kind) {\n"
"    NameList* list = (kind == 1) ? &struct_type_names : &enum_type_names;\n"
"    if (namelist_contains(list, name)) return;\n"
"    namelist_add(list, name);\n"
"}\n"
"\n"
"// 1 = struct, 2 = enum, 0 = not a declared type.\n"
"int ir_named_type_kind(const char* name) {\n"
"    if (namelist_contains(&struct_type_names, name)) return 1;\n"
"    if (namelist_contains(&enum_type_names, name)) return 2;\n"
"    return 0;\n"
"}\n"
"\n"
"void ir_reset_named_types(void) {\n"
"    struct_type_names.count = 0;\n"
"    enum_type_names.count = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Top-level declaration index -- \"which declarations carry this name?\"\n"
"//\n"
"// REQUIREMENTS 16. Every pass that wanted a declaration by name used to walk the\n"
"// module's statement list looking for it, and overload resolution does that once\n"
"// per call site: a module with D declarations and C calls paid D*C. It is the\n"
"// dominant cost on a large module and it is quadratic, so it does not show on\n"
"// the corpus and does show on anything the size of a real program.\n"
"//\n"
"// Filled once per module by index_module_declarations() (src/ast/types.psm),\n"
"// which every pass that reads the index calls first. It is a cache of exactly\n"
"// what a walk of the module would have found, in exactly the order the walk\n"
"// would have found it -- source order matters to two readers: the\n"
"// duplicate-definition diagnostic points at the *first* declaration carrying a\n"
"// symbol, and overload resolution reports the first match.\n"
"//\n"
"// The nodes are AST pointers, which the frontend puns as String. They are\n"
"// stored as opaque addresses and never compared as text -- strcmp on one would\n"
"// compare the bytes of the node.\n"
"// ============================================================================\n"
"\n"
"#define DECL_INDEX_BUCKETS 1024\n"
"\n"
"typedef struct DeclEntry {\n"
"    struct DeclEntry* next;\n"
"    const char* name; // interned\n"
"    const char** nodes;\n"
"    int count;\n"
"    int capacity;\n"
"} DeclEntry;\n"
"\n"
"static DeclEntry* decl_buckets[DECL_INDEX_BUCKETS];\n"
"\n"
"static DeclEntry* decl_entry(const char* name, int create) {\n"
"    const char* interned = ir_intern(name);\n"
"    unsigned bucket = hash_str(interned) & (DECL_INDEX_BUCKETS - 1);\n"
"\n"
"    for (DeclEntry* e = decl_buckets[bucket]; e; e = e->next) {\n"
"        if (e->name == interned) return e;\n"
"    }\n"
"    if (!create) return NULL;\n"
"\n"
"    DeclEntry* e = (DeclEntry*)xmalloc(sizeof(DeclEntry), \"the declaration index\");\n"
"    e->name = interned;\n"
"    e->nodes = NULL;\n"
"    e->count = 0;\n"
"    e->capacity = 0;\n"
"    e->next = decl_buckets[bucket];\n"
"    decl_buckets[bucket] = e;\n"
"    return e;\n"
"}\n"
"\n"
"// Empties the index without freeing it. A second module is compiled in the same\n"
"// process during bootstrap, and reusing the node arrays is both simpler and\n"
"// correct -- the same reason ir_reset_types() keeps its field arrays.\n"
"void ir_reset_decl_index(void) {\n"
"    for (int b = 0; b < DECL_INDEX_BUCKETS; b++) {\n"
"        for (DeclEntry* e = decl_buckets[b]; e; e = e->next) e->count = 0;\n"
"    }\n"
"}\n"
"\n"
"void ir_index_decl(const char* name, const char* node) {\n"
"    DeclEntry* e = decl_entry(name, 1);\n"
"    if (e->count == e->capacity) {\n"
"        int next = e->capacity ? e->capacity * 2 : 4;\n"
"        e->nodes = (const char**)xrealloc((void*)e->nodes, (size_t)next * sizeof(char*),\n"
"                                          \"a declaration index entry\");\n"
"        e->capacity = next;\n"
"    }\n"
"    e->nodes[e->count++] = node;\n"
"}\n"
"\n"
"int ir_decl_count(const char* name) {\n"
"    DeclEntry* e = decl_entry(name, 0);\n"
"    return e ? e->count : 0;\n"
"}\n"
"\n"
"// \"\" rather than NULL for an out-of-range index: the frontend spells \"no node\"\n"
"// as the empty string, and nodeExists() tests exactly that.\n"
"const char* ir_decl_at(const char* name, int index) {\n"
"    DeclEntry* e = decl_entry(name, 0);\n"
"    if (!e || index < 0 || index >= e->count) return \"\";\n"
"    return e->nodes[index];\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Function return types, by mangled symbol\n"
"//\n"
"// This was a binding in the table below, under a \"$fn$\" key that could not\n"
"// collide with a variable name. That made every one of them permanent -- they\n"
"// survive ir_clear_local_var_types() by design -- so find_binding(), which\n"
"// scans the table backwards, walked past one entry per function in the module\n"
"// for every identifier in every function body *and* for every call expression\n"
"// in codegen. Same shape as the walk above: quadratic, invisible on a small\n"
"// program.\n"
"//\n"
"// A table of its own also retires the \"$fn$\" prefix and the str_concat that\n"
"// built one per call site. There is no shared namespace left to disambiguate.\n"
"// ============================================================================\n"
"\n"
"#define FN_RETURN_BUCKETS 1024\n"
"\n"
"typedef struct FnReturn {\n"
"    struct FnReturn* next;\n"
"    const char* symbol; // interned\n"
"    const char* type;   // interned\n"
"} FnReturn;\n"
"\n"
"static FnReturn* fn_return_buckets[FN_RETURN_BUCKETS];\n"
"\n"
"void ir_set_fn_return_type(const char* symbol, const char* type) {\n"
"    const char* interned = ir_intern(symbol);\n"
"    unsigned bucket = hash_str(interned) & (FN_RETURN_BUCKETS - 1);\n"
"\n"
"    for (FnReturn* r = fn_return_buckets[bucket]; r; r = r->next) {\n"
"        if (r->symbol == interned) {\n"
"            // Last writer wins, which is what a shadowing binding did.\n"
"            r->type = ir_intern(type);\n"
"            return;\n"
"        }\n"
"    }\n"
"\n"
"    FnReturn* r = (FnReturn*)xmalloc(sizeof(FnReturn), \"the function return-type table\");\n"
"    r->symbol = interned;\n"
"    r->type = ir_intern(type);\n"
"    r->next = fn_return_buckets[bucket];\n"
"    fn_return_buckets[bucket] = r;\n"
"}\n"
"\n"
"// \"i64\" for an unknown symbol, which is what ir_get_var_type() answered for a\n"
"// \"$fn$\" key that was never set. Same default, deliberately: a different one\n"
"// would change the IR emitted for a call the frontend failed to predeclare.\n"
"const char* ir_get_fn_return_type(const char* symbol) {\n"
"    const char* interned = ir_intern(symbol);\n"
"    unsigned bucket = hash_str(interned) & (FN_RETURN_BUCKETS - 1);\n"
"\n"
"    for (FnReturn* r = fn_return_buckets[bucket]; r; r = r->next) {\n"
"        if (r->symbol == interned) return r->type;\n"
"    }\n"
"    return \"i64\";\n"
"}\n"
"\n"
"// Frees, where ir_reset_decl_index() keeps its entries. The difference is that\n"
"// this table is read with two different vocabularies: sema stores its own type\n"
"// keys and codegen stores LLVM storage types. An entry left behind by sema and\n"
"// not overwritten by codegen -- an extern that a profile build stubs rather than\n"
"// declares -- would be read as a storage type. Emptying it is what kept the two\n"
"// apart when both lived in the binding table.\n"
"void ir_reset_fn_return_types(void) {\n"
"    for (int b = 0; b < FN_RETURN_BUCKETS; b++) {\n"
"        FnReturn* r = fn_return_buckets[b];\n"
"        while (r) {\n"
"            FnReturn* next = r->next;\n"
"            free(r);\n"
"            r = next;\n"
"        }\n"
"        fn_return_buckets[b] = NULL;\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Struct / enum type registry\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    const char* name;\n"
"    const char* type;\n"
"} FieldInfo;\n"
"\n"
"typedef struct {\n"
"    const char* name;\n"
"    FieldInfo* fields;\n"
"    int field_count;\n"
"    int field_capacity;\n"
"} StructInfo;\n"
"\n"
"static StructInfo* struct_infos = NULL;\n"
"static int struct_info_count = 0;\n"
"static int struct_info_capacity = 0;\n"
"\n"
"typedef struct {\n"
"    const char* enum_name;\n"
"    const char* variant_name;\n"
"    int value;\n"
"} EnumVariantInfo;\n"
"\n"
"static EnumVariantInfo* enum_variants = NULL;\n"
"static int enum_variant_count = 0;\n"
"static int enum_variant_capacity = 0;\n"
"\n"
"void ir_reset_types(void) {\n"
"    // The field arrays are kept, not freed: a reset is followed by another\n"
"    // module being compiled in the same process only during bootstrap, and\n"
"    // reusing the allocations is both simpler and correct.\n"
"    for (int i = 0; i < struct_info_count; i++) struct_infos[i].field_count = 0;\n"
"    struct_info_count = 0;\n"
"    enum_variant_count = 0;\n"
"}\n"
"\n"
"static StructInfo* find_struct(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < struct_info_count; i++) {\n"
"        if (struct_infos[i].name == interned) return &struct_infos[i];\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"int ir_is_struct_type_name(const char* name) {\n"
"    return find_struct(name) != NULL;\n"
"}\n"
"\n"
"void ir_register_struct(const char* name) {\n"
"    if (find_struct(name)) return;\n"
"\n"
"    if (struct_info_count == struct_info_capacity) {\n"
"        int next = struct_info_capacity ? struct_info_capacity * 2 : 32;\n"
"        struct_infos = (StructInfo*)xrealloc(struct_infos, (size_t)next * sizeof(StructInfo),\n"
"                                             \"the struct table\");\n"
"        for (int i = struct_info_capacity; i < next; i++) {\n"
"            struct_infos[i].fields = NULL;\n"
"            struct_infos[i].field_count = 0;\n"
"            struct_infos[i].field_capacity = 0;\n"
"        }\n"
"        struct_info_capacity = next;\n"
"    }\n"
"\n"
"    struct_infos[struct_info_count].name = ir_intern(name);\n"
"    struct_infos[struct_info_count].field_count = 0;\n"
"    struct_info_count++;\n"
"}\n"
"\n"
"void ir_register_struct_field(const char* struct_name, const char* field_name, const char* field_type) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (!s) return;\n"
"\n"
"    if (s->field_count == s->field_capacity) {\n"
"        int next = s->field_capacity ? s->field_capacity * 2 : 16;\n"
"        s->fields = (FieldInfo*)xrealloc(s->fields, (size_t)next * sizeof(FieldInfo),\n"
"                                         \"a struct's field table\");\n"
"        s->field_capacity = next;\n"
"    }\n"
"\n"
"    s->fields[s->field_count].name = ir_intern(field_name);\n"
"    s->fields[s->field_count].type = ir_intern(field_type);\n"
"    s->field_count++;\n"
"}\n"
"\n"
"int ir_get_struct_field_index(const char* struct_name, const char* field_name) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (!s) return -1;\n"
"    const char* interned = ir_intern(field_name);\n"
"    for (int j = 0; j < s->field_count; j++) {\n"
"        if (s->fields[j].name == interned) return j;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"const char* ir_get_struct_field_type(const char* struct_name, const char* field_name) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (s) {\n"
"        const char* interned = ir_intern(field_name);\n"
"        for (int j = 0; j < s->field_count; j++) {\n"
"            if (s->fields[j].name == interned) return s->fields[j].type;\n"
"        }\n"
"    }\n"
"    return \"i32\";\n"
"}\n"
"\n"
"// Number of fields registered for a struct, so a backend can build the type\n"
"// body without knowing how the frontend stored it.\n"
"int ir_get_struct_field_count(const char* struct_name) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    return s ? s->field_count : 0;\n"
"}\n"
"\n"
"const char* ir_get_struct_field_type_at(const char* struct_name, int index) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (!s || index < 0 || index >= s->field_count) return \"i32\";\n"
"    return s->fields[index].type;\n"
"}\n"
"\n"
"// The field's *source* name at a physical index. The sibling above answers what\n"
"// occupies slot i; this answers what the programmer called it, which is the half\n"
"// DWARF needs and the only place the two orders have to be reconciled.\n"
"// generateStructDecl registers in the order aif_layout_field chose, so index i\n"
"// here and element i of the LLVM struct are the same field by construction.\n"
"// Empty rather than a placeholder for an unknown index: a made-up field name in\n"
"// a debugger is worse than a gap.\n"
"const char* ir_get_struct_field_name_at(const char* struct_name, int index) {\n"
"    StructInfo* s = find_struct(struct_name);\n"
"    if (!s || index < 0 || index >= s->field_count) return \"\";\n"
"    return s->fields[index].name;\n"
"}\n"
"\n"
"void ir_register_enum_variant(const char* enum_name, const char* variant_name, int value) {\n"
"    if (enum_variant_count == enum_variant_capacity) {\n"
"        int next = enum_variant_capacity ? enum_variant_capacity * 2 : 128;\n"
"        enum_variants = (EnumVariantInfo*)xrealloc(enum_variants,\n"
"                                                   (size_t)next * sizeof(EnumVariantInfo),\n"
"                                                   \"the enum variant table\");\n"
"        enum_variant_capacity = next;\n"
"    }\n"
"\n"
"    enum_variants[enum_variant_count].enum_name = ir_intern(enum_name);\n"
"    enum_variants[enum_variant_count].variant_name = ir_intern(variant_name);\n"
"    enum_variants[enum_variant_count].value = value;\n"
"    enum_variant_count++;\n"
"}\n"
"\n"
"// The variants of one enum, by position. The table is flat -- every variant of\n"
"// every enum in one array -- so \"index i of this enum\" means the i-th entry\n"
"// whose enum_name matches, not the i-th entry.\n"
"//\n"
"// The pair exists for DWARF: DW_TAG_enumeration_type needs every enumerator, and\n"
"// ir_get_enum_variant answers the other direction (name -> value), which cannot\n"
"// enumerate. Interned names make the comparison a pointer compare.\n"
"int ir_get_enum_variant_count(const char* enum_name) {\n"
"    const char* e = ir_intern(enum_name);\n"
"    int n = 0;\n"
"    for (int i = 0; i < enum_variant_count; i++) {\n"
"        if (enum_variants[i].enum_name == e) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// Empty name and a zero value for an index that is not there, matching\n"
"// ir_get_struct_field_name_at: a made-up enumerator in a debugger is worse than\n"
"// a gap, and the caller checks the name.\n"
"const char* ir_get_enum_variant_name_at(const char* enum_name, int index) {\n"
"    const char* e = ir_intern(enum_name);\n"
"    int n = 0;\n"
"    for (int i = 0; i < enum_variant_count; i++) {\n"
"        if (enum_variants[i].enum_name != e) continue;\n"
"        if (n == index) return enum_variants[i].variant_name;\n"
"        n++;\n"
"    }\n"
"    return \"\";\n"
"}\n"
"\n"
"int ir_get_enum_variant_value_at(const char* enum_name, int index) {\n"
"    const char* e = ir_intern(enum_name);\n"
"    int n = 0;\n"
"    for (int i = 0; i < enum_variant_count; i++) {\n"
"        if (enum_variants[i].enum_name != e) continue;\n"
"        if (n == index) return enum_variants[i].value;\n"
"        n++;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"int ir_get_enum_variant(const char* enum_name, const char* variant_name) {\n"
"    const char* e = ir_intern(enum_name);\n"
"    const char* v = ir_intern(variant_name);\n"
"    for (int i = 0; i < enum_variant_count; i++) {\n"
"        if (enum_variants[i].enum_name == e && enum_variants[i].variant_name == v) {\n"
"            return enum_variants[i].value;\n"
"        }\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Variable type tracking\n"
"// ============================================================================\n"
"\n"
"// Bindings, innermost last.\n"
"//\n"
"// A block pushes a scope on entry and pops it on exit, which simply truncates\n"
"// the table back to where it started. Lookup scans backwards, so the innermost\n"
"// binding of a name wins and an outer one becomes visible again when the inner\n"
"// scope is popped. Before this existed the table was flat and cleared only per\n"
"// function, so a `let` inside an `if` stayed visible after the block ended.\n"
"//\n"
"// Each binding also carries its own slot name -- the identifier codegen uses for\n"
"// the alloca. Two `let x` in sibling blocks are two entries with two distinct\n"
"// slots, which is what stops them sharing one stack allocation sized by\n"
"// whichever appeared first (an i8 slot written with an 8-byte pointer, say).\n"
"//\n"
"// is_global distinguishes a module-level binding from a local, because codegen\n"
"// has to emit @name for one and %slot for the other. Asking a separate registry\n"
"// \"is this name a global?\" was wrong in the presence of shadowing: a local named\n"
"// the same as a global had its writes go to the local slot and its reads come\n"
"// from the global.\n"
"\n"
"#define MAX_SCOPES 1024\n"
"\n"
"typedef struct {\n"
"    const char* name;\n"
"    const char* type;\n"
"    const char* slot;\n"
"    int is_global;\n"
"    int is_mutable;\n"
"    // AIF Level 2: this binding's initialiser allocated a value whose escape\n"
"    // bottoms at the scope holding the binding, so the scope's exits are where\n"
"    // it is freed. Set by codegen from the tier; nothing here decides policy.\n"
"    int is_droppable;\n"
"    // AIF Level 4: which deallocator reclaims it. A list owns a second block --\n"
"    // its element array -- so a plain free on the handle leaks that block, and\n"
"    // the storage type cannot tell you: a list and a string are both `ptr`.\n"
"    int drop_kind;\n"
"} VarBinding;\n"
"\n"
"static VarBinding* var_bindings = NULL;\n"
"static int var_type_count = 0;\n"
"static int var_type_capacity = 0;\n"
"\n"
"static int scope_marks[MAX_SCOPES];\n"
"static int scope_depth = 0;\n"
"\n"
"// Monotonic across a whole module, so a slot name is unique no matter how many\n"
"// blocks declare the same identifier.\n"
"static int slot_serial = 0;\n"
"\n"
"void ir_scope_push(void) {\n"
"    if (scope_depth >= MAX_SCOPES) {\n"
"        fprintf(stderr, \"internal error: blocks nested more than %d deep\\n\", MAX_SCOPES);\n"
"        exit(1);\n"
"    }\n"
"    scope_marks[scope_depth] = var_type_count;\n"
"    scope_depth++;\n"
"}\n"
"\n"
"void ir_scope_pop(void) {\n"
"    if (scope_depth > 0) {\n"
"        scope_depth--;\n"
"        var_type_count = scope_marks[scope_depth];\n"
"    }\n"
"}\n"
"\n"
"// Loop barriers: the binding-table watermark on entry to each loop body.\n"
"//\n"
"// Move checking is per-name and runs over the AST in source order, so it sees a\n"
"// `drop(x)` inside a loop exactly once and concludes the value is consumed once\n"
"// -- while at run time the loop executes it repeatedly. That is a double free\n"
"// the checker could not see. A binding that predates the innermost loop is one\n"
"// the loop did not create, so moving out of it inside the loop is the case that\n"
"// actually repeats.\n"
"static int loop_barriers[MAX_LOOP_DEPTH];\n"
"static int loop_barrier_depth = 0;\n"
"\n"
"void ir_loop_barrier_push(void) {\n"
"    if (loop_barrier_depth < MAX_LOOP_DEPTH) loop_barriers[loop_barrier_depth++] = var_type_count;\n"
"}\n"
"\n"
"void ir_loop_barrier_pop(void) {\n"
"    if (loop_barrier_depth > 0) loop_barrier_depth--;\n"
"}\n"
"\n"
"static int find_binding(const char* name);\n"
"\n"
"// 1 when `name` is bound outside the innermost enclosing loop.\n"
"int ir_binding_predates_loop(const char* name) {\n"
"    if (loop_barrier_depth == 0) return 0;\n"
"    int i = find_binding(name);\n"
"    if (i < 0) return 0;\n"
"    return i < loop_barriers[loop_barrier_depth - 1] ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Scope drop lists (AIF Level 2)\n"
"//\n"
"// A drop list is not a separate structure: the binding table is already a flat\n"
"// array with a watermark per scope, so \"what dies when this scope exits\" is the\n"
"// droppable bindings above that watermark. The same read with a different floor\n"
"// answers it for a `return` (the whole function) and for `break`/`continue` (the\n"
"// loop barrier), which is why those two watermarks already existing matters.\n"
"//\n"
"// Enumeration is reverse construction order, which SPEC's RAII requires: a value\n"
"// may hold a reference to one constructed before it, never after.\n"
"//\n"
"// Whether a binding was *moved* is deliberately not consulted, here or by the\n"
"// caller: move state belongs to sema and is cleared per function before codegen\n"
"// starts. What would have needed it is carried by the facts instead -- see\n"
"// generate_scope_drops.\n"
"// ============================================================================\n"
"\n"
"void ir_mark_droppable(const char* name, int kind) {\n"
"    int i = find_binding(name);\n"
"    if (i >= 0) {\n"
"        var_bindings[i].is_droppable = 1;\n"
"        var_bindings[i].drop_kind = kind;\n"
"    }\n"
"}\n"
"\n"
"int ir_scope_drop_floor(void) {\n"
"    return scope_depth > 0 ? scope_marks[scope_depth - 1] : 0;\n"
"}\n"
"\n"
"// Its own stack rather than loop_barriers above: that one is sema's, pushed\n"
"// while move checking runs, and codegen is a separate walk. Sharing it would\n"
"// have made break/continue read a watermark of 0 and drop the whole function.\n"
"static int drop_barriers[MAX_LOOP_DEPTH];\n"
"static int barrier_regions[MAX_LOOP_DEPTH];\n"
"static int drop_barrier_depth = 0;\n"
"\n"
"// How many `region` blocks are open. A return has to close all of them and a\n"
"// break/continue those the loop did not open, for the same reason each has to\n"
"// run the drops: an arena still on the stack at function exit is never released.\n"
"static int region_depth = 0;\n"
"\n"
"void ir_region_enter(void) { region_depth++; }\n"
"void ir_region_exit(void)  { if (region_depth > 0) region_depth--; }\n"
"int  ir_region_depth(void) { return region_depth; }\n"
"\n"
"int ir_loop_region_depth(void) {\n"
"    return drop_barrier_depth > 0 ? barrier_regions[drop_barrier_depth - 1] : 0;\n"
"}\n"
"\n"
"void ir_drop_barrier_push(void) {\n"
"    if (drop_barrier_depth < MAX_LOOP_DEPTH) {\n"
"        barrier_regions[drop_barrier_depth] = region_depth;\n"
"        drop_barriers[drop_barrier_depth++] = var_type_count;\n"
"    }\n"
"}\n"
"\n"
"void ir_drop_barrier_pop(void) {\n"
"    if (drop_barrier_depth > 0) drop_barrier_depth--;\n"
"}\n"
"\n"
"int ir_loop_drop_floor(void) {\n"
"    return drop_barrier_depth > 0 ? drop_barriers[drop_barrier_depth - 1] : 0;\n"
"}\n"
"\n"
"int ir_drop_count(int floor) {\n"
"    if (floor < 0) floor = 0;\n"
"    int n = 0;\n"
"    for (int i = floor; i < var_type_count; i++) {\n"
"        if (var_bindings[i].is_droppable) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// The i-th droppable binding at or above `floor`, counting from the most\n"
"// recently constructed.\n"
"static int drop_index(int floor, int i) {\n"
"    if (floor < 0) floor = 0;\n"
"    int n = 0;\n"
"    for (int k = var_type_count - 1; k >= floor; k--) {\n"
"        if (!var_bindings[k].is_droppable) continue;\n"
"        if (n == i) return k;\n"
"        n++;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"const char* ir_drop_slot(int floor, int i) {\n"
"    int k = drop_index(floor, i);\n"
"    return k >= 0 ? var_bindings[k].slot : \"\";\n"
"}\n"
"\n"
"const char* ir_drop_type(int floor, int i) {\n"
"    int k = drop_index(floor, i);\n"
"    return k >= 0 ? var_bindings[k].type : \"\";\n"
"}\n"
"\n"
"int ir_drop_kind(int floor, int i) {\n"
"    int k = drop_index(floor, i);\n"
"    return k >= 0 ? var_bindings[k].drop_kind : 0;\n"
"}\n"
"\n"
"static int find_binding(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = var_type_count - 1; i >= 0; i--) {\n"
"        if (var_bindings[i].name == interned) return i;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"static void add_binding(const char* name, const char* type, int is_global) {\n"
"    if (var_type_count == var_type_capacity) {\n"
"        int next = var_type_capacity ? var_type_capacity * 2 : 256;\n"
"        var_bindings = (VarBinding*)xrealloc(var_bindings, (size_t)next * sizeof(VarBinding),\n"
"                                             \"the binding table\");\n"
"        var_type_capacity = next;\n"
"    }\n"
"\n"
"    VarBinding* b = &var_bindings[var_type_count];\n"
"    b->name = ir_intern(name);\n"
"    b->type = ir_intern(type);\n"
"    b->is_global = is_global;\n"
"    b->is_mutable = 0;\n"
"    b->is_droppable = 0;\n"
"    b->drop_kind = 0;\n"
"\n"
"    if (is_global) {\n"
"        // Globals are addressed by their own name (@name), so no renaming.\n"
"        b->slot = b->name;\n"
"    } else {\n"
"        // '.' cannot appear in a Prismio identifier, so a slot name can never\n"
"        // collide with a user variable. Built at full length: truncating here\n"
"        // was how two long distinct names ended up sharing one stack slot.\n"
"        size_t len = strlen(b->name) + 24;\n"
"        char* slot = (char*)xmalloc(len, \"a slot name\");\n"
"        snprintf(slot, len, \"%s.%d\", b->name, slot_serial++);\n"
"        b->slot = ir_intern(slot);\n"
"        free(slot);\n"
"    }\n"
"\n"
"    var_type_count++;\n"
"}\n"
"\n"
"// Declares a binding in the current scope. Each call is a distinct binding, so\n"
"// re-declaring a name shadows rather than overwrites.\n"
"void ir_set_var_type(const char* name, const char* type) {\n"
"    add_binding(name, type, 0);\n"
"}\n"
"\n"
"void ir_set_global_var_type(const char* name, const char* type) {\n"
"    add_binding(name, type, 1);\n"
"}\n"
"\n"
"const char* ir_get_var_type(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].type : \"i64\"; // default if unknown\n"
"}\n"
"\n"
"// The LLVM-level name for the innermost binding of `name`.\n"
"const char* ir_get_var_slot(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].slot : name;\n"
"}\n"
"\n"
"// Whether the innermost binding of `name` is module-level. Shadowing-aware, so\n"
"// a local that happens to share a global's name reports 0.\n"
"int ir_var_is_global(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].is_global : 0;\n"
"}\n"
"\n"
"int ir_has_var_type(const char* name) {\n"
"    return find_binding(name) >= 0;\n"
"}\n"
"\n"
"// `let mut` marks the binding just declared. Assignment to anything not so\n"
"// marked is rejected -- the parser has always recorded `mut`, but nothing read\n"
"// it, so explicit mutability was advertised and unenforced.\n"
"void ir_mark_mutable(const char* name) {\n"
"    int i = find_binding(name);\n"
"    if (i >= 0) var_bindings[i].is_mutable = 1;\n"
"}\n"
"\n"
"int ir_var_is_mutable(const char* name) {\n"
"    int i = find_binding(name);\n"
"    return i >= 0 ? var_bindings[i].is_mutable : 1; // unknown names error elsewhere\n"
"}\n"
"\n"
"void ir_clear_var_types(void) {\n"
"    var_type_count = 0;\n"
"    scope_depth = 0;\n"
"    slot_serial = 0;\n"
"}\n"
"\n"
"// Drops everything a function introduced, keeping module-level bindings and the\n"
"// $fn$ return-type keys. Scopes handle blocks; this handles the function\n"
"// boundary itself.\n"
"void ir_clear_local_var_types(void) {\n"
"    int write = 0;\n"
"    for (int read = 0; read < var_type_count; read++) {\n"
"        if (strncmp(var_bindings[read].name, \"$fn$\", 4) == 0 || var_bindings[read].is_global) {\n"
"            if (write != read) var_bindings[write] = var_bindings[read];\n"
"            write++;\n"
"        }\n"
"    }\n"
"    var_type_count = write;\n"
"    scope_depth = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Move tracking (MVS): names of move-only values that have been moved-from\n"
"// ============================================================================\n"
"\n"
"static NameList moved_names = { NULL, 0, 0, \"the moved-value table\" };\n"
"\n"
"void ir_clear_moved(void) {\n"
"    moved_names.count = 0;\n"
"}\n"
"\n"
"int ir_is_moved(const char* name) {\n"
"    return namelist_contains(&moved_names, name);\n"
"}\n"
"\n"
"void ir_mark_moved(const char* name) {\n"
"    if (ir_is_moved(name)) return;\n"
"    namelist_add(&moved_names, name);\n"
"}\n"
"\n"
"// Moved-from state is tracked per name, but a `let` binds a *fresh* value to that\n"
"// name, so whatever was moved out of the previous binding no longer applies. Without\n"
"// this, reusing an ordinary name (`let t = ...` twice in one function, in different\n"
"// branches) makes every use after the first move a spurious \"use of moved value\".\n"
"void ir_unmark_moved(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < moved_names.count; i++) {\n"
"        if (moved_names.items[i] == interned) {\n"
"            for (int j = i; j < moved_names.count - 1; j++) {\n"
"                moved_names.items[j] = moved_names.items[j + 1];\n"
"            }\n"
"            moved_names.count--;\n"
"            return;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Borrow tracking (MVS): names bound to non-owning (let/inout) parameters\n"
"// ============================================================================\n"
"\n"
"static NameList borrowed_names = { NULL, 0, 0, \"the borrowed-value table\" };\n"
"\n"
"void ir_clear_borrowed(void) {\n"
"    borrowed_names.count = 0;\n"
"}\n"
"\n"
"int ir_is_borrowed(const char* name) {\n"
"    return namelist_contains(&borrowed_names, name);\n"
"}\n"
"\n"
"void ir_mark_borrowed(const char* name) {\n"
"    if (ir_is_borrowed(name)) return;\n"
"    namelist_add(&borrowed_names, name);\n"
"}\n"
"\n"
"// Same reason ir_unmark_moved exists. A `let` binds a fresh value, and AIF Level\n"
"// 4 made borrowing something a `let` can do -- `let p = node.child1` reborrows\n"
"// the field -- so a name that reborrowed once and owns the next time must not\n"
"// keep the first answer.\n"
"void ir_unmark_borrowed(const char* name) {\n"
"    const char* interned = ir_intern(name);\n"
"    for (int i = 0; i < borrowed_names.count; i++) {\n"
"        if (borrowed_names.items[i] == interned) {\n"
"            for (int j = i; j < borrowed_names.count - 1; j++) {\n"
"                borrowed_names.items[j] = borrowed_names.items[j + 1];\n"
"            }\n"
"            borrowed_names.count--;\n"
"            return;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Return tracking\n"
"//\n"
"// Set when a block has emitted its terminator, so the caller knows not to emit\n"
"// a fall-through branch. break/continue reuse it for the same purpose.\n"
"// ============================================================================\n"
"\n"
"static int has_returned = 0;\n"
"\n"
"void ir_set_returned(void) {\n"
"    has_returned = 1;\n"
"}\n"
"\n"
"int ir_has_returned(void) {\n"
"    return has_returned;\n"
"}\n"
"\n"
"void ir_clear_returned(void) {\n"
"    has_returned = 0;\n"
"}\n"
;

static const char prismio_embedded_aif_support_c[] =
"// ============================================================================\n"
"// AIF \342\200\224 the inference engine's data structures and fixed point.\n"
"//\n"
"// AIF (aif/) is Prismio's memory model. The engine assigns every allocation\n"
"// site a tier T0-T4 from four inferred fact domains, and this file holds\n"
"// everything iteration needs: the scope forest, the site table, the points-to\n"
"// graph, the constraint list, and the solver loop itself.\n"
"//\n"
"// WHY THIS IS IN C. The policy lives in src/aif.psm -- which nodes become\n"
"// sites, which transfer rule fires where, what an extern's ownership contract\n"
"// is, how a tier becomes a manifest line. None of that is here. What is here is\n"
"// the container layer: growable bitsets, an interning table, and a hash map\n"
"// from key tuples to ids. Prismio has no generics, no maps and no growable\n"
"// vectors (aif/implementation/COMPILER-AUDIT.md 4.3 calls this the finding that\n"
"// most changes the schedule), so the engine would otherwise be written with\n"
"// parallel arrays and integer indices -- in the one component where a silent\n"
"// bug yields a wrong-tier binary rather than a crash.\n"
"//\n"
"// This is the same split ir_symbols.c already makes for the symbol tables, and\n"
"// it is deliberate rather than expedient: the compiler is written in Prismio,\n"
"// its containers are written in C.\n"
"//\n"
"// SOUNDNESS NOTE. Every fact here only ever *rises* (INFERENCE.md M2). No\n"
"// operation in this file lowers E, A or C, which is what makes the iteration\n"
"// monotone, terminating, and safe to abandon -- see aif_widen().\n"
"// ============================================================================\n"
"\n"
"#include <stdio.h>\n"
"#include <stdint.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"static void aif_oom(const char* what) {\n"
"    fprintf(stderr, \"internal error: out of memory growing %s\\n\", what);\n"
"    fflush(stderr);\n"
"    exit(1);\n"
"}\n"
"\n"
"static void* xmalloc(size_t n, const char* what) {\n"
"    void* p = malloc(n);\n"
"    if (!p) aif_oom(what);\n"
"    return p;\n"
"}\n"
"\n"
"static void* xcalloc(size_t n, size_t sz, const char* what) {\n"
"    void* p = calloc(n ? n : 1, sz);\n"
"    if (!p) aif_oom(what);\n"
"    return p;\n"
"}\n"
"\n"
"static void* xrealloc(void* p, size_t n, const char* what) {\n"
"    void* q = realloc(p, n);\n"
"    if (!q) aif_oom(what);\n"
"    return q;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Fact encodings\n"
"//\n"
"// Escape is a single int so that it fits an array slot and a Prismio `Int`\n"
"// alike: the two top elements are negative, and every Region(s) is the scope id\n"
"// itself. The ordering Region(s) < Caller < Global is not the integer ordering\n"
"// -- escape_join() implements it.\n"
"// ============================================================================\n"
"\n"
"#define AIF_E_GLOBAL (-2)\n"
"#define AIF_E_CALLER (-1)\n"
"\n"
"#define AIF_A_UNIQUE   0\n"
"#define AIF_A_BORROWED 1\n"
"#define AIF_A_SHARED   2\n"
"\n"
"#define AIF_C_ACYCLIC 0\n"
"#define AIF_C_MAYBE   1\n"
"\n"
"// INFERENCE 2.3. Thread affinity: Isolated < Transferred < CrossThread.\n"
"//\n"
"// Vacuous until 2026-08-19 -- the language had no tasks, so every value sat at\n"
"// the bottom and SPEC 4.2's two `T` conjuncts were tautologies this file did\n"
"// not bother to write down. REQUIREMENTS 15 ended that, and the conjuncts are\n"
"// now in derived_tier where the spec puts them.\n"
"//\n"
"// The middle element is the one the whole design is for. `Transferred` means\n"
"// ownership moved between tasks but only one may reach the value at a time, so\n"
"// the transfer point is itself a synchronisation edge and a release/acquire\n"
"// pair there is sufficient -- the count stays **non-atomic**. Only CrossThread\n"
"// forces atomics, and SPEC 11 item 10 exists to keep that column empty.\n"
"#define AIF_T_ISOLATED    0\n"
"#define AIF_T_TRANSFERRED 1\n"
"#define AIF_T_CROSS       2\n"
"\n"
"// Site kinds. Mirrors what src/aif.psm classifies a type as; the solver only\n"
"// cares that kind 0 is a struct (the T0 clause and the copy rule both test it).\n"
"// LAYOUT 4. Assumed trip count of a loop with no profile, and the one estimator\n"
"// both static profiles share -- arena placement's allocs_in(s) and the layout\n"
"// search's access counts. One definition, so they cannot drift apart.\n"
"#define AIF_LOOP_ITERS      16\n"
"\n"
"#define AIF_K_STRUCT 0\n"
"#define AIF_K_STRING 1\n"
"#define AIF_K_ARRAY  2\n"
"#define AIF_K_LIST   3\n"
"#define AIF_K_OPAQUE 4\n"
"\n"
"// ============================================================================\n"
"// Growable bitsets\n"
"//\n"
"// Both halves of the solver state are sets of small integers: a points-to node\n"
"// holds a set of sites, and a site holds the set of nodes referencing it.\n"
"// Bitsets make union and subset one word-loop each, which keeps the round cost\n"
"// proportional to the graph rather than to the constraint list.\n"
"// ============================================================================\n"
"\n"
"typedef unsigned long long Word;\n"
"#define WORD_BITS 64\n"
"\n"
"typedef struct {\n"
"    Word* w;\n"
"    int nwords;\n"
"} Bits;\n"
"\n"
"static void bits_ensure(Bits* b, int bit, const char* what) {\n"
"    int need = bit / WORD_BITS + 1;\n"
"    if (need <= b->nwords) return;\n"
"    int grow = b->nwords ? b->nwords * 2 : 8;\n"
"    if (grow < need) grow = need;\n"
"    b->w = (Word*)xrealloc(b->w, (size_t)grow * sizeof(Word), what);\n"
"    memset(b->w + b->nwords, 0, (size_t)(grow - b->nwords) * sizeof(Word));\n"
"    b->nwords = grow;\n"
"}\n"
"\n"
"static int bits_test(const Bits* b, int bit) {\n"
"    int wi = bit / WORD_BITS;\n"
"    if (bit < 0 || wi >= b->nwords) return 0;\n"
"    return (int)((b->w[wi] >> (bit % WORD_BITS)) & 1u);\n"
"}\n"
"\n"
"// Returns 1 only when the bit was absent. The solver's `changed` flag is the\n"
"// disjunction of every such return, so an update that adds nothing must report\n"
"// nothing -- otherwise the loop never terminates.\n"
"static int bits_set(Bits* b, int bit, const char* what) {\n"
"    bits_ensure(b, bit, what);\n"
"    int wi = bit / WORD_BITS;\n"
"    Word m = (Word)1 << (bit % WORD_BITS);\n"
"    if (b->w[wi] & m) return 0;\n"
"    b->w[wi] |= m;\n"
"    return 1;\n"
"}\n"
"\n"
"static void bits_clear(Bits* b) {\n"
"    if (b->nwords) memset(b->w, 0, (size_t)b->nwords * sizeof(Word));\n"
"}\n"
"\n"
"static int bits_is_empty(const Bits* b) {\n"
"    for (int i = 0; i < b->nwords; i++) {\n"
"        if (b->w[i]) return 0;\n"
"    }\n"
"    return 1;\n"
"}\n"
"\n"
"// dst |= src, reporting whether dst grew.\n"
"static int bits_or(Bits* dst, const Bits* src, const char* what) {\n"
"    int changed = 0;\n"
"    for (int i = 0; i < src->nwords; i++) {\n"
"        if (!src->w[i]) continue;\n"
"        bits_ensure(dst, i * WORD_BITS, what);\n"
"        Word before = dst->w[i];\n"
"        Word after = before | src->w[i];\n"
"        if (after != before) {\n"
"            dst->w[i] = after;\n"
"            changed = 1;\n"
"        }\n"
"    }\n"
"    return changed;\n"
"}\n"
"\n"
"static int bits_count_at_least_two(const Bits* b) {\n"
"    int seen = 0;\n"
"    for (int i = 0; i < b->nwords; i++) {\n"
"        Word x = b->w[i];\n"
"        while (x) {\n"
"            x &= x - 1;\n"
"            if (++seen >= 2) return 1;\n"
"        }\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"static void bits_free(Bits* b) {\n"
"    free(b->w);\n"
"    b->w = NULL;\n"
"    b->nwords = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Int vectors\n"
"//\n"
"// Set membership is a bitset, but the solver's rules need to *enumerate* a set,\n"
"// sometimes two of them nested. Materialising a bitset into a plain int array\n"
"// keeps that a pair of ordinary loops. The buffers are reused across rounds,\n"
"// so this allocates a handful of times for the whole run.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int* v;\n"
"    int len, cap;\n"
"} IntVec;\n"
"\n"
"static void vec_push(IntVec* iv, int x, const char* what) {\n"
"    if (iv->len == iv->cap) {\n"
"        iv->cap = iv->cap ? iv->cap * 2 : 64;\n"
"        iv->v = (int*)xrealloc(iv->v, (size_t)iv->cap * sizeof(int), what);\n"
"    }\n"
"    iv->v[iv->len++] = x;\n"
"}\n"
"\n"
"// Portable count-trailing-zeros. A branchless intrinsic exists on every\n"
"// compiler that matters and on none of them by the same name, and this runs\n"
"// once per set bit rather than once per word, so a six-step binary search costs\n"
"// nothing measurable next to the round it sits inside.\n"
"static int ctz64(Word x) {\n"
"    int n = 0;\n"
"    if (!(x & 0xFFFFFFFFull)) { x >>= 32; n += 32; }\n"
"    if (!(x & 0xFFFFull))     { x >>= 16; n += 16; }\n"
"    if (!(x & 0xFFull))       { x >>= 8;  n += 8;  }\n"
"    if (!(x & 0xFull))        { x >>= 4;  n += 4;  }\n"
"    if (!(x & 0x3ull))        { x >>= 2;  n += 2;  }\n"
"    if (!(x & 0x1ull))        { n += 1; }\n"
"    return n;\n"
"}\n"
"\n"
"static void bits_to_vec(const Bits* b, IntVec* out) {\n"
"    out->len = 0;\n"
"    for (int wi = 0; wi < b->nwords; wi++) {\n"
"        for (Word x = b->w[wi]; x; x &= x - 1) {\n"
"            vec_push(out, wi * WORD_BITS + ctz64(x), \"AIF bit enumeration\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// String interning\n"
"//\n"
"// Type names, field names and variable names all become integer ids, because\n"
"// every key in the points-to graph is a tuple of small integers and comparing\n"
"// tuples of ints is what makes the key map cheap. Id 0 is always \"\".\n"
"// ============================================================================\n"
"\n"
"#define AIF_INTERN_BUCKETS 8192\n"
"\n"
"typedef struct InternNode {\n"
"    struct InternNode* next;\n"
"    unsigned hash;\n"
"    int id;\n"
"    char text[1];   // over-allocated to hold the whole name\n"
"} InternNode;\n"
"\n"
"static InternNode* intern_buckets[AIF_INTERN_BUCKETS];\n"
"static const char** intern_by_id;\n"
"static int intern_count, intern_cap;\n"
"\n"
"static unsigned hash_str(const char* s) {\n"
"    unsigned h = 2166136261u;   // FNV-1a\n"
"    while (*s) {\n"
"        h ^= (unsigned char)*s++;\n"
"        h *= 16777619u;\n"
"    }\n"
"    return h;\n"
"}\n"
"\n"
"int aif_intern(const char* s) {\n"
"    if (!s) s = \"\";\n"
"    unsigned h = hash_str(s);\n"
"    unsigned bucket = h & (AIF_INTERN_BUCKETS - 1);\n"
"\n"
"    for (InternNode* n = intern_buckets[bucket]; n; n = n->next) {\n"
"        if (n->hash == h && strcmp(n->text, s) == 0) return n->id;\n"
"    }\n"
"\n"
"    size_t len = strlen(s);\n"
"    InternNode* n = (InternNode*)xmalloc(sizeof(InternNode) + len, \"AIF interned names\");\n"
"    memcpy(n->text, s, len + 1);\n"
"    n->hash = h;\n"
"    n->next = intern_buckets[bucket];\n"
"    intern_buckets[bucket] = n;\n"
"\n"
"    if (intern_count == intern_cap) {\n"
"        intern_cap = intern_cap ? intern_cap * 2 : 256;\n"
"        intern_by_id = (const char**)xrealloc(intern_by_id,\n"
"            (size_t)intern_cap * sizeof(char*), \"AIF name index\");\n"
"    }\n"
"    n->id = intern_count;\n"
"    intern_by_id[intern_count++] = n->text;\n"
"    return n->id;\n"
"}\n"
"\n"
"const char* aif_str(int id) {\n"
"    if (id < 0 || id >= intern_count) return \"\";\n"
"    return intern_by_id[id];\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Scope forest\n"
"//\n"
"// Each function body is a root; a block nests inside its parent. The join of\n"
"// two Region values is their least common ancestor, which exists because scopes\n"
"// nest (INFERENCE 2.1). Scopes in different functions have no common region --\n"
"// scope_lca reports -1 and escape_join falls back to Caller.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int parent;\n"
"    int depth;\n"
"    int owner;      // function id\n"
"    // SPEC 5.2. -1 unless a `region` statement opened this scope, in which case\n"
"    // it is the interned name -- which is what the manifest's `region:<name>`\n"
"    // placement reports, and how codegen knows an arena is live here.\n"
"    int region_name;\n"
"    // LAYOUT 7.1. Set by aif_place_arenas when the cost model chooses this scope,\n"
"    // or unconditionally when `region` pinned it. Codegen reads it through the\n"
"    // block node to know where to bracket arena_push/arena_pop.\n"
"    int arena;\n"
"    // How many loops enclose this scope, within its function. The weight a site\n"
"    // contributes to its arena's benefit is one allocation per entry of the\n"
"    // arena, times the trip count of every loop between them.\n"
"    int loop_depth;\n"
"    const void* node;   // the BLOCK this scope came from, for the codegen lookup\n"
"    // REQUIREMENTS 19. A byte cap asserted by `region name pin(N)`, or 0. The\n"
"    // span travels with it so a refuted budget can underline the annotation\n"
"    // rather than the block.\n"
"    long budget;\n"
"    int budget_file, budget_line, budget_col;\n"
"    // SPEC 5.2's diagnostic. Recorded for every `region`, not only for one that\n"
"    // carries a budget, because the warning that matters most fires on the plain\n"
"    // form -- a region that serves nothing and says nothing.\n"
"    int region_file, region_line, region_col;\n"
"} Scope;\n"
"\n"
"static Scope* scopes;\n"
"static int scope_count, scope_cap;\n"
"\n"
"int aif_scope_new(int parent, int owner) {\n"
"    if (scope_count == scope_cap) {\n"
"        scope_cap = scope_cap ? scope_cap * 2 : 256;\n"
"        scopes = (Scope*)xrealloc(scopes, (size_t)scope_cap * sizeof(Scope), \"AIF scopes\");\n"
"    }\n"
"    Scope* s = &scopes[scope_count];\n"
"    s->parent = parent;\n"
"    s->owner = owner;\n"
"    s->depth = (parent < 0) ? 0 : scopes[parent].depth + 1;\n"
"    s->region_name = -1;\n"
"    s->arena = 0;\n"
"    s->loop_depth = 0;\n"
"    s->node = NULL;\n"
"    s->budget = 0;\n"
"    s->budget_file = s->budget_line = s->budget_col = 0;\n"
"    s->region_file = s->region_line = s->region_col = 0;\n"
"    return scope_count++;\n"
"}\n"
"\n"
"void aif_scope_set_region_span(int scope, int file, int line, int col) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].region_file = file;\n"
"    scopes[scope].region_line = line;\n"
"    scopes[scope].region_col = col;\n"
"}\n"
"\n"
"void aif_scope_set_budget(int scope, int bytes, int file, int line, int col) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].budget = bytes;\n"
"    scopes[scope].budget_file = file;\n"
"    scopes[scope].budget_line = line;\n"
"    scopes[scope].budget_col = col;\n"
"}\n"
"\n"
"void aif_scope_set_region(int scope, const char* name) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].region_name = aif_intern(name);\n"
"    // SPEC 5.2: `region` is a pin on the placement decision, not an input to it.\n"
"    // The cost model never sees this scope -- it is guaranteed an arena whether\n"
"    // or not the model would have chosen one, and the manifest records that.\n"
"    scopes[scope].arena = 1;\n"
"}\n"
"\n"
"void aif_scope_set_loop_depth(int scope, int depth) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].loop_depth = depth < 0 ? 0 : depth;\n"
"}\n"
"\n"
"void aif_scope_note_node(int scope, const void* node) {\n"
"    if (scope < 0 || scope >= scope_count) return;\n"
"    scopes[scope].node = node;\n"
"}\n"
"\n"
"int aif_scope_count(void) { return scope_count; }\n"
"\n"
"static int scope_lca(int a, int b) {\n"
"    if (a < 0 || b < 0 || a >= scope_count || b >= scope_count) return -1;\n"
"    if (scopes[a].owner != scopes[b].owner) return -1;\n"
"    while (scopes[a].depth > scopes[b].depth) a = scopes[a].parent;\n"
"    while (scopes[b].depth > scopes[a].depth) b = scopes[b].parent;\n"
"    while (a != b) {\n"
"        a = scopes[a].parent;\n"
"        b = scopes[b].parent;\n"
"        if (a < 0 || b < 0) return -1;\n"
"    }\n"
"    return a;\n"
"}\n"
"\n"
"// Least upper bound on Region(s) < Caller < Global.\n"
"static int escape_join(int x, int y) {\n"
"    if (x == AIF_E_GLOBAL || y == AIF_E_GLOBAL) return AIF_E_GLOBAL;\n"
"    if (x == AIF_E_CALLER || y == AIF_E_CALLER) return AIF_E_CALLER;\n"
"    int m = scope_lca(x, y);\n"
"    return (m < 0) ? AIF_E_CALLER : m;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Functions\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int symbol;     // interned mangled symbol -- the identity\n"
"    int name;       // interned plain name\n"
"    int file;\n"
"    int sealed;     // no visible body: analysed like an FFI call (PIR 5)\n"
"    int nsites;     // running count, so each site gets a stable ordinal\n"
"} Fn;\n"
"\n"
"static Fn* fns;\n"
"static int fn_count, fn_cap;\n"
"\n"
"// Interned symbol id -> function id, -1 where the string is not a function\n"
"// symbol. Sparse and grown on demand, which beats a second hash table.\n"
"static int* fn_by_symbol;\n"
"static int fn_by_symbol_cap;\n"
"\n"
"static void fn_index_put(int symbol, int fid) {\n"
"    if (symbol >= fn_by_symbol_cap) {\n"
"        int grow = fn_by_symbol_cap ? fn_by_symbol_cap * 2 : 1024;\n"
"        if (grow <= symbol) grow = symbol + 1;\n"
"        fn_by_symbol = (int*)xrealloc(fn_by_symbol, (size_t)grow * sizeof(int),\n"
"                                      \"AIF function index\");\n"
"        for (int i = fn_by_symbol_cap; i < grow; i++) fn_by_symbol[i] = -1;\n"
"        fn_by_symbol_cap = grow;\n"
"    }\n"
"    fn_by_symbol[symbol] = fid;\n"
"}\n"
"\n"
"int aif_fn_new(const char* symbol, const char* name, int file) {\n"
"    int sym = aif_intern(symbol);\n"
"    if (sym < fn_by_symbol_cap && fn_by_symbol[sym] >= 0) return fn_by_symbol[sym];\n"
"\n"
"    if (fn_count == fn_cap) {\n"
"        fn_cap = fn_cap ? fn_cap * 2 : 256;\n"
"        fns = (Fn*)xrealloc(fns, (size_t)fn_cap * sizeof(Fn), \"AIF functions\");\n"
"    }\n"
"    Fn* f = &fns[fn_count];\n"
"    f->symbol = sym;\n"
"    f->name = aif_intern(name);\n"
"    f->file = file;\n"
"    f->sealed = 0;\n"
"    f->nsites = 0;\n"
"    fn_index_put(sym, fn_count);\n"
"    return fn_count++;\n"
"}\n"
"\n"
"int aif_fn_lookup(const char* symbol) {\n"
"    int sym = aif_intern(symbol);\n"
"    if (sym >= fn_by_symbol_cap) return -1;\n"
"    return fn_by_symbol[sym];\n"
"}\n"
"\n"
"int aif_fn_count(void) { return fn_count; }\n"
"const char* aif_fn_symbol(int f) { return (f < 0 || f >= fn_count) ? \"\" : aif_str(fns[f].symbol); }\n"
"const char* aif_fn_name(int f)   { return (f < 0 || f >= fn_count) ? \"\" : aif_str(fns[f].name); }\n"
"int aif_fn_file(int f)           { return (f < 0 || f >= fn_count) ? 0 : fns[f].file; }\n"
"void aif_fn_seal(int f)          { if (f >= 0 && f < fn_count) fns[f].sealed = 1; }\n"
"int aif_fn_is_sealed(int f)      { return (f < 0 || f >= fn_count) ? 0 : fns[f].sealed; }\n"
"\n"
"// ============================================================================\n"
"// Nominal types\n"
"//\n"
"// Structs carry a field count (the T0/T1 size proxy -- see aif_tier_of) and an\n"
"// edge set for the type reference graph. Enums are recorded only so the\n"
"// frontend can exclude them: an enum is an i32 and participates in no memory\n"
"// model.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int name;\n"
"    int nfields;\n"
"    int bytes;          // 0 until the frontend computes a layout for it\n"
"    int is_enum;\n"
"    Bits reaches;       // direct edges, then closed transitively\n"
"    int acyclic;\n"
"    // LAYOUT 7.2. The fields themselves, in declaration order, plus the access\n"
"    // profile over them and the permutation the search chose.\n"
"    int* field_name;    // interned\n"
"    // The field's *declared* type, base-named. Struct-field ownership compares\n"
"    // it against what the sites say is in the slot: this compiler puns an\n"
"    // ASTNode pointer as `String`, and a release chosen from the sites alone\n"
"    // would emit a call to __aif_release_String.\n"
"    int* field_type;\n"
"    int* field_bytes;   // width, from the frontend -- it knows the lowering\n"
"    long long* field_acc;\n"
"    int* order;         // order[i] is the declaration index placed i-th\n"
"    int field_cap;\n"
"    int reordered;\n"
"    // LAYOUT 2.1's `range(f)`, which the table marks **dynamic only**. It is the\n"
"    // observed value range and no reading of the source supplies it, which is why\n"
"    // the bit-packing dimension had nothing to search against until `workload`\n"
"    // existed. Zero when no profile was loaded, and the packer declines then --\n"
"    // it must, because \"no range recorded\" and \"range is 0..0\" are the same bits\n"
"    // and only one of them permits narrowing a field to nothing.\n"
"    long long* field_lo;\n"
"    long long* field_hi;\n"
"    int* field_has_range;\n"
"    // LAYOUT 6's hot/cold split, once it is emitted rather than reported.\n"
"    //\n"
"    // `hot_count` is 0 for an unsplit type and otherwise the number of fields the\n"
"    // hot record keeps, in the *split* order aif_layout_field hands codegen --\n"
"    // hot fields first, in the placement order, then the cold ones. `hot` is the\n"
"    // same set by declaration index, which is the space the cost model works in.\n"
"    //\n"
"    // `no_split` is a veto pushed in before the decision is taken, never after:\n"
"    // type_releases_of reads the decision during the solve, and a veto arriving\n"
"    // later would leave a type whose release path had been decided one way and\n"
"    // whose layout went the other.\n"
"    //\n"
"    // `no_split_unmodelled` is the *other* kind of veto, and the two are kept\n"
"    // apart because LAYOUT 8 may override exactly one of them. `no_split` means\n"
"    // the cold block cannot be reached at all (vetoes 1-3): a wild load or a\n"
"    // double free, and no measurement makes it safe. `no_split_unmodelled` means\n"
"    // the model declined to choose because an input is absent (vetoes 4-5) -- the\n"
"    // layout is perfectly sound, there was just no evidence it pays. A forced\n"
"    // candidate is evidence being gathered, so it clears the second and never the\n"
"    // first.\n"
"    int hot_count;\n"
"    int no_split;\n"
"    int no_split_unmodelled;\n"
"    Bits hot;\n"
"} Nominal;\n"
"\n"
"static Nominal* nominals;\n"
"static int nominal_count, nominal_cap;\n"
"static int* nominal_by_name;\n"
"static int nominal_by_name_cap;\n"
"\n"
"static void nominal_index_put(int name, int id) {\n"
"    if (name >= nominal_by_name_cap) {\n"
"        int grow = nominal_by_name_cap ? nominal_by_name_cap * 2 : 1024;\n"
"        if (grow <= name) grow = name + 1;\n"
"        nominal_by_name = (int*)xrealloc(nominal_by_name, (size_t)grow * sizeof(int),\n"
"                                         \"AIF type index\");\n"
"        for (int i = nominal_by_name_cap; i < grow; i++) nominal_by_name[i] = -1;\n"
"        nominal_by_name_cap = grow;\n"
"    }\n"
"    nominal_by_name[name] = id;\n"
"}\n"
"\n"
"static int nominal_find_id(int name) {\n"
"    if (name < 0 || name >= nominal_by_name_cap) return -1;\n"
"    return nominal_by_name[name];\n"
"}\n"
"\n"
"static int nominal_find(const char* name) {\n"
"    return nominal_find_id(aif_intern(name));\n"
"}\n"
"\n"
"static int nominal_intern(const char* name, int is_enum) {\n"
"    int existing = nominal_find(name);\n"
"    if (existing >= 0) return existing;\n"
"\n"
"    if (nominal_count == nominal_cap) {\n"
"        nominal_cap = nominal_cap ? nominal_cap * 2 : 64;\n"
"        nominals = (Nominal*)xrealloc(nominals, (size_t)nominal_cap * sizeof(Nominal),\n"
"                                      \"AIF nominal types\");\n"
"    }\n"
"    Nominal* t = &nominals[nominal_count];\n"
"    t->name = aif_intern(name);\n"
"    t->nfields = 0;\n"
"    t->bytes = 0;\n"
"    t->is_enum = is_enum;\n"
"    t->reaches.w = NULL;\n"
"    t->reaches.nwords = 0;\n"
"    t->acyclic = 1;\n"
"    t->field_name = NULL;\n"
"    t->field_type = NULL;\n"
"    t->field_bytes = NULL;\n"
"    t->field_acc = NULL;\n"
"    t->order = NULL;\n"
"    t->field_cap = 0;\n"
"    t->reordered = 0;\n"
"    t->field_lo = NULL;\n"
"    t->field_hi = NULL;\n"
"    t->field_has_range = NULL;\n"
"    t->hot_count = 0;\n"
"    t->no_split = 0;\n"
"    t->no_split_unmodelled = 0;\n"
"    t->hot.w = NULL;\n"
"    t->hot.nwords = 0;\n"
"    nominal_index_put(t->name, nominal_count);\n"
"    return nominal_count++;\n"
"}\n"
"\n"
"void aif_struct_new(const char* name) { nominal_intern(name, 0); }\n"
"void aif_enum_new(const char* name)   { nominal_intern(name, 1); }\n"
"\n"
"int aif_is_struct(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0 && !nominals[id].is_enum) ? 1 : 0;\n"
"}\n"
"\n"
"int aif_is_enum(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0 && nominals[id].is_enum) ? 1 : 0;\n"
"}\n"
"\n"
"int aif_struct_nfields(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0) ? nominals[id].nfields : 0;\n"
"}\n"
"\n"
"void aif_struct_add_field(const char* name, const char* field, const char* type, int bytes) {\n"
"    Nominal* t = &nominals[nominal_intern(name, 0)];\n"
"    if (t->nfields == t->field_cap) {\n"
"        int grow = t->field_cap ? t->field_cap * 2 : 8;\n"
"        t->field_name  = (int*)xrealloc(t->field_name,  (size_t)grow * sizeof(int), \"AIF fields\");\n"
"        t->field_type  = (int*)xrealloc(t->field_type,  (size_t)grow * sizeof(int), \"AIF field types\");\n"
"        t->field_bytes = (int*)xrealloc(t->field_bytes, (size_t)grow * sizeof(int), \"AIF field widths\");\n"
"        t->field_acc = (long long*)xrealloc(t->field_acc,\n"
"                                           (size_t)grow * sizeof(long long), \"AIF field accesses\");\n"
"        t->order = (int*)xrealloc(t->order, (size_t)grow * sizeof(int), \"AIF field order\");\n"
"        t->field_lo = (long long*)xrealloc(t->field_lo,\n"
"                                           (size_t)grow * sizeof(long long), \"AIF field range lo\");\n"
"        t->field_hi = (long long*)xrealloc(t->field_hi,\n"
"                                           (size_t)grow * sizeof(long long), \"AIF field range hi\");\n"
"        t->field_has_range = (int*)xrealloc(t->field_has_range,\n"
"                                            (size_t)grow * sizeof(int), \"AIF field range flag\");\n"
"        t->field_cap = grow;\n"
"    }\n"
"    int i = t->nfields++;\n"
"    t->field_name[i] = aif_intern(field);\n"
"    t->field_type[i] = aif_intern(type);\n"
"    t->field_bytes[i] = bytes;\n"
"    t->field_acc[i] = 0;\n"
"    t->order[i] = i;\n"
"    t->field_lo[i] = 0;\n"
"    t->field_hi[i] = 0;\n"
"    t->field_has_range[i] = 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// The access profile (LAYOUT 2.1) and layout selection (LAYOUT 7.2)\n"
"//\n"
"// LAYOUT 2 wants the profile measured, by running a declared `workload` under\n"
"// instrumentation. When no workload is declared this is the static estimate\n"
"// LAYOUT 10.4 names as the fallback -- one count per syntactic access, weighted\n"
"// by AIF_LOOP_ITERS per enclosing loop, which is exactly how automatic arena\n"
"// placement estimates allocs_in(s). Same estimator, same known crudeness, and\n"
"// the same property that matters: it is deterministic and needs no profile file.\n"
"//\n"
"// When a workload *is* declared, aif_profile_load replaces the estimate with\n"
"// measured counts. The two are not merged: a measured count and an estimated one\n"
"// are in different units (AIF_LOOP_ITERS^depth against real iterations), and\n"
"// adding them would produce a number that is neither. LAYOUT 2's diagram has the\n"
"// same shape -- the two paths both produce *a profile*, and the cost model\n"
"// consumes one of them.\n"
"//\n"
"// **Only one candidate dimension is searched, and the rest is not caution.**\n"
"// LAYOUT 6's table lists grouping (AoS/SoA), a hot/cold split, field order,\n"
"// bit-packing and handle width. Field order is the only one this compiler can\n"
"// *emit*: SoA and a hot/cold split both make one logical object several\n"
"// allocations, so a field reference stops being `getelementptr` on a pointer and\n"
"// becomes a base plus an index -- which is 1's finding 6, handles, rated as\n"
"// touching every layer. Bit-packing needs a mask and a shift at every access.\n"
"// Choosing a layout codegen cannot produce would be a manifest that describes a\n"
"// binary nobody built.\n"
"// ============================================================================\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Reading a measured profile back (LAYOUT 2.2)\n"
"//\n"
"// The format is the one rt_profile_dump writes, and the parser is deliberately\n"
"// forgiving: an unknown line is skipped rather than rejected. A profile is an\n"
"// *input to codegen only* (W4), so a malformed one can make the layout worse and\n"
"// can never make the program wrong -- which means failing the build over it would\n"
"// trade a real cost for no correctness, exactly what W2 forbids.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static int g_profile_source = -1;      // interned \"workload:NAME\", or -1 for static\n"
"static int g_profile_runs = 0;\n"
"\n"
"static void profile_set_field(const char* type, const char* field,\n"
"                              long long reads, long long writes,\n"
"                              int has_range, long long lo, long long hi) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return;\n"
"    Nominal* t = &nominals[id];\n"
"    int f = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] != f) continue;\n"
"        t->field_acc[i] = reads + writes;\n"
"        t->field_has_range[i] = has_range;\n"
"        t->field_lo[i] = lo;\n"
"        t->field_hi[i] = hi;\n"
"        return;\n"
"    }\n"
"}\n"
"\n"
"// Returns 1 on success. A type or field the profile names but this module does\n"
"// not declare is dropped rather than diagnosed: a checked-in profile outlives\n"
"// edits to the source it was taken against (LAYOUT 10.3), and a renamed field is\n"
"// a stale profile, not a broken build.\n"
"int aif_profile_load(const char* path) {\n"
"    FILE* f = fopen(path, \"r\");\n"
"    if (!f) return 0;\n"
"\n"
"    char line[1024];\n"
"    int any = 0;\n"
"\n"
"    // Every field this module declares that the profile does not mention was not\n"
"    // touched by the measured region, and its count is therefore a measured\n"
"    // *zero* -- not \"unknown\". Clearing first is what makes that true; without it\n"
"    // an untouched field would keep the static estimate and read as hot, which\n"
"    // is precisely backwards for the hot/cold cut the counts feed.\n"
"    for (int n = 0; n < nominal_count; n++) {\n"
"        for (int i = 0; i < nominals[n].nfields; i++) {\n"
"            nominals[n].field_acc[i] = 0;\n"
"            nominals[n].field_has_range[i] = 0;\n"
"        }\n"
"    }\n"
"\n"
"    while (fgets(line, (int)sizeof(line), f)) {\n"
"        if (line[0] == '#' || line[0] == '\\n') continue;\n"
"\n"
"        char kind[32], a[256], b[256];\n"
"        if (sscanf(line, \"%31s\", kind) != 1) continue;\n"
"\n"
"        if (strcmp(kind, \"source\") == 0) {\n"
"            if (sscanf(line, \"%31s %255s\", kind, a) == 2) g_profile_source = aif_intern(a);\n"
"            continue;\n"
"        }\n"
"        if (strcmp(kind, \"runs\") == 0) {\n"
"            int r = 0;\n"
"            if (sscanf(line, \"%31s %d\", kind, &r) == 2) g_profile_runs = r;\n"
"            continue;\n"
"        }\n"
"        if (strcmp(kind, \"field\") == 0) {\n"
"            long long reads = 0, writes = 0, lo = 0, hi = 0;\n"
"            char range[64];\n"
"            int got = sscanf(line, \"%31s %255s %lld %lld %63s\",\n"
"                             kind, a, &reads, &writes, range);\n"
"            if (got < 4) continue;\n"
"            // \"Type.field\" -- split at the last dot, because a field name cannot\n"
"            // contain one and a type name in this language cannot either, but\n"
"            // splitting at the first would break if that ever changes.\n"
"            char* dot = strrchr(a, '.');\n"
"            if (!dot) continue;\n"
"            *dot = '\\0';\n"
"            int has_range = 0;\n"
"            if (got == 5 && sscanf(range, \"%lld..%lld\", &lo, &hi) == 2) has_range = 1;\n"
"            profile_set_field(a, dot + 1, reads, writes, has_range, lo, hi);\n"
"            any = 1;\n"
"            continue;\n"
"        }\n"
"        if (strcmp(kind, \"type\") == 0) {\n"
"            long long allocs = 0, live = 0;\n"
"            if (sscanf(line, \"%31s %255s %lld %lld\", kind, b, &allocs, &live) == 4) {\n"
"                any = 1;\n"
"            }\n"
"            continue;\n"
"        }\n"
"    }\n"
"\n"
"    fclose(f);\n"
"    return any;\n"
"}\n"
"\n"
"// For the manifest. LAYOUT 2.2: \"An implementation SHALL ... record in the\n"
"// manifest which was used.\"\n"
"const char* aif_profile_source(void) {\n"
"    return g_profile_source < 0 ? \"static\" : aif_str(g_profile_source);\n"
"}\n"
"\n"
"int aif_profile_is_measured(void) { return g_profile_source >= 0 ? 1 : 0; }\n"
"\n"
"int aif_field_has_range(const char* type, const char* field) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return 0;\n"
"    Nominal* t = &nominals[id];\n"
"    int fn = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] == fn) return t->field_has_range[i];\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"long long aif_field_range_lo(const char* type, const char* field) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return 0;\n"
"    Nominal* t = &nominals[id];\n"
"    int fn = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] == fn) return t->field_lo[i];\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"long long aif_field_range_hi(const char* type, const char* field) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return 0;\n"
"    Nominal* t = &nominals[id];\n"
"    int fn = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] == fn) return t->field_hi[i];\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// The narrowest signed width that holds the measured range, in bytes.\n"
"//\n"
"// In C rather than in the frontend because Prismio's integer literals infer as\n"
"// `Int` and the language does not widen across a comparison, so writing\n"
"// `lo >= -2147483648` against an I64 is a type error and the workaround is six\n"
"// annotated bindings. The arithmetic is the same either way; this is where it\n"
"// reads as what it is.\n"
"//\n"
"// Signed even when the range is non-negative: the field's declared type is\n"
"// signed, and a narrowing that changed signedness would change what a comparison\n"
"// against it means.\n"
"int aif_field_range_bytes(const char* type, const char* field) {\n"
"    if (!aif_field_has_range(type, field)) return 8;\n"
"    long long lo = aif_field_range_lo(type, field);\n"
"    long long hi = aif_field_range_hi(type, field);\n"
"    if (lo >= -128LL && hi <= 127LL) return 1;\n"
"    if (lo >= -32768LL && hi <= 32767LL) return 2;\n"
"    if (lo >= -2147483648LL && hi <= 2147483647LL) return 4;\n"
"    return 8;\n"
"}\n"
"\n"
"// Defined with the cost model below, which is where the traversal table lives.\n"
"static void traversal_note_field(int type_name, int field_index);\n"
"\n"
"void aif_field_access(const char* type, const char* field, int loops) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return;\n"
"    Nominal* t = &nominals[id];\n"
"    int f = aif_intern(field);\n"
"    long long weight = 1;\n"
"    if (loops > 6) loops = 6;       // capped as weight_of caps it, and for the same reason\n"
"    for (int i = 0; i < loops; i++) weight *= AIF_LOOP_ITERS;\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] == f) {\n"
"            t->field_acc[i] += weight;\n"
"            // LAYOUT 5's cost model needs which fields are touched *together*,\n"
"            // not just how often each is touched. Same call site, because a\n"
"            // second walk would be a second chance to disagree about what an\n"
"            // access is.\n"
"            traversal_note_field(t->name, i);\n"
"            return;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// **The first field never moves, and this is not a tuning choice.**\n"
"//\n"
"// The compiler puns a struct pointer as `String` and spells \"this slot is empty\"\n"
"// as `str_equals(ptr, \"\")`, which reads the *first byte of the pointed-to\n"
"// struct*. That is why NodeKind and TypeKind both reserve ordinal 0: a live node\n"
"// whose first field is zero is byte-for-byte an empty slot, and every\n"
"// node_exists in the compiler rests on it (tests/test_41_punned_slot_bytes.psm).\n"
"//\n"
"// Sorting by width puts an 8-byte pointer at offset 0, and a pointer to \"\" has a\n"
"// zero first byte -- so every live node with an empty `s1` began reading as\n"
"// absent. The generation built by the first compiler that did this could not\n"
"// parse its own source. SPEC 8.2 grants the compiler layout freedom; this\n"
"// implementation's representation of \"absent\" spends the first field of it, and\n"
"// the search has to know that rather than rediscover it.\n"
"// **Descending width alone is wrong here, and measurement is what says so.**\n"
"//\n"
"// LAYOUT 6 derives field order as a sort -- descending frequency, then descending\n"
"// alignment -- and a sort is optimal for padding only when placement starts at\n"
"// offset 0 with nothing fixed. The pinned first field breaks that: pinning a\n"
"// 4-byte `kind` leaves a 4-byte hole that only a narrow field can fill, and a\n"
"// width sort puts the widest field next and pays the padding. Measured on the\n"
"// corpus, sorting made `Health` 16 bytes -> 24 and `Sprite` 40 -> 48. It made\n"
"// nothing smaller.\n"
"//\n"
"// So placement is greedy over the running offset instead: at each step take the\n"
"// widest remaining field that needs *no* padding where the last one ended, and\n"
"// only when nothing fits fall back to the widest overall. That fills the pin's\n"
"// hole with the narrow field declaration order would have put there, and is at\n"
"// least as good as both a sort and source order everywhere on this corpus.\n"
"//\n"
"// Frequency is the tie-break rather than the primary key, and LAYOUT 6's ordering\n"
"// of the two is right for the reason it gives -- frequency decides where a\n"
"// hot/cold cut falls. There is no cut here (it needs handles), so frequency has\n"
"// nothing structural to decide and only costs padding if it leads.\n"
"static int layout_pad(int offset, int width) {\n"
"    if (width <= 0) return 0;\n"
"    int slack = offset % width;\n"
"    return slack == 0 ? 0 : width - slack;\n"
"}\n"
"\n"
"void aif_layout_select(void) {\n"
"    for (int n = 0; n < nominal_count; n++) {\n"
"        Nominal* t = &nominals[n];\n"
"        if (t->is_enum || t->nfields < 3) continue;   // nothing to permute past field 0\n"
"\n"
"        // The first field never moves; see above. Everything else is chosen by\n"
"        // greedy best-fit from the offset the pinned prefix left.\n"
"        int offset = t->field_bytes[0];\n"
"        for (int slot = 1; slot < t->nfields; slot++) {\n"
"            int best = -1, best_pad = 0;\n"
"            for (int c = slot; c < t->nfields; c++) {\n"
"                int f = t->order[c];\n"
"                int pad = layout_pad(offset, t->field_bytes[f]);\n"
"                if (best < 0) { best = c; best_pad = pad; continue; }\n"
"                int b = t->order[best];\n"
"                // Fits without padding beats anything that does not; then wider;\n"
"                // then hotter; then declaration index, so the order is total and\n"
"                // the output deterministic (LAYOUT 9).\n"
"                int better = 0;\n"
"                if ((pad == 0) != (best_pad == 0))            better = (pad == 0);\n"
"                else if (t->field_bytes[f] != t->field_bytes[b]) better = t->field_bytes[f] > t->field_bytes[b];\n"
"                else if (t->field_acc[f] != t->field_acc[b])     better = t->field_acc[f] > t->field_acc[b];\n"
"                else                                             better = f < b;\n"
"                if (better) { best = c; best_pad = pad; }\n"
"            }\n"
"            int chosen = t->order[best];\n"
"            t->order[best] = t->order[slot];\n"
"            t->order[slot] = chosen;\n"
"            offset += best_pad + t->field_bytes[chosen];\n"
"        }\n"
"\n"
"        for (int i = 0; i < t->nfields; i++) {\n"
"            if (t->order[i] != i) { t->reordered = 1; break; }\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// LAYOUT 5's cost model, ported from aif/prototype/layout.py\n"
"//\n"
"// **What this is for.** LAYOUT 7.2 specifies selection as\n"
"// `best := argmin over candidates(tau) of Cost(...)`, and until now this compiler\n"
"// had neither half: `aif_layout_select` above runs one greedy placement and never\n"
"// scores it, so \"the top-k candidates ranked by modelled cost\" (LAYOUT 8) named a\n"
"// set with one member and a function that did not exist. This is that function.\n"
"//\n"
"// It is **reported and not yet acted on**. Nothing below changes a byte of IR:\n"
"// `aif_layout_select` still chooses field order exactly as it did, and the\n"
"// ranking is surfaced through `prismio aif --layout` so the hot/cold cut can be\n"
"// audited before anything emits it. That ordering is deliberate -- a split object\n"
"// is two allocations and needs the whole release path (RESULTS-layout 5) before\n"
"// any of it may be emitted.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// Three deliberate divergences from the prototype, each of which changes the\n"
"// answer, and each measured rather than argued.\n"
"// ---------------------------------------------------------------------------\n"
"//\n"
"// **1. Candidates are AoS x splits, not AoS/SoA x splits.** The prototype ranks\n"
"// SoA and picks it: on `g1_particles.psm` it returns `SoA 5.37x`. SoA needs\n"
"// handles, which do not exist (RESULTS-layout 1), so a compiler that ranked it\n"
"// would select a layout it cannot emit -- \"a manifest that describes a binary\n"
"// nobody built\", which is the rule the block above this one already states for\n"
"// the search. Restricted to what codegen can produce, the same model on the same\n"
"// program returns `AoS+split(8/12) 1.44x`, and that cut is exactly the one\n"
"// `aif/evidence/bench/layout_repr.c` variant B measures at **0.87x**. The\n"
"// restriction is what makes the model useful here rather than a weaker version of\n"
"// the prototype.\n"
"//\n"
"// **2. The hot record carries the link word, and the prototype's does not.**\n"
"// `record_size(hot)` in layout.py is the hot fields alone, because its split is\n"
"// indexed rather than linked. This implementation's cold block hangs off the hot\n"
"// record -- that is precisely why hot/cold needs no handles -- so the hot record\n"
"// pays 8 bytes for the pointer. Particle's 8/12 cut is 72 bytes here (8 doubles +\n"
"// link) against the prototype's 64, and RESULTS-layout's \"96 -> 72 bytes\" is the\n"
"// linked number. Without the link word the model over-values every split, and\n"
"// most sharply the ones that barely pay.\n"
"//\n"
"// **3. There is no SimdCredit term, which resolves LAYOUT 5.4's defect by\n"
"// construction.** layout.py records the defect at `traversal_cost`: 5.4 subtracts\n"
"// SimdCredit from a sum of *memory* costs, so an arithmetic saving nets against\n"
"// something it has nothing to do with and the total can go negative. The\n"
"// prototype clamps with `max(0, ...)`. Here the term cannot arise: the credit is\n"
"// gated on `grouping in (SoA, AoSoA)` and this candidate set is AoS-only, so\n"
"// there is nothing to subtract and nothing to clamp. The arithmetic term itself\n"
"// is layout-invariant -- it is the same for every candidate of a type -- so it\n"
"// cannot move an argmin and is not computed. **This does not resolve the\n"
"// specification defect**, it only means this port never reaches it; 5.4 still\n"
"// needs fixing before any grouping dimension is searched.\n"
"//\n"
"// Integer arithmetic throughout, as LAYOUT 9 obligation 2 requires: a parallel\n"
"// float reduction can flip a tie, and layout must be reproducible.\n"
"//\n"
"// Costs are per element and scaled by 100 (`pi` is already in hundredths), rather\n"
"// than the prototype's per-collection absolute figures. N_ASSUMED is a common\n"
"// factor of every term, so dividing it out changes no ordering and keeps the\n"
"// products inside 64 bits by a wide margin. Only ratios are ever reported.\n"
"// ============================================================================\n"
"\n"
"#define AIF_LINE        64\n"
"#define AIF_C1      (32 * 1024)\n"
"#define AIF_C2   (1024 * 1024)\n"
"#define AIF_C3   (32 * 1024 * 1024)\n"
"#define AIF_MU1          4\n"
"#define AIF_MU2         12\n"
"#define AIF_MU3         40\n"
"#define AIF_MUM        250\n"
"#define AIF_N_ASSUMED (1 << 20)   // LAYOUT 2.1: length unknown statically -> large\n"
"#define AIF_PI_SEQ      15        // hundredths, as in layout.py's PI\n"
"#define AIF_PI_RANDOM  100\n"
"#define AIF_LAMBDA_NUM   2\n"
"#define AIF_LAMBDA_DEN 100\n"
"\n"
"// A loop, and the fields of one type it touches. LAYOUT 2.1's \"co-accessed\"\n"
"// half, which is the structural fact the model needs and a per-field count\n"
"// cannot supply: two fields with equal counts touched by *different* loops want\n"
"// opposite sides of a cut, and summed counts cannot tell them apart.\n"
"typedef struct {\n"
"    int type;               // interned nominal name\n"
"    int loop_id;\n"
"    int depth;\n"
"    int sequential;         // 1 sequential, 0 random -- see aif_traversal_elem\n"
"    Bits touched;           // by declaration index\n"
"} Traversal;\n"
"\n"
"static Traversal* traversals;\n"
"static int traversal_count, traversal_cap;\n"
"static int g_loop_ids[64];\n"
"static int g_loop_depth;\n"
"static int g_loop_next_id;\n"
"\n"
"void aif_traversal_begin(void) {\n"
"    if (g_loop_depth < 64) g_loop_ids[g_loop_depth] = ++g_loop_next_id;\n"
"    g_loop_depth++;\n"
"}\n"
"\n"
"void aif_traversal_end(void) {\n"
"    if (g_loop_depth > 0) g_loop_depth--;\n"
"}\n"
"\n"
"static Traversal* traversal_for(int type) {\n"
"    if (g_loop_depth <= 0 || g_loop_depth > 64) return NULL;\n"
"    int loop_id = g_loop_ids[g_loop_depth - 1];\n"
"    for (int i = 0; i < traversal_count; i++) {\n"
"        if (traversals[i].type == type && traversals[i].loop_id == loop_id)\n"
"            return &traversals[i];\n"
"    }\n"
"    if (traversal_count == traversal_cap) {\n"
"        traversal_cap = traversal_cap ? traversal_cap * 2 : 64;\n"
"        traversals = (Traversal*)xrealloc(traversals,\n"
"                                          (size_t)traversal_cap * sizeof(Traversal),\n"
"                                          \"AIF traversals\");\n"
"    }\n"
"    Traversal* t = &traversals[traversal_count++];\n"
"    t->type = type;\n"
"    t->loop_id = loop_id;\n"
"    t->depth = g_loop_depth;\n"
"    // Random until something says otherwise. The prototype's default is the same\n"
"    // and for the same reason: a field walked through a chain of member accesses\n"
"    // (`n.world.px`) is a pointer chase, and treating an unproven walk as\n"
"    // sequential would credit a split with locality nothing established.\n"
"    t->sequential = 0;\n"
"    t->touched.w = NULL;\n"
"    t->touched.nwords = 0;\n"
"    return t;\n"
"}\n"
"\n"
"// The walk calls this when a loop binds a container element -- `let p =\n"
"// list_get(ps, i)`. That is the shape the cost model's `sequential` means: the\n"
"// records are visited in container order, so a smaller hot record puts more of\n"
"// them per line.\n"
"//\n"
"// **Weaker than the prototype's rule, and the difference is nameable.**\n"
"// layout.py additionally requires the index to be an induction variable of the\n"
"// loop, so `list_get(ps, perm[i])` -- a gather -- is random there and sequential\n"
"// here. No loop in `tests/`, `aif/corpus/` or `aif/evidence/` indexes a container\n"
"// by anything but its own counter, so the two rules agree on every program in\n"
"// this tree; the divergence is recorded because the first gather written will\n"
"// separate them, and it will do so silently.\n"
"void aif_traversal_elem(const char* type, int sequential) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return;\n"
"    Traversal* t = traversal_for(nominals[id].name);\n"
"    if (t) t->sequential = sequential ? 1 : 0;\n"
"}\n"
"\n"
"static void traversal_note_field(int type_name, int field_index) {\n"
"    Traversal* t = traversal_for(type_name);\n"
"    if (!t) return;\n"
"    bits_set(&t->touched, field_index, \"AIF traversal fields\");\n"
"}\n"
"\n"
"static void traversals_reset(void) {\n"
"    for (int i = 0; i < traversal_count; i++) free(traversals[i].touched.w);\n"
"    free(traversals);\n"
"    traversals = NULL;\n"
"    traversal_count = traversal_cap = 0;\n"
"    g_loop_depth = 0;\n"
"    g_loop_next_id = 0;\n"
"}\n"
"\n"
"// Size of a subset of a type's fields, padded, fields placed widest-first --\n"
"// layout.py's record_size. `link` adds the 8-byte pointer to the cold block; see\n"
"// divergence 2 above.\n"
"static int record_size_of(Nominal* t, Bits* subset, int link) {\n"
"    int off = 0;\n"
"    for (int width = 8; width >= 1; width >>= 1) {\n"
"        for (int i = 0; i < t->nfields; i++) {\n"
"            if (!bits_test(subset, i)) continue;\n"
"            int w = t->field_bytes[i];\n"
"            if (w > 8) w = 8;\n"
"            if (w != width) continue;\n"
"            int a = t->field_bytes[i] < 8 ? t->field_bytes[i] : 8;\n"
"            if (a > 0 && off % a) off += a - off % a;\n"
"            off += t->field_bytes[i];\n"
"        }\n"
"    }\n"
"    if (link) {\n"
"        if (off % 8) off += 8 - off % 8;\n"
"        off += 8;\n"
"    }\n"
"    if (off < 1) off = 1;\n"
"    return (off + 7) / 8 * 8;\n"
"}\n"
"\n"
"static int min_size_of(Nominal* t) {\n"
"    int s = 0;\n"
"    for (int i = 0; i < t->nfields; i++) s += t->field_bytes[i];\n"
"    return s;\n"
"}\n"
"\n"
"static int mu_for(long long footprint) {\n"
"    if (footprint <= AIF_C1) return AIF_MU1;\n"
"    if (footprint <= AIF_C2) return AIF_MU2;\n"
"    if (footprint <= AIF_C3) return AIF_MU3;\n"
"    return AIF_MUM;\n"
"}\n"
"\n"
"static long long iters_of(int depth) {\n"
"    long long it = 1;\n"
"    int d = depth < 1 ? 1 : depth;\n"
"    if (d > 6) d = 6;\n"
"    for (int i = 0; i < d; i++) it *= AIF_LOOP_ITERS;\n"
"    return it;\n"
"}\n"
"\n"
"// LAYOUT 5's Cost for one candidate: `hot` is the set kept in the primary\n"
"// allocation, everything else splits cold. Returns cost per element, x100.\n"
"static long long layout_cost(Nominal* t, Bits* hot, int is_split) {\n"
"    int hot_size = record_size_of(t, hot, is_split);\n"
"    Bits cold;\n"
"    cold.w = NULL;\n"
"    cold.nwords = 0;\n"
"    int cold_size = 0;\n"
"    if (is_split) {\n"
"        for (int i = 0; i < t->nfields; i++)\n"
"            if (!bits_test(hot, i)) bits_set(&cold, i, \"AIF cold group\");\n"
"        cold_size = record_size_of(t, &cold, 0);\n"
"    }\n"
"\n"
"    long long total = 0;\n"
"    for (int i = 0; i < traversal_count; i++) {\n"
"        Traversal* tr = &traversals[i];\n"
"        if (tr->type != t->name) continue;\n"
"\n"
"        int hot_touched = 0, cold_touched = 0;\n"
"        for (int f = 0; f < t->nfields; f++) {\n"
"            if (!bits_test(&tr->touched, f)) continue;\n"
"            if (bits_test(hot, f)) hot_touched = 1;\n"
"            else                   cold_touched = 1;\n"
"        }\n"
"        if (!hot_touched && !cold_touched) continue;\n"
"\n"
"        long long iters = iters_of(tr->depth);\n"
"        if (!tr->sequential) {\n"
"            // A pointer chase pays a line per group it lands in, so a split that\n"
"            // both halves are read through costs a second miss. This is the term\n"
"            // that stops the model splitting everything.\n"
"            int groups = (hot_touched ? 1 : 0) + (cold_touched ? 1 : 0);\n"
"            long long bytes_per = (long long)groups * AIF_LINE;\n"
"            long long fp = (long long)AIF_N_ASSUMED * (hot_size < 1 ? 1 : hot_size);\n"
"            total += iters * bytes_per * mu_for(fp) * AIF_PI_RANDOM / AIF_LINE;\n"
"        } else {\n"
"            // The hot record is walked in container order.\n"
"            long long fp = (long long)AIF_N_ASSUMED * (hot_size < 1 ? 1 : hot_size);\n"
"            total += iters * hot_size * mu_for(fp) * AIF_PI_SEQ / AIF_LINE;\n"
"\n"
"            // **A cold touch is a pointer chase, not a longer scan, and this is\n"
"            // the one place the port must not follow the prototype.**\n"
"            //\n"
"            // layout.py adds `record_size(cold)` to the bytes scanned, which is\n"
"            // correct for the split it models -- cold[i] sits at a computed\n"
"            // offset in a parallel block, so reaching it is more streaming. This\n"
"            // implementation's cold block is *linked*: the hot record holds a\n"
"            // pointer to it, which is exactly why hot/cold needs no handles\n"
"            // (RESULTS-layout 2). Reaching a cold field is therefore a dependent\n"
"            // load into a separately malloc'd block -- a miss at random-access\n"
"            // probability, not 32 more bytes of sequential scan.\n"
"            //\n"
"            // **It changes the answer, and the prototype's margin says why it has\n"
"            // to.** On g1, layout.py ranks its top two candidates 1188M and\n"
"            // 1180M -- 0.7% apart -- and prefers 8/12 by that margin over a cut\n"
"            // that pushes five of `integrate`'s six fields cold. Ported\n"
"            // faithfully, the link word alone flips it: this compiler scored\n"
"            // 2/12 at 73 against 8/12 at 75. Two candidates whose real\n"
"            // performance differs enormously were being separated by less than\n"
"            // the model's own noise. With the chase priced, 8/12 wins at 75\n"
"            // against 314, which agrees with layout_repr.c's measured 0.87x for\n"
"            // exactly that cut.\n"
"            if (cold_touched) {\n"
"                long long cfp = (long long)AIF_N_ASSUMED * (cold_size < 1 ? 1 : cold_size);\n"
"                total += iters * AIF_LINE * mu_for(cfp) * AIF_PI_RANDOM / AIF_LINE;\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    // LAYOUT 5's footprint penalty: padding the layout added over the packed\n"
"    // minimum, weighted by lambda. Scaled x100 to match the traversal term.\n"
"    int size = hot_size + cold_size;\n"
"    int slack = size - min_size_of(t);\n"
"    if (slack > 0) total += (long long)slack * AIF_LAMBDA_NUM * 100 / AIF_LAMBDA_DEN;\n"
"\n"
"    free(cold.w);\n"
"    return total;\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// The candidate space (LAYOUT 6), and the ranking LAYOUT 8 asks for.\n"
"//\n"
"// Cuts are taken at strict frequency boundaries down the access-count ranking,\n"
"// which is layout.py's `candidates`. **The first boundary is not the answer** --\n"
"// on Particle it cuts 2/12 and pushes `integrate`'s own six fields cold, which is\n"
"// slower, not faster. Only scoring every cut finds 8/12. That is the argument for\n"
"// this file existing rather than a `rank[i] > rank[i+1]` test in the search.\n"
"//\n"
"// Field 0 of the *chosen order* is pinned hot and never offered to a cut: the\n"
"// punned-slot invariant is about the first byte of the object\n"
"// (tests/test_41_punned_slot_bytes.psm), and a cut by frequency alone would\n"
"// happily put a never-read field there.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"#define AIF_MAX_CANDIDATES 32\n"
"\n"
"typedef struct {\n"
"    int hot_count;              // fields in the hot group, including the pinned one\n"
"    long long cost;\n"
"    Bits hot;\n"
"} Candidate;\n"
"\n"
"static Candidate g_cands[AIF_MAX_CANDIDATES];\n"
"static int g_cand_count;\n"
"static int g_cand_type = -1;\n"
"static int g_cand_best;\n"
"\n"
"static void candidates_clear(void) {\n"
"    for (int i = 0; i < g_cand_count; i++) free(g_cands[i].hot.w);\n"
"    g_cand_count = 0;\n"
"    g_cand_type = -1;\n"
"    g_cand_best = 0;\n"
"}\n"
"\n"
"// Ranks every admissible layout for `type`, cheapest first-scoring wins. Returns\n"
"// the number of candidates, 0 when the type is not splittable at all.\n"
"int aif_layout_rank(const char* type) {\n"
"    candidates_clear();\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return 0;\n"
"    Nominal* t = &nominals[id];\n"
"    if (t->is_enum || t->nfields < 3) return 0;\n"
"    g_cand_type = t->name;\n"
"\n"
"    // Candidate 0 is the unsplit record -- the baseline every ratio is against,\n"
"    // and a real candidate: if no split beats it, none is taken.\n"
"    Bits all;\n"
"    all.w = NULL;\n"
"    all.nwords = 0;\n"
"    for (int i = 0; i < t->nfields; i++) bits_set(&all, i, \"AIF layout baseline\");\n"
"    g_cands[0].hot_count = t->nfields;\n"
"    g_cands[0].hot = all;\n"
"    g_cands[0].cost = layout_cost(t, &all, 0);\n"
"    g_cand_count = 1;\n"
"\n"
"    // Rank the movable fields by access count descending, then by declaration\n"
"    // index, so the order is total and the output deterministic (LAYOUT 9).\n"
"    int pinned = t->order[0];\n"
"    int rank[256], nrank = 0;\n"
"    for (int i = 0; i < t->nfields && nrank < 256; i++)\n"
"        if (i != pinned) rank[nrank++] = i;\n"
"    for (int a = 0; a < nrank; a++) {\n"
"        for (int b = a + 1; b < nrank; b++) {\n"
"            int x = rank[a], y = rank[b];\n"
"            int swap = t->field_acc[y] > t->field_acc[x]\n"
"                       || (t->field_acc[y] == t->field_acc[x] && y < x);\n"
"            if (swap) { rank[a] = y; rank[b] = x; }\n"
"        }\n"
"    }\n"
"\n"
"    for (int cut = 1; cut < nrank && g_cand_count < AIF_MAX_CANDIDATES; cut++) {\n"
"        if (t->field_acc[rank[cut - 1]] == t->field_acc[rank[cut]]) continue;\n"
"        Bits hot;\n"
"        hot.w = NULL;\n"
"        hot.nwords = 0;\n"
"        bits_set(&hot, pinned, \"AIF hot group\");\n"
"        for (int i = 0; i < cut; i++) bits_set(&hot, rank[i], \"AIF hot group\");\n"
"        Candidate* c = &g_cands[g_cand_count++];\n"
"        c->hot_count = cut + 1;\n"
"        c->hot = hot;\n"
"        c->cost = layout_cost(t, &hot, 1);\n"
"    }\n"
"\n"
"    g_cand_best = 0;\n"
"    for (int i = 1; i < g_cand_count; i++) {\n"
"        // Strictly cheaper wins, so a tie keeps the unsplit record: a split costs\n"
"        // a second allocation and a second free at run time, and none of that is\n"
"        // in the model.\n"
"        if (g_cands[i].cost < g_cands[g_cand_best].cost) g_cand_best = i;\n"
"    }\n"
"    return g_cand_count;\n"
"}\n"
"\n"
"int aif_layout_candidates(void)        { return g_cand_count; }\n"
"int aif_layout_best(void)              { return g_cand_best; }\n"
"int aif_layout_cand_hot(int i)         { return (i >= 0 && i < g_cand_count) ? g_cands[i].hot_count : 0; }\n"
"\n"
"// LAYOUT 8 compiles \"the top-k candidates, ranked by modelled cost\". `g_cands` is\n"
"// in cut order and `g_cand_best` is only the argmin, so the ranking is computed\n"
"// here rather than stored: k = 0 is the argmin, k = 1 the next cheapest, and so on.\n"
"//\n"
"// Ties break on the candidate index, which is LAYOUT 9.1's total order -- the\n"
"// candidates are generated in increasing cut order, so the index *is* the split\n"
"// rank, and a tie between two equal-cost cuts resolves the same way on every host\n"
"// rather than by whichever the scan reached first.\n"
"int aif_layout_cand_at_rank(int k) {\n"
"    if (k < 0 || k >= g_cand_count) return -1;\n"
"    // Selection rather than a sort: g_cands must stay in cut order, because every\n"
"    // other accessor here is indexed by it and the report prints it in that order.\n"
"    int prev = -1;\n"
"    for (int rank = 0; rank <= k; rank++) {\n"
"        int pick = -1;\n"
"        for (int i = 0; i < g_cand_count; i++) {\n"
"            // Skip everything at or before `prev` in the (cost, index) order.\n"
"            if (prev >= 0 && (g_cands[i].cost < g_cands[prev].cost ||\n"
"                              (g_cands[i].cost == g_cands[prev].cost && i <= prev)))\n"
"                continue;\n"
"            // `i` ascends, so a strict `<` leaves ties on the lower index.\n"
"            if (pick < 0 || g_cands[i].cost < g_cands[pick].cost) pick = i;\n"
"        }\n"
"        if (pick < 0) return -1;\n"
"        prev = pick;\n"
"    }\n"
"    return prev;\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// LAYOUT 8's forced candidate\n"
"//\n"
"// \302\2478 selects a layout by *measuring* the top-k candidates instead of trusting the\n"
"// model's argmin, and \302\2477.2's argmin is the only thing wired to codegen -- so the\n"
"// one mechanism \302\2478 needs that does not exist is a way to say \"emit this candidate,\n"
"// not the cheapest one\". This is that, and it is deliberately the whole of it: the\n"
"// search loop, the timing and the manifest record are the frontend's business.\n"
"//\n"
"// **A candidate is named by its hot-field count, not by its rank.** Ranks move\n"
"// whenever the cost model changes, so a manifest record or a reproduction command\n"
"// naming \"the 2nd best candidate\" stops meaning the same layout the moment a\n"
"// constant is retuned. `hot_count` is a property of the layout itself, and it is\n"
"// what `--layout` already prints (`split 8/12`), so the number a human reads off\n"
"// the report is the number they can force.\n"
"//\n"
"// **It lives outside the Nominal table.** aif_reset tears every Nominal down, and\n"
"// a declared `workload` runs the whole engine twice in one process (LAYOUT 3.2) --\n"
"// so a force stored on the type would apply to the instrumented pass and silently\n"
"// not to the real one, which is the pass that ships. Keyed by name string for the\n"
"// same reason: the interned ids are per-run too.\n"
"//\n"
"// **A force that matches nothing is reported, not ignored.** Naming a type that is\n"
"// not in the program, or a cut that is not a candidate, is the shape of mistake\n"
"// this project has made most -- an instrument that matched nothing and reported\n"
"// success. `aif_layout_force_applied` is how the frontend can raise it.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"#define AIF_MAX_FORCED 32\n"
"\n"
"typedef struct {\n"
"    char* type;\n"
"    int hot_count;\n"
"    int applied;\n"
"} Forced;\n"
"\n"
"static Forced g_forced[AIF_MAX_FORCED];\n"
"static int g_forced_count;\n"
"\n"
"void aif_layout_force(const char* type, int hot_count) {\n"
"    if (!type || hot_count < 1) return;\n"
"    for (int i = 0; i < g_forced_count; i++) {\n"
"        if (strcmp(g_forced[i].type, type) == 0) {\n"
"            g_forced[i].hot_count = hot_count;   // last writer wins, so a repeated\n"
"            g_forced[i].applied = 0;             // --force-layout is not two forces\n"
"            return;\n"
"        }\n"
"    }\n"
"    if (g_forced_count >= AIF_MAX_FORCED) return;\n"
"    size_t n = strlen(type) + 1;\n"
"    char* copy = (char*)xmalloc(n, \"AIF forced layout\");\n"
"    memcpy(copy, type, n);\n"
"    g_forced[g_forced_count].type = copy;\n"
"    g_forced[g_forced_count].hot_count = hot_count;\n"
"    g_forced[g_forced_count].applied = 0;\n"
"    g_forced_count++;\n"
"}\n"
"\n"
"// -1 when `type` carries no force, which is the common case and the one the\n"
"// selection loop asks about per type.\n"
"static int forced_hot_for(const char* type) {\n"
"    for (int i = 0; i < g_forced_count; i++)\n"
"        if (strcmp(g_forced[i].type, type) == 0) return g_forced[i].hot_count;\n"
"    return -1;\n"
"}\n"
"\n"
"static void forced_mark_applied(const char* type) {\n"
"    for (int i = 0; i < g_forced_count; i++)\n"
"        if (strcmp(g_forced[i].type, type) == 0) g_forced[i].applied = 1;\n"
"}\n"
"\n"
"int aif_layout_forced_count(void) { return g_forced_count; }\n"
"\n"
"const char* aif_layout_forced_type(int i) {\n"
"    return (i >= 0 && i < g_forced_count) ? g_forced[i].type : \"\";\n"
"}\n"
"\n"
"int aif_layout_forced_hot(int i) {\n"
"    return (i >= 0 && i < g_forced_count) ? g_forced[i].hot_count : 0;\n"
"}\n"
"\n"
"int aif_layout_force_applied(int i) {\n"
"    return (i >= 0 && i < g_forced_count) ? g_forced[i].applied : 0;\n"
"}\n"
"\n"
"// Costs are reported as a ratio against the unsplit baseline, x100, because the\n"
"// absolute figure is in units nobody can act on. 100 means \"no better than not\n"
"// splitting\"; 87 would mean the model expects 0.87x.\n"
"int aif_layout_cand_ratio(int i) {\n"
"    if (i < 0 || i >= g_cand_count || g_cand_count == 0) return 100;\n"
"    long long base = g_cands[0].cost;\n"
"    if (base <= 0) return 100;\n"
"    return (int)(g_cands[i].cost * 100 / base);\n"
"}\n"
"\n"
"// Whether field `f` (declaration index) is hot in candidate `i`. The report needs\n"
"// it to name the cold fields, which is the part a reader can act on.\n"
"int aif_layout_cand_field_hot(int i, int f) {\n"
"    if (i < 0 || i >= g_cand_count) return 1;\n"
"    return bits_test(&g_cands[i].hot, f) ? 1 : 0;\n"
"}\n"
"\n"
"int aif_layout_cand_bytes(int i, int cold) {\n"
"    if (i < 0 || i >= g_cand_count || g_cand_type < 0) return 0;\n"
"    int id = nominal_find_id(g_cand_type);\n"
"    if (id < 0) return 0;\n"
"    Nominal* t = &nominals[id];\n"
"    int is_split = g_cands[i].hot_count < t->nfields;\n"
"    if (!cold) return record_size_of(t, &g_cands[i].hot, is_split);\n"
"    if (!is_split) return 0;\n"
"    Bits c;\n"
"    c.w = NULL;\n"
"    c.nwords = 0;\n"
"    for (int f = 0; f < t->nfields; f++)\n"
"        if (!bits_test(&g_cands[i].hot, f)) bits_set(&c, f, \"AIF cold group\");\n"
"    int b = record_size_of(t, &c, 0);\n"
"    free(c.w);\n"
"    return b;\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// LAYOUT 6's hot/cold split, taken rather than reported\n"
"//\n"
"// The ranking above scores every admissible cut; this decides which one codegen\n"
"// emits. The split is **linked** (LAYOUT 5.2.1): the hot record ends in a pointer\n"
"// to a separately allocated cold block, which is why it needs no handles, and\n"
"// which is also why a split object is *two* allocations and every release path\n"
"// has to know it.\n"
"//\n"
"// **Three vetoes, and each is a way the second allocation cannot be reached --\n"
"// not a way it would be slow.** The cost model decides the rest.\n"
"//\n"
"//   1. `no_split`, pushed in by the frontend for any type embedded **inline** in\n"
"//      another struct. An inline field is storage inside its owner: nothing calls\n"
"//      an allocator for it, so its link word would hold whatever the owner's\n"
"//      allocation left there and the first cold read would be a wild load. The\n"
"//      predicate is `typeAnnIsPod` + `ir_is_struct_type_name`, asked once in\n"
"//      src/aif/layout.psm -- the same pair `fieldTypeFor` asks to decide\n"
"//      inline-ness in the first place, so the two cannot drift.\n"
"//   2. A type in a **non-trivial SCC**, i.e. a T4b candidate. `cyc_free_object`\n"
"//      calls the generated release on the *payload* while the object's base is\n"
"//      `payload - CYC_HDR`; forcing a release onto a type that reaches itself\n"
"//      would put a second block behind that asymmetry. T4b splits are excluded\n"
"//      because the collector's release contract is a separate question, not\n"
"//      because they are hard.\n"
"//   3. Fewer than three fields, or an enum -- there is no cut past the pinned\n"
"//      field 0.\n"
"//   4. **A type with no sequential traversal.** This one is a measurement, and it\n"
"//      is the third time on this project that a measurement has refuted the cost\n"
"//      model. The mechanism RESULTS-layout 2 measured is that a walk *in container\n"
"//      order* over smaller hot records streams less and packs closer -- 0.87x on\n"
"//      g1's shape. A type nobody walks in container order collects the split's\n"
"//      cost, a dependent miss per cold touch, and none of that benefit. The model\n"
"//      nevertheless prefers a split for such types, and the reason is nameable:\n"
"//      `mu_for` reads a cache tier off `AIF_N_ASSUMED * hot_size`, and\n"
"//      AIF_N_ASSUMED is a fabricated 2^20 for every type in the program, so\n"
"//      shaving 8 bytes off a *singleton* can cross a tier boundary and divide its\n"
"//      modelled cost by six. Measured, interleaved, 20 pairs: g4's `World` -- one\n"
"//      instance, six fields, five of them Lists -- was split 2/6 at a modelled 24\n"
"//      and ran at 1.04x. LAYOUT 10.4 already records that static frequency\n"
"//      estimation is crude; this is the clause that stops it choosing a layout.\n"
"//   5. **A type with an inline struct field.** The model does not know how big\n"
"//      such a type is. `aifDeclare` sizes every field with `aifTypeBytes`, which\n"
"//      answers 8 for a struct-typed field because the struct registry is empty\n"
"//      during the analysis -- so `g3_scene_graph`'s `Node`, whose two inline\n"
"//      `Transform`s are 48 bytes each, is modelled as 40 bytes and is really 112.\n"
"//      A cut chosen from a shape that wrong is not a choice. Measured: Node was\n"
"//      split 4/7 at a modelled 12 and ran at 1.11x, the largest regression in the\n"
"//      corpus. Sizing inline fields correctly would move Theta_stack and therefore\n"
"//      tiers, which is a separate change; declining to choose is not.\n"
"//\n"
"// Field 0 of the chosen order is pinned hot by `aif_layout_rank` and never\n"
"// offered to a cut, because the punned-slot invariant is about the first byte of\n"
"// the object (tests/test_41_punned_slot_bytes.psm). The split cannot move it, and\n"
"// `str_equals(ptr, \"\")` still reads what it read.\n"
"//\n"
"// Runs after `aif_layout_select` and after `aifComputeSizes`, and *before* the\n"
"// solve. Before the solve because `type_releases_of` reads the answer; after the\n"
"// sizes because the sizes are computed from the unsplit order on purpose -- see\n"
"// aif_layout_field_bytes.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"void aif_layout_no_split(const char* type) {\n"
"    int id = nominal_find(type);\n"
"    if (id >= 0) nominals[id].no_split = 1;\n"
"}\n"
"\n"
"// Veto 5's channel, separate from veto 1's because LAYOUT 8 may override this one\n"
"// and must never override that one. Both are pushed in by aifLayoutVetoInline from\n"
"// the same discovery -- a struct with an inline struct field -- but they say\n"
"// different things: the *field's type* cannot be split at all (no allocator hook\n"
"// writes its link word), while the *owner* merely cannot be modelled, because\n"
"// aifTypeBytes sizes that field as one pointer. The owner's split is sound.\n"
"void aif_layout_no_split_unmodelled(const char* type) {\n"
"    int id = nominal_find(type);\n"
"    if (id >= 0) nominals[id].no_split_unmodelled = 1;\n"
"}\n"
"\n"
"// Veto 4's test. `sequential` is set by aif_traversal_elem when a loop binds a\n"
"// container element -- `let p = list_get(ps, i)` -- which is exactly the shape\n"
"// layout_repr.c measured and the only shape the 0.87x is evidence for.\n"
"static int has_sequential_traversal(int id) {\n"
"    for (int i = 0; i < traversal_count; i++) {\n"
"        if (traversals[i].type == nominals[id].name && traversals[i].sequential)\n"
"            return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// `forced` says a human named this type's cut, so the two vetoes that exist\n"
"// because the *model* had no basis to choose (4 and 5) are not reasons to decline\n"
"// -- gathering the missing evidence is what LAYOUT 8 does. The three that say the\n"
"// cold block cannot be reached are checked either way, and a force cannot clear\n"
"// them: no measurement makes a wild load or a double free acceptable.\n"
"static int split_admissible(int id, int forced) {\n"
"    Nominal* t = &nominals[id];\n"
"    if (t->is_enum || t->nfields < 3) return 0;    // veto 3\n"
"    if (t->no_split) return 0;                     // veto 1, and veto 2 via the frontend\n"
"    if (bits_test(&t->reaches, id)) return 0;      // veto 2\n"
"    if (forced) return 1;\n"
"    if (t->no_split_unmodelled) return 0;          // veto 5\n"
"    if (!has_sequential_traversal(id)) return 0;   // veto 4\n"
"    return 1;\n"
"}\n"
"\n"
"// The candidate whose hot group is exactly `hot_count` fields, or -1. Cuts are\n"
"// generated one per distinct access-count boundary, so at most one candidate has\n"
"// any given hot_count and this is a lookup rather than a search for a best match.\n"
"static int candidate_with_hot(int hot_count) {\n"
"    for (int i = 0; i < g_cand_count; i++)\n"
"        if (g_cands[i].hot_count == hot_count) return i;\n"
"    return -1;\n"
"}\n"
"\n"
"void aif_layout_split_select(void) {\n"
"    for (int n = 0; n < nominal_count; n++) {\n"
"        Nominal* t = &nominals[n];\n"
"        t->hot_count = 0;\n"
"        bits_free(&t->hot);\n"
"        t->hot.w = NULL;\n"
"        t->hot.nwords = 0;\n"
"        int forced = forced_hot_for(aif_str(t->name));\n"
"        if (!split_admissible(n, forced >= 0)) continue;\n"
"        if (aif_layout_rank(aif_str(t->name)) < 2) continue;\n"
"\n"
"        int pick = g_cand_best;\n"
"        if (forced >= 0) {\n"
"            // A forced cut still has to *be* a candidate. Anything else would let\n"
"            // a typo emit a layout the model never scored and the report never\n"
"            // printed -- and `--layout`'s table is where the number came from.\n"
"            int match = candidate_with_hot(forced);\n"
"            if (match >= 0) {\n"
"                forced_mark_applied(aif_str(t->name));\n"
"                pick = match;\n"
"            } else if (!split_admissible(n, 0)) {\n"
"                // **\"Did not apply\" has to mean nothing changed**, and getting\n"
"                // here by `continue` is what it meant for one build of this\n"
"                // function: an unmatched force left hot_count at 0, so a mistyped\n"
"                // cut did not fall back to the argmin, it turned the split *off*.\n"
"                // A search script would then measure the unsplit record, be told\n"
"                // by the warning that its force missed, and still have a plausible\n"
"                // number filed against a cut nothing emitted.\n"
"                //\n"
"                // So an unmatched force falls through to the argmin -- except for a\n"
"                // type that only became admissible *because* it was forced, where\n"
"                // the argmin is a split the vetoes had excluded. Re-asking without\n"
"                // the force is what distinguishes the two, and it is the same\n"
"                // question this loop already answered a few lines up.\n"
"                continue;\n"
"            }\n"
"        }\n"
"\n"
"        // Candidate 0 is the unsplit record and wins ties, so `pick != 0` already\n"
"        // means \"strictly cheaper than not splitting\" (see aif_layout_rank). A\n"
"        // force of the unsplit candidate lands here too, and correctly: it applied,\n"
"        // and what it asked for is no split.\n"
"        if (pick == 0) continue;\n"
"        int hc = g_cands[pick].hot_count;\n"
"        if (hc < 1 || hc >= t->nfields) continue;\n"
"        for (int f = 0; f < t->nfields; f++) {\n"
"            if (bits_test(&g_cands[pick].hot, f))\n"
"                bits_set(&t->hot, f, \"AIF hot group\");\n"
"        }\n"
"        t->hot_count = hc;\n"
"    }\n"
"    candidates_clear();\n"
"}\n"
"\n"
"// How many fields the hot record keeps, or 0 when the type is not split. Codegen\n"
"// reads it once per type and passes it straight to ir_struct_type_split; the\n"
"// backend needs no other AIF fact to emit the whole transform.\n"
"int aif_layout_hot_count(const char* type) {\n"
"    int id = nominal_find(type);\n"
"    return id >= 0 ? nominals[id].hot_count : 0;\n"
"}\n"
"\n"
"// The declaration index of the field placed i-th in the order codegen emits.\n"
"//\n"
"// Unsplit that is `order` and nothing else. Split, it is `order` read twice --\n"
"// the hot fields in placement order, then the cold ones -- so the emitted index\n"
"// space is exactly `[0, hot_count)` hot and `[hot_count, nfields)` cold, and\n"
"// ir_struct_field_ptr can decide which side a field is on by comparing one\n"
"// integer.\n"
"static int split_slot(Nominal* t, int i) {\n"
"    if (t->hot_count <= 0) return t->order[i];\n"
"    int seen = 0;\n"
"    for (int j = 0; j < t->nfields; j++) {\n"
"        int f = t->order[j];\n"
"        if (!bits_test(&t->hot, f)) continue;\n"
"        if (seen == i) return f;\n"
"        seen++;\n"
"    }\n"
"    for (int j = 0; j < t->nfields; j++) {\n"
"        int f = t->order[j];\n"
"        if (bits_test(&t->hot, f)) continue;\n"
"        if (seen == i) return f;\n"
"        seen++;\n"
"    }\n"
"    return t->order[i];\n"
"}\n"
"\n"
"// How many traversals the profile recorded for a type. A type with none is one\n"
"// the model has nothing to say about, and the report says so rather than printing\n"
"// a ratio derived from an empty sum.\n"
"int aif_layout_traversals(const char* type) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return 0;\n"
"    int n = 0;\n"
"    for (int i = 0; i < traversal_count; i++)\n"
"        if (traversals[i].type == nominals[id].name) n++;\n"
"    return n;\n"
"}\n"
"\n"
"// The i-th field of `type` in the chosen order, or \"\" when there is none. Codegen\n"
"// reads this to emit the struct body, and ir_register_struct_field follows in the\n"
"// same loop -- so the name -> index map and the LLVM type stay in lockstep and\n"
"// every field access follows without knowing anything about layout.\n"
"const char* aif_layout_field(const char* type, int i) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return \"\";\n"
"    Nominal* t = &nominals[id];\n"
"    if (i < 0 || i >= t->nfields) return \"\";\n"
"    return aif_str(t->field_name[split_slot(t, i)]);\n"
"}\n"
"\n"
"int aif_layout_reordered(const char* type) {\n"
"    int id = nominal_find(type);\n"
"    return id >= 0 ? nominals[id].reordered : 0;\n"
"}\n"
"\n"
"// The width of the field placed i-th, so the size computation walks the layout\n"
"// the search chose rather than the one the source wrote.\n"
"//\n"
"// **Deliberately `order` and not `split_slot`, and the link word is deliberately\n"
"// not counted.** This feeds aifComputeSizes, which feeds Theta_stack, which the\n"
"// T0 clause reads -- so anything this returns can move a tier. The split is\n"
"// chosen *after* the sizes are computed for exactly that reason: layout selection\n"
"// runs before the solve (SPEC 7.2, test_49's note) so that a layout cannot change\n"
"// what the analysis concludes, and a split that added 8 bytes per object to the\n"
"// stack budget would be layout feeding back into the solve that chose it. The\n"
"// cost is that a split T0 object's frame is understated by one pointer per\n"
"// object; the alternative is a cycle.\n"
"int aif_layout_field_bytes(const char* type, int i) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0) return 0;\n"
"    Nominal* t = &nominals[id];\n"
"    if (i < 0 || i >= t->nfields) return 0;\n"
"    return t->field_bytes[t->order[i]];\n"
"}\n"
"\n"
"// The frontend computes this from the field types once every type is known.\n"
"// It is here rather than derived here because AIF-1's layout *is* declaration\n"
"// order (SPEC 8.2 gives the compiler layout freedom; AIF-1 does not use it), and\n"
"// the frontend is what knows what a field's type lowers to.\n"
"void aif_struct_set_size(const char* name, int bytes) {\n"
"    nominals[nominal_intern(name, 0)].bytes = bytes;\n"
"}\n"
"\n"
"int aif_struct_size(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    return (id >= 0) ? nominals[id].bytes : 0;\n"
"}\n"
"\n"
"// One edge of the type reference graph (INFERENCE 4.4 stage 1). The frontend\n"
"// walks each field's type annotation and reports every nominal type it can\n"
"// reach, so `List<Node>` and `[Node]` both produce an edge to Node -- the\n"
"// element is reachable from the container whatever the container is.\n"
"void aif_type_edge(const char* from, const char* to) {\n"
"    int a = nominal_find(from);\n"
"    int b = nominal_find(to);\n"
"    if (a < 0 || b < 0) return;\n"
"    bits_set(&nominals[a].reaches, b, \"AIF type graph\");\n"
"}\n"
"\n"
"// Transitive closure, then: a type is cyclic when it reaches itself, or reaches\n"
"// anything that reaches itself. Acyclic is the complement.\n"
"//\n"
"// Closure rather than Tarjan because the graph has one node per nominal type --\n"
"// tens, not thousands -- so an O(n^3/64) fixpoint is free and has no recursion\n"
"// depth to get wrong.\n"
"void aif_compute_type_acyclic(void) {\n"
"    int changed = 1;\n"
"    while (changed) {\n"
"        changed = 0;\n"
"        for (int t = 0; t < nominal_count; t++) {\n"
"            for (int u = 0; u < nominal_count; u++) {\n"
"                if (!bits_test(&nominals[t].reaches, u)) continue;\n"
"                if (bits_or(&nominals[t].reaches, &nominals[u].reaches, \"AIF type graph\")) {\n"
"                    changed = 1;\n"
"                }\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    for (int t = 0; t < nominal_count; t++) {\n"
"        int cyclic = bits_test(&nominals[t].reaches, t);\n"
"        for (int u = 0; !cyclic && u < nominal_count; u++) {\n"
"            if (bits_test(&nominals[t].reaches, u) && bits_test(&nominals[u].reaches, u)) {\n"
"                cyclic = 1;\n"
"            }\n"
"        }\n"
"        nominals[t].acyclic = !cyclic;\n"
"    }\n"
"}\n"
"\n"
"// Unknown types report acyclic. They are scalars and externs' opaque returns --\n"
"// none of which can hold a reference back into the program, so there is nothing\n"
"// for them to be part of a cycle with.\n"
"static int type_acyclic_id(int name) {\n"
"    int id = nominal_find_id(name);\n"
"    return (id < 0) ? 1 : nominals[id].acyclic;\n"
"}\n"
"\n"
"int aif_type_acyclic(const char* name) { return type_acyclic_id(aif_intern(name)); }\n"
"\n"
"int aif_nominal_count(void) { return nominal_count; }\n"
"const char* aif_nominal_name(int i) { return (i < 0 || i >= nominal_count) ? \"\" : aif_str(nominals[i].name); }\n"
"int aif_nominal_is_struct(int i)    { return (i < 0 || i >= nominal_count) ? 0 : !nominals[i].is_enum; }\n"
"int aif_nominal_acyclic(int i)      { return (i < 0 || i >= nominal_count) ? 1 : nominals[i].acyclic; }\n"
"\n"
"// ============================================================================\n"
"// Allocation sites\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int type;       // interned type display name\n"
"    int kind;\n"
"    int fn;\n"
"    int ordinal;    // position among its function's sites, in walk order\n"
"    int scope;\n"
"    int file, line, col;\n"
"    int nfields;\n"
"    // M3.2. Position of the statement this site sits in, within its own block,\n"
"    // or -1 where the walk did not stamp one. A scope is a lexical *set* of\n"
"    // statements and says nothing about their order, so an extent that ends at\n"
"    // last use rather than at the closing brace cannot be expressed without\n"
"    // this. Recorded ahead of the analysis that reads it, and inert until then.\n"
"    int stmt;\n"
"    int bytes;          // stamped once, before iteration\n"
"    int E, A, C, T;\n"
"    int type_acyclic;   // stamped once, before iteration\n"
"    int no_stack;       // explicitly dropped -- see AIF_CON_NO_STACK\n"
"    // Stored into a container by a `retain_in` call. The container owns it from\n"
"    // that point on, which is what makes a container teardown a release point --\n"
"    // and what takes the value's own binding off the drop list.\n"
"    int in_container;\n"
"    // SPEC 5.1. `unique` asserts A = Unique and cuts the aliasing graph: a rule\n"
"    // that would raise A above Unique is suppressed rather than applied.\n"
"    int alias_axiom;\n"
"    int alias_suppressed;   // the axiom actually stopped a rule; reported\n"
"    // SPEC 5.4. The tier a `pin` froze, or -1. Applied after convergence.\n"
"    int pin_tier;\n"
"    int pin_verdict;        // AIF_PIN_*, decided by aif_check_pins\n"
"    // SPEC 5.4 on placement rather than on the tier: the interned name of the\n"
"    // `region` a `pin(<region-name>)` asserted must serve this value, or -1.\n"
"    // Separate from pin_tier because they are orthogonal claims about one site\n"
"    // and a single slot would make `let pin(T2) pin(frame) x` silently drop one\n"
"    // of them.\n"
"    int pin_region;\n"
"    int pin_region_verdict; // AIF_PIN_*, decided by aif_check_placement_pins\n"
"} Site;\n"
"\n"
"// SPEC 5.4's four outcomes, plus \"there is no pin here\".\n"
"#define AIF_PIN_NONE     0\n"
"#define AIF_PIN_HONOURED 1\n"
"#define AIF_PIN_REFUTED  2   // converged facts make it unreachable -- an error\n"
"#define AIF_PIN_UNPROVEN 3   // budget ran out -- a warning, and the pin is dropped\n"
"\n"
"static Site* sites;\n"
"static int site_count, site_cap;\n"
"static int orphan_sites;    // sites with no enclosing function; none today\n"
"\n"
"// The statement the walk is currently inside, in the same style as aif_con_at's\n"
"// source position: set by the frontend as it goes, read by whatever gets\n"
"// created next. -1 means \"not stamped\", which is what every site had before\n"
"// M3.2 and what any construction the walk reaches by another path still has.\n"
"static int g_stmt = -1;\n"
"\n"
"// Per scope, the statement of *that* scope the walk is currently inside. The\n"
"// array rather than a single cursor is what makes a nested use answerable: while\n"
"// the walk is down inside a nested block, scope_stmt[outer] still names the\n"
"// statement of `outer` that contains it, because only `outer`'s own chain ever\n"
"// writes it. That is exactly the question an extent has to answer -- \"which\n"
"// statement of the region does this use pin open\" -- and a single cursor would\n"
"// have already been overwritten by the inner block.\n"
"static int* scope_stmt;\n"
"static int scope_stmt_cap;\n"
"\n"
"static void scope_stmt_grow(int scope) {\n"
"    if (scope < scope_stmt_cap) return;\n"
"    int grow = scope_stmt_cap ? scope_stmt_cap * 2 : 256;\n"
"    if (grow <= scope) grow = scope + 1;\n"
"    scope_stmt = (int*)xrealloc(scope_stmt, (size_t)grow * sizeof(int), \"AIF statement positions\");\n"
"    for (int i = scope_stmt_cap; i < grow; i++) scope_stmt[i] = -1;\n"
"    scope_stmt_cap = grow;\n"
"}\n"
"\n"
"void aif_stmt_at(int scope, int index) {\n"
"    g_stmt = index < 0 ? -1 : index;\n"
"    if (scope < 0) return;\n"
"    scope_stmt_grow(scope);\n"
"    scope_stmt[scope] = g_stmt;\n"
"}\n"
"\n"
"// M3.2b. The last statement, in a key's own declaring scope, at which the key is\n"
"// read. The end of a non-lexical extent is the maximum of this over the keys\n"
"// holding what the arena serves.\n"
"//\n"
"// **Monotone by construction, which is why one slot is enough.** Statements are\n"
"// walked in source order, so scope_stmt[d] only ever grows while d's chain is\n"
"// being walked; taking the max over mentions therefore lands on the last one\n"
"// without having to know in advance which mention that is.\n"
"static int* key_last_stmt;\n"
"static int key_last_stmt_cap;\n"
"\n"
"static void key_last_stmt_grow(int key) {\n"
"    if (key < key_last_stmt_cap) return;\n"
"    int grow = key_last_stmt_cap ? key_last_stmt_cap * 2 : 1024;\n"
"    if (grow <= key) grow = key + 1;\n"
"    key_last_stmt = (int*)xrealloc(key_last_stmt, (size_t)grow * sizeof(int), \"AIF last use\");\n"
"    for (int i = key_last_stmt_cap; i < grow; i++) key_last_stmt[i] = -1;\n"
"    key_last_stmt_cap = grow;\n"
"}\n"
"\n"
"\n"
"\n"
"int aif_site_new(const char* type, int kind, int fn, int scope,\n"
"                 int file, int line, int col, int nfields) {\n"
"    if (site_count == site_cap) {\n"
"        site_cap = site_cap ? site_cap * 2 : 1024;\n"
"        sites = (Site*)xrealloc(sites, (size_t)site_cap * sizeof(Site), \"AIF sites\");\n"
"    }\n"
"    Site* s = &sites[site_count];\n"
"    s->type = aif_intern(type);\n"
"    s->kind = kind;\n"
"    s->fn = fn;\n"
"    // The manifest is diffed, so a record's name must not move when an\n"
"    // unrelated line elsewhere in the file does. Numbering within the declaring\n"
"    // function gives that: an edit is visible on the function it changed and\n"
"    // nowhere else.\n"
"    s->ordinal = (fn >= 0 && fn < fn_count) ? fns[fn].nsites++ : orphan_sites++;\n"
"    s->scope = scope;\n"
"    s->file = file;\n"
"    s->line = line;\n"
"    s->col = col;\n"
"    s->nfields = nfields;\n"
"    s->stmt = g_stmt;\n"
"    s->bytes = 0;\n"
"    s->type_acyclic = 1;\n"
"    s->no_stack = 0;\n"
"    s->in_container = 0;\n"
"    s->alias_axiom = 0;\n"
"    s->alias_suppressed = 0;\n"
"    s->pin_tier = -1;\n"
"    s->pin_verdict = AIF_PIN_NONE;\n"
"    s->pin_region = -1;\n"
"    s->pin_region_verdict = AIF_PIN_NONE;\n"
"    // Bottom, per INFERENCE 5.2 line 2: Region(defscope), Unique, Acyclic,\n"
"    // Isolated. T-DEFAULT is this line and nothing else -- \"any node has\n"
"    // T >= Isolated\" is a statement about the bottom element, not a rule that\n"
"    // has to fire.\n"
"    s->E = scope;\n"
"    s->A = AIF_A_UNIQUE;\n"
"    s->C = AIF_C_ACYCLIC;\n"
"    s->T = AIF_T_ISOLATED;\n"
"    return site_count++;\n"
"}\n"
"\n"
"int aif_site_count(void) { return site_count; }\n"
"\n"
"const char* aif_site_type(int id) { return (id < 0 || id >= site_count) ? \"\" : aif_str(sites[id].type); }\n"
"int aif_site_kind(int id)    { return (id < 0 || id >= site_count) ? AIF_K_OPAQUE : sites[id].kind; }\n"
"int aif_site_fn(int id)      { return (id < 0 || id >= site_count) ? -1 : sites[id].fn; }\n"
"int aif_site_scope(int id)   { return (id < 0 || id >= site_count) ? -1 : sites[id].scope; }\n"
"int aif_site_file(int id)    { return (id < 0 || id >= site_count) ? 0 : sites[id].file; }\n"
"int aif_site_line(int id)    { return (id < 0 || id >= site_count) ? 0 : sites[id].line; }\n"
"int aif_site_col(int id)     { return (id < 0 || id >= site_count) ? 0 : sites[id].col; }\n"
"int aif_site_nfields(int id) { return (id < 0 || id >= site_count) ? 0 : sites[id].nfields; }\n"
"int aif_site_ordinal(int id) { return (id < 0 || id >= site_count) ? 0 : sites[id].ordinal; }\n"
"int aif_site_escape(int id)  { return (id < 0 || id >= site_count) ? AIF_E_GLOBAL : sites[id].E; }\n"
"int aif_site_alias(int id)   { return (id < 0 || id >= site_count) ? AIF_A_SHARED : sites[id].A; }\n"
"int aif_site_cyc(int id)     { return (id < 0 || id >= site_count) ? AIF_C_MAYBE : sites[id].C; }\n"
"\n"
"// ============================================================================\n"
"// Points-to keys\n"
"//\n"
"// A key names a location that can hold references: a local binding, a struct\n"
"// field (field-sensitive, object-insensitive -- INFERENCE 3.1), a return\n"
"// position, or a parameter. Identity is the tuple, so the same name in two\n"
"// functions is two keys, and `Lexer.source` is one key across every Lexer.\n"
"// ============================================================================\n"
"\n"
"#define AIF_KEY_VAR    0\n"
"#define AIF_KEY_FIELD  1\n"
"#define AIF_KEY_RET    2\n"
"#define AIF_KEY_PARAM  3\n"
"#define AIF_KEY_EXTERN 4\n"
"\n"
"#define AIF_KEY_BUCKETS 16384\n"
"\n"
"typedef struct KeyNode {\n"
"    struct KeyNode* next;\n"
"    int kind, a, b;\n"
"    int id;\n"
"} KeyNode;\n"
"\n"
"static KeyNode* key_buckets[AIF_KEY_BUCKETS];\n"
"static int key_count;\n"
"\n"
"static int key_intern(int kind, int a, int b) {\n"
"    unsigned h = (unsigned)kind * 2654435761u\n"
"               ^ (unsigned)a * 40503u\n"
"               ^ (unsigned)b * 2246822519u;\n"
"    unsigned bucket = h & (AIF_KEY_BUCKETS - 1);\n"
"    for (KeyNode* n = key_buckets[bucket]; n; n = n->next) {\n"
"        if (n->kind == kind && n->a == a && n->b == b) return n->id;\n"
"    }\n"
"    KeyNode* n = (KeyNode*)xmalloc(sizeof(KeyNode), \"AIF points-to keys\");\n"
"    n->kind = kind;\n"
"    n->a = a;\n"
"    n->b = b;\n"
"    n->id = key_count++;\n"
"    n->next = key_buckets[bucket];\n"
"    key_buckets[bucket] = n;\n"
"    return n->id;\n"
"}\n"
"\n"
"int aif_key_var(int fn, const char* name)            { return key_intern(AIF_KEY_VAR, fn, aif_intern(name)); }\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Declaring scopes\n"
"//\n"
"// E-BIND needs the scope a *variable* was declared in, not the scope the\n"
"// assignment sits in. Without it a value created inside a loop and assigned to a\n"
"// binding declared outside keeps the loop body's escape -- which reads as \"dies\n"
"// at the end of this iteration\" and is false, because the outer binding still\n"
"// refers to it on the next one.\n"
"//\n"
"// At Level 0 that was invisible: every tier is semantically valid and nothing\n"
"// allocated differently. It stops being invisible the moment T0 emits one\n"
"// hoisted alloca per site and every iteration writes the same slot.\n"
"//\n"
"// Shadowing joins outward. Two declarations of one name in sibling blocks join\n"
"// to their least common ancestor, which is at least as long-lived as either, so\n"
"// the answer is conservative rather than dependent on which the walk saw last.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static int* var_scope;\n"
"static int var_scope_cap;\n"
"\n"
"static void var_scope_grow(int key) {\n"
"    if (key < var_scope_cap) return;\n"
"    int grow = var_scope_cap ? var_scope_cap * 2 : 1024;\n"
"    if (grow <= key) grow = key + 1;\n"
"    var_scope = (int*)xrealloc(var_scope, (size_t)grow * sizeof(int), \"AIF declaring scopes\");\n"
"    for (int i = var_scope_cap; i < grow; i++) var_scope[i] = -1;\n"
"    var_scope_cap = grow;\n"
"}\n"
"\n"
"void aif_var_note_scope(int fn, const char* name, int scope) {\n"
"    int key = aif_key_var(fn, name);\n"
"    var_scope_grow(key);\n"
"    if (var_scope[key] < 0) {\n"
"        var_scope[key] = scope;\n"
"        return;\n"
"    }\n"
"    int m = scope_lca(var_scope[key], scope);\n"
"    if (m >= 0) var_scope[key] = m;\n"
"}\n"
"\n"
"// Called at every read of a binding. Declines rather than guesses in the two\n"
"// cases where the answer would not mean anything: a name with no declaration on\n"
"// record yet (a global, or an assignment the walk reached first -- the same case\n"
"// aif_var_scope returns -1 for), and a read that is not underneath its declaring\n"
"// scope's statement list at all.\n"
"void aif_var_note_use(int fn, const char* name, int scope) {\n"
"    (void)scope;\n"
"    int key = aif_key_var(fn, name);\n"
"    int d = (key < var_scope_cap) ? var_scope[key] : -1;\n"
"    if (d < 0 || d >= scope_stmt_cap) return;\n"
"    int at = scope_stmt[d];\n"
"    if (at < 0) return;\n"
"    key_last_stmt_grow(key);\n"
"    if (at > key_last_stmt[key]) key_last_stmt[key] = at;\n"
"}\n"
"\n"
"int aif_key_last_stmt(int key) {\n"
"    return (key < 0 || key >= key_last_stmt_cap) ? -1 : key_last_stmt[key];\n"
"}\n"
"\n"
"// -1 when the name has no declaration on record -- a global, or an assignment\n"
"// the walk reached before the declaration. The caller falls back to the\n"
"// assignment's own scope, which is what this function replaced.\n"
"int aif_var_scope(int fn, const char* name) {\n"
"    int key = aif_key_var(fn, name);\n"
"    return (key < var_scope_cap) ? var_scope[key] : -1;\n"
"}\n"
"int aif_key_field(const char* type, const char* fld) { return key_intern(AIF_KEY_FIELD, aif_intern(type), aif_intern(fld)); }\n"
"int aif_key_ret(int fn)                              { return key_intern(AIF_KEY_RET, fn, 0); }\n"
"int aif_key_param(int fn, int index)                 { return key_intern(AIF_KEY_PARAM, fn, index); }\n"
"int aif_key_count(void)                              { return key_count; }\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Declared FFI contracts\n"
"//\n"
"// What an `extern` declaration says about ownership (FFI 5), keyed by the\n"
"// callee's name and a parameter index. Index -1 holds the return contract and\n"
"// -2 marks the name as declared at all.\n"
"//\n"
"// Keyed through the same tuple map as everything else, so a contract lookup at a\n"
"// call site is one hash rather than a scan over declarations.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static int* extern_contract;    // key id -> interned contract text, -1 unset\n"
"static int extern_contract_cap;\n"
"\n"
"static void extern_contract_grow(int key) {\n"
"    if (key < extern_contract_cap) return;\n"
"    int grow = extern_contract_cap ? extern_contract_cap * 2 : 1024;\n"
"    if (grow <= key) grow = key + 1;\n"
"    extern_contract = (int*)xrealloc(extern_contract, (size_t)grow * sizeof(int),\n"
"                                     \"AIF extern contracts\");\n"
"    for (int i = extern_contract_cap; i < grow; i++) extern_contract[i] = -1;\n"
"    extern_contract_cap = grow;\n"
"}\n"
"\n"
"void aif_extern_contract_set(const char* fn, int index, const char* contract) {\n"
"    int key = key_intern(AIF_KEY_EXTERN, aif_intern(fn), index);\n"
"    extern_contract_grow(key);\n"
"    extern_contract[key] = aif_intern(contract);\n"
"}\n"
"\n"
"// \"\" when nothing was declared, which the frontend reads as \"fall through to the\n"
"// default\" rather than as a contract in its own right.\n"
"const char* aif_extern_contract(const char* fn, int index) {\n"
"    int key = key_intern(AIF_KEY_EXTERN, aif_intern(fn), index);\n"
"    if (key >= extern_contract_cap || extern_contract[key] < 0) return \"\";\n"
"    return aif_str(extern_contract[key]);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Value-set expressions\n"
"//\n"
"// The set of sites an expression may denote: part known while walking (a struct\n"
"// literal is its own site), part only at the fixed point (an identifier is\n"
"// whatever its binding points to). Holding both in one object is what lets the\n"
"// AST walk compose expressions uniformly without knowing which it has.\n"
"//\n"
"// Items are tagged integers -- an even item is a site, an odd item is a key.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int* items;\n"
"    int len, cap;\n"
"    // SPEC 8.4 view provenance: the collections these values are views *of*,\n"
"    // held as value-set ids and resolved with everything else at solve time.\n"
"    // Empty for every value set that is not a view, which is nearly all of them.\n"
"    int* views;\n"
"    int vlen, vcap;\n"
"} ValueSet;\n"
"\n"
"static ValueSet* vsets;\n"
"static int vs_count, vs_cap;\n"
"\n"
"int aif_vs_new(void) {\n"
"    if (vs_count == vs_cap) {\n"
"        vs_cap = vs_cap ? vs_cap * 2 : 1024;\n"
"        vsets = (ValueSet*)xrealloc(vsets, (size_t)vs_cap * sizeof(ValueSet), \"AIF value sets\");\n"
"    }\n"
"    ValueSet* v = &vsets[vs_count];\n"
"    v->items = NULL;\n"
"    v->len = 0;\n"
"    v->cap = 0;\n"
"    v->views = NULL;\n"
"    v->vlen = 0;\n"
"    v->vcap = 0;\n"
"    return vs_count++;\n"
"}\n"
"\n"
"static void vs_push(int vs, int item) {\n"
"    if (vs < 0 || vs >= vs_count) return;\n"
"    ValueSet* v = &vsets[vs];\n"
"    for (int i = 0; i < v->len; i++) {\n"
"        if (v->items[i] == item) return;\n"
"    }\n"
"    if (v->len == v->cap) {\n"
"        v->cap = v->cap ? v->cap * 2 : 4;\n"
"        v->items = (int*)xrealloc(v->items, (size_t)v->cap * sizeof(int), \"AIF value set\");\n"
"    }\n"
"    v->items[v->len++] = item;\n"
"}\n"
"\n"
"void aif_vs_site(int vs, int site) { vs_push(vs, site * 2); }\n"
"void aif_vs_key(int vs, int key)   { vs_push(vs, key * 2 + 1); }\n"
"\n"
"static void vs_push_view(int vs, int cvs) {\n"
"    if (vs < 0 || vs >= vs_count || cvs < 0) return;\n"
"    ValueSet* v = &vsets[vs];\n"
"    for (int i = 0; i < v->vlen; i++) {\n"
"        if (v->views[i] == cvs) return;\n"
"    }\n"
"    if (v->vlen == v->vcap) {\n"
"        v->vcap = v->vcap ? v->vcap * 2 : 2;\n"
"        v->views = (int*)xrealloc(v->views, (size_t)v->vcap * sizeof(int), \"AIF view provenance\");\n"
"    }\n"
"    v->views[v->vlen++] = cvs;\n"
"}\n"
"\n"
"// SPEC 8.4. Mark this value set as denoting views of `container_vs`.\n"
"//\n"
"// Provenance rather than a points-to edge, and the difference is the whole of\n"
"// item 3's reconciliation. The element key still says *which values* a read can\n"
"// return -- that is what stores through the result need, and merging the\n"
"// container into it is the bug that made a receiving container call\n"
"// list_release on a struct. Provenance says something the points-to graph\n"
"// cannot: *how long the container must live* for the reference to be legal.\n"
"void aif_vs_view_of(int vs, int container_vs) { vs_push_view(vs, container_vs); }\n"
"\n"
"int aif_vs_is_empty(int vs) {\n"
"    return (vs < 0 || vs >= vs_count) ? 1 : (vsets[vs].len == 0);\n"
"}\n"
"\n"
"int aif_vs_union(int a, int b) {\n"
"    int out = aif_vs_new();\n"
"    if (a >= 0 && a < vs_count) {\n"
"        for (int i = 0; i < vsets[a].len; i++) vs_push(out, vsets[a].items[i]);\n"
"        for (int i = 0; i < vsets[a].vlen; i++) vs_push_view(out, vsets[a].views[i]);\n"
"    }\n"
"    if (b >= 0 && b < vs_count) {\n"
"        for (int i = 0; i < vsets[b].len; i++) vs_push(out, vsets[b].items[i]);\n"
"        for (int i = 0; i < vsets[b].vlen; i++) vs_push_view(out, vsets[b].views[i]);\n"
"    }\n"
"    return out;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Argument stacks\n"
"//\n"
"// Two FFI contracts refer to another argument of the same call: `retain_in(k)`\n"
"// says \"the callee stores me into argument k\", and `alias` says \"my return is\n"
"// argument k\". Both need the call's arguments addressable by index while it is\n"
"// being walked -- and calls nest, because an argument can itself be a call.\n"
"//\n"
"// Evaluating an argument creates allocation sites, so it must happen exactly\n"
"// once; re-walking to find argument k would duplicate every site inside it.\n"
"// Hence a stack: the frontend opens a frame, pushes each argument's value set\n"
"// as it evaluates it, indexes freely, and closes the frame.\n"
"// ============================================================================\n"
"\n"
"static IntVec argv;\n"
"\n"
"int aif_argv_begin(void) { return argv.len; }\n"
"\n"
"void aif_argv_push(int vs) { vec_push(&argv, vs, \"AIF call arguments\"); }\n"
"\n"
"int aif_argv_count(int base) { return argv.len - base; }\n"
"\n"
"// Out of range yields -1, which every consumer reads as the empty value set --\n"
"// a contract naming an argument the call does not have contributes nothing.\n"
"int aif_argv_get(int base, int i) {\n"
"    int at = base + i;\n"
"    if (i < 0 || at >= argv.len) return -1;\n"
"    return argv.v[at];\n"
"}\n"
"\n"
"void aif_argv_end(int base) { argv.len = base; }\n"
"\n"
"// ============================================================================\n"
"// Constraints\n"
"//\n"
"// One entry per transfer-rule instance the AST walk discovered. Solving is\n"
"// re-applying all of them until nothing rises.\n"
"// ============================================================================\n"
"\n"
"#define AIF_CON_BIND          0\n"
"#define AIF_CON_ARG           1\n"
"#define AIF_CON_STORE         2\n"
"#define AIF_CON_LIVE_IN       3\n"
"#define AIF_CON_OPAQUE        4\n"
"#define AIF_CON_RETAIN_IN     5\n"
"#define AIF_CON_BORROW        6\n"
"#define AIF_CON_ESCAPE_CALLER 7\n"
"#define AIF_CON_ESCAPE_GLOBAL 8\n"
"#define AIF_CON_NO_STACK      9\n"
"// SPEC 5's annotations. Neither is a transfer rule: both are applied once,\n"
"// between the points-to fixed point and the fact loop, because an axiom that\n"
"// arrives mid-iteration would only cut what had not already been raised.\n"
"#define AIF_CON_UNIQUE       10\n"
"#define AIF_CON_PIN          11\n"
"// Not constraints: the two rules that read a site's own state rather than an\n"
"// incoming edge. They still need names, because a witness path that ends at one\n"
"// has to say so rather than reporting \"no cause\".\n"
"#define AIF_RULE_A_ESCAPE    12\n"
"#define AIF_RULE_A_COPY      13\n"
"#define AIF_RULE_ALLOC       14   // the root: this is where the value is made\n"
"#define AIF_RULE_A_CONTAIN   15\n"
"\n"
"// SPEC 8.4. A view of a collection -- a slice, or a reference to one element.\n"
"//\n"
"// Appended after the synthetic rules rather than inserted beside the other\n"
"// constraints because AIF_RULE_ALLOC's ordinal is spelled again in\n"
"// src/aif/model.psm. Renumbering here would rename the derivation root there,\n"
"// and the two would disagree without either one failing to build.\n"
"#define AIF_CON_VIEW_OF      16\n"
"\n"
"// SPEC 5.4 applied to placement: `pin(<region-name>)`. Appended for the same\n"
"// reason AIF_CON_VIEW_OF was -- AIF_RULE_ALLOC's ordinal is written out again in\n"
"// src/aif/model.psm, so inserting anything below 16 renames the derivation root\n"
"// there and neither side fails to build.\n"
"//\n"
"// `b` is the interned region name, not a tier. Applied in the same pass as\n"
"// AIF_CON_PIN because it is an assertion about the result and not a transfer\n"
"// rule; *adjudicated* much later than AIF_CON_PIN, because what it asserts is an\n"
"// output of arena placement, which has not run yet.\n"
"#define AIF_CON_PIN_REGION   17\n"
"\n"
"// REQUIREMENTS 15, INFERENCE 4.1/4.3. The arguments of one `spawn`.\n"
"//\n"
"// Appended for the third time for the same reason AIF_CON_VIEW_OF and\n"
"// AIF_CON_PIN_REGION were: AIF_RULE_ALLOC's ordinal 14 is written out again in\n"
"// src/aif/model.psm, so anything inserted below it renames the derivation root\n"
"// there and neither side fails to build.\n"
"//\n"
"// One constraint per spawn site rather than one per argument. E-SPAWN-J's\n"
"// premise -- \"joined on every path before scope s exits\" -- is a property of\n"
"// the *call*, and splitting it per argument would make each one re-derive it.\n"
"// `b` carries the enclosing scope so E-SPAWN-J has somewhere to bind to; `c` is\n"
"// 1 when the task is joined in that scope and 0 when it is not.\n"
"#define AIF_CON_SPAWN        18\n"
"\n"
"typedef struct {\n"
"    int kind, a, b, c;\n"
"    // Where in the source this constraint came from. Carried so a manifest diff\n"
"    // can name the store or the call that moved a fact (SPEC 6.3's example puts\n"
"    // a file:line on every edge of the witness path), not just which rule fired.\n"
"    int file, line, col;\n"
"} Constraint;\n"
"\n"
"static Constraint* cons;\n"
"static int con_count, con_cap;\n"
"static int con_file, con_line, con_col;\n"
"\n"
"static void con_add(int kind, int a, int b, int c) {\n"
"    if (con_count == con_cap) {\n"
"        con_cap = con_cap ? con_cap * 2 : 4096;\n"
"        cons = (Constraint*)xrealloc(cons, (size_t)con_cap * sizeof(Constraint), \"AIF constraints\");\n"
"    }\n"
"    cons[con_count].file = con_file;\n"
"    cons[con_count].line = con_line;\n"
"    cons[con_count].col = con_col;\n"
"    Constraint* k = &cons[con_count++];\n"
"    k->kind = kind;\n"
"    k->a = a;\n"
"    k->b = b;\n"
"    k->c = c;\n"
"}\n"
"\n"
"void aif_con_bind(int key, int vs)              { con_add(AIF_CON_BIND, key, vs, 0); }\n"
"void aif_con_arg(int key, int vs)               { con_add(AIF_CON_ARG, key, vs, 0); }\n"
"void aif_con_store(int key, int vs, int owners) { con_add(AIF_CON_STORE, key, vs, owners); }\n"
"void aif_con_live_in(int vs, int scope, int fn) { con_add(AIF_CON_LIVE_IN, vs, scope, fn); }\n"
"void aif_con_opaque(int vs)                     { con_add(AIF_CON_OPAQUE, vs, 0, 0); }\n"
"void aif_con_retain_in(int vs, int holder)      { con_add(AIF_CON_RETAIN_IN, vs, holder, 0); }\n"
"void aif_con_borrow(int vs)                     { con_add(AIF_CON_BORROW, vs, 0, 0); }\n"
"void aif_con_escape_caller(int vs)              { con_add(AIF_CON_ESCAPE_CALLER, vs, 0, 0); }\n"
"void aif_con_escape_global(int vs)              { con_add(AIF_CON_ESCAPE_GLOBAL, vs, 0, 0); }\n"
"void aif_con_unique(int vs)                     { con_add(AIF_CON_UNIQUE, vs, 0, 0); }\n"
"void aif_con_pin(int vs, int tier)              { con_add(AIF_CON_PIN, vs, tier, 0); }\n"
"// INFERENCE 4.3's T-STATIC premise is \"the program creates any task\", which is\n"
"// a whole-program property and therefore not something a per-site rule can ask.\n"
"// Recorded as the constraints are built rather than scanned for later, so a\n"
"// module with no spawn never pays for the question.\n"
"static int program_has_tasks;\n"
"\n"
"int aif_program_has_tasks(void) { return program_has_tasks; }\n"
"\n"
"void aif_con_spawn(int vs, int scope, int joined) {\n"
"    program_has_tasks = 1;\n"
"    con_add(AIF_CON_SPAWN, vs, scope, joined);\n"
"}\n"
"\n"
"void aif_con_pin_region(int vs, const char* name) {\n"
"    con_add(AIF_CON_PIN_REGION, vs, aif_intern(name), 0);\n"
"}\n"
"\n"
"// SPEC 8.4's E-VIEW is not a constraint. It rides the rules that already bound\n"
"// how long a value lives, because that bound is exactly what its collection has\n"
"// to satisfy -- see raise_view_owners. AIF_CON_VIEW_OF survives only as the\n"
"// rule *name* the derivation prints; aif_vs_view_of is what attaches it.\n"
"\n"
"// `drop(x)` lowers to a free, and a stack slot is not a thing that can be freed.\n"
"// A T0 value has no allocation to release -- its storage *is* the frame -- so\n"
"// promoting a value the source explicitly drops turns a working program into\n"
"// heap corruption.\n"
"//\n"
"// This is not a fact about the value and deliberately does not touch E, A or C:\n"
"// an explicit drop says nothing about lifetime or aliasing, and distorting a\n"
"// fact domain to carry a codegen constraint would make the manifest lie about\n"
"// why. It suppresses the T0 clause and nothing else, so the value lands T1/T2 --\n"
"// heap-allocated, with something to free.\n"
"//\n"
"// The better answer is for `drop` on a T0 value to emit nothing at all, which\n"
"// needs codegen to resolve the tier of a *binding* at the drop site rather than\n"
"// the tier of an allocation at its literal. That wants COMPILER-AUDIT 4.1's node\n"
"// ids. Until then this is the sound direction to be wrong in.\n"
"void aif_con_no_stack(int vs)                   { con_add(AIF_CON_NO_STACK, vs, 0, 0); }\n"
"\n"
"int aif_con_count(void) { return con_count; }\n"
"\n"
"// ============================================================================\n"
"// The fixed point\n"
"// ============================================================================\n"
"\n"
"static Bits* pt;            // key id -> set of sites\n"
"static Bits* holders;       // site id -> set of keys holding it\n"
"// site id -> set of *container sites* holding it. Separate from `holders`, which\n"
"// counts keys -- named locations the move checker governs. A container element is\n"
"// neither: `list_push` is a call, so nothing about it is a move, and two pushes\n"
"// of one value are two owners the language never had to notice.\n"
"static Bits* container_of;\n"
"// SPEC 8.4. key id -> set of *collection sites* that values bound to this key\n"
"// are views of. Provenance has to ride the points-to graph and not the value\n"
"// set alone, because a view is nearly always bound to a name before it travels:\n"
"//\n"
"//     let e = list_get(items, i)      // provenance attaches to this value set\n"
"//     return e                        // ...and must still be here\n"
"//\n"
"// The `return` sees the value set of the identifier `e`, which is a key\n"
"// reference with no view of its own. So a key accumulates the provenance of\n"
"// everything bound into it, and resolve_views unions the direct provenance with\n"
"// every key's. Grown in the points-to phase, which reads no fact -- so this is\n"
"// a points-to-shaped relation and it converges with the rest of that phase.\n"
"static Bits* key_views;\n"
"static int pt_len, holders_len;\n"
"static Bits scratch_val, scratch_own, scratch_views;\n"
"static IntVec vec_val, vec_own, vec_views;\n"
"static int solve_rounds;\n"
"static int pt_rounds;       // of solve_rounds, how many the points-to phase used\n"
"\n"
"// Delta, in INFERENCE 5.3's sense: what moved in the round that just ran. On a\n"
"// truncated run that is the frontier the widening has to start from, so it is\n"
"// reset at the top of every round and only the last one's survives.\n"
"static Bits delta;          // sites whose facts moved\n"
"static int  delta_pt;       // did any points-to or holders set grow?\n"
"static Bits widened;        // sites aif_widen raised, for the manifest\n"
"\n"
"// Whether collections are affine, i.e. whether the copy rule applies to them.\n"
"// Today's Prismio makes only structs move-only (types.psm); AIF specifies\n"
"// affine references for every heap value (SPEC 11 item 10). The difference is\n"
"// 100% of the measured T3 residue, so it is a switch rather than an assumption.\n"
"static int owned_collections;\n"
"\n"
"void aif_set_owned_collections(int on) { owned_collections = on ? 1 : 0; }\n"
"\n"
"// A move-only value can be held by several bindings over its lifetime without\n"
"// ever being aliased -- the move checker guarantees the earlier binding is dead\n"
"// -- so multiple holders means sequential ownership, not sharing. A copyable\n"
"// one has no such guarantee.\n"
"static int site_is_move_only(const Site* s) {\n"
"    if (s->kind == AIF_K_STRUCT) return 1;\n"
"    if (!owned_collections) return 0;\n"
"    return s->kind == AIF_K_STRING || s->kind == AIF_K_ARRAY || s->kind == AIF_K_LIST;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// The derivation DAG (INFERENCE 5.6, SPEC 6.3)\n"
"//\n"
"// A manifest diff has to answer *why* a tier moved, and the answer is a witness\n"
"// path from a root cause to the record. INFERENCE 5.6 specifies a backward BFS\n"
"// through **maximal contributors**: for a fact `f` at node `n` holding value\n"
"// `v`, the predecessors whose transfer produced `v`.\n"
"//\n"
"// Keeping every predecessor and searching backward is one way to get that. This\n"
"// keeps **one edge per site per domain** instead, written the moment a rule\n"
"// first raises the fact to the value it ends at -- which is a maximal\n"
"// contributor by construction, because a rule that raises is one that set the\n"
"// value rather than one that merely failed to contradict it. Walking those edges\n"
"// backward is then a chain rather than a search.\n"
"//\n"
"// Two honest consequences of that choice:\n"
"//\n"
"//   * The path is *a* witness, not provably the *shortest* one. The first rule\n"
"//     to reach the final value is recorded, which is the shortest among the\n"
"//     rules that fired in that round, but a different constraint order could\n"
"//     have produced a shorter chain. INFERENCE 5.1 permits the order to vary,\n"
"//     so \"shortest\" was never stable anyway.\n"
"//   * Memory is O(sites), not O(edges). 5.6's requirement is that the DAG be\n"
"//     *retained through tier assignment*, and one maximal edge per fact is\n"
"//     enough to retain what a diff reads back.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int rule;   // the AIF_CON_* that fired, or -1 for \"never raised\"\n"
"    int from;   // the site the value came from, or -1 for an axiom or a root\n"
"    int value;  // what it was raised to\n"
"    int file, line, col;\n"
"} Deriv;\n"
"\n"
"static Deriv* deriv_e;      // why each site's E is what it is\n"
"static Deriv* deriv_a;      // and its A\n"
"static int cur_con = -1;    // the constraint being applied, for attribution\n"
"static int synth_rule = -1; // ...or the rule, when there is no constraint\n"
"static int force_rule = -1; // ...or E-VIEW, which rides other constraints (SPEC 8.4)\n"
"\n"
"// Where the constraint currently being *built* came from. Constraints are added\n"
"// during the walk, one node at a time, so a sticky position costs nothing and\n"
"// keeps ten aif_con_* signatures unchanged.\n"
"void aif_con_at(int file, int line, int col) {\n"
"    con_file = file;\n"
"    con_line = line;\n"
"    con_col = col;\n"
"}\n"
"\n"
"static void note_deriv(Deriv* d, int site, int from, int value) {\n"
"    if (!d) return;\n"
"    int live = (cur_con >= 0 && cur_con < con_count);\n"
"    // SPEC 8.4. A provenance raise is E-VIEW whichever constraint carried it --\n"
"    // the constraint says where the view escaped to, the rule says why the\n"
"    // collection had to follow. The file:line stays the constraint's, because\n"
"    // \"the read that produced the view\" is not the useful place to point: the\n"
"    // use that let it outlive the scope is.\n"
"    d[site].rule  = (force_rule >= 0) ? force_rule\n"
"                                      : (live ? cons[cur_con].kind : synth_rule);\n"
"    d[site].from  = from;\n"
"    d[site].value = value;\n"
"    d[site].file  = live ? cons[cur_con].file : sites[site].file;\n"
"    d[site].line  = live ? cons[cur_con].line : sites[site].line;\n"
"    d[site].col   = live ? cons[cur_con].col  : sites[site].col;\n"
"}\n"
"\n"
"\n"
"static void solver_alloc(void) {\n"
"    pt_len = key_count;\n"
"    holders_len = site_count;\n"
"    pt = (Bits*)xcalloc((size_t)pt_len, sizeof(Bits), \"AIF points-to\");\n"
"    holders = (Bits*)xcalloc((size_t)holders_len, sizeof(Bits), \"AIF holders\");\n"
"    container_of = (Bits*)xcalloc((size_t)holders_len, sizeof(Bits), \"AIF container holders\");\n"
"    key_views = (Bits*)xcalloc((size_t)pt_len, sizeof(Bits), \"AIF view provenance\");\n"
"    // INFERENCE 5.6 requires the derivation be retained through tier assignment.\n"
"    deriv_e = (Deriv*)xcalloc((size_t)site_count, sizeof(Deriv), \"AIF derivation (E)\");\n"
"    deriv_a = (Deriv*)xcalloc((size_t)site_count, sizeof(Deriv), \"AIF derivation (A)\");\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        // A site nothing ever raised is at its own allocation, which is the root\n"
"        // every witness path terminates at.\n"
"        deriv_e[s].rule = AIF_RULE_ALLOC;\n"
"        deriv_a[s].rule = AIF_RULE_ALLOC;\n"
"        deriv_e[s].from = -1;\n"
"        deriv_a[s].from = -1;\n"
"        // The bottom values, so a fact nothing ever raised still reports what it\n"
"        // is rather than whatever calloc left behind.\n"
"        deriv_e[s].value = sites[s].E;\n"
"        deriv_a[s].value = sites[s].A;\n"
"        deriv_e[s].file = deriv_a[s].file = sites[s].file;\n"
"        deriv_e[s].line = deriv_a[s].line = sites[s].line;\n"
"        deriv_e[s].col  = deriv_a[s].col  = sites[s].col;\n"
"    }\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        sites[s].type_acyclic = type_acyclic_id(sites[s].type);\n"
"        int t = nominal_find_id(sites[s].type);\n"
"        sites[s].bytes = (t >= 0) ? nominals[t].bytes : 0;\n"
"    }\n"
"}\n"
"\n"
"// Flatten a value-set expression against the current points-to state.\n"
"static void resolve(int vs, Bits* out) {\n"
"    bits_clear(out);\n"
"    if (vs < 0 || vs >= vs_count) return;\n"
"    ValueSet* v = &vsets[vs];\n"
"    for (int i = 0; i < v->len; i++) {\n"
"        int item = v->items[i];\n"
"        if (item & 1) {\n"
"            int key = item >> 1;\n"
"            if (key < pt_len) bits_or(out, &pt[key], \"AIF resolve\");\n"
"        } else {\n"
"            bits_set(out, item >> 1, \"AIF resolve\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// SPEC 8.4. The collections whose lifetime this value set depends on: its own\n"
"// provenance, plus that of every key it reads through.\n"
"//\n"
"// Not recursive past one key hop, and it does not need to be -- a key's set is\n"
"// already the union of everything ever bound into it, provenance included, so\n"
"// the transitive closure is taken by the points-to fixed point rather than here.\n"
"static void resolve_views(int vs, Bits* out) {\n"
"    bits_clear(out);\n"
"    if (vs < 0 || vs >= vs_count) return;\n"
"    ValueSet* v = &vsets[vs];\n"
"    for (int i = 0; i < v->vlen; i++) {\n"
"        static Bits tmp;                     // reentrancy is not possible: no rule nests this\n"
"        resolve(v->views[i], &tmp);\n"
"        bits_or(out, &tmp, \"AIF view provenance\");\n"
"    }\n"
"    for (int i = 0; i < v->len; i++) {\n"
"        int item = v->items[i];\n"
"        if (item & 1) {\n"
"            int key = item >> 1;\n"
"            if (key < pt_len) bits_or(out, &key_views[key], \"AIF view provenance\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// Records the site in this round's delta and returns 1, so a rule reads\n"
"// `if (raise_alias(s, X)) changed = moved(s);`.\n"
"static int moved(int site) {\n"
"    bits_set(&delta, site, \"AIF delta\");\n"
"    return 1;\n"
"}\n"
"\n"
"static int raise_escape(int site, int target, int from) {\n"
"    int j = escape_join(sites[site].E, target);\n"
"    if (j == sites[site].E) return 0;\n"
"    sites[site].E = j;\n"
"    note_deriv(deriv_e, site, from, j);\n"
"    return 1;\n"
"}\n"
"\n"
"// SPEC 8.4 E-VIEW:  v is a view of c  =>  E(c) \342\212\222 E(v).\n"
"//\n"
"// Applied wherever a rule bounds how long the *view* lives, because that bound\n"
"// is exactly what the collection has to satisfy. `target` is the escape the\n"
"// caller's rule just established for the view; `in_fn` is the function that\n"
"// bound is expressed in, or -1 when the target is function-independent.\n"
"//\n"
"// **The direction is the opposite of every other rule in this solver, and that\n"
"// is the whole mechanism.** Everywhere else a value inherits a fact from\n"
"// something holding it; here the *collection* is raised to cover the view,\n"
"// because a view must not outlive what it views. A view that escapes to the\n"
"// caller forces the collection to escape to the caller -- the collection sinks\n"
"// a tier and compilation succeeds, where Rust's borrow checker would reject the\n"
"// program. That is SPEC 1's invariant applied to views, and it is why `a[i]`\n"
"// needs no lifetime annotation here.\n"
"//\n"
"// **A is deliberately untouched.** SPEC 8.4 permits overlapping mutable views:\n"
"// a view is not a second holder, and two views of one collection in one task\n"
"// threaten neither property this model claims (no use-after-free, no data\n"
"// race). Raising A here would import Rust's no-aliasing property, which AIF\n"
"// does not have and does not want.\n"
"static int raise_view_owners(int vs, int target, int in_fn) {\n"
"    resolve_views(vs, &scratch_views);\n"
"    if (bits_is_empty(&scratch_views)) return 0;\n"
"    bits_to_vec(&scratch_views, &vec_views);\n"
"    int any = 0;\n"
"    force_rule = AIF_CON_VIEW_OF;\n"
"    for (int i = 0; i < vec_views.len; i++) {\n"
"        int c = vec_views.v[i];\n"
"        // A Region target is a scope id, and a scope id means something only\n"
"        // inside the function that owns it. When the collection was allocated\n"
"        // in a *different* function, this rule contributes nothing -- and that\n"
"        // is a case analysis, not a shortcut. The view is bound in a scope of\n"
"        // `in_fn`, so it dies with that activation, and the collection reached\n"
"        // `in_fn` in exactly one of three ways:\n"
"        //\n"
"        //   - passed down as an argument, in which case it is live across the\n"
"        //     call by construction and already outlives the view;\n"
"        //   - returned up, in which case E-RETURN has it at Caller already;\n"
"        //   - read from static storage, in which case E-STATIC has it Global.\n"
"        //\n"
"        // In all three the constraint is already implied. Raising to Caller\n"
"        // \"to be safe\" is what demoted g5's `ents` -- a list `main` allocates\n"
"        // and `render` reads -- costing it its list_release for nothing.\n"
"        //\n"
"        // A view that outlives `in_fn` is NOT this case: escaping one is a\n"
"        // return, a store or a push, and those arrive here with a Caller,\n"
"        // Global or holder-derived target, which is function-independent and\n"
"        // passes straight through.\n"
"        if (target >= 0 && in_fn >= 0 && sites[c].fn != in_fn) continue;\n"
"        if (raise_escape(c, target, -1)) { any = 1; moved(c); }\n"
"    }\n"
"    force_rule = -1;\n"
"    return any;\n"
"}\n"
"\n"
"static int raise_alias(int site, int level, int from) {\n"
"    if (sites[site].A >= level) return 0;\n"
"    // SPEC 5.1: `unique` is an axiom, so the solver takes A = Unique as given\n"
"    // and does not propagate aliasing into the annotated binding. This is the\n"
"    // cut, and it is the whole mechanism -- an axiom that a rule could overrule\n"
"    // is not one.\n"
"    //\n"
"    // What makes it sound here rather than merely asserted is the language: a\n"
"    // second *owning* reference within the declaring scope is already a\n"
"    // compile error under affine collections, because taking one is a move and\n"
"    // using the original afterwards is `use of moved value`. So the local\n"
"    // verification SPEC 5.1 asks for is discharged by the move checker, and\n"
"    // what remains is the interprocedural half -- exactly what an axiom is for.\n"
"    // The suppression is recorded so the manifest can say which values rest on\n"
"    // the assertion.\n"
"    if (sites[site].alias_axiom && level > AIF_A_UNIQUE) {\n"
"        sites[site].alias_suppressed = 1;\n"
"        return 0;\n"
"    }\n"
"    sites[site].A = level;\n"
"    note_deriv(deriv_a, site, from, level);\n"
"    return 1;\n"
"}\n"
"\n"
"// INFERENCE 4.3. No axiom cuts this one: SPEC 5's four annotations say nothing\n"
"// about thread affinity, which is why `unique` has no counterpart here and why\n"
"// there is no `alias_suppressed` equivalent to record.\n"
"//\n"
"// Deliberately without a derivation edge. deriv_e and deriv_a exist so a\n"
"// manifest diff can walk a witness path back to a root (INFERENCE 5.6), and the\n"
"// domain that path walks is chosen by aif_cause_domain_for from the tier. A T4a\n"
"// site's interesting fact is *aliasing* -- see the comment there -- so a third\n"
"// Deriv array would cost one word per site to answer a question nothing asks.\n"
"static int raise_thread(int site, int level) {\n"
"    if (sites[site].T >= level) return 0;\n"
"    sites[site].T = level;\n"
"    return 1;\n"
"}\n"
"\n"
"// Iteration runs to full convergence, so by Kleene's theorem the result is the\n"
"// least fixed point regardless of the order constraints are applied in\n"
"// (INFERENCE 5.1 permits asynchronous iteration on exactly that condition).\n"
"// Order-independence is what licenses updating in place rather than\n"
"// double-buffering -- and it is why this engine's manifest must equal the\n"
"// Python oracle's, which applies the same constraints the same way.\n"
"//\n"
"// Returns 1 on convergence, 0 when the round budget ran out. A 0 return is NOT\n"
"// safe to assign tiers from: see aif_widen.\n"
"// Every rule that writes pt or holders reads only pt -- no fact feeds back into\n"
"// the points-to relation -- so its least fixed point is independent of the facts\n"
"// and reaching it first changes no answer. What it changes is the frontier:\n"
"// solved together, points-to is still growing when a budget bites, and a set\n"
"// that may still gain members this pass cannot name makes every site a possible\n"
"// successor. Separated, the fact phase always truncates over a final graph.\n"
"static int solve_points_to(int max_rounds) {\n"
"    for (int r = 0; r < max_rounds; r++) {\n"
"        solve_rounds++;\n"
"        int changed = 0;\n"
"\n"
"        for (int ci = 0; ci < con_count; ci++) {\n"
"            Constraint* k = &cons[ci];\n"
"            if (k->kind != AIF_CON_BIND && k->kind != AIF_CON_ARG\n"
"                && k->kind != AIF_CON_STORE) {\n"
"                continue;\n"
"            }\n"
"\n"
"            resolve(k->b, &scratch_val);\n"
"            if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = 1;\n"
"\n"
"            // SPEC 8.4. View provenance flows with the value, into the key it\n"
"            // is bound, passed or stored into. Grown here rather than in the\n"
"            // fact loop because it reads only value sets and pt -- so it is a\n"
"            // points-to-shaped relation, and the fact phase gets to run over a\n"
"            // finished one, exactly as it does for pt itself.\n"
"            resolve_views(k->b, &scratch_views);\n"
"            if (!bits_is_empty(&scratch_views)) {\n"
"                if (bits_or(&key_views[k->a], &scratch_views, \"AIF view provenance\")) changed = 1;\n"
"            }\n"
"\n"
"            // Passing a value as an argument does not make the parameter a\n"
"            // holder of it, so ARG records none.\n"
"            if (k->kind == AIF_CON_ARG) continue;\n"
"            bits_to_vec(&scratch_val, &vec_val);\n"
"            for (int i = 0; i < vec_val.len; i++) {\n"
"                if (bits_set(&holders[vec_val.v[i]], k->a, \"AIF holders\")) changed = 1;\n"
"            }\n"
"        }\n"
"\n"
"        if (!changed) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"int aif_solve(int max_rounds) {\n"
"    solver_alloc();\n"
"    solve_rounds = 0;\n"
"\n"
"    if (!solve_points_to(max_rounds)) {\n"
"        delta_pt = 1;\n"
"        pt_rounds = solve_rounds;\n"
"        return 0;\n"
"    }\n"
"    pt_rounds = solve_rounds;\n"
"\n"
"    // SPEC 5: annotations enter here, after points-to and before the facts.\n"
"    //\n"
"    // After, because a value set may name a variable rather than a site, and\n"
"    // resolving one needs the points-to relation. Before, because both are\n"
"    // statements about the *result*: an axiom applied mid-iteration would only\n"
"    // cut the rules that had not fired yet, which would make the answer depend\n"
"    // on constraint order -- and INFERENCE 5.1 lets the order vary.\n"
"    for (int ci = 0; ci < con_count; ci++) {\n"
"        Constraint* k = &cons[ci];\n"
"        if (k->kind != AIF_CON_UNIQUE && k->kind != AIF_CON_PIN\n"
"            && k->kind != AIF_CON_PIN_REGION) continue;\n"
"        resolve(k->a, &scratch_val);\n"
"        bits_to_vec(&scratch_val, &vec_val);\n"
"        for (int i = 0; i < vec_val.len; i++) {\n"
"            if (k->kind == AIF_CON_UNIQUE) {\n"
"                sites[vec_val.v[i]].alias_axiom = 1;\n"
"            } else if (k->kind == AIF_CON_PIN_REGION) {\n"
"                // First writer wins, unlike the tier pin below, and there is no\n"
"                // \"stricter reading\" to prefer: two region names on one site are\n"
"                // two incompatible claims, not two strengths of one claim. The\n"
"                // second is left to refute on its own site rather than silently\n"
"                // replacing the first.\n"
"                if (sites[vec_val.v[i]].pin_region < 0) {\n"
"                    sites[vec_val.v[i]].pin_region = k->b;\n"
"                }\n"
"            } else if (k->b > sites[vec_val.v[i]].pin_tier) {\n"
"                // Two pins on one site is a program that annotated the same\n"
"                // allocation twice; the stricter reading is the more expensive\n"
"                // tier, which is the one that cannot be unsound.\n"
"                sites[vec_val.v[i]].pin_tier = k->b;\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    // Nothing has been proved about any site yet, so if the budget leaves no\n"
"    // round for the facts the frontier is the whole graph. Overwritten by the\n"
"    // first round that runs.\n"
"    for (int s = 0; s < site_count; s++) bits_set(&delta, s, \"AIF delta\");\n"
"\n"
"    for (int r = solve_rounds; r < max_rounds; r++) {\n"
"        solve_rounds = r + 1;\n"
"        int changed = 0;\n"
"        bits_clear(&delta);\n"
"        delta_pt = 0;\n"
"\n"
"        for (int ci = 0; ci < con_count; ci++) {\n"
"            Constraint* k = &cons[ci];\n"
"            cur_con = ci;\n"
"\n"
"            if (k->kind == AIF_CON_BIND) {\n"
"                resolve(k->b, &scratch_val);\n"
"                if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = delta_pt = 1;\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (bits_set(&holders[vec_val.v[i]], k->a, \"AIF holders\")) changed = delta_pt = 1;\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_ARG) {\n"
"                resolve(k->b, &scratch_val);\n"
"                if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = delta_pt = 1;\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                // A-CALL: passing a value hands out a borrow of it.\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (raise_alias(vec_val.v[i], AIF_A_BORROWED, -1)) changed = moved(vec_val.v[i]);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_STORE) {\n"
"                resolve(k->b, &scratch_val);\n"
"                resolve(k->c, &scratch_own);\n"
"                if (bits_or(&pt[k->a], &scratch_val, \"AIF points-to\")) changed = delta_pt = 1;\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                bits_to_vec(&scratch_own, &vec_own);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    if (bits_set(&holders[s], k->a, \"AIF holders\")) changed = delta_pt = 1;\n"
"                    for (int j = 0; j < vec_own.len; j++) {\n"
"                        int o = vec_own.v[j];\n"
"                        // E-STORE: reachable from the container, so it lives at\n"
"                        // least as long as the container does.\n"
"                        if (raise_escape(s, sites[o].E, o)) changed = moved(s);\n"
"                        // A-STORE: sharing is inherited through reachability.\n"
"                        if (raise_alias(s, sites[o].A, o)) changed = moved(s);\n"
"                        // T-REACH: and so is thread affinity. A value reachable\n"
"                        // from something a task can see is something that task\n"
"                        // can see.\n"
"                        if (raise_thread(s, sites[o].T)) changed = moved(s);\n"
"                    }\n"
"                }\n"
"                // E-VIEW: storing a view into a field makes the viewed\n"
"                // collection live at least as long as the object holding it.\n"
"                for (int j = 0; j < vec_own.len; j++) {\n"
"                    if (raise_view_owners(k->b, sites[vec_own.v[j]].E,\n"
"                                          sites[vec_own.v[j]].fn)) changed = 1;\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_LIVE_IN) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    // Cross-function flow does not extend a lifetime: only a\n"
"                    // binding in the site's own function says anything about\n"
"                    // which of that function's scopes the value outlives.\n"
"                    int target = (sites[s].fn == k->c) ? k->b : AIF_E_CALLER;\n"
"                    if (raise_escape(s, target, -1)) changed = moved(s);\n"
"                }\n"
"                // E-VIEW: this binding is how long the view lives, so it is how\n"
"                // long the collection has to.\n"
"                if (raise_view_owners(k->a, k->b, k->c)) changed = 1;\n"
"\n"
"            } else if (k->kind == AIF_CON_OPAQUE) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    if (sites[s].E != AIF_E_GLOBAL && raise_escape(s, AIF_E_CALLER, -1)) changed = moved(s);\n"
"                    if (raise_alias(s, AIF_A_SHARED, -1)) changed = moved(s);\n"
"                }\n"
"                // A view handed to something we cannot see could be kept.\n"
"                if (raise_view_owners(k->a, AIF_E_CALLER, -1)) changed = 1;\n"
"\n"
"            } else if (k->kind == AIF_CON_RETAIN_IN) {\n"
"                // E-STORE / A-STORE against a container reached through a call\n"
"                // rather than through a field assignment (FFI `retain_in`).\n"
"                resolve(k->a, &scratch_val);\n"
"                resolve(k->b, &scratch_own);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                bits_to_vec(&scratch_own, &vec_own);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    for (int j = 0; j < vec_own.len; j++) {\n"
"                        int h = vec_own.v[j];\n"
"                        if (raise_escape(s, sites[h].E, h)) changed = moved(s);\n"
"                        if (raise_alias(s, sites[h].A, h)) changed = moved(s);\n"
"                        // T-REACH, through a container rather than a field.\n"
"                        if (raise_thread(s, sites[h].T)) changed = moved(s);\n"
"                        // Which containers hold it, not merely that one does. The\n"
"                        // count is the fact A-CONTAIN reads, and it is the only\n"
"                        // thing separating \"the container owns this, free it at\n"
"                        // teardown\" from a double free through the second one.\n"
"                        if (bits_set(&container_of[s], h, \"AIF container holders\")) {\n"
"                            changed = moved(s);\n"
"                        }\n"
"                    }\n"
"                    if (!sites[s].in_container && vec_own.len > 0) {\n"
"                        sites[s].in_container = 1;\n"
"                        changed = moved(s);\n"
"                    }\n"
"                    if (raise_alias(s, AIF_A_BORROWED, -1)) changed = moved(s);\n"
"                }\n"
"                // E-VIEW: pushing a view into a container makes the viewed\n"
"                // collection live at least as long as that container.\n"
"                for (int j = 0; j < vec_own.len; j++) {\n"
"                    if (raise_view_owners(k->a, sites[vec_own.v[j]].E,\n"
"                                          sites[vec_own.v[j]].fn)) changed = 1;\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_BORROW) {\n"
"                // Raises A to Borrowed for the call's duration and nothing\n"
"                // else. Escape is untouched: a callee that does not retain\n"
"                // cannot extend a lifetime (FFI 6, `borrow` row).\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (raise_alias(vec_val.v[i], AIF_A_BORROWED, -1)) changed = moved(vec_val.v[i]);\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_ESCAPE_CALLER) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (raise_escape(vec_val.v[i], AIF_E_CALLER, -1)) changed = moved(vec_val.v[i]);\n"
"                }\n"
"                // E-VIEW, and the case the safety gap was actually about:\n"
"                // `return list_get(l, i)` hands the caller a reference into a\n"
"                // collection this frame owns. The collection follows it out.\n"
"                if (raise_view_owners(k->a, AIF_E_CALLER, -1)) changed = 1;\n"
"\n"
"            } else if (k->kind == AIF_CON_NO_STACK) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    if (!sites[vec_val.v[i]].no_stack) {\n"
"                        sites[vec_val.v[i]].no_stack = 1;\n"
"                        changed = moved(vec_val.v[i]);\n"
"                    }\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_SPAWN) {\n"
"                // INFERENCE 4.1's E-SPAWN / E-SPAWN-J and 4.3's T-SPAWN-MOVE /\n"
"                // T-SPAWN-SHARE, which are the same four arguments seen through\n"
"                // two domains.\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"\n"
"                    if (k->c) {\n"
"                        // E-SPAWN-J. The task is joined on every path before the\n"
"                        // scope exits, so the argument has to outlive the join\n"
"                        // and nothing more. This is the clause INFERENCE calls\n"
"                        // \"where structured concurrency pays\": it is the whole\n"
"                        // difference between concurrent code at T1 and the same\n"
"                        // code at T4.\n"
"                        if (raise_escape(s, k->b, -1)) changed = moved(s);\n"
"                    } else {\n"
"                        // E-SPAWN. An unjoined task may outlive every scope in\n"
"                        // this function, so the value is reachable from a root\n"
"                        // this analysis cannot see the end of.\n"
"                        if (sites[s].E != AIF_E_GLOBAL) {\n"
"                            sites[s].E = AIF_E_GLOBAL;\n"
"                            note_deriv(deriv_e, s, -1, AIF_E_GLOBAL);\n"
"                            changed = moved(s);\n"
"                        }\n"
"                    }\n"
"\n"
"                    // T-SPAWN-MOVE. The argument was moved in -- sema's\n"
"                    // semaConsumeOperand guarantees it, and the move checker\n"
"                    // enforces it -- so exactly one task can reach it at a time.\n"
"                    // Transferred, not CrossThread: this is the case T3's\n"
"                    // non-atomic count is sound for.\n"
"                    if (raise_thread(s, AIF_T_TRANSFERRED)) changed = moved(s);\n"
"\n"
"                    // T-SPAWN-SHARE is *not* here. It is a per-site rule\n"
"                    // below, because the argument is not the only thing a task\n"
"                    // can reach -- everything reachable from it is too, and\n"
"                    // that is where the sharing actually shows up.\n"
"                }\n"
"\n"
"            } else if (k->kind == AIF_CON_ESCAPE_GLOBAL) {\n"
"                resolve(k->a, &scratch_val);\n"
"                bits_to_vec(&scratch_val, &vec_val);\n"
"                for (int i = 0; i < vec_val.len; i++) {\n"
"                    int s = vec_val.v[i];\n"
"                    if (sites[s].E != AIF_E_GLOBAL) {\n"
"                        sites[s].E = AIF_E_GLOBAL;\n"
"                        note_deriv(deriv_e, s, -1, AIF_E_GLOBAL);\n"
"                        changed = moved(s);\n"
"                    }\n"
"                }\n"
"\n"
"            }\n"
"        }\n"
"\n"
"        // Rules that read a site's own state rather than an incoming edge. They\n"
"        // have no constraint to attribute to, so the derivation names the rule\n"
"        // directly -- cur_con of -1 makes note_deriv fall back to synth_rule.\n"
"        cur_con = -1;\n"
"        for (int s = 0; s < site_count; s++) {\n"
"            // A-ESCAPE: anything globally reachable is reachable more than once.\n"
"            synth_rule = AIF_RULE_A_ESCAPE;\n"
"            if (sites[s].E == AIF_E_GLOBAL && raise_alias(s, AIF_A_SHARED, -1)) changed = moved(s);\n"
"\n"
"            // A-COPY: only a copyable value can be genuinely multiply held.\n"
"            synth_rule = AIF_RULE_A_COPY;\n"
"            if (!site_is_move_only(&sites[s])\n"
"                && bits_count_at_least_two(&holders[s])\n"
"                && raise_alias(s, AIF_A_SHARED, -1)) {\n"
"                changed = moved(s);\n"
"            }\n"
"\n"
"            // A-CONTAIN: two containers holding one value is sharing, whatever\n"
"            // the type.\n"
"            //\n"
"            // A-COPY exempts move-only values because a second *binding* is a\n"
"            // move, so the earlier one is provably dead. That argument does not\n"
"            // reach a container: `list_push(l, x)` is a call, and a call is not a\n"
"            // move -- so `store(l1, x); store(l2, x)` puts one value under two\n"
"            // owners with nothing in the language to notice. Once a container\n"
"            // teardown releases its elements, that is the double free.\n"
"            //\n"
"            // Making it Shared is not a workaround for the gap; it is the correct\n"
"            // reading, and it lands the value on the tier built for exactly this\n"
"            // shape. One container owns and frees (T2); two share and count (T3).\n"
"            synth_rule = AIF_RULE_A_CONTAIN;\n"
"            if (bits_count_at_least_two(&container_of[s])\n"
"                && raise_alias(s, AIF_A_SHARED, -1)) {\n"
"                changed = moved(s);\n"
"            }\n"
"\n"
"            // T-SPAWN-SHARE. Stated as a per-site rule over the two facts\n"
"            // rather than as a clause on the spawn, and both halves of that\n"
"            // are deliberate.\n"
"            //\n"
"            // **Why the premise is `A = Shared` and not syntax.** INFERENCE\n"
"            // writes it as \"y is still live in the parent\". Under affine\n"
"            // references that is never syntactically true: the move checker\n"
"            // rejects any program that names the value twice. But a value can\n"
"            // be live in the parent without its *binding* being -- two\n"
"            // containers holding one element, one moved into a task and one\n"
"            // retained, is the ordinary shape and no binding names it twice.\n"
"            // `Shared` is exactly INFERENCE 2.2's \"two or more references\n"
"            // whose relative lifetimes are not statically ordered\", so a\n"
"            // Shared value that a task can reach is one nothing proved the\n"
"            // parent dropped. This is the same move C-UNIQUE makes one domain\n"
"            // over (INFERENCE 4.4): the aliasing module does the work and the\n"
"            // derived domain reads its answer.\n"
"            //\n"
"            // **Why per-site and not on the spawn's arguments.** Testing the\n"
"            // arguments alone was the first version and it was unsound. The\n"
"            // spawn's argument is the *container*; the shared thing is the\n"
"            // element, which reaches Transferred through T-REACH and never\n"
"            // appears in any spawn's value set. tests/aif_concurrency_shared.psm\n"
"            // is that program, and it derived T3 with a non-atomic count for a\n"
"            // value two threads could reach.\n"
"            //\n"
"            // Read as one sentence: a value that crosses a task boundary at\n"
"            // all, and has two references nothing ordered, is cross-thread.\n"
"            // `unique` earns its keep twice here -- an axiom holding A at\n"
"            // Unique keeps a transferred value off the atomic path.\n"
"            if (sites[s].T >= AIF_T_TRANSFERRED && sites[s].A >= AIF_A_SHARED\n"
"                && raise_thread(s, AIF_T_CROSS)) {\n"
"                changed = moved(s);\n"
"            }\n"
"\n"
"            // T-STATIC. A static root in a program with concurrency is\n"
"            // assumed reachable from every task.\n"
"            //\n"
"            // INFERENCE calls this \"deliberately blunt\" and it is: refining it\n"
"            // wants a global reachability analysis whose payoff is small in a\n"
"            // language where static mutable roots are rare. What the bluntness\n"
"            // buys is the honest answer to \"when is T4a actually reachable?\" --\n"
"            // under isolation, a value cannot be shared by being passed around,\n"
"            // so the static root is the residue, and it is the residue *because*\n"
"            // the rest of the design closed the other doors.\n"
"            if (program_has_tasks && sites[s].E == AIF_E_GLOBAL\n"
"                && raise_thread(s, AIF_T_CROSS)) {\n"
"                changed = moved(s);\n"
"            }\n"
"\n"
"            // C-UNIQUE / C-TYPE (INFERENCE 4.4 stage 2).\n"
"            int acyclic = (sites[s].A == AIF_A_UNIQUE) || sites[s].type_acyclic;\n"
"            int want = acyclic ? AIF_C_ACYCLIC : AIF_C_MAYBE;\n"
"            if (want > sites[s].C) {\n"
"                sites[s].C = want;\n"
"                changed = moved(s);\n"
"            }\n"
"        }\n"
"\n"
"        if (!changed) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"int aif_rounds(void) { return solve_rounds; }\n"
"int aif_pt_rounds(void) { return pt_rounds; }\n"
"\n"
"// INFERENCE 5.3: a truncated ascending iteration is a *pre*-fixed point, so its\n"
"// facts are too optimistic -- assigning tiers from one would hand a value T2\n"
"// where the unexplored rounds would have proved it Shared. That is a\n"
"// use-after-free, not a slowdown, so truncation must be followed by widening to\n"
"// a post-fixed point.\n"
"//\n"
"// U := delta union transitive_succs(delta). If a site's facts change in round\n"
"// r+1, some input of it changed in round r, so chaining back puts everything\n"
"// still in motion inside the closure of the last round's delta -- and raising\n"
"// exactly that set to top yields a post-fixed point.\n"
"//\n"
"// Fact flow between sites runs owner -> value and only through STORE and\n"
"// RETAIN_IN; every other rule raises a site from a constant, and the per-site\n"
"// rules are self-edges. Those two edges are read out of the points-to state,\n"
"// which takes no input from the facts -- so once points-to has settled the\n"
"// successor graph is final and the frontier is exact. While points-to is still\n"
"// growing it is not: a later round can put a site into a set this pass cannot\n"
"// name, so there the whole graph is the only sound answer.\n"
"static void widen_sites(const Bits* u) {\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (u && !bits_test(u, s)) continue;\n"
"        sites[s].E = AIF_E_GLOBAL;\n"
"        sites[s].A = AIF_A_SHARED;\n"
"        sites[s].C = AIF_C_MAYBE;\n"
"        // Top of the T lattice too -- but only where a task exists to reach\n"
"        // it from. Omitting the raise entirely would make a truncated build\n"
"        // *cheaper* than a converged one, an atomic count skipped because the\n"
"        // budget ran out, which is the exact unsoundness INFERENCE 5.3\n"
"        // introduces widening to prevent.\n"
"        //\n"
"        // The guard is not a weakening of that. Widening raises a site to top\n"
"        // because the analysis ran out of rounds to prove otherwise; \"this\n"
"        // program contains no spawn\" is not something it was trying to prove,\n"
"        // it is something the constraint set already said, and no number of\n"
"        // further rounds could contradict it. So CrossThread in a task-free\n"
"        // module is not conservatism, it is a false statement that costs\n"
"        // atomics -- and SPEC 1's invariant is that inference failure degrades\n"
"        // performance, which this keeps to the programs that have tasks.\n"
"        if (program_has_tasks) sites[s].T = AIF_T_CROSS;\n"
"        bits_set(&widened, s, \"AIF widened\");\n"
"    }\n"
"}\n"
"\n"
"void aif_widen(void) {\n"
"    if (site_count <= 0) return;\n"
"\n"
"    if (delta_pt) {\n"
"        widen_sites(NULL);\n"
"        return;\n"
"    }\n"
"\n"
"    Bits* succ = (Bits*)xcalloc((size_t)site_count, sizeof(Bits), \"AIF widen succ\");\n"
"    for (int ci = 0; ci < con_count; ci++) {\n"
"        Constraint* k = &cons[ci];\n"
"        int vs_val, vs_own;\n"
"        if (k->kind == AIF_CON_STORE)           { vs_val = k->b; vs_own = k->c; }\n"
"        else if (k->kind == AIF_CON_RETAIN_IN)  { vs_val = k->a; vs_own = k->b; }\n"
"        else continue;\n"
"\n"
"        resolve(vs_val, &scratch_val);\n"
"        resolve(vs_own, &scratch_own);\n"
"        bits_to_vec(&scratch_own, &vec_own);\n"
"        for (int j = 0; j < vec_own.len; j++) {\n"
"            bits_or(&succ[vec_own.v[j]], &scratch_val, \"AIF widen succ\");\n"
"        }\n"
"    }\n"
"\n"
"    Bits u;\n"
"    memset(&u, 0, sizeof(u));\n"
"    bits_or(&u, &delta, \"AIF widen frontier\");\n"
"\n"
"    IntVec work;\n"
"    memset(&work, 0, sizeof(work));\n"
"    bits_to_vec(&delta, &vec_val);\n"
"    for (int i = 0; i < vec_val.len; i++) vec_push(&work, vec_val.v[i], \"AIF widen work\");\n"
"\n"
"    while (work.len > 0) {\n"
"        int s = work.v[--work.len];\n"
"        bits_to_vec(&succ[s], &vec_own);\n"
"        for (int i = 0; i < vec_own.len; i++) {\n"
"            if (bits_set(&u, vec_own.v[i], \"AIF widen frontier\")) {\n"
"                vec_push(&work, vec_own.v[i], \"AIF widen work\");\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    widen_sites(&u);\n"
"\n"
"    free(work.v);\n"
"    bits_free(&u);\n"
"    for (int s = 0; s < site_count; s++) bits_free(&succ[s]);\n"
"    free(succ);\n"
"}\n"
"\n"
"// Whether this site's facts were raised by the widening rather than inferred.\n"
"// SPEC 6.2 marks exactly those records budget-exhausted; the rest of a truncated\n"
"// build carries facts that converged and are as good as any other build's.\n"
"int aif_site_widened(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return bits_test(&widened, id);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Tier derivation (SPEC 4.2)\n"
"//\n"
"// Here rather than in Prismio because the first clause needs defscope(s), and\n"
"// the escape encoding that makes that comparison a single integer test is this\n"
"// file's private business. The derivation itself is the spec's, clause for\n"
"// clause, first match wins.\n"
"//\n"
"// Theta_stack is approximated by field count: at this stage the frontend has no\n"
"// layout, so a byte threshold is not available. SPEC 4.2 requires the threshold\n"
"// be documented by the implementation -- it is emitted in the manifest header.\n"
"//\n"
"// T4a was unreachable by construction until 2026-08-19, because the language had\n"
"// no tasks and the thread domain was vacuous. REQUIREMENTS 15 built the task\n"
"// model and the two `T` conjuncts below are no longer tautologies.\n"
"//\n"
"// **The single-threaded path is unchanged, and it is unchanged structurally\n"
"// rather than by measurement.** A module with no `spawn` raises no site above\n"
"// AIF_T_ISOLATED: T-SPAWN-* fires only on a spawn constraint, T-REACH can only\n"
"// propagate a value some rule already raised, and T-STATIC is guarded on\n"
"// program_has_tasks. So `T <= AIF_T_TRANSFERRED` holds at every site, both new\n"
"// conjuncts are true, and T4a is unreachable -- exactly the shape the clauses\n"
"// had before. This is the property the whole design is for, so it is stated\n"
"// where the clauses are and not only in a document.\n"
"// ============================================================================\n"
"\n"
"#define AIF_THETA_STACK_FIELDS 8\n"
"#define AIF_THETA_STACK_BYTES 256\n"
"\n"
"#define AIF_THETA_MODE_BYTES  0\n"
"#define AIF_THETA_MODE_FIELDS 1\n"
"\n"
"#define AIF_T0  0\n"
"#define AIF_T1  1\n"
"#define AIF_T2  2\n"
"#define AIF_T3  3\n"
"#define AIF_T4B 4\n"
"// SPEC 3 is emphatic that \"T4 is one tier, not two\", and these are its two\n"
"// sub-classes rather than two tiers. They still need distinct ordinals, because\n"
"// the manifest names them separately and `pin` adjudicates numerically.\n"
"//\n"
"// T4a above T4b is a real decision and this is the argument for it. The order\n"
"// has to be a linear extension of the fact lattice for aif_check_pins to stay\n"
"// sound (SPEC 4.3's monotonicity), and it has to make raising T never *lower*\n"
"// the ordinal: from <Transferred, MaybeCyclic> = T4b, raising T to CrossThread\n"
"// must not go down. Putting T4a on top satisfies both, and it makes the useful\n"
"// pin the honest one -- `pin(T4a)` on a T3 site asks for an atomic count and is\n"
"// granted, `pin(T4b)` on a T4a site asks to drop one and is refuted.\n"
"#define AIF_T4A 5\n"
"\n"
"// Which Theta_stack to apply. Bytes is the real threshold and the default;\n"
"// fields is the prototype's approximation (its A5), kept switchable because the\n"
"// oracle reads a JSON dump with no layout in it and cannot compute the other.\n"
"// A comparison against the oracle therefore runs in fields mode -- otherwise the\n"
"// two would differ on the T0/T1 split alone and the differential test would stop\n"
"// saying anything about the part that matters, which is the inference.\n"
"static int theta_mode = AIF_THETA_MODE_BYTES;\n"
"\n"
"void aif_set_theta_mode(int mode) {\n"
"    theta_mode = (mode == AIF_THETA_MODE_FIELDS) ? AIF_THETA_MODE_FIELDS\n"
"                                                 : AIF_THETA_MODE_BYTES;\n"
"}\n"
"\n"
"int aif_theta_mode(void) { return theta_mode; }\n"
"\n"
"int aif_theta_stack(void) {\n"
"    return (theta_mode == AIF_THETA_MODE_FIELDS) ? AIF_THETA_STACK_FIELDS\n"
"                                                 : AIF_THETA_STACK_BYTES;\n"
"}\n"
"\n"
"// SPEC 4.2 requires the size be *statically known* as well as under the\n"
"// threshold. A struct whose size the frontend never computed is not known, and\n"
"// unknown must not read as small.\n"
"static int fits_on_stack(const Site* s) {\n"
"    if (theta_mode == AIF_THETA_MODE_FIELDS) {\n"
"        return s->nfields <= AIF_THETA_STACK_FIELDS;\n"
"    }\n"
"    return s->bytes > 0 && s->bytes <= AIF_THETA_STACK_BYTES;\n"
"}\n"
"\n"
"// The cheapest tier the converged facts permit. This is where SPEC 3's ladder\n"
"// becomes a decision, and the clauses are ordered so the first match wins.\n"
"static int derived_tier(const Site* s) {\n"
"    // in_container joins no_stack here for the same reason it sits next to it in\n"
"    // the drop predicate: the container reclaims its elements, and a frame slot is\n"
"    // not something a deallocator can take. Reachable whenever the container and\n"
"    // the element share a scope, which keeps E at that scope and every other T0\n"
"    // conjunct satisfied.\n"
"    if (s->E == s->scope && s->A <= AIF_A_BORROWED\n"
"        && s->kind == AIF_K_STRUCT && fits_on_stack(s)\n"
"        && !s->no_stack && !s->in_container) {\n"
"        return AIF_T0;\n"
"    }\n"
"    // Neither the T1 clause nor T0's tests T, and that is SPEC 4.2 read\n"
"    // literally rather than an omission. A value whose escape bottoms inside a\n"
"    // region did not leave it, and E-SPAWN-J is what keeps a joined task's\n"
"    // arguments there -- which is INFERENCE 4.1's \"this single distinction\n"
"    // determines whether concurrent code lands at T1 or T4\", visible here as\n"
"    // the absence of a test.\n"
"    if (s->E != AIF_E_CALLER && s->E != AIF_E_GLOBAL) return AIF_T1;\n"
"    if (s->A <= AIF_A_BORROWED && s->T <= AIF_T_TRANSFERRED) return AIF_T2;\n"
"    if (s->T <= AIF_T_TRANSFERRED && s->C == AIF_C_ACYCLIC) return AIF_T3;\n"
"    // SPEC 3: \"a value meeting both conditions pays both\". The sub-class named\n"
"    // here is the one that decides the *count*, because that is what codegen\n"
"    // reads it for; a T4a site that is also cyclic still reports C =\n"
"    // MaybeCyclic through aif_site_cyclic, so collector registration is\n"
"    // decided from the fact and not from this name.\n"
"    if (s->T == AIF_T_CROSS) return AIF_T4A;\n"
"    return AIF_T4B;\n"
"}\n"
"\n"
"int aif_tier_of(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_T4B;\n"
"    Site* s = &sites[id];\n"
"    // SPEC 5.4: a honoured pin freezes the tier, and everything downstream --\n"
"    // codegen, the drop predicate, the arena test -- has to read the frozen one\n"
"    // or they would disagree with the manifest about what was built.\n"
"    if (s->pin_verdict == AIF_PIN_HONOURED) return s->pin_tier;\n"
"    return derived_tier(s);\n"
"}\n"
"\n"
"// SPEC 5.4, after convergence. The pin derives nothing and seeds nothing; it\n"
"// constrains the output, so this runs once the facts are final.\n"
"//\n"
"// SPEC's pseudocode has four branches and the middle one -- \"the facts permit\n"
"// the pinned tier but the solver did not reach it\" -- is **vacuous here**, and\n"
"// saying why matters more than the code. derived_tier returns the cheapest tier\n"
"// its clauses admit, and the clauses read the facts directly; there is no search\n"
"// that could settle above its own optimum. An implementation whose tier\n"
"// assignment was a separate optimisation would need that branch. This one cannot\n"
"// enter it, so a pin below the derived tier is refuted rather than rescued.\n"
"void aif_check_pins(int converged) {\n"
"    for (int i = 0; i < site_count; i++) {\n"
"        Site* s = &sites[i];\n"
"        if (s->pin_tier < 0) continue;\n"
"\n"
"        int derived = derived_tier(s);\n"
"        if (s->pin_tier >= derived) {\n"
"            s->pin_verdict = AIF_PIN_HONOURED;\n"
"        } else if (converged) {\n"
"            s->pin_verdict = AIF_PIN_REFUTED;\n"
"        } else {\n"
"            // SPEC 5.4.2: unproven is not disproven. Failing here would punish\n"
"            // the programmer for the budget, which SPEC 1 forbids. The tier is\n"
"            // kept so the warning can name what was asked for; only the verdict\n"
"            // decides whether aif_tier_of uses it, and this one does not.\n"
"            s->pin_verdict = AIF_PIN_UNPROVEN;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"int aif_site_pin_verdict(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_PIN_NONE;\n"
"    return sites[id].pin_verdict;\n"
"}\n"
"\n"
"int aif_site_pin_tier(int id) {\n"
"    if (id < 0 || id >= site_count) return -1;\n"
"    return sites[id].pin_tier;\n"
"}\n"
"\n"
"// The tier the facts would have given, so a refuted pin's diagnostic can say\n"
"// what the analysis actually proved instead of just refusing.\n"
"int aif_site_derived_tier(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_T4B;\n"
"    return derived_tier(&sites[id]);\n"
"}\n"
"\n"
"// INFERENCE 2.3, read back. Codegen needs it to choose an atomic count, and the\n"
"// manifest needs it to say why.\n"
"int aif_site_thread(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_T_CROSS;\n"
"    return sites[id].T;\n"
"}\n"
"\n"
"int aif_site_alias_axiom(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return sites[id].alias_axiom;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Minimal cause (INFERENCE 5.6, SPEC 6.3)\n"
"//\n"
"// Walk the derivation backward from a site through maximal contributors until a\n"
"// root -- an allocation, an axiom, or a rule with no incoming site. The result\n"
"// is the witness path SPEC 6.3 prints under \"minimal cause\", innermost edge\n"
"// first, which is the order it reads in: the change, then what made the change\n"
"// matter.\n"
"//\n"
"// Which domain to walk is decided by the tier, and that mapping is the reason\n"
"// the two are kept separately. A T1 -> T2 move is an *escape* question and a\n"
"// T2 -> T3 move is an *aliasing* one; showing the E path for a value that lost\n"
"// its tier to sharing would be a confident answer to the wrong question.\n"
"// ============================================================================\n"
"\n"
"#define AIF_CAUSE_MAX 32\n"
"\n"
"static int cause_site[AIF_CAUSE_MAX];\n"
"static int cause_rule[AIF_CAUSE_MAX];\n"
"static int cause_value[AIF_CAUSE_MAX];\n"
"static int cause_file[AIF_CAUSE_MAX];\n"
"static int cause_line[AIF_CAUSE_MAX];\n"
"static int cause_col[AIF_CAUSE_MAX];\n"
"static int cause_len;\n"
"static int cause_domain;    // 0 = escape, 1 = aliasing\n"
"\n"
"// Which fact cost this site its tier, and therefore which derivation explains\n"
"// it.\n"
"//\n"
"// The order matters and is the reverse of the tier clauses'. A site is asked\n"
"// about because its tier is worse than someone wanted, so the interesting fact\n"
"// is the *last* one that was binding, not the first. Aliasing is checked before\n"
"// escape because A > Borrowed is what separates T3 from T2: a T3 record whose E\n"
"// is also Caller would otherwise be explained by the escape that only got it as\n"
"// far as T2, which is a confident answer to the wrong question.\n"
"//\n"
"// T4b is cyclicity, which is derived from A and the type graph rather than\n"
"// propagated, so it reports the aliasing path too -- that is where its own\n"
"// witness would start.\n"
"int aif_cause_domain_for(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    Site* s = &sites[id];\n"
"    if (s->A > AIF_A_BORROWED) return 1;                          // aliasing\n"
"    return 0;                                                     // escape\n"
"}\n"
"\n"
"// Builds the path and returns its length. The caller reads it back edge by edge;\n"
"// one buffer is enough because a diff explains one record at a time.\n"
"int aif_cause_build(int id, int domain) {\n"
"    cause_len = 0;\n"
"    cause_domain = domain;\n"
"    if (id < 0 || id >= site_count || !deriv_e || !deriv_a) return 0;\n"
"\n"
"    Deriv* d = domain == 1 ? deriv_a : deriv_e;\n"
"    int cur = id;\n"
"    for (int hops = 0; hops < AIF_CAUSE_MAX; hops++) {\n"
"        cause_site[cause_len]  = cur;\n"
"        cause_rule[cause_len]  = d[cur].rule;\n"
"        cause_value[cause_len] = d[cur].value;\n"
"        cause_file[cause_len]  = d[cur].file;\n"
"        cause_line[cause_len]  = d[cur].line;\n"
"        cause_col[cause_len]   = d[cur].col;\n"
"        cause_len++;\n"
"\n"
"        int next = d[cur].from;\n"
"        if (next < 0 || next >= site_count) break;   // a root: nothing fed it\n"
"        // The derivation is a DAG by construction -- a fact only ever rises, so\n"
"        // an edge always points at a site that reached its value earlier -- but\n"
"        // a cap costs nothing and turns a bug here into a truncated explanation\n"
"        // rather than a hang.\n"
"        int seen = 0;\n"
"        for (int i = 0; i < cause_len; i++) {\n"
"            if (cause_site[i] == next) { seen = 1; break; }\n"
"        }\n"
"        if (seen) break;\n"
"        cur = next;\n"
"    }\n"
"    return cause_len;\n"
"}\n"
"\n"
"int aif_cause_len(void)          { return cause_len; }\n"
"int aif_cause_site(int i)        { return (i < 0 || i >= cause_len) ? -1 : cause_site[i]; }\n"
"int aif_cause_rule(int i)        { return (i < 0 || i >= cause_len) ? -1 : cause_rule[i]; }\n"
"int aif_cause_value(int i)       { return (i < 0 || i >= cause_len) ? -1 : cause_value[i]; }\n"
"int aif_cause_file(int i)        { return (i < 0 || i >= cause_len) ? 0 : cause_file[i]; }\n"
"int aif_cause_line(int i)        { return (i < 0 || i >= cause_len) ? 0 : cause_line[i]; }\n"
"int aif_cause_col(int i)         { return (i < 0 || i >= cause_len) ? 0 : cause_col[i]; }\n"
"\n"
"// The E value an edge raised to, spelled the way the manifest spells a scope.\n"
"// Region ids are per-function and meaningless outside one, so a scope reports as\n"
"// its depth rather than its id -- what a reader needs is \"an enclosing scope\",\n"
"// not which array slot it occupies.\n"
"const char* aif_escape_name(int value) {\n"
"    if (value == AIF_E_CALLER) return \"Caller\";\n"
"    if (value == AIF_E_GLOBAL) return \"Global\";\n"
"    return \"Region\";\n"
"}\n"
"\n"
"const char* aif_alias_name(int value) {\n"
"    if (value <= AIF_A_UNIQUE) return \"Unique\";\n"
"    if (value <= AIF_A_BORROWED) return \"Borrowed\";\n"
"    return \"Shared\";\n"
"}\n"
"\n"
"// SPEC 6.3 prints the rule that fired on each edge, because that is what makes\n"
"// a repair derivable: breaking the edge restores the tier, and the rule says\n"
"// what breaking it would mean.\n"
"const char* aif_rule_name(int rule) {\n"
"    if (rule == AIF_CON_BIND)           return \"E-BIND\";\n"
"    if (rule == AIF_CON_ARG)            return \"A-CALL\";\n"
"    if (rule == AIF_CON_STORE)          return \"A-STORE\";\n"
"    if (rule == AIF_CON_LIVE_IN)        return \"E-BIND\";\n"
"    if (rule == AIF_CON_OPAQUE)         return \"E-OPAQUE\";\n"
"    if (rule == AIF_CON_RETAIN_IN)      return \"A-RETAIN\";\n"
"    if (rule == AIF_CON_BORROW)         return \"A-CALL\";\n"
"    if (rule == AIF_CON_ESCAPE_CALLER)  return \"E-RETURN\";\n"
"    if (rule == AIF_CON_ESCAPE_GLOBAL)  return \"E-STATIC\";\n"
"    if (rule == AIF_RULE_A_ESCAPE)      return \"A-ESCAPE\";\n"
"    if (rule == AIF_RULE_A_COPY)        return \"A-COPY\";\n"
"    if (rule == AIF_RULE_A_CONTAIN)     return \"A-CONTAIN\";\n"
"    if (rule == AIF_CON_VIEW_OF)        return \"E-VIEW\";\n"
"    if (rule == AIF_RULE_ALLOC)         return \"ALLOC\";\n"
"    return \"?\";\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Tier lookup by AST node\n"
"//\n"
"// Codegen has to ask \"what tier is the value this expression allocates?\", and\n"
"// the answer has to survive the gap between the two passes. The join key is the\n"
"// node itself: the AIF pass and codegen walk the same in-memory tree in the same\n"
"// process, so the address the parser allocated is a name for the expression that\n"
"// costs nothing to carry and cannot collide.\n"
"//\n"
"// It replaces a file:line:col key, which could: an array literal and its first\n"
"// element start at the same column, and `[str_concat(a,b), ...]` puts a site at\n"
"// each. That key had to resolve a collision by keeping the *highest* tier, since\n"
"// codegen reads T0 as permission to use a stack slot and rounding down there is\n"
"// heap corruption. Nothing rounds now -- one node, one site.\n"
"// ============================================================================\n"
"\n"
"#define AIF_NODE_BUCKETS 8192\n"
"\n"
"typedef struct NodeSite {\n"
"    struct NodeSite* next;\n"
"    const void* node;\n"
"    int site;\n"
"} NodeSite;\n"
"\n"
"static NodeSite* node_buckets[AIF_NODE_BUCKETS];\n"
"\n"
"static unsigned node_hash(const void* p) {\n"
"    uintptr_t v = (uintptr_t)p;\n"
"    v ^= v >> 33;\n"
"    v *= 0xff51afd7ed558ccdull;\n"
"    v ^= v >> 29;\n"
"    return (unsigned)v & (AIF_NODE_BUCKETS - 1);\n"
"}\n"
"\n"
"// One site per allocating expression, so a node that already has one is a bug\n"
"// in the walk rather than a collision to resolve. Recording the first keeps that\n"
"// deterministic if it ever happens.\n"
"void aif_site_note_node(int site, const void* node) {\n"
"    if (site < 0 || site >= site_count || node == NULL) return;\n"
"    unsigned b = node_hash(node);\n"
"    for (NodeSite* n = node_buckets[b]; n; n = n->next) {\n"
"        if (n->node == node) return;\n"
"    }\n"
"    NodeSite* n = (NodeSite*)xmalloc(sizeof(NodeSite), \"AIF node index\");\n"
"    n->node = node;\n"
"    n->site = site;\n"
"    n->next = node_buckets[b];\n"
"    node_buckets[b] = n;\n"
"}\n"
"\n"
"// -1 when no site was inferred for this node. Codegen must read that as \"no\n"
"// information\" and allocate the way it always did -- which is what makes SPEC\n"
"// 7.1's zero-analysis build behaviourally identical rather than merely intended\n"
"// to be.\n"
"int aif_tier_at_node(const void* node) {\n"
"    if (node == NULL) return -1;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) return aif_tier_of(n->site);\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// Level 2's question: may the value this node allocates be freed when the scope\n"
"// that allocated it exits?\n"
"//\n"
"// Two things have to hold, and the analysis supplies only one of them.\n"
"//\n"
"// The escape must bottom at that scope -- the same test the T0 clause opens\n"
"// with, and the reason the declaring-scope fix in the escape module had to be\n"
"// right. The tier alone does not answer it: T1 says \"some region\", which may be\n"
"// an enclosing scope if the value was also bound further out, and freeing at the\n"
"// inner exit would then be a use-after-free rather than a leak.\n"
"//\n"
"// The *language* must also guarantee a single owner, which is what\n"
"// site_is_move_only reports. Without it there is nothing to stop a second\n"
"// binding holding the same value, and a free at one binding's scope exit is a\n"
"// double free through the other. Today that admits structs only; it widens on\n"
"// its own when SPEC 11 item 10's affine collections land, which is what makes\n"
"// this the change Level 4 pays off rather than Level 2.\n"
"// The innermost scope at or above this one that has an arena, or -1.\n"
"//\n"
"// \"Has an arena\" is a `region` statement (which pins one) or a scope the cost\n"
"// model chose (LAYOUT 7.1). Both are the same thing to every question below:\n"
"// what matters is where the bump allocator that would serve this site lives.\n"
"static int enclosing_region(int scope) {\n"
"    for (int s = scope; s >= 0; s = scopes[s].parent) {\n"
"        if (scopes[s].arena) return s;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Automatic arena placement (LAYOUT 7.1)\n"
"//\n"
"//     ArenaBenefit(s) = allocs_in(s)\302\267(\316\261_T2 \342\210\222 \316\261_T1)\n"
"//                     \342\210\222 entries(s)\302\267arenaSetupCost\n"
"//                     \342\210\222 \316\273\302\267(bytes_held(s) \342\210\222 peak_live_bytes(s))\n"
"//\n"
"// Every scope is already an implicit region (SPEC 4.1), so the question is not\n"
"// which scopes *could* have an arena but which ones are worth the setup. Both\n"
"// inputs are supposed to come from an access profile; there is no profiler, so\n"
"// they are estimated statically and the estimate is stated rather than hidden:\n"
"//\n"
"//   entries(s)     factors out. It multiplies both terms once `allocs_in` is\n"
"//                  written as \"allocations per entry of s\", so the *sign* of the\n"
"//                  benefit -- which is the only thing the decision reads -- does\n"
"//                  not depend on it. That is why no loop-trip estimate above s\n"
"//                  is needed, and it is the reason to write the model this way.\n"
"//   allocs_in(s)   per entry: one per site the arena would serve, weighted by\n"
"//                  AIF_LOOP_ITERS for each loop between the site and s, since a\n"
"//                  site in a loop inside s allocates many times per entry.\n"
"//   bytes_held(s)  what the arena accumulates over one entry: the same weighted\n"
"//                  sum, in bytes. An arena reclaims nothing until its scope\n"
"//                  exits, so this is what it is holding at the end.\n"
"//   peak_live(s)   what would be live at once if each value were reclaimed when\n"
"//                  it died: one instance per site, unweighted. Two sites in one\n"
"//                  loop body are both live, so it is a sum over sites and not a\n"
"//                  maximum over them.\n"
"//\n"
"// The third term is the footprint one, and it is the only term that can make a\n"
"// scope decline an arena on grounds other than speed. Their difference is\n"
"// \316\243 bytes\302\267(weight \342\210\222 1): exactly the bytes a scope allocates and then abandons\n"
"// while holding on to them. A scope that allocates a great deal in a loop and\n"
"// keeps almost none of it live now takes individual objects, which is the\n"
"// trade LAYOUT 4 defines \316\273 for and which the first two terms alone cannot see --\n"
"// they are both counts, so arena-vs-object was decided purely on speed.\n"
"//\n"
"// Both new inputs are static estimates, like allocs_in above: bytes come from\n"
"// the computed layout and the weight from AIF_LOOP_ITERS. A site whose size is\n"
"// not statically known contributes 0 to both, so it moves the decision by\n"
"// nothing rather than by a guess -- the same rule the peak-bytes report uses.\n"
"//\n"
"// Placement is greedy innermost-first, which needs no separate nesting rule.\n"
"// A site can only be served by an arena its escape bottoms at or below, so an\n"
"// inner arena takes exactly the values that die earlier -- LAYOUT's condition\n"
"// for an inner arena being worth it, satisfied by construction rather than by a\n"
"// heuristic. Whatever the inner one cannot take, the next one out sees.\n"
"//\n"
"// Ties break by scope id, which is creation order and therefore node order\n"
"// (LAYOUT 7.1 last line).\n"
"// ============================================================================\n"
"\n"
"#define AIF_ALPHA_T1        3     // LAYOUT 4: allocation cycles at T1 (bump)\n"
"#define AIF_ALPHA_T2        90    //           and at T2 (a general allocator)\n"
"#define AIF_ARENA_SETUP    40     // LAYOUT 4: ~one block acquisition plus reset\n"
"// LAYOUT 4's \316\273, cache-pressure cost per wasted live byte. Kept as a ratio\n"
"// because the whole model is integer: 0.02 exactly, not a rounded 0.\n"
"#define AIF_LAMBDA_NUM      2\n"
"#define AIF_LAMBDA_DEN      100\n"
"\n"
"// Loops between `inner` and its ancestor `outer`, or 0 if unrelated.\n"
"static int loops_between(int inner, int outer) {\n"
"    if (inner < 0 || outer < 0) return 0;\n"
"    int d = scopes[inner].loop_depth - scopes[outer].loop_depth;\n"
"    return d > 0 ? d : 0;\n"
"}\n"
"\n"
"static long weight_of(int site_scope, int arena_scope) {\n"
"    long w = 1;\n"
"    int loops = loops_between(site_scope, arena_scope);\n"
"    // Capped so a deeply nested site cannot overflow the benefit; anything past\n"
"    // the cap is already far above the threshold and the exact value is noise.\n"
"    if (loops > 6) loops = 6;\n"
"    for (int i = 0; i < loops; i++) w *= AIF_LOOP_ITERS;\n"
"    return w;\n"
"}\n"
"\n"
"static int is_ancestor_or_self(int anc, int s) {\n"
"    for (int p = s; p >= 0; p = scopes[p].parent) {\n"
"        if (p == anc) return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// Would an arena at `cand` serve this site, given the arenas chosen so far?\n"
"static int arena_would_serve(int site_id, int cand) {\n"
"    Site* s = &sites[site_id];\n"
"    if (aif_tier_of(site_id) != AIF_T1) return 0;   // T0 has the frame already\n"
"    if (s->no_stack) return 0;                      // an explicit drop frees it\n"
"    if (s->kind == AIF_K_LIST) return 0;            // grows past its site; see below\n"
"    // The container reclaims it, so codegen will not route it here whatever this\n"
"    // model decides -- site_arena_scope declines on the same flag. Counting it as\n"
"    // benefit placed arenas whose whole justification was traffic they would never\n"
"    // see, which is the automatic-placement form of the inert `region`.\n"
"    if (s->in_container) return 0;\n"
"    if (s->E < 0) return 0;                         // Caller or Global\n"
"    if (!is_ancestor_or_self(cand, s->scope)) return 0;\n"
"    if (scope_lca(s->E, cand) != cand) return 0;    // outlives the arena\n"
"    // A nearer arena already claimed it. Innermost-first placement means any\n"
"    // scope strictly between the site and `cand` that has one gets it first.\n"
"    for (int p = s->scope; p >= 0 && p != cand; p = scopes[p].parent) {\n"
"        if (scopes[p].arena) return 0;\n"
"    }\n"
"    return 1;\n"
"}\n"
"\n"
"// SPEC 5.2.1.1, as an *input* to placement rather than a consequence of it: what\n"
"// a bracketed call sitting in `cand` would serve, had `cand` an arena. Defined\n"
"// with the bracket machinery below, because it asks that machinery's obligations\n"
"// rather than a second copy of them, and declared here because aif_place_arenas\n"
"// is its only caller.\n"
"static long bracket_candidate_serves(int cand, long* held, long* live);\n"
"\n"
"// M3.2c. Defined with the bracket machinery it reads; declared here because the\n"
"// trace in aif_place_arenas is the first thing to ask for it.\n"
"static int arena_stmt_range(int scope, int* first, int* last);\n"
"\n"
"// Placement is the input to bracketing now, so a bracket answer cached before\n"
"// placement ran is stale. aif_check_pins asks for one, so this is not\n"
"// hypothetical.\n"
"static void bracket_invalidate(void);\n"
"\n"
"// 1 once aif_place_arenas has run. Read by bracket_place to decide whether a\n"
"// cost-model arena is a region it may bracket into -- see the note above\n"
"// enclosing_pinned_region for why the answer used to be \"never\".\n"
"static int arenas_placed;\n"
"\n"
"// Chosen after the fixed point, because every input is a converged fact.\n"
"void aif_place_arenas(void) {\n"
"    // Innermost-first: a higher scope id is a scope created later, and the walk\n"
"    // creates a parent before its children, so descending id visits every child\n"
"    // before its parent.\n"
"    for (int s = scope_count - 1; s >= 0; s--) {\n"
"        if (scopes[s].arena) continue;              // pinned by `region`\n"
"        if (scopes[s].node == NULL) continue;       // no block for codegen to bracket\n"
"\n"
"        // Inside a `region`, the region decides. SPEC 5.2 makes `region` a pin on\n"
"        // this decision, and a pin that the cost model can undercut by placing a\n"
"        // tighter arena two lines in is not one -- the named region would serve\n"
"        // nothing and the manifest would stop being able to say which block owns\n"
"        // a value. A programmer who wants per-iteration reclamation inside a\n"
"        // region writes a nested `region`, which test_44's breaks_out does.\n"
"        //\n"
"        // Only *explicit* ancestors count, and the traversal is what makes that\n"
"        // true for free: innermost-first means an ancestor's flag is set here\n"
"        // only if `region` set it, never if this pass did.\n"
"        int pinned_above = 0;\n"
"        for (int p = scopes[s].parent; p >= 0; p = scopes[p].parent) {\n"
"            if (scopes[p].arena) { pinned_above = 1; break; }\n"
"        }\n"
"        if (pinned_above) continue;\n"
"\n"
"        long served = 0;\n"
"        long held = 0;\n"
"        long live = 0;\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            if (!arena_would_serve(k, s)) continue;\n"
"            long w = weight_of(sites[k].scope, s);\n"
"            served += w;\n"
"            held += (long)sites[k].bytes * w;\n"
"            live += (long)sites[k].bytes;\n"
"        }\n"
"        // The other half of the traffic, and on this corpus it is nearly all of\n"
"        // it: 198 of 236 blocked sites are in a callee, where arena_would_serve\n"
"        // cannot reach them by construction -- enclosing_region walks a lexical\n"
"        // tree rooted per function, so scope_lca across two owners is -1 whatever\n"
"        // the escape says. Those sites are asked of the bracket obligations\n"
"        // instead, which are a call-graph question and answer across functions.\n"
"        //\n"
"        // This is the clause that makes an automatic region worth placing on g2:\n"
"        // every DrawCmd in the frame loop is allocated inside `cull`, so the\n"
"        // lexical sum above is 0 and the scope was never a candidate at all.\n"
"        served += bracket_candidate_serves(s, &held, &live);\n"
"        if (served == 0) continue;\n"
"\n"
"        long benefit = served * (AIF_ALPHA_T2 - AIF_ALPHA_T1)\n"
"                     - (long)AIF_ARENA_SETUP\n"
"                     - (AIF_LAMBDA_NUM * (held - live)) / AIF_LAMBDA_DEN;\n"
"        if (benefit > 0) scopes[s].arena = 1;\n"
"    }\n"
"\n"
"    // From here a cost-model arena is as good a region to bracket into as a\n"
"    // written one, and any answer cached while that was false has to go.\n"
"    arenas_placed = 1;\n"
"    bracket_invalidate();\n"
"\n"
"    // M3.2b's data, on demand. A field nothing reads yet is a field nothing has\n"
"    // checked, and \"the IR did not change\" only proves it is inert -- not that\n"
"    // it is right. Sibling of AIF_BRACKET_TRACE, and prints once because\n"
"    // aif_place_arenas runs once.\n"
"    if (getenv(\"AIF_STMT_TRACE\") != NULL) {\n"
"        for (int s = 0; s < scope_count; s++) {\n"
"            if (!scopes[s].arena) continue;\n"
"            int lo = -1, hi = -1;\n"
"            if (arena_stmt_range(s, &lo, &hi)) {\n"
"                fprintf(stderr, \"aif: arena scope %d extent [%d,%d]%s\\n\", s, lo, hi,\n"
"                        scopes[s].region_name >= 0 ? \" (written)\" : \" (auto)\");\n"
"            } else {\n"
"                fprintf(stderr, \"aif: arena scope %d extent whole-block%s\\n\", s,\n"
"                        scopes[s].region_name >= 0 ? \" (written)\" : \" (auto)\");\n"
"            }\n"
"        }\n"
"        // Over the buckets rather than key_by_id, which is built further down\n"
"        // the file than this runs.\n"
"        for (int b = 0; b < AIF_KEY_BUCKETS; b++) {\n"
"            for (KeyNode* kn = key_buckets[b]; kn; kn = kn->next) {\n"
"                if (kn->kind != AIF_KEY_VAR) continue;\n"
"                int last = aif_key_last_stmt(kn->id);\n"
"                if (last < 0) continue;\n"
"                int d = (kn->id < var_scope_cap) ? var_scope[kn->id] : -1;\n"
"                fprintf(stderr, \"aif: last-use %s.%s scope %d stmt %d\\n\",\n"
"                        kn->a >= 0 && kn->a < fn_count ? aif_str(fns[kn->a].name) : \"?\",\n"
"                        aif_str(kn->b), d, last);\n"
"            }\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// ============================================================================\n"
"// REQUIREMENTS 19 -- memory budget reporting\n"
"//\n"
"// The arena high-water mark, statically estimated. Fixed budgets are a hard\n"
"// constraint on console targets, and arenas are what make one tractable: a\n"
"// region's peak is the sum of what it serves, and the peak for a program is the\n"
"// largest sum along a **root-to-leaf chain** of arena scopes -- not the total,\n"
"// which would add sibling regions that are never live at the same time.\n"
"//\n"
"// Weighted by AIF_LOOP_ITERS per enclosing loop, the same estimator automatic\n"
"// placement uses for allocs_in(s), so the two cannot disagree about how much a\n"
"// scope serves.\n"
"//\n"
"// **It is an estimate, and the manifest says which part it cannot see.** A\n"
"// struct's size is known from its layout; a string's is its length, which is a\n"
"// run-time value. Sites whose size is not statically known are counted\n"
"// separately rather than guessed at, because a fabricated per-string constant\n"
"// would make a budget gate that passes or fails on a number nobody computed.\n"
"// ============================================================================\n"
"\n"
"// SPEC 5.2.1.1's contribution, defined with the placement it comes from.\n"
"static long bracket_bytes_of(int scope, int* unsized);\n"
"\n"
"long aif_arena_high_water(void) {\n"
"    if (scope_count <= 0) return 0;\n"
"    long* own = (long*)xcalloc((size_t)scope_count, sizeof(long), \"AIF arena bytes\");\n"
"\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (!scopes[s].arena) continue;\n"
"        long b = 0;\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            if (!arena_would_serve(k, s)) continue;\n"
"            b += (long)sites[k].bytes * weight_of(sites[k].scope, s);\n"
"        }\n"
"        own[s] = b + bracket_bytes_of(s, NULL);\n"
"    }\n"
"\n"
"    long peak = 0;\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (!scopes[s].arena) continue;\n"
"        long chain = 0;\n"
"        for (int p = s; p >= 0; p = scopes[p].parent) {\n"
"            if (scopes[p].arena) chain += own[p];\n"
"        }\n"
"        if (chain > peak) peak = chain;\n"
"    }\n"
"\n"
"    free(own);\n"
"    return peak;\n"
"}\n"
"\n"
"// What one region's arena serves, for the `pin(N)` gate. Its own scope only:\n"
"// a nested region has its own arena and its own cap.\n"
"static long arena_bytes_of(int scope) {\n"
"    long b = 0;\n"
"    for (int k = 0; k < site_count; k++) {\n"
"        if (!arena_would_serve(k, scope)) continue;\n"
"        b += (long)sites[k].bytes * weight_of(sites[k].scope, scope);\n"
"    }\n"
"    // SPEC 5.2.1.1. What a bracketed call routes here is memory this region\n"
"    // holds, so a `pin(N)` gate has to see it -- see bracket_bytes_of.\n"
"    return b + bracket_bytes_of(scope, NULL);\n"
"}\n"
"\n"
"// REQUIREMENTS 19's gate. A refuted budget is an error for the same reason a\n"
"// refuted `pin` is (SPEC 5.4.1): it is a false assertion about one's own\n"
"// program, not an inference failure, so SPEC 1's invariant is untouched.\n"
"//\n"
"// Returns the number refuted; the frontend prints them.\n"
"int aif_budget_count(void) { return scope_count; }\n"
"\n"
"long aif_scope_budget(int s)     { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget; }\n"
"long aif_scope_served(int s)     { return (s < 0 || s >= scope_count) ? 0 : arena_bytes_of(s); }\n"
"const char* aif_scope_region(int s) {\n"
"    if (s < 0 || s >= scope_count || scopes[s].region_name < 0) return \"\";\n"
"    return aif_str(scopes[s].region_name);\n"
"}\n"
"int aif_scope_budget_file(int s) { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget_file; }\n"
"int aif_scope_budget_line(int s) { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget_line; }\n"
"int aif_scope_budget_col(int s)  { return (s < 0 || s >= scope_count) ? 0 : scopes[s].budget_col; }\n"
"\n"
"// Arena-served sites whose size is not statically known -- strings, whose length\n"
"// is a run-time value. Reported alongside the estimate so the number above is\n"
"// read as covering what it covers.\n"
"int aif_arena_unsized_sites(void) {\n"
"    int n = 0;\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (!scopes[s].arena) continue;\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            if (arena_would_serve(k, s) && sites[k].bytes == 0) n++;\n"
"        }\n"
"        bracket_bytes_of(s, &n);    // and the bracketed ones it cannot size either\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// 1 when this BLOCK node opens an arena the cost model chose. A `region`\n"
"// statement is excluded: codegen already brackets that one, and bracketing it\n"
"// twice would push two arenas and pop only the inner one at an early exit.\n"
"int aif_auto_arena_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (int s = 0; s < scope_count; s++) {\n"
"        if (scopes[s].node != node) continue;\n"
"        if (scopes[s].region_name >= 0) return 0;\n"
"        return scopes[s].arena;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// SPEC 5.2: may this value come from the enclosing region's arena?\n"
"//\n"
"// **This is the only arena gate.** Codegen (aif_arena_at_node), the manifest's\n"
"// placement column (aif_region_name_at_site), the zero-serving diagnostic\n"
"// (aif_region_serves), the LAYOUT 7.1 cost model and `--why`'s placement section\n"
"// all read this one function. A disagreement between them is a manifest\n"
"// describing a build that did not happen -- the defect the `rc`/`rc:none` split\n"
"// exists to prevent, one tier down. They were four separate copies of these\n"
"// clauses until 2026-08-14, and the copy that had drifted was placing arenas\n"
"// that served nothing.\n"
"//\n"
"// The nesting case is what makes the last clause more than a lexical question:\n"
"//\n"
"//     region outer { let mut x = ...; region inner { x = Foo{} } use(x) }\n"
"//\n"
"// `Foo{}` is lexically inside `inner`, but its escape is `outer`'s scope, and\n"
"// inner's arena is gone by `use(x)`. lca(outer, inner) is outer, not inner, so\n"
"// this correctly declines and the value goes to the heap.\n"
"//\n"
"// **`blockers` receives EVERY clause that rejected, not the first**, and that is\n"
"// the whole reason it is a mask. A short-circuiting answer told a reader of g2\n"
"// \"the tier is not T1\" -- true, and the wrong thing to act on, because\n"
"// `in_container` and `no_region` reject the same site immediately afterwards. So\n"
"// the tier gets fixed, the binary does not change, and the session ends with a\n"
"// design note explaining a gate nobody read to the end. That happened three\n"
"// times before this mask existed.\n"
"\n"
"#define AIF_ARENA_B_NOT_T1       1\n"
"#define AIF_ARENA_B_NO_STACK     2\n"
"#define AIF_ARENA_B_IN_CONTAINER 4\n"
"#define AIF_ARENA_B_IS_LIST      8\n"
"#define AIF_ARENA_B_NO_REGION   16\n"
"#define AIF_ARENA_B_ESCAPES     32\n"
"#define AIF_ARENA_B_OUTLIVES    64\n"
"\n"
"// SPEC 5.2.1.1. The region a bracketed call hands this site, or -1. Defined\n"
"// after the call graph it reads; declared here because it is the first clause of\n"
"// the gate below and must not be a second copy of it.\n"
"static int site_bracket_region(int id);\n"
"\n"
"static int site_arena_scope_full(int id, int* blockers) {\n"
"    if (id < 0 || id >= site_count) {\n"
"        if (blockers) *blockers = AIF_ARENA_B_NOT_T1;\n"
"        return -1;\n"
"    }\n"
"    Site* s = &sites[id];\n"
"    int mask = 0;\n"
"\n"
"    // SPEC 5.2.1.1's placement. This site is in a bracketed extent, so its arena\n"
"    // is the caller's region and the five clauses below do not apply to it:\n"
"    // every one of them asks about an arena in *this* function, and the whole\n"
"    // point of bracketing is that there is not one. The obligations that replace\n"
"    // them were discharged once, over the entire extent, in bracket_place.\n"
"    //\n"
"    // What survives is what a *deallocator* would still do to this value, which\n"
"    // bracketing does not change:\n"
"    //\n"
"    //   * T0 storage is the frame. Codegen checks the arena before the tier\n"
"    //     (src/ir/expr.psm), so accepting a T0 site here would take a hoisted\n"
"    //     alloca and turn it into one bump allocation per loop iteration.\n"
"    //   * T3 and T4b carry a count in a prefix header and are released by a\n"
"    //     decrement. The last decrement calls the deallocator, and a bump\n"
"    //     pointer is not a thing it can take.\n"
"    //   * `drop(x)` frees it explicitly, for the same reason as below.\n"
"    //\n"
"    // T1 and T2 both pass, and T2 passing is the point: SPEC 5.2 makes the tier\n"
"    // the derived fact and the placement a codegen decision, so a bracketed site\n"
"    // keeps the tier it derived and the manifest reads `T2  region:<name>`.\n"
"    // Promoting it to T1 would move the tier distribution, and the oracle does\n"
"    // not model placement -- the differential would then fail on a difference\n"
"    // that is not an inference difference.\n"
"    int br = site_bracket_region(id);\n"
"    if (br >= 0) {\n"
"        int tier = aif_tier_of(id);\n"
"        if (tier != AIF_T1 && tier != AIF_T2) mask |= AIF_ARENA_B_NOT_T1;\n"
"        if (s->no_stack) mask |= AIF_ARENA_B_NO_STACK;\n"
"        if (blockers) *blockers = mask;\n"
"        return mask == 0 ? br : -1;\n"
"    }\n"
"\n"
"    if (aif_tier_of(id) != AIF_T1) mask |= AIF_ARENA_B_NOT_T1;  // T0 has the frame\n"
"    // The same reason the T0 clause asks: an arena pointer is not a thing a\n"
"    // deallocator can take, and `drop(x)` emits one unconditionally -- the\n"
"    // source, not the model, decided when that value dies.\n"
"    if (s->no_stack) mask |= AIF_ARENA_B_NO_STACK;\n"
"    // The container frees its elements through the deallocator, and a pointer\n"
"    // into the middle of an arena chunk is not one it can take.\n"
"    if (s->in_container) mask |= AIF_ARENA_B_IN_CONTAINER;\n"
"    // An arena serves values allocated once. A list is not one: list_push\n"
"    // reallocates the element block long after this site returned, at whatever\n"
"    // arena depth the program happens to be at then -- so the block would be\n"
"    // tied to a region the list can outlive, and freeing the old block would\n"
"    // hand arena memory to the deallocator.\n"
"    if (s->kind == AIF_K_LIST) mask |= AIF_ARENA_B_IS_LIST;\n"
"\n"
"    // **The clause that decides the corpus, and the one three sessions of design\n"
"    // notes walked past.** `enclosing_region` walks scopes[].parent, a *lexical*\n"
"    // tree rooted per function -- scope_lca returns -1 across owners. So a site\n"
"    // in a callee can never find an arena its caller opened, however its escape\n"
"    // is spelled. Measured 2026-08-14: of 234 allocation sites in aif/corpus and\n"
"    // aif/evidence, 38 are served and 196 are not -- and **all 196 fail here**.\n"
"    // Every one of the 38 is a case where the region and the allocation share a\n"
"    // function. No value of E moves that number, because E holds a scope id in\n"
"    // the site's own function while the arena that would serve a callee's\n"
"    // allocation is chosen at run time by arena_depth. SPEC 5.2.1 states it\n"
"    // normatively; aif/evidence/arena_census.py re-derives it in one command.\n"
"    int r = enclosing_region(s->scope);\n"
"    if (r < 0) {\n"
"        mask |= AIF_ARENA_B_NO_REGION;\n"
"    } else if (s->E < 0) {\n"
"        mask |= AIF_ARENA_B_ESCAPES;                // Caller or Global\n"
"    } else if (scope_lca(s->E, r) != r) {\n"
"        mask |= AIF_ARENA_B_OUTLIVES;\n"
"    }\n"
"\n"
"    if (blockers) *blockers = mask;\n"
"    return mask == 0 ? r : -1;\n"
"}\n"
"\n"
"static int site_arena_scope(int id) {\n"
"    return site_arena_scope_full(id, NULL);\n"
"}\n"
"\n"
"// SPEC 6.3's witness path, for placement rather than for the tier. `--why`\n"
"// answered \"what made this T2\" and said nothing about where the value lives.\n"
"int aif_arena_blockers(int id) {\n"
"    int mask = 0;\n"
"    site_arena_scope_full(id, &mask);\n"
"    return mask;\n"
"}\n"
"\n"
"// The region a site would have been served by if the gate had not declined --\n"
"// i.e. the nearest enclosing one, ignoring every other clause. \"\" when there is\n"
"// none, which is what AIF_ARENA_B_NO_REGION already says; this exists so the\n"
"// OUTLIVES case can name the arena the value escaped past.\n"
"const char* aif_nearest_region_name(int id) {\n"
"    if (id < 0 || id >= site_count) return \"\";\n"
"    int r = enclosing_region(sites[id].scope);\n"
"    if (r < 0) return \"\";\n"
"    return scopes[r].region_name < 0 ? \"auto\" : aif_str(scopes[r].region_name);\n"
"}\n"
"\n"
"int aif_arena_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        return site_arena_scope(n->site) >= 0 ? 1 : 0;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// The region name to report for this site, or \"\" when it is not arena-placed.\n"
"// An arena the cost model chose has no name to report -- it is a scope, not a\n"
"// declaration -- so it reports \"auto\", which is what distinguishes it in the\n"
"// manifest from a `region` the programmer pinned.\n"
"const char* aif_region_name_at_site(int id) {\n"
"    int r = site_arena_scope(id);\n"
"    if (r < 0) return \"\";\n"
"    if (scopes[r].region_name < 0) return \"auto\";\n"
"    return aif_str(scopes[r].region_name);\n"
"}\n"
"\n"
"// SPEC 5.2's diagnostic. How many allocation sites this scope's arena actually\n"
"// serves -- by the codegen gate above, not by the cost model's estimate, because\n"
"// the question a programmer is asking is \"did my annotation do anything\" and only\n"
"// the emitted code answers that.\n"
"int aif_region_serves(int scope) {\n"
"    if (scope < 0 || scope >= scope_count) return 0;\n"
"    int n = 0;\n"
"    for (int i = 0; i < site_count; i++) {\n"
"        if (site_arena_scope(i) == scope) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// ----------------------------------------------------------------------------\n"
"// SPEC 5.4 applied to placement -- `pin(<region-name>)`\n"
"//\n"
"// SPEC 5.2.1.1 says this of its own regime (a): \"(a) is fragile as a language\n"
"// guarantee -- adding a second call to a bracketed callee silently removes the\n"
"// placement -- which is why an implementation using it SHALL record in the\n"
"// manifest which call sites it bracketed, so the loss appears as a diff rather\n"
"// than as a slowdown.\" The manifest does record them. A diff is only read by\n"
"// somebody who looks; this is the same fact stated by the *programmer*, so a\n"
"// build fails instead.\n"
"//\n"
"// **It reads aif_region_name_at_site and computes nothing.** That is\n"
"// site_arena_scope, the one arena gate every other consumer already reads --\n"
"// codegen, the manifest's placement column, the zero-serving warning, the cost\n"
"// model and `--why`. Re-deriving \"is this bracketed\" from the bracket table here\n"
"// would be a fifth copy of a predicate this file has already paid for having\n"
"// four of, and the copy that drifts is always the one that decides.\n"
"//\n"
"// It is an assertion, never a directive (SPEC 5.0.1): nothing below writes to\n"
"// scopes[].arena or to site_bracket, so a build with these annotations deleted\n"
"// emits the same instructions. That is what makes the feature diagnostic-only,\n"
"// and what makes \"the IR must not move\" the test for it.\n"
"//\n"
"// Ordering: this runs after aif_place_arenas, unlike aif_check_pins which must\n"
"// run before it. A tier pin is an *input* to placement (the cost model ranks\n"
"// scopes by tier); a placement pin is an assertion about its *output*.\n"
"// ----------------------------------------------------------------------------\n"
"void aif_check_placement_pins(int converged) {\n"
"    for (int i = 0; i < site_count; i++) {\n"
"        Site* s = &sites[i];\n"
"        if (s->pin_region < 0) continue;\n"
"\n"
"        const char* placed = aif_region_name_at_site(i);\n"
"        if (placed[0] != '\\0' && strcmp(placed, aif_str(s->pin_region)) == 0) {\n"
"            s->pin_region_verdict = AIF_PIN_HONOURED;\n"
"        } else if (converged) {\n"
"            // SPEC 5.4.1. There is no third branch here and there is one in\n"
"            // aif_check_pins: a tier pin *above* the derived tier is honoured\n"
"            // because every tier is semantically valid and a more expensive one\n"
"            // needs no proof (SPEC 5.4.4). Placement has no such order -- an\n"
"            // arena either serves this site or does not -- so the direction\n"
"            // limit has nothing to be a limit on, and \"served by some other\n"
"            // region\" is a refutation rather than a weaker honour.\n"
"            s->pin_region_verdict = AIF_PIN_REFUTED;\n"
"        } else {\n"
"            // SPEC 5.4.2, and it is not a formality here. A truncated analysis\n"
"            // widens every unproven site to its top tier, which takes the arena\n"
"            // away from sites a converged run keeps it for -- so a build that\n"
"            // ran out of budget would refute pins a full one honours.\n"
"            s->pin_region_verdict = AIF_PIN_UNPROVEN;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"int aif_site_pin_region_verdict(int id) {\n"
"    if (id < 0 || id >= site_count) return AIF_PIN_NONE;\n"
"    return sites[id].pin_region_verdict;\n"
"}\n"
"\n"
"const char* aif_site_pin_region(int id) {\n"
"    if (id < 0 || id >= site_count || sites[id].pin_region < 0) return \"\";\n"
"    return aif_str(sites[id].pin_region);\n"
"}\n"
"\n"
"int aif_scope_region_file(int s) { return (s < 0 || s >= scope_count) ? 0 : scopes[s].region_file; }\n"
"int aif_scope_region_line(int s) { return (s < 0 || s >= scope_count) ? 0 : scopes[s].region_line; }\n"
"int aif_scope_region_col(int s)  { return (s < 0 || s >= scope_count) ? 0 : scopes[s].region_col; }\n"
"\n"
"// 1 when this site's arena was pinned by a `region` statement rather than chosen\n"
"// by the cost model. SPEC 6.2's `origin` column distinguishes them: a pin that\n"
"// stops being honoured is a gate regression, an inferred placement moving is not.\n"
"int aif_site_arena_is_pinned(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    // SPEC 5.2.1.1. A bracketed site's arena is a `region` in *another* function,\n"
"    // which enclosing_region cannot see -- and it is always a pinned one, because\n"
"    // bracketing only ever targets a `region` (see bracket_place). Asked of the\n"
"    // gate rather than of the lexical tree for that reason, and asked first so\n"
"    // the lexical answer below is left exactly as it was for every other site.\n"
"    int served = site_arena_scope(id);\n"
"    if (served >= 0 && scopes[served].region_name >= 0) return 1;\n"
"    int r = enclosing_region(sites[id].scope);\n"
"    if (r < 0) return 0;\n"
"    return scopes[r].region_name >= 0 ? 1 : 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Call-site bracketing: may a caller's region reach a callee's allocations?\n"
"// (SPEC 5.2.1's first named repair. Report only -- nothing here places anything.)\n"
"//\n"
"// The gate above rejects a site whose `region` is in another function, and the\n"
"// census says that is 196 of 196 blocked sites. The repair is not to make the\n"
"// site's E name the caller's arena -- it cannot; E is a scope id in the site's\n"
"// own function -- but to *bracket the call*, so that the arena serving the\n"
"// callee's allocations is chosen at run time by the region stack that is\n"
"// already there.\n"
"//\n"
"// That is only sound when nothing the callee allocates can outlive the region.\n"
"// This computes exactly that question, per function, and answers it as a mask\n"
"// rather than a verdict -- the same decision `aif_arena_blockers` records, for\n"
"// the same reason: a conjunction reported as its first failure sends a reader\n"
"// to the wrong work, and this file has three sessions of evidence for it.\n"
"//\n"
"//   GLOBAL       an allocation in the extent escapes to static storage. Nothing\n"
"//                bounds its lifetime, so no region can.\n"
"//   PARAM_STORE  the extent stores into something it did not allocate. This is\n"
"//                the counterexample that kills the naive version:\n"
"//\n"
"//                    fn add_to(dest: List<Node>, n: Int) {\n"
"//                        list_push(dest, Node { id: n })\n"
"//                    }\n"
"//                    region R { add_to(long_lived_list, 5) }\n"
"//\n"
"//                the Node comes from R's arena and the list outlives R. Caught\n"
"//                by asking whether every *owner* the extent stores into was\n"
"//                itself allocated inside the extent.\n"
"//   OPAQUE       a callee with no visible body. A summary of a body nobody can\n"
"//                see is a guess, and the optimistic direction is the one that\n"
"//                produces a use-after-free.\n"
"//   DROP         `drop(x)` inside the extent. The source, not the model, decided\n"
"//                when that value dies, and a bump pointer is not a thing free()\n"
"//                can take. Same clause as AIF_ARENA_B_NO_STACK, one level up.\n"
"//   SHARED_BODY  the body serves more than one placement regime -- SPEC 5.2.1's\n"
"//                regime (a). Codegen's frees are static decisions, so a body\n"
"//                reachable both inside and outside a bracket would have to free\n"
"//                arena memory on one path or leak heap memory on the other.\n"
"//                Not an allocation obligation; reported separately for that\n"
"//                reason, and the reason the manifest must say when it fired.\n"
"//\n"
"// Obligation 4 -- the summary is a fixpoint over the call graph -- is not a\n"
"// blocker but how every clause above is evaluated: recursion and mutual\n"
"// recursion mean the transitive callee set is a closure, not a walk. The\n"
"// remaining obligation, \"the returned value does not outlive R\", is a property\n"
"// of the *call site* rather than of the function, and `site_arena_scope`'s\n"
"// scope_lca test already answers it in the caller.\n"
"// ============================================================================\n"
"\n"
"#define AIF_BR_B_GLOBAL       1\n"
"#define AIF_BR_B_PARAM_STORE  2\n"
"#define AIF_BR_B_OPAQUE       4\n"
"#define AIF_BR_B_DROP         8\n"
"#define AIF_BR_B_SHARED_BODY 16\n"
"\n"
"// One entry per call *expression*, so the count of entries naming a callee is\n"
"// its static call-site count -- which is what regime (a) asks about. A bitset\n"
"// would collapse two calls to one and silently make every callee sole-owned.\n"
"typedef struct {\n"
"    int caller;\n"
"    int callee;\n"
"    int scope;      // the caller's scope the call sits in, for \"calls in a region\"\n"
"    // M3.2, and the reason the call edge needs it as much as the site does: the\n"
"    // clause that refuses `g2.psm` is \"an opaque call is in the region body\",\n"
"    // asked of the whole block. A non-lexical extent has to ask it of a\n"
"    // statement range instead, and `clock_gettime_nsec_np` sits outside the one\n"
"    // that matters.\n"
"    int stmt;\n"
"} CallEdge;\n"
"\n"
"static CallEdge* call_edges;\n"
"static int call_edge_count, call_edge_cap;\n"
"\n"
"static CallEdge* call_edge_push(void) {\n"
"    if (call_edge_count == call_edge_cap) {\n"
"        call_edge_cap = call_edge_cap ? call_edge_cap * 2 : 256;\n"
"        call_edges = (CallEdge*)xrealloc(call_edges, (size_t)call_edge_cap * sizeof(CallEdge),\n"
"                                         \"AIF call graph\");\n"
"    }\n"
"    return &call_edges[call_edge_count++];\n"
"}\n"
"\n"
"// Value sets a function stores *into*: the holder of a `retain_in` and the owner\n"
"// set of a field store. Resolved after the solve, because until then a value set\n"
"// names keys rather than sites.\n"
"typedef struct {\n"
"    int fn;\n"
"    int vs;\n"
"} OwnerUse;\n"
"\n"
"static OwnerUse* owner_uses;\n"
"static int owner_use_count, owner_use_cap;\n"
"\n"
"// The per-function facts the closure walk reads. Built once, lazily, because\n"
"// every one of them needs the converged facts.\n"
"static Bits* fn_callees;        // fn -> direct callees, for the closure\n"
"static Bits* fn_owner_fns;      // fn -> functions that allocated what it stores into\n"
"static char* fn_has_global;\n"
"static char* fn_has_drop;\n"
"static char* fn_calls_opaque;\n"
"static int bracket_ready;\n"
"// How many functions the arrays above were sized for. Kept because aif_reset\n"
"// runs after fn_count has been zeroed by the caller in some orders, and freeing\n"
"// a bitset array by a count that is no longer the one it was allocated with is\n"
"// how a teardown leaks or double-frees.\n"
"static int bracket_fn_cap;\n"
"static Bits bracket_closure, bracket_scratch;\n"
"\n"
"void aif_call_edge(int caller, int callee, int scope) {\n"
"    if (caller < 0 || callee < 0) return;\n"
"    CallEdge* e = call_edge_push();\n"
"    e->caller = caller;\n"
"    e->callee = callee;\n"
"    e->scope = scope;\n"
"    e->stmt = g_stmt;\n"
"}\n"
"\n"
"// A call this compilation cannot summarise: a sealed function, or an extern\n"
"// whose contract table says nothing about it. An extern the table *does* know\n"
"// is already modelled -- `retain_in` puts the value under a container,\n"
"// `retain` sends it to Global, `consume` marks it no_stack -- so the clauses\n"
"// below see it and this does not have to.\n"
"//\n"
"// Recorded as an edge to callee -1 rather than into a per-function flag array,\n"
"// because the walk creates functions as it goes: an array sized at the first\n"
"// opaque call would be short by every function declared after it.\n"
"void aif_call_opaque(int caller, int scope) {\n"
"    if (caller < 0) return;\n"
"    CallEdge* e = call_edge_push();\n"
"    e->caller = caller;\n"
"    e->callee = -1;\n"
"    e->scope = scope;\n"
"    e->stmt = g_stmt;\n"
"}\n"
"\n"
"void aif_note_owner_use(int fn, int vs) {\n"
"    if (fn < 0 || vs < 0) return;\n"
"    if (owner_use_count == owner_use_cap) {\n"
"        owner_use_cap = owner_use_cap ? owner_use_cap * 2 : 256;\n"
"        owner_uses = (OwnerUse*)xrealloc(owner_uses, (size_t)owner_use_cap * sizeof(OwnerUse),\n"
"                                         \"AIF owner uses\");\n"
"    }\n"
"    owner_uses[owner_use_count].fn = fn;\n"
"    owner_uses[owner_use_count].vs = vs;\n"
"    owner_use_count++;\n"
"}\n"
"\n"
"static void bracket_prepare(void) {\n"
"    if (bracket_ready || fn_count == 0) return;\n"
"    bracket_ready = 1;\n"
"\n"
"    bracket_fn_cap = fn_count;\n"
"    fn_callees   = (Bits*)xcalloc((size_t)fn_count, sizeof(Bits), \"AIF call graph\");\n"
"    fn_owner_fns = (Bits*)xcalloc((size_t)fn_count, sizeof(Bits), \"AIF store owners\");\n"
"    fn_has_global = (char*)xcalloc((size_t)fn_count, 1, \"AIF bracket facts\");\n"
"    fn_has_drop   = (char*)xcalloc((size_t)fn_count, 1, \"AIF bracket facts\");\n"
"    fn_calls_opaque = (char*)xcalloc((size_t)fn_count, 1, \"AIF opaque calls\");\n"
"\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        CallEdge* e = &call_edges[i];\n"
"        if (e->caller < 0 || e->caller >= fn_count) continue;\n"
"        if (e->callee < 0) {\n"
"            fn_calls_opaque[e->caller] = 1;\n"
"        } else if (e->callee < fn_count) {\n"
"            bits_set(&fn_callees[e->caller], e->callee, \"AIF call graph\");\n"
"        }\n"
"    }\n"
"\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        int f = sites[s].fn;\n"
"        if (f < 0 || f >= fn_count) continue;\n"
"        if (sites[s].E == AIF_E_GLOBAL) fn_has_global[f] = 1;\n"
"        if (sites[s].no_stack) fn_has_drop[f] = 1;\n"
"    }\n"
"\n"
"    // A store's owners are sites; which *function* allocated them is the fact\n"
"    // the closure test needs, and it does not depend on which caller is asking,\n"
"    // so it is computed once here rather than per query.\n"
"    for (int i = 0; i < owner_use_count; i++) {\n"
"        int f = owner_uses[i].fn;\n"
"        if (f < 0 || f >= fn_count) continue;\n"
"        resolve(owner_uses[i].vs, &bracket_scratch);\n"
"        for (int s = 0; s < site_count; s++) {\n"
"            if (!bits_test(&bracket_scratch, s)) continue;\n"
"            // An orphan site belongs to no function, so no closure can contain\n"
"            // it. fn_count is the id reserved for exactly that, and it is one\n"
"            // past the end -- so a closure bitset never holds it and the subset\n"
"            // test below rejects, which is the sound direction.\n"
"            int owner_fn = sites[s].fn;\n"
"            bits_set(&fn_owner_fns[f], (owner_fn < 0 || owner_fn >= fn_count) ? fn_count : owner_fn,\n"
"                     \"AIF store owners\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// Every function reachable from `f` through the call graph, `f` included.\n"
"// INFERENCE-style worklist rather than a walk, because mutual recursion makes\n"
"// the transitive set a least fixed point (obligation 4).\n"
"static void bracket_reachable(int f, Bits* out) {\n"
"    bits_clear(out);\n"
"    bits_set(out, f, \"AIF bracket closure\");\n"
"    int changed = 1;\n"
"    while (changed) {\n"
"        changed = 0;\n"
"        for (int g = 0; g < fn_count; g++) {\n"
"            if (!bits_test(out, g)) continue;\n"
"            for (int h = 0; h < fn_count; h++) {\n"
"                if (!bits_test(&fn_callees[g], h)) continue;\n"
"                if (bits_set(out, h, \"AIF bracket closure\")) changed = 1;\n"
"            }\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"static int bits_subset(const Bits* a, const Bits* b) {\n"
"    for (int i = 0; i < a->nwords; i++) {\n"
"        Word x = a->w[i];\n"
"        if (!x) continue;\n"
"        Word y = (i < b->nwords) ? b->w[i] : 0;\n"
"        if (x & ~y) return 0;\n"
"    }\n"
"    return 1;\n"
"}\n"
"\n"
"int aif_fn_bracket_blockers(int f) {\n"
"    if (f < 0 || f >= fn_count) return AIF_BR_B_OPAQUE;\n"
"    bracket_prepare();\n"
"    bracket_reachable(f, &bracket_closure);\n"
"\n"
"    int mask = 0;\n"
"    for (int g = 0; g < fn_count; g++) {\n"
"        if (!bits_test(&bracket_closure, g)) continue;\n"
"        if (fn_has_global[g])   mask |= AIF_BR_B_GLOBAL;\n"
"        if (fn_has_drop[g])     mask |= AIF_BR_B_DROP;\n"
"        if (fn_calls_opaque[g]) mask |= AIF_BR_B_OPAQUE;\n"
"        if (fns[g].sealed)      mask |= AIF_BR_B_OPAQUE;\n"
"        if (!bits_subset(&fn_owner_fns[g], &bracket_closure)) mask |= AIF_BR_B_PARAM_STORE;\n"
"    }\n"
"\n"
"    // Regime (a). `f` itself must have exactly one call site -- the one that\n"
"    // would be bracketed -- and everything it reaches must be reached only from\n"
"    // inside the extent, or that callee's body would have to free arena memory\n"
"    // on one path and heap memory on the other.\n"
"    int f_calls = 0;\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        CallEdge* e = &call_edges[i];\n"
"        if (e->callee == f) { f_calls++; continue; }\n"
"        if (!bits_test(&bracket_closure, e->callee)) continue;\n"
"        if (!bits_test(&bracket_closure, e->caller)) mask |= AIF_BR_B_SHARED_BODY;\n"
"    }\n"
"    if (f_calls != 1) mask |= AIF_BR_B_SHARED_BODY;\n"
"\n"
"    return mask;\n"
"}\n"
"\n"
"int aif_fn_call_sites(int f) {\n"
"    int n = 0;\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        if (call_edges[i].callee == f) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// Of this function's call sites, how many sit inside a region. This is the half\n"
"// of the answer the obligations do not carry: a function can clear every one of\n"
"// them and still never be placed, because nobody calls it from a region. Telling\n"
"// a reader \"bracketable\" without it is the manifest defect one level up --\n"
"// reporting a property that reads as a placement and is not one.\n"
"int aif_fn_calls_in_region(int f) {\n"
"    int n = 0;\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        if (call_edges[i].callee != f) continue;\n"
"        if (enclosing_region(call_edges[i].scope) >= 0) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// How many call expressions sit lexically inside a `region` (or inside a scope\n"
"// the cost model gave an arena). This is the population call-site placement can\n"
"// draw from, and printing it beside the qualifying-function count is what makes\n"
"// \"N functions qualify\" mean something: a thousand safe functions nobody calls\n"
"// from a region is still zero placements.\n"
"int aif_region_call_sites(void) {\n"
"    int n = 0;\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        if (call_edges[i].callee < 0) continue;   // an opaque call is never bracketed\n"
"        if (enclosing_region(call_edges[i].scope) >= 0) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// Of those, the ones whose callee clears every obligation. This is the number\n"
"// task 4 would act on, and it is deliberately printed next to the two counts it\n"
"// is derived from: a large qualifying-function count with a zero here means the\n"
"// analysis is right and the programs are not shaped the way it assumed.\n"
"int aif_bracketable_region_call_sites(void) {\n"
"    int n = 0;\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        if (call_edges[i].callee < 0) continue;\n"
"        if (enclosing_region(call_edges[i].scope) < 0) continue;\n"
"        if (aif_fn_bracket_blockers(call_edges[i].callee) == 0) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// Call sites whose callee this compilation can see. The opaque ones are not in\n"
"// the denominator because they are not in the numerator either -- a call nobody\n"
"// can summarise is never a candidate, so counting it would make the ratio read\n"
"// worse than the question it answers.\n"
"int aif_call_edge_count(void) {\n"
"    int n = 0;\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        if (call_edges[i].callee >= 0) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Call-site placement (SPEC 5.2.1.1)\n"
"//\n"
"// The section above answers \"may a caller's region reach this function\". This\n"
"// one decides it, per call site, and hands the resulting sites an arena.\n"
"//\n"
"// **There is no new codegen mechanism, and that is the shape of the thing.** An\n"
"// arena is on a dynamic stack: `region r { ... }` already emits arena_push at\n"
"// entry and arena_pop at every exit, so while a bracketed callee runs, its\n"
"// caller's arena is the top of that stack. All that was missing was for the\n"
"// *analysis* to say a callee's site belongs to it -- after which the two hooks\n"
"// that already exist do the work. ir_alloc_region takes a struct literal\n"
"// straight to arena_alloc, and ir_arena_hint_begin/end takes a producing runtime\n"
"// call (a string, a list) there. Both are keyed on aif_arena_at_node, which is\n"
"// this file's gate, so both follow from the clause below and neither needed a\n"
"// line of frontend change. An earlier design bracketed the Prismio call itself\n"
"// with the hint; that would have routed *every* runtime allocation in the extent\n"
"// to the arena, including ones the per-site gate declined.\n"
"//\n"
"// Three decisions, none of them re-derivable from the code alone:\n"
"//\n"
"// **Only a `region`-pinned arena, never a cost-model-chosen one.** Otherwise\n"
"// placement depends on bracketing depends on placement: enclosing_region reads\n"
"// scopes[].arena, which aif_place_arenas sets from arena_would_serve, which\n"
"// would then have to count bracketed sites as benefit. `region` sets the flag at\n"
"// parse time, before placement runs, so restricting to it cuts the loop -- and\n"
"// leaves arena_would_serve, the one clause-list copy deliberately *not* behind\n"
"// site_arena_scope, correct without change.\n"
"//\n"
"// **Obligation 3 is not readable from E.** \"The value the call returns does not\n"
"// outlive R\" is a property of the call site, and E cannot express it:\n"
"// AIF_CON_LIVE_IN's transfer sets E = Caller for every site whose fn is not the\n"
"// binding function, by construction, because a scope id in one function does not\n"
"// order against one in another. The fact wanted is the *caller-side* binding, and\n"
"// the points-to graph already holds it -- pt[k] for a VAR key names the function\n"
"// and var_scope names the declaring scope. So obligation 3 is asked of the keys\n"
"// and of the owner sites, not of E. bracket_site_bounded is that question.\n"
"//\n"
"// **Regime (a) is what makes one body serve one regime**, and it is checked by\n"
"// aif_fn_bracket_blockers above: the callee has exactly one call site, and every\n"
"// function the extent reaches is reached only from inside it. Together with the\n"
"// bracketed call being inside the region, that means the extent's bodies run at\n"
"// the region's arena depth on every path they can be entered from.\n"
"// ============================================================================\n"
"\n"
"// Key ids are dense and the interning table is a hash, so a reverse index is the\n"
"// only way to ask \"what kind of location is key k\". Rebuilt when key_count moves,\n"
"// which after the solve it does not.\n"
"static KeyNode** key_by_id;\n"
"static int key_by_id_len;\n"
"\n"
"static void key_index_build(void) {\n"
"    if (key_by_id && key_by_id_len == key_count) return;\n"
"    free(key_by_id);\n"
"    key_by_id = key_count > 0\n"
"        ? (KeyNode**)xcalloc((size_t)key_count, sizeof(KeyNode*), \"AIF key index\")\n"
"        : NULL;\n"
"    for (int b = 0; b < AIF_KEY_BUCKETS; b++) {\n"
"        for (KeyNode* n = key_buckets[b]; n; n = n->next) {\n"
"            if (n->id >= 0 && n->id < key_count) key_by_id[n->id] = n;\n"
"        }\n"
"    }\n"
"    key_by_id_len = key_count;\n"
"}\n"
"\n"
"// Which *objects* hold each site: the owner set of every field store and of every\n"
"// `retain_in` call. container_of already records the second, and E-STORE consumes\n"
"// the first without keeping it, so this reconstructs both from cons[] after the\n"
"// solve. It is the half of obligation 3 the keys cannot answer: a FIELD key is\n"
"// object-insensitive (INFERENCE 3.1), so `Wrapper.list` says nothing about which\n"
"// Wrapper -- and *which* is exactly the question, because a Wrapper the extent\n"
"// allocated dies with the extent and one the caller allocated does not.\n"
"static Bits* site_owner_sites;\n"
"static int site_owner_len;\n"
"static Bits owner_bits_val, owner_bits_own;\n"
"static IntVec owner_vec_val, owner_vec_own;\n"
"\n"
"static void site_owners_build(void) {\n"
"    if (site_owner_sites || site_count == 0) return;\n"
"    site_owner_sites = (Bits*)xcalloc((size_t)site_count, sizeof(Bits), \"AIF store owners\");\n"
"    site_owner_len = site_count;\n"
"\n"
"    for (int i = 0; i < con_count; i++) {\n"
"        Constraint* k = &cons[i];\n"
"        int vset, oset;\n"
"        if (k->kind == AIF_CON_STORE)          { vset = k->b; oset = k->c; }\n"
"        else if (k->kind == AIF_CON_RETAIN_IN) { vset = k->a; oset = k->b; }\n"
"        else continue;\n"
"        resolve(vset, &owner_bits_val);\n"
"        resolve(oset, &owner_bits_own);\n"
"        bits_to_vec(&owner_bits_val, &owner_vec_val);\n"
"        bits_to_vec(&owner_bits_own, &owner_vec_own);\n"
"        for (int a = 0; a < owner_vec_val.len; a++) {\n"
"            for (int b = 0; b < owner_vec_own.len; b++) {\n"
"                bits_set(&site_owner_sites[owner_vec_val.v[a]], owner_vec_own.v[b],\n"
"                         \"AIF store owners\");\n"
"            }\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"// The innermost `region` enclosing this scope, or -1. Distinct from\n"
"// enclosing_region, which also answers for an arena the cost model chose: only a\n"
"// pinned one may be bracketed into, and the reason is the circularity above.\n"
"static int enclosing_pinned_region(int scope) {\n"
"    for (int s = scope; s >= 0; s = scopes[s].parent) {\n"
"        if (scopes[s].arena && scopes[s].region_name >= 0) return s;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// Functions that cannot be running unless the region is.\n"
"//\n"
"// The bracketed extent is one of them, and it is not all of them. `submit(cmds)`\n"
"// in g2_region takes the list the bracketed `cull` returned; the walk binds a\n"
"// parameter to a local of the same name, so `cmds` lands in a VAR key belonging\n"
"// to a function that is in no extent at all. Rejecting that would reject the\n"
"// case the whole feature exists for, and accepting it unconditionally would\n"
"// accept a function that also runs somewhere the region does not.\n"
"//\n"
"// So the set is closed the same way regime (a) closes the extent: a function\n"
"// joins when **every** call site of it is inside the region -- either from a\n"
"// member (which is therefore itself only running inside the region) or from the\n"
"// bracketing caller at a scope at or below `r`. A function with no callers at all\n"
"// never joins; `main` is the one that matters there.\n"
"//\n"
"// The bracketing caller is excluded by construction. It is running when the\n"
"// region is *not* -- that is what the \"at or below r\" test on its bindings is\n"
"// for -- and admitting it would make every call it makes anywhere read as\n"
"// confined.\n"
"static void region_confined(int r, int caller_fn, const Bits* extent, Bits* out) {\n"
"    bits_clear(out);\n"
"    bits_or(out, extent, \"AIF region confinement\");\n"
"\n"
"    // Tri-state, and `signed char` rather than `char` on purpose: plain `char` is\n"
"    // unsigned on some ARM targets, and -1 would read back as 255. The logic\n"
"    // survives that by accident -- every promotion is guarded by `== 0` -- and an\n"
"    // invariant that holds by accident is one the next edit breaks silently.\n"
"    //   0  no call site seen yet     1  every call site so far is inside r\n"
"    //  -1  entered from outside; final, and never promoted back\n"
"    signed char* ok = (signed char*)xcalloc((size_t)(fn_count ? fn_count : 1), 1,\n"
"                                            \"AIF region confinement\");\n"
"    for (int pass = 0; pass <= fn_count; pass++) {\n"
"        for (int g = 0; g < fn_count; g++) ok[g] = 0;\n"
"        for (int i = 0; i < call_edge_count; i++) {\n"
"            CallEdge* e = &call_edges[i];\n"
"            if (e->callee < 0 || e->callee >= fn_count) continue;\n"
"            if (ok[e->callee] < 0) continue;\n"
"            if (bits_test(out, e->caller)) { if (ok[e->callee] == 0) ok[e->callee] = 1; continue; }\n"
"            if (e->caller == caller_fn && scope_lca(e->scope, r) == r) {\n"
"                if (ok[e->callee] == 0) ok[e->callee] = 1;\n"
"                continue;\n"
"            }\n"
"            ok[e->callee] = -1;     // entered from somewhere the region is not\n"
"        }\n"
"        int changed = 0;\n"
"        for (int g = 0; g < fn_count; g++) {\n"
"            if (ok[g] != 1 || g == caller_fn || bits_test(out, g)) continue;\n"
"            bits_set(out, g, \"AIF region confinement\");\n"
"            changed = 1;\n"
"        }\n"
"        if (!changed) break;\n"
"    }\n"
"    free(ok);\n"
"}\n"
"\n"
"// Obligation 3, for one site of a bracketed extent.\n"
"//\n"
"// Every location that may hold this value has to die no later than `r`. Three\n"
"// kinds of location can, and everything else fails:\n"
"//\n"
"//   * a binding, a parameter or a return in a function confined to the region --\n"
"//     those frames are gone before the region exits;\n"
"//   * a binding in the bracketing caller declared at or below `r`;\n"
"//   * a field or element of an object the extent itself allocated.\n"
"//\n"
"// A PARAM key is allowed and that is not a hole: the walk binds every parameter\n"
"// to a local of the same name, so the same value reaches a VAR key of the same\n"
"// function and that is the one this decides on. A RET key of the bracketing\n"
"// caller is `return f(...)` straight through the region, and it is the case an\n"
"// `E`-based test cannot see at all -- E is already Caller for every site in the\n"
"// extent, by construction.\n"
"static int bracket_trace;   // AIF_BRACKET_TRACE=1 -- why one site failed obligation 3\n"
"\n"
"static int bracket_reject(int s, const char* why, int detail) {\n"
"    if (bracket_trace) {\n"
"        fprintf(stderr, \"aif: site %d (%s %s:%d) not bounded: %s %d\\n\",\n"
"                s, aif_str(sites[s].type),\n"
"                sites[s].fn >= 0 ? aif_str(fns[sites[s].fn].name) : \"?\",\n"
"                sites[s].line, why, detail);\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"static int bracket_site_bounded(int s, const Bits* confined, const Bits* extent,\n"
"                                int r, int caller_fn) {\n"
"    for (int k = 0; k < pt_len; k++) {\n"
"        if (!bits_test(&pt[k], s)) continue;\n"
"        KeyNode* kn = key_by_id[k];\n"
"        if (kn == NULL) return bracket_reject(s, \"unknown key\", k);\n"
"        if (kn->kind == AIF_KEY_PARAM) continue;        // decided at the callee's own VAR key\n"
"        if (kn->kind == AIF_KEY_FIELD) continue;        // decided by the owner set below\n"
"        if (kn->kind == AIF_KEY_RET) {\n"
"            if (kn->a == caller_fn) return bracket_reject(s, \"returned past the region\", k);\n"
"            continue;\n"
"        }\n"
"        if (kn->kind != AIF_KEY_VAR) return bracket_reject(s, \"extern key\", k);\n"
"        int fn = kn->a;\n"
"        if (fn >= 0 && fn < fn_count && bits_test(confined, fn)) continue;\n"
"        if (fn != caller_fn) return bracket_reject(s, \"bound in\", fn);\n"
"        int declared = (k < var_scope_cap) ? var_scope[k] : -1;\n"
"        if (declared < 0) return bracket_reject(s, \"undeclared binding\", k);\n"
"        if (scope_lca(declared, r) != r) return bracket_reject(s, \"binding above r, scope\", declared);\n"
"    }\n"
"    // The owner has to be in the *extent*, not merely confined to the region.\n"
"    // An object a confined function allocated may still be returned out of the\n"
"    // region -- confinement bounds the activation, not the value -- whereas\n"
"    // every extent site is one this same loop is deciding, so requiring the\n"
"    // owner to be one of those makes the answer inductive rather than assumed.\n"
"    for (int o = 0; o < site_count; o++) {\n"
"        if (!bits_test(&site_owner_sites[s], o)) continue;\n"
"        int of = sites[o].fn;\n"
"        if (of < 0 || of >= fn_count || !bits_test(extent, of)) {\n"
"            return bracket_reject(s, \"owner site outside the extent\", o);\n"
"        }\n"
"    }\n"
"    // **The inverse, and it is a separate obligation rather than the same one\n"
"    // read backwards.** Above asks that nothing outside the extent *owns* this\n"
"    // value, which is about the value outliving the region. This asks that this\n"
"    // value owns nothing from outside, which is about the *teardown*: serving a\n"
"    // container from the arena deletes its teardown (aif_frees_at_scope_node\n"
"    // declines an arena site), and the teardown is what applies the element\n"
"    // disposition. If an element came from outside the extent it is an ordinary\n"
"    // heap object with a count, and the decrement that would have reclaimed it\n"
"    // goes with the teardown.\n"
"    //\n"
"    // Measured, on test_48_aif_shared_elements: `temp` in borrow_into_temp is a\n"
"    // List<Item> whose one element is borrowed out of `src`, allocated in the\n"
"    // caller. Bracketed without this clause it read 22 allocated / 21 released /\n"
"    // 1 leaked / 0 violations, and the program still printed PASS -- the leaked\n"
"    // Item is one nobody reads again, so the ledger is the only witness.\n"
"    //\n"
"    // Rejecting the *container* rather than the element is deliberate: the\n"
"    // element is not the site whose teardown was deleted, and an extent is\n"
"    // served whole or not at all.\n"
"    for (int o = 0; o < site_count; o++) {\n"
"        if (!bits_test(&site_owner_sites[o], s)) continue;\n"
"        int of = sites[o].fn;\n"
"        if (of < 0 || of >= fn_count || !bits_test(extent, of)) {\n"
"            return bracket_reject(s, \"owns a site outside the extent\", o);\n"
"        }\n"
"    }\n"
"    return 1;\n"
"}\n"
"\n"
"// site -> the region scope a bracketed call hands it, or -1.\n"
"static int* site_bracket;\n"
"static int bracket_place_ready;\n"
"static Bits bracket_place_extent, bracket_place_confined;\n"
"// The candidate pass gets its own pair. It runs inside aif_place_arenas, which\n"
"// is not on bracket_place's stack, but bracket_bytes_of and aif_bracket_served\n"
"// both reuse the buffers above -- and two passes sharing one answer-in-progress\n"
"// is the kind of aliasing that shows up as a placement that moved without a\n"
"// source change.\n"
"static Bits bracket_cand_extent, bracket_cand_confined;\n"
"\n"
"// One entry per bracketed call. SPEC 5.2.1.1 requires the manifest to record\n"
"// them, because regime (a) is fragile as a language guarantee -- adding a second\n"
"// call to a bracketed callee silently removes the placement -- and a loss that\n"
"// appears as a diff is one somebody notices.\n"
"typedef struct {\n"
"    int callee;     // function id\n"
"    int scope;      // the region scope that brackets it\n"
"    int call_scope; // the caller scope the call sits in, for the footprint estimate\n"
"    // M3.2c. Which statement of the region the call sits at. A bracketed site's\n"
"    // own `stmt` is a position in the *callee's* block and says nothing about\n"
"    // where the region has to open; the call does.\n"
"    int call_stmt;\n"
"} Bracket;\n"
"\n"
"static Bracket* brackets;\n"
"static int bracket_count, bracket_cap;\n"
"\n"
"// The obligations SPEC 5.2.1.1 puts on one bracketed call, asked of an arbitrary\n"
"// region scope `r` instead of the one enclosing_region happens to return.\n"
"//\n"
"// **It reads no arena flag**, and that is the property the whole of M3.1 rests\n"
"// on: aif_place_arenas can ask it about a scope it has not chosen yet, so the\n"
"// circularity the note above describes (\"placement depends on bracketing depends\n"
"// on placement\") is cut by making the dependency one-way. Placement asks a\n"
"// hypothetical question here, decides, and bracketing then answers the real one\n"
"// against the placement that resulted. Every input below is the call graph, the\n"
"// points-to graph or scope shape; none of them is scopes[].arena.\n"
"//\n"
"// `extent` and `confined` belong to the caller because bracket_place needs both\n"
"// again afterwards to stamp site_bracket, while the candidate pass needs only the\n"
"// extent -- and one shared static would have the two passes overwriting each\n"
"// other's answer mid-loop.\n"
"static int bracket_edge_ok(int r, int caller_fn, const CallEdge* e,\n"
"                           Bits* extent, Bits* confined) {\n"
"    if (aif_fn_bracket_blockers(e->callee) != 0) return 0;\n"
"\n"
"    bracket_reachable(e->callee, extent);\n"
"    region_confined(r, caller_fn, extent, confined);\n"
"\n"
"    // A call this compilation cannot summarise may be handed one of the\n"
"    // extent's values, and FFI 5.1's `borrow` default is an assumption\n"
"    // adequate for assigning a tier and **not** adequate for handing a callee\n"
"    // arena memory -- SPEC 5.2.1.1's last paragraph says so in as many words.\n"
"    // It is invisible to every check above: an undeclared extern's arguments\n"
"    // produce only a borrow edge, which raises A and leaves E and the\n"
"    // points-to graph alone. So it is asked of the call graph instead, over\n"
"    // every function that can be running while the region is.\n"
"    //\n"
"    // AIF_BR_B_OPAQUE already covers the extent. What this adds is the\n"
"    // caller's own region body, and the confined functions it reaches\n"
"    // through calls other than the bracketed one.\n"
"    for (int j = 0; j < call_edge_count; j++) {\n"
"        CallEdge* o = &call_edges[j];\n"
"        if (o->callee >= 0) continue;\n"
"        if (bits_test(confined, o->caller)) return 0;\n"
"        if (o->caller == caller_fn && scope_lca(o->scope, r) == r) return 0;\n"
"    }\n"
"\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        int f = sites[s].fn;\n"
"        if (f < 0 || f >= fn_count || !bits_test(extent, f)) continue;\n"
"        if (!bracket_site_bounded(s, confined, extent, r, caller_fn)) return 0;\n"
"    }\n"
"    return 1;\n"
"}\n"
"\n"
"static void bracket_invalidate(void) {\n"
"    free(site_bracket);\n"
"    site_bracket = NULL;\n"
"    bracket_count = 0;\n"
"    bracket_place_ready = 0;\n"
"}\n"
"\n"
"static void bracket_place(void) {\n"
"    if (bracket_place_ready) return;\n"
"    bracket_place_ready = 1;\n"
"    if (site_count == 0) return;\n"
"\n"
"    bracket_prepare();\n"
"    key_index_build();\n"
"    site_owners_build();\n"
"    bracket_trace = getenv(\"AIF_BRACKET_TRACE\") != NULL;\n"
"\n"
"    site_bracket = (int*)xcalloc((size_t)site_count, sizeof(int), \"AIF call-site placement\");\n"
"    for (int s = 0; s < site_count; s++) site_bracket[s] = -1;\n"
"\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        CallEdge* e = &call_edges[i];\n"
"        if (e->callee < 0 || e->callee >= fn_count) continue;\n"
"        // Placement has run by now, so an arena the cost model chose is as good a\n"
"        // region to bracket into as a written one -- that is M3.1, and the note\n"
"        // above enclosing_pinned_region explains why the answer used to be\n"
"        // \"never\". Before placement the only safe answer is still the pinned one:\n"
"        // the auto table is empty, and a \"no bracket\" cached from it would\n"
"        // outlive the placement that would have justified one. bracket_invalidate\n"
"        // is what stops that cache from surviving; this clause is what stops it\n"
"        // from being wrong in the window before it runs.\n"
"        int r = arenas_placed ? enclosing_region(e->scope)\n"
"                              : enclosing_pinned_region(e->scope);\n"
"        if (r < 0) continue;\n"
"\n"
"        // The bracketing caller. It is the region's owner and not e->caller,\n"
"        // because those are the same function -- e->scope is a scope of e->caller\n"
"        // and enclosing_region walked its own parents -- and naming it this\n"
"        // way is what the obligation is actually about.\n"
"        int caller_fn = scopes[r].owner;\n"
"\n"
"        if (!bracket_edge_ok(r, caller_fn, e,\n"
"                             &bracket_place_extent, &bracket_place_confined)) continue;\n"
"\n"
"        if (bracket_count == bracket_cap) {\n"
"            bracket_cap = bracket_cap ? bracket_cap * 2 : 16;\n"
"            brackets = (Bracket*)xrealloc(brackets, (size_t)bracket_cap * sizeof(Bracket),\n"
"                                          \"AIF call-site placement\");\n"
"        }\n"
"        brackets[bracket_count].callee = e->callee;\n"
"        brackets[bracket_count].scope = r;\n"
"        brackets[bracket_count].call_scope = e->scope;\n"
"        brackets[bracket_count].call_stmt = e->stmt;\n"
"        bracket_count++;\n"
"\n"
"        for (int s = 0; s < site_count; s++) {\n"
"            int f = sites[s].fn;\n"
"            if (f < 0 || f >= fn_count || !bits_test(&bracket_place_extent, f)) continue;\n"
"            // Regime (a) means a function is in at most one extent -- SHARED_BODY\n"
"            // rejects a body reachable from outside the one that would be\n"
"            // bracketed. Asserted rather than assumed: two answers for one site\n"
"            // would be two arenas, and the wrong one is a use-after-free.\n"
"            if (site_bracket[s] >= 0 && site_bracket[s] != r) { site_bracket[s] = -1; continue; }\n"
"            site_bracket[s] = r;\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"static int site_bracket_region(int id) {\n"
"    if (id < 0 || id >= site_count) return -1;\n"
"    bracket_place();\n"
"    return site_bracket ? site_bracket[id] : -1;\n"
"}\n"
"\n"
"int aif_bracket_count(void) { bracket_place(); return bracket_count; }\n"
"\n"
"int aif_bracket_callee(int i) {\n"
"    bracket_place();\n"
"    return (i < 0 || i >= bracket_count) ? -1 : brackets[i].callee;\n"
"}\n"
"\n"
"int aif_bracket_scope(int i) {\n"
"    bracket_place();\n"
"    return (i < 0 || i >= bracket_count) ? -1 : brackets[i].scope;\n"
"}\n"
"\n"
"// How many sites this bracket actually places. A bracket that reaches nothing is\n"
"// still recorded -- it is a real placement decision and a later edit can make it\n"
"// serve something -- but the manifest has to be able to say so, for the same\n"
"// reason `region` warns when it serves nothing.\n"
"int aif_bracket_served(int i) {\n"
"    bracket_place();\n"
"    if (i < 0 || i >= bracket_count) return 0;\n"
"    // Per *extent*, not per scope. Two brackets into one region is the ordinary\n"
"    // case -- g2_region's `cull` and `submit` are both in `frame_arena` -- and\n"
"    // counting by scope would report each of them as serving the other's sites,\n"
"    // which is how a manifest starts describing a build that did not happen.\n"
"    bracket_reachable(brackets[i].callee, &bracket_place_extent);\n"
"    int n = 0;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        int f = sites[s].fn;\n"
"        if (f < 0 || f >= fn_count || !bits_test(&bracket_place_extent, f)) continue;\n"
"        if (site_arena_scope(s) >= 0) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"// 1 when this site is served by a bracketed call rather than by a `region` in its\n"
"// own function. `--why` needs the two apart: the second is what the programmer\n"
"// wrote and the first is what the compiler decided on their behalf.\n"
"int aif_site_is_bracketed(int id) {\n"
"    return site_bracket_region(id) >= 0 && site_arena_scope(id) >= 0;\n"
"}\n"
"\n"
"// ----------------------------------------------------------------------------\n"
"// What a bracketed call adds to its region's footprint (REQUIREMENTS 19)\n"
"//\n"
"// `arena_would_serve` deliberately does not count these, and must not: it is the\n"
"// input to aif_place_arenas, so counting a bracketed site there would make\n"
"// placement depend on bracketing depend on placement. But the high-water\n"
"// estimate and the `region name pin(N)` gate run *after* placement, and the\n"
"// question they ask is different -- not \"would an arena here be worth it\" but\n"
"// \"how much will this arena hold\". Leaving the bracketed sites out of that\n"
"// answer is a budget gate passing on memory the binary really does bump-allocate,\n"
"// which is the wrong direction for a fixed-budget target to be wrong in.\n"
"//\n"
"// The weight is a product of two estimates and neither is new. How many times\n"
"// the site runs per entry of its own function is its loop depth there; how many\n"
"// times the call runs per entry of the region is the call site's loop depth\n"
"// relative to `r`. Both use AIF_LOOP_ITERS, so this cannot disagree with\n"
"// allocs_in(s) about what a loop multiplies -- and both are static, like every\n"
"// other input to this estimate. `weight_of` cannot be used for the first half:\n"
"// loop_depth is counted *within* a function, so a difference taken across two of\n"
"// them is not a number.\n"
"// ----------------------------------------------------------------------------\n"
"\n"
"static long weight_in_own_fn(int site_scope) {\n"
"    if (site_scope < 0 || site_scope >= scope_count) return 1;\n"
"    int loops = scopes[site_scope].loop_depth;\n"
"    if (loops > 6) loops = 6;               // capped as weight_of caps it\n"
"    long w = 1;\n"
"    for (int i = 0; i < loops; i++) w *= AIF_LOOP_ITERS;\n"
"    return w;\n"
"}\n"
"\n"
"// SPEC 5.2.1.1 as an input to LAYOUT 7.1's cost model: what a bracketed call\n"
"// sitting in `cand` would serve, had `cand` an arena.\n"
"//\n"
"// The cross-function mirror of arena_would_serve, and it has to be a separate\n"
"// function rather than a clause in that one. arena_would_serve asks\n"
"// `is_ancestor_or_self(cand, s->scope)`, and a site in a callee fails it however\n"
"// its escape is spelled, because scopes[] is a lexical tree rooted per function.\n"
"// No per-site clause can cross that; only the call graph can, which is what the\n"
"// bracket obligations are asked of.\n"
"//\n"
"// **The per-site gate here is the bracketed one, not the lexical one** -- tier in\n"
"// {T1,T2} and not explicitly dropped, exactly the two clauses\n"
"// site_arena_scope_full applies once it has a bracket region. Applying the\n"
"// lexical list instead would count in_container and is_list against these sites,\n"
"// and those are precisely the clauses bracketing replaces: a bracketed value is\n"
"// reclaimed with the region, so the container that holds it never hands its\n"
"// pointer to the deallocator. Keeping this in step with that gate is the whole\n"
"// correctness argument, so it reads those two conditions and no others.\n"
"//\n"
"// Weighting matches bracket_bytes_of and for the reason given above it: loop\n"
"// depth is counted within a function, so the site's own depth and the call's\n"
"// depth relative to `r` are two separate factors and their product is the count.\n"
"static long bracket_candidate_serves(int cand, long* held, long* live) {\n"
"    if (cand < 0 || cand >= scope_count || site_count == 0) return 0;\n"
"    int caller_fn = scopes[cand].owner;\n"
"    if (caller_fn < 0 || caller_fn >= fn_count) return 0;\n"
"\n"
"    bracket_prepare();\n"
"    key_index_build();\n"
"    site_owners_build();\n"
"\n"
"    long served = 0;\n"
"    for (int i = 0; i < call_edge_count; i++) {\n"
"        CallEdge* e = &call_edges[i];\n"
"        if (e->callee < 0 || e->callee >= fn_count) continue;\n"
"        // The call has to sit in this scope and belong to the function that owns\n"
"        // it -- the same two facts enclosing_region would establish, asked\n"
"        // directly because `cand` has no arena flag set yet for it to find.\n"
"        if (e->caller != caller_fn) continue;\n"
"        if (scope_lca(e->scope, cand) != cand) continue;\n"
"        // Innermost-first, as the lexical loop above: an arena already placed\n"
"        // between the call and `cand` brackets it first, and counting its traffic\n"
"        // here too would justify `cand` with allocations it will never see. This\n"
"        // is the automatic-placement form of the inert `region`.\n"
"        int claimed = 0;\n"
"        for (int p = e->scope; p >= 0 && p != cand; p = scopes[p].parent) {\n"
"            if (scopes[p].arena) { claimed = 1; break; }\n"
"        }\n"
"        if (claimed) continue;\n"
"        if (!bracket_edge_ok(cand, caller_fn, e,\n"
"                             &bracket_cand_extent, &bracket_cand_confined)) continue;\n"
"\n"
"        long callw = weight_of(e->scope, cand);\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            int f = sites[k].fn;\n"
"            if (f < 0 || f >= fn_count || !bits_test(&bracket_cand_extent, f)) continue;\n"
"            int tier = aif_tier_of(k);\n"
"            if (tier != AIF_T1 && tier != AIF_T2) continue;\n"
"            if (sites[k].no_stack) continue;\n"
"            long w = weight_in_own_fn(sites[k].scope) * callw;\n"
"            served += w;\n"
"            if (held) *held += (long)sites[k].bytes * w;\n"
"            if (live) *live += (long)sites[k].bytes;\n"
"        }\n"
"    }\n"
"    return served;\n"
"}\n"
"\n"
"// M3.2c. The statement range an arena at `scope` actually has to cover: from the\n"
"// first statement that puts something in it to the last statement that still\n"
"// reads something it holds. Returns 0 when the range cannot be narrowed, and\n"
"// **every uncertainty returns 0 rather than a guess** -- a range that is too wide\n"
"// is the arena we already emit, and a range that is too narrow frees memory the\n"
"// program is still using.\n"
"//\n"
"// Positions are taken in `scope`'s own numbering. For a lexically served site\n"
"// that is the site's own `stmt`; for a bracketed one it is the *call's*\n"
"// statement, because the site's own position is an index into the callee's block\n"
"// and says nothing about where this region opens.\n"
"static int arena_stmt_range(int scope, int* first, int* last) {\n"
"    if (scope < 0 || scope >= scope_count || !scopes[scope].arena) return 0;\n"
"    bracket_place();\n"
"\n"
"    int lo = -1, hi = -1;\n"
"    int any = 0;\n"
"\n"
"    for (int k = 0; k < site_count; k++) {\n"
"        if (site_arena_scope(k) != scope) continue;\n"
"        any = 1;\n"
"        int at;\n"
"        if (sites[k].scope == scope) {\n"
"            at = sites[k].stmt;                 // lexical: the site is a statement here\n"
"        } else {\n"
"            at = -1;                            // bracketed: ask the call below\n"
"            for (int b = 0; b < bracket_count; b++) {\n"
"                if (brackets[b].scope != scope) continue;\n"
"                if (brackets[b].call_scope != scope) continue;\n"
"                bracket_reachable(brackets[b].callee, &bracket_cand_extent);\n"
"                if (!bits_test(&bracket_cand_extent, sites[k].fn)) continue;\n"
"                if (brackets[b].call_stmt < 0) return 0;\n"
"                if (at < 0 || brackets[b].call_stmt < at) at = brackets[b].call_stmt;\n"
"            }\n"
"        }\n"
"        if (at < 0) return 0;                   // unpositioned: cannot narrow\n"
"        if (lo < 0 || at < lo) lo = at;\n"
"        if (at > hi) hi = at;\n"
"    }\n"
"    if (!any || lo < 0) return 0;\n"
"\n"
"    // The end is the last *use*, not the last allocation, and it is asked of the\n"
"    // keys because a value outlives the statement that made it. A key declared\n"
"    // in a nested block is declined outright: key_last_stmt is recorded against\n"
"    // that block's numbering, and there is no way from here to say which\n"
"    // statement of `scope` contains it.\n"
"    key_index_build();\n"
"    for (int k = 0; k < key_count; k++) {\n"
"        KeyNode* kn = key_by_id[k];\n"
"        if (kn == NULL || kn->kind != AIF_KEY_VAR) continue;\n"
"        int holds = 0;\n"
"        for (int s = 0; s < site_count && !holds; s++) {\n"
"            if (!bits_test(&pt[k], s)) continue;\n"
"            if (site_arena_scope(s) == scope) holds = 1;\n"
"        }\n"
"        if (!holds) continue;\n"
"        int d = (k < var_scope_cap) ? var_scope[k] : -1;\n"
"        if (d < 0) return 0;                    // no declaration on record\n"
"        // A key belonging to a *different* function needs no position here. It\n"
"        // lives in the bracketed extent, and region_confined already proved every\n"
"        // one of those activations is gone before the region exits -- that is the\n"
"        // whole content of obligation 3. Asking it for a statement index of this\n"
"        // block would be asking the wrong question, and declining on it would\n"
"        // decline every bracketed region, which is all of the interesting ones.\n"
"        if (scopes[d].owner != scopes[scope].owner) continue;\n"
"        if (d != scope) return 0;               // same function, deeper: position unknown\n"
"        int lu = aif_key_last_stmt(k);\n"
"        if (lu < 0) return 0;                   // no use on record: do not narrow\n"
"        if (lu > hi) hi = lu;\n"
"    }\n"
"\n"
"    if (hi < lo) return 0;\n"
"    if (first) *first = lo;\n"
"    if (last) *last = hi;\n"
"    return 1;\n"
"}\n"
"\n"
"// `unsized` counts sites whose size the frontend never computed -- a string or a\n"
"// list, whose length is a run-time value -- rather than guessing at one.\n"
"static long bracket_bytes_of(int scope, int* unsized) {\n"
"    bracket_place();\n"
"    long total = 0;\n"
"    for (int i = 0; i < bracket_count; i++) {\n"
"        if (brackets[i].scope != scope) continue;\n"
"        long callw = weight_of(brackets[i].call_scope, scope);\n"
"        bracket_reachable(brackets[i].callee, &bracket_place_extent);\n"
"        for (int k = 0; k < site_count; k++) {\n"
"            int f = sites[k].fn;\n"
"            if (f < 0 || f >= fn_count || !bits_test(&bracket_place_extent, f)) continue;\n"
"            if (site_arena_scope(k) != scope) continue;\n"
"            if (sites[k].bytes == 0) { if (unsized) (*unsized)++; continue; }\n"
"            total += (long)sites[k].bytes * weight_in_own_fn(sites[k].scope) * callw;\n"
"        }\n"
"    }\n"
"    return total;\n"
"}\n"
"\n"
"static int site_in_released_field(int s);\n"
"\n"
"int aif_frees_at_scope_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    // An arena releases in bulk when its region exits. Freeing one of its\n"
"    // objects individually would hand a pointer into the middle of a chunk to\n"
"    // the deallocator -- so a value the arena serves is never on a drop list.\n"
"    if (aif_arena_at_node(node)) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        Site* s = &sites[n->site];\n"
"        if (s->E != s->scope) return 0;\n"
"        if (!site_is_move_only(s)) return 0;\n"
"        // An array literal lowers to ir_array_alloca -- frame storage, like T0\n"
"        // below, so there is nothing here for a deallocator to take. This is the\n"
"        // one place the language and site_is_move_only disagree: affine\n"
"        // collections make arrays move-only in the model (and in the oracle), and\n"
"        // types.psm deliberately does not, because an affine value with no\n"
"        // allocation behind it buys the aliasing rule and costs a `drop(arr)`\n"
"        // that frees a stack pointer.\n"
"        if (s->kind == AIF_K_ARRAY) return 0;\n"
"        // An explicit `drop` already frees it; a scope drop as well is a double\n"
"        // free. Same flag that bars T0, and for the same reason -- it records\n"
"        // that the source, not the model, decides when this value dies.\n"
"        if (s->no_stack) return 0;\n"
"        // A container took ownership, so the container's teardown is the release\n"
"        // point and this binding is not one. Reachable only when the two share a\n"
"        // scope -- otherwise the container's escape already lifted E past it and\n"
"        // the test above declined -- and in that case the element would otherwise\n"
"        // be freed here *and* at the teardown, newest binding first.\n"
"        if (s->in_container) return 0;\n"
"        // The same rule one level out: a struct field the type now releases is\n"
"        // this value's release point, so its binding is not. See\n"
"        // site_in_released_field for why the E test above does not already cover\n"
"        // it.\n"
"        if (site_in_released_field(n->site)) return 0;\n"
"        return aif_tier_of(n->site) == AIF_T0 ? 0 : 1;   // T0 storage is the frame\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Ownership inside containers\n"
"//\n"
"// A container teardown is a release point, and the container has to be told what\n"
"// its elements are: probing a pointer's header to find out would be reading\n"
"// memory in front of a pointer this compilation did not allocate, which is the\n"
"// same unsound move that bars refcounting an OPAQUE site.\n"
"//\n"
"// So the disposition is decided here, once, and codegen stamps it on the\n"
"// container at construction. It is a property of the *container site*, not of the\n"
"// element, because that is the only granularity a teardown loop has: one call per\n"
"// element, all elements alike.\n"
"//\n"
"// Which means a mixed container has no answer. If one element wants a free and\n"
"// another wants a decrement, neither is right for both and the honest outcome is\n"
"// to reclaim nothing -- today's behaviour, and a leak rather than a wrong free.\n"
"// The same goes for anything the deallocator cannot take: an array element is\n"
"// frame storage and an opaque one was never ours.\n"
"// ============================================================================\n"
"\n"
"#define AIF_ELEM_NONE   0\n"
"#define AIF_ELEM_OBJECT 1   // the deallocator\n"
"#define AIF_ELEM_LIST   2   // list_release, which is two allocations\n"
"#define AIF_ELEM_RC     3   // Level 5: a decrement, and the last holder frees\n"
"#define AIF_ELEM_TYPED  4   // the type's generated release -- struct-field ownership\n"
"#define AIF_ELEM_CYCLE  5   // T4b: a decrement, and a non-zero result buffers a candidate\n"
"// REQUIREMENTS 15. The two above with an atomic decrement, for T4a. Two\n"
"// constants and not one plus a flag: SPEC 3 requires an implementation to\n"
"// distinguish the sub-classes and forbids charging collector participation to a\n"
"// T4a value that is provably acyclic, which is exactly what separates these.\n"
"#define AIF_ELEM_RC_ATOMIC    6\n"
"#define AIF_ELEM_CYCLE_ATOMIC 7\n"
"\n"
"// AIF Level 5. Whether this site is allocated with a reference count.\n"
"//\n"
"// Three exclusions, and each is a different kind of \"we did not allocate this\":\n"
"//\n"
"//   * OPAQUE -- the pointer came back from a function this compilation cannot\n"
"//     see. There is no header in front of it. This is the exclusion that matters,\n"
"//     because it covers all 37 of the compiler's own T3 sites.\n"
"//   * STRING and LIST -- allocated inside lang_runtime.c, past the seam, so the\n"
"//     site cannot choose its own allocator. The same asymmetry Level 4 hit with\n"
"//     the arena; a hint would work here too and is not this level.\n"
"//   * ARRAY -- frame storage.\n"
"//\n"
"// And a positive requirement: the site must be in a container. A count is a count\n"
"// of container edges, so a value in none of them would be born at zero, never\n"
"// retained, never released, and pay 16 bytes of header for nothing.\n"
"static int site_is_rc(const Site* s, int tier) {\n"
"    // T4a counts too -- SPEC 3's cost table gives it \"atomic count word\", which\n"
"    // is the same header and the same container edges as T3's, differing only\n"
"    // in the instruction that touches it. Which instruction that is, is decided\n"
"    // where the decrement is emitted and not here.\n"
"    if (tier != AIF_T3 && tier != AIF_T4A) return 0;\n"
"    if (s->kind != AIF_K_STRUCT) return 0;\n"
"    if (s->no_stack) return 0;              // an explicit drop needs a plain free\n"
"    return s->in_container;\n"
"}\n"
"\n"
"// AIF T4b. The same shape one tier up, and the exclusions are the same: the\n"
"// object must be one this compilation allocated, so there is a header in front\n"
"// of it, and it must be in a container, because a container edge is the only\n"
"// count this compiler both increments and decrements.\n"
"//\n"
"// The extra requirement over T3 is structural rather than a policy choice: a\n"
"// T4b site is one whose type is *not* acyclic (SPEC 4.2's C = MaybeCyclic), so\n"
"// there is an SCC to walk. Without one there are no cyclic children and the\n"
"// collector would buffer candidates it can never reclaim.\n"
"static int site_is_cyclic(const Site* s, int tier) {\n"
"    // SPEC 3: \"A value meeting both conditions pays both. An implementation\n"
"    // SHALL distinguish the sub-classes; it SHALL NOT charge atomics to a T4b\n"
"    // value that is thread-local, nor collector participation to a T4a value\n"
"    // that is provably acyclic.\"\n"
"    //\n"
"    // Both halves of that last sentence are enforced right here. T4b never\n"
"    // reaches the atomic path because site_is_rc's tier test excludes it; and a\n"
"    // T4a value that is provably acyclic is turned away by the type_acyclic\n"
"    // test below, which is the *same* test that has always excluded acyclic\n"
"    // types -- so admitting T4a costs no new rule, only a wider tier test.\n"
"    if (tier != AIF_T4B && tier != AIF_T4A) return 0;\n"
"    if (s->kind != AIF_K_STRUCT) return 0;\n"
"    if (s->no_stack) return 0;\n"
"    if (s->type_acyclic) return 0;\n"
"    return s->in_container;\n"
"}\n"
"\n"
"int aif_site_is_cyclic(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return site_is_cyclic(&sites[id], aif_tier_of(id));\n"
"}\n"
"\n"
"int aif_cycle_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        return site_is_cyclic(&sites[n->site], aif_tier_of(n->site));\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"static int type_releases_of(int nominal);\n"
"\n"
"static int elem_disposition_of(int id, int tier) {\n"
"    if (id < 0 || id >= site_count) return AIF_ELEM_NONE;\n"
"    const Site* s = &sites[id];\n"
"    if (s->kind == AIF_K_ARRAY || s->kind == AIF_K_OPAQUE) return AIF_ELEM_NONE;\n"
"    // SPEC 5.2.1.1's disposition half. An arena reclaims in bulk when its region\n"
"    // exits, so a value it serves is never released individually: handing a\n"
"    // pointer into the middle of a chunk to the deallocator is heap corruption,\n"
"    // and for a container element it is that once per element.\n"
"    //\n"
"    // **Disjoint from every clause below today**, because the placement gate\n"
"    // rejects `in_container` and `is_list`, so no arena-served site is ever an\n"
"    // element or a released field. It is here first, and deliberately: call-site\n"
"    // placement removes exactly those two rejections, and a disposition that\n"
"    // learned about arenas in the same change as placement would be a\n"
"    // use-after-free with nothing to compare it against. Verified inert on\n"
"    // landing -- byte-identical IR for every program in tests/, aif/corpus/ and\n"
"    // aif/evidence/.\n"
"    //\n"
"    // One clause rather than one per consumer, and that is the load-bearing part.\n"
"    // aif_elem_owner_at_node (a container's element release), field_release_of\n"
"    // (a struct's generated release), type_is_reclaimed and\n"
"    // aif_owns_call_result_at_node all read this function. The 2026-08-14 session\n"
"    // found the arena gate wearing four copies, one of which had drifted and was\n"
"    // placing arenas that served nothing; a second copy of *this* clause would be\n"
"    // the same defect with a use-after-free behind it instead of a wasted push.\n"
"    if (site_arena_scope(id) >= 0) return AIF_ELEM_NONE;\n"
"    // SPEC 3, in one place: \"A value meeting both conditions pays both. An\n"
"    // implementation SHALL distinguish the sub-classes; it SHALL NOT charge\n"
"    // atomics to a T4b value that is thread-local, nor collector participation\n"
"    // to a T4a value that is provably acyclic.\"\n"
"    //\n"
"    // The four outcomes below are that sentence. T4a with an acyclic type gets\n"
"    // the atomic count and no collector; T4a whose type lies in an SCC gets\n"
"    // both; T4b gets the collector and a *plain* decrement, because a\n"
"    // thread-local cycle is still thread-local; T3 gets neither.\n"
"    //\n"
"    // Checked before the T3 clause rather than folded into it, because\n"
"    // site_is_rc now admits T4a as well -- an atomic value must not be able to\n"
"    // fall through to the non-atomic disposition on any path.\n"
"    if (tier == AIF_T4A) {\n"
"        if (site_is_cyclic(s, tier)) return AIF_ELEM_CYCLE_ATOMIC;\n"
"        if (site_is_rc(s, tier)) return AIF_ELEM_RC_ATOMIC;\n"
"        return AIF_ELEM_NONE;\n"
"    }\n"
"    if (site_is_rc(s, tier)) return AIF_ELEM_RC;\n"
"    if (site_is_cyclic(s, tier)) return AIF_ELEM_CYCLE;\n"
"    // T0 is the frame, and a T3 or T4b site the two predicates above declined has\n"
"    // no header to decrement.\n"
"    if (tier != AIF_T1 && tier != AIF_T2) return AIF_ELEM_NONE;\n"
"    if (s->no_stack) return AIF_ELEM_NONE;      // an explicit drop already frees it\n"
"    if (s->kind == AIF_K_LIST) return AIF_ELEM_LIST;\n"
"    // Struct-field ownership. Handing a struct with owned fields to the plain\n"
"    // deallocator frees the object and leaks everything it owns -- which is g3's\n"
"    // entire residue: 1365 Nodes, three owned struct fields each, 4095 leaks.\n"
"    if (s->kind == AIF_K_STRUCT && type_releases_of(nominal_find_id(s->type))) {\n"
"        return AIF_ELEM_TYPED;\n"
"    }\n"
"    return AIF_ELEM_OBJECT;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Struct-field ownership\n"
"//\n"
"// The sibling of container ownership, and deliberately not the same mechanism.\n"
"// A container is *told* its element disposition at construction because its\n"
"// contents are dynamic -- the runtime is the only thing that knows how many\n"
"// elements there are or when the last one arrived. A struct's fields are known\n"
"// statically, right here in the nominal registry, so the answer is a **function\n"
"// generated per type** with one release per owned field emitted in line.\n"
"//\n"
"// Two consequences follow from that difference, and both are the point:\n"
"//\n"
"//   * **The disposition is per field, not per type.** A container reclaims\n"
"//     nothing when its elements disagree, because a teardown loop makes one call\n"
"//     for all of them. A generated function has a separate statement per field,\n"
"//     so `World` -- five owned `List`s and an `Int` -- releases the five and\n"
"//     steps over the Int. A single answer for the whole type would have to be\n"
"//     NONE for all six, which is exactly the leak this closes.\n"
"//   * **No runtime word.** The container needs `elem_own` on the object; a struct\n"
"//     needs nothing, because the type is what selects the function.\n"
"//\n"
"// The fact this reads is not new. A struct literal's field initialiser has been\n"
"// a STORE into `key_field(type, field)` since Level 0 -- that is what carries\n"
"// E-STORE and A-STORE -- so the sites that may reach a field are exactly\n"
"// `pt[key_field(type, field)]`. This adds a query, not a rule.\n"
"// ============================================================================\n"
"\n"
"// Lookup without interning. A query after the solve must not add a key: pt is\n"
"// sized to key_count at solve start, so a fresh id would index past it, and a\n"
"// table that grows while it is being read is a table nobody can reason about.\n"
"static int key_find(int kind, int a, int b) {\n"
"    unsigned h = (unsigned)kind * 2654435761u\n"
"               ^ (unsigned)a * 40503u\n"
"               ^ (unsigned)b * 2246822519u;\n"
"    for (KeyNode* n = key_buckets[h & (AIF_KEY_BUCKETS - 1)]; n; n = n->next) {\n"
"        if (n->kind == kind && n->a == a && n->b == b) return n->id;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"// What release `type.field` needs, or NONE.\n"
"//\n"
"// Agreement over the field's points-to set, for the same reason the container\n"
"// case agrees over its elements: one field holds one pointer, but the analysis\n"
"// may not be able to say which site produced it, and a field that is a `List` on\n"
"// one path and an opaque on another has no single correct release.\n"
"// `List<Token>` -> `List`, on interned ids. The frontend's aif_base_type exists\n"
"// for the same reason field keys are object-insensitive: `list_new()` types as\n"
"// `List<Invalid>` and an annotated field does not, so a raw comparison of the\n"
"// two spellings would reject every container field.\n"
"static int base_type_id(int name) {\n"
"    const char* s = aif_str(name);\n"
"    const char* lt = strchr(s, '<');\n"
"    if (!lt) return name;\n"
"    char buf[128];\n"
"    size_t n = (size_t)(lt - s);\n"
"    if (n >= sizeof(buf)) n = sizeof(buf) - 1;\n"
"    memcpy(buf, s, n);\n"
"    buf[n] = '\\0';\n"
"    return aif_intern(buf);\n"
"}\n"
"\n"
"// Whether releasing this field would re-enter the type that owns it.\n"
"//\n"
"// `struct Node { parent: Node?, children: List<Node> }` is the shape:\n"
"// __aif_release_Node(n) releasing n.parent releases *its* parent, and so on\n"
"// until the stack gives out -- or, worse, around a cycle and back to an object\n"
"// already freed. A statically generated release is for the acyclic part of the\n"
"// type graph by construction, and a cycle is what SPEC's T4b collector is for.\n"
"//\n"
"// **Only reachable once REQUIREMENTS 4 exists.** Before `none` a parent\n"
"// back-reference did not typecheck, which is precisely why CYCLES had nothing to\n"
"// run against.\n"
"static int field_closes_cycle(int owner, int declared_type) {\n"
"    if (owner < 0 || declared_type < 0) return 0;\n"
"    int fid = nominal_find_id(declared_type);\n"
"    if (fid < 0) return 0;\n"
"    if (fid == owner) return 1;\n"
"    return bits_test(&nominals[fid].reaches, owner);\n"
"}\n"
"\n"
"static int field_release_of(int type_name, int field_name, int declared_type) {\n"
"    int key = key_find(AIF_KEY_FIELD, type_name, field_name);\n"
"    if (key < 0 || key >= pt_len) return AIF_ELEM_NONE;\n"
"    if (field_closes_cycle(nominal_find_id(type_name), declared_type)) return AIF_ELEM_NONE;\n"
"\n"
"    int agreed = AIF_ELEM_NONE;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&pt[key], s)) continue;\n"
"        // **The slot has to hold what it says it holds.** This compiler puns an\n"
"        // ASTNode pointer as `String` and walks node chains through it, so a\n"
"        // `String` field can receive struct sites -- and a release chosen from\n"
"        // the sites alone emits `__aif_release_String`, which is not a function.\n"
"        // That is not a naming bug to paper over: the language and the analysis\n"
"        // genuinely disagree about what is in the slot, and the honest answer is\n"
"        // to reclaim nothing. Same discipline as arrays in\n"
"        // aif_frees_at_scope_node, which decline by kind for the same reason.\n"
"        if (declared_type >= 0 && base_type_id(sites[s].type) != declared_type) {\n"
"            return AIF_ELEM_NONE;\n"
"        }\n"
"        int d = elem_disposition_of(s, aif_tier_of(s));\n"
"        if (d == AIF_ELEM_NONE) return AIF_ELEM_NONE;\n"
"        if (agreed == AIF_ELEM_NONE) agreed = d;\n"
"        else if (agreed != d) return AIF_ELEM_NONE;\n"
"    }\n"
"    return agreed;\n"
"}\n"
"\n"
"// The declared type of a struct's i-th field, base-named, or -1.\n"
"static int field_declared_type(const Nominal* t, int i) {\n"
"    return t->field_type ? t->field_type[i] : -1;\n"
"}\n"
"\n"
"// -1 not computed, -2 in progress.\n"
"//\n"
"// The in-progress marker is what a self-referential type needs. `struct Node {\n"
"// child: Node }` would otherwise have to know whether Node releases in order to\n"
"// decide whether Node releases. Read as \"does not\", which leaks rather than\n"
"// double-frees -- and a type that reaches itself is C-MAYBE anyway, so it is the\n"
"// cycle collector's problem and not this one's.\n"
"static int* type_releases;\n"
"static int type_releases_cap;\n"
"\n"
"static int type_releases_of(int nominal) {\n"
"    if (nominal < 0 || nominal >= nominal_count) return 0;\n"
"    if (nominals[nominal].is_enum) return 0;\n"
"\n"
"    // **The release half of the hot/cold split, and it is one clause.**\n"
"    //\n"
"    // A split object is two allocations. The type-blind deallocator behind\n"
"    // ir_free_object frees one block and cannot name the type, so it would leak\n"
"    // the cold half of every split object it ever saw. Forcing this true routes\n"
"    // every drop, every container element and every owned field of a split type\n"
"    // through the generated `__aif_release_T` instead -- which *does* know the\n"
"    // type, and which frees the cold block before the base (ir_free_cold).\n"
"    //\n"
"    // This is the \"generated release even when the type owns no fields\" the\n"
"    // original brief names. It is safe to force because the generated body is the\n"
"    // same code either way: it emits one release per field whose disposition is\n"
"    // not NONE, and a type that owned nothing before still owns nothing now, so\n"
"    // all the forcing adds is the wrapper and the cold free.\n"
"    //\n"
"    // Not cached, and deliberately ahead of the cache: the cache is keyed on the\n"
"    // field walk alone, and a split decision that arrived after a cached 0 would\n"
"    // be a leak nothing reports.\n"
"    if (nominals[nominal].hot_count > 0) return 1;\n"
"\n"
"    if (nominal >= type_releases_cap) {\n"
"        int grow = type_releases_cap ? type_releases_cap * 2 : 64;\n"
"        if (grow <= nominal) grow = nominal + 1;\n"
"        type_releases = (int*)xrealloc(type_releases, (size_t)grow * sizeof(int),\n"
"                                       \"AIF type release cache\");\n"
"        for (int i = type_releases_cap; i < grow; i++) type_releases[i] = -1;\n"
"        type_releases_cap = grow;\n"
"    }\n"
"    if (type_releases[nominal] == -2) return 0;\n"
"    if (type_releases[nominal] >= 0) return type_releases[nominal];\n"
"\n"
"    type_releases[nominal] = -2;\n"
"    Nominal* t = &nominals[nominal];\n"
"    int any = 0;\n"
"    for (int i = 0; i < t->nfields && !any; i++) {\n"
"        if (field_release_of(t->name, t->field_name[i], field_declared_type(t, i))\n"
"            != AIF_ELEM_NONE) any = 1;\n"
"    }\n"
"    type_releases[nominal] = any;\n"
"    return any;\n"
"}\n"
"\n"
"int aif_type_releases(const char* name) {\n"
"    return type_releases_of(nominal_find(name));\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// CYCLES 4 -- the cyclic-edge restriction\n"
"//\n"
"// Every edge of a value-level reference cycle connects two types in one SCC of\n"
"// the type reference graph: an edge x -> y arises from a field of type(x) that\n"
"// can hold a type(y), so the types of a value cycle form a directed cycle in the\n"
"// type graph and therefore lie in one SCC.\n"
"//\n"
"// So a collector that traverses only fields whose type is in the owner's SCC\n"
"// still finds every cycle -- and never *leaves* the skeleton. A Node with two\n"
"// child pointers and six fields of tokens, strings and spans is walked through\n"
"// two edges rather than eight, and the collector never descends into the string\n"
"// graph hanging off it. Those subgraphs are usually far larger than the cyclic\n"
"// skeleton, which is what makes CYCLES 6's work bounds credible.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static int same_scc(int a, int b) {\n"
"    if (a < 0 || b < 0) return 0;\n"
"    if (a == b) return bits_test(&nominals[a].reaches, a);   // a non-trivial self-loop\n"
"    return bits_test(&nominals[a].reaches, b) && bits_test(&nominals[b].reaches, a);\n"
"}\n"
"\n"
"// Whether this type lies in a non-trivial SCC. The transitive closure marks a\n"
"// type as reaching itself exactly then, which is also what makes it not acyclic.\n"
"int aif_type_in_cycle(const char* name) {\n"
"    int id = nominal_find(name);\n"
"    if (id < 0 || nominals[id].is_enum) return 0;\n"
"    return bits_test(&nominals[id].reaches, id) ? 1 : 0;\n"
"}\n"
"\n"
"// Whether this field is a cyclic edge, i.e. one the collector traverses.\n"
"int aif_field_is_cyclic(const char* type, const char* field) {\n"
"    int owner = nominal_find(type);\n"
"    if (owner < 0 || nominals[owner].is_enum) return 0;\n"
"    Nominal* t = &nominals[owner];\n"
"    int fname = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] != fname) continue;\n"
"        return same_scc(owner, nominal_find_id(field_declared_type(t, i)));\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// Whether a store into this field must move a reference count.\n"
"//\n"
"// **Bacon-Rajan requires the count to reflect every reference the traversal\n"
"// walks.** Trial deletion subtracts the internal edges and reads what is left as\n"
"// \"held from outside\"; an edge the collector traverses but nobody ever counted\n"
"// makes that subtraction remove a reference that was never added, and the\n"
"// arithmetic says unreachable for a live object. That is a premature free, and\n"
"// it is what the first build of the collector did -- a segfault on the fixture,\n"
"// not a leak.\n"
"//\n"
"// So a cyclic field is counted, and only when every site that can reach it is\n"
"// one the collector can take. A field mixing a counted object with an opaque or\n"
"// stack one has no correct answer and moves no count, which leaks rather than\n"
"// corrupting.\n"
"int aif_field_is_counted(const char* type, const char* field) {\n"
"    if (!aif_field_is_cyclic(type, field)) return 0;\n"
"    int owner = nominal_find(type);\n"
"    if (owner < 0) return 0;\n"
"    int key = key_find(AIF_KEY_FIELD, nominals[owner].name, aif_intern(field));\n"
"    if (key < 0 || key >= pt_len) return 0;\n"
"\n"
"    int any = 0;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&pt[key], s)) continue;\n"
"        any = 1;\n"
"        if (!site_is_cyclic(&sites[s], aif_tier_of(s))) return 0;\n"
"    }\n"
"    return any;\n"
"}\n"
"\n"
"// CYCLES 2's headline result, as a number the manifest can print: how many types\n"
"// lie in a non-trivial SCC. Zero means the program cannot leak a cycle and the\n"
"// collector is omitted from the binary entirely -- a property checkable from the\n"
"// type declarations alone, before any inference runs.\n"
"int aif_scc_type_count(void) {\n"
"    int n = 0;\n"
"    for (int i = 0; i < nominal_count; i++) {\n"
"        if (nominals[i].is_enum) continue;\n"
"        if (bits_test(&nominals[i].reaches, i)) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"int aif_t4b_site_count(void) {\n"
"    int n = 0;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (aif_tier_of(s) == AIF_T4B) n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"int aif_field_release(const char* type, const char* field) {\n"
"    int id = nominal_find(type);\n"
"    if (id < 0 || nominals[id].is_enum) return AIF_ELEM_NONE;\n"
"    Nominal* t = &nominals[id];\n"
"    int fname = aif_intern(field);\n"
"    for (int i = 0; i < t->nfields; i++) {\n"
"        if (t->field_name[i] != fname) continue;\n"
"        return field_release_of(t->name, fname, field_declared_type(t, i));\n"
"    }\n"
"    return AIF_ELEM_NONE;\n"
"}\n"
"\n"
"// Whether any released field may hold this site.\n"
"//\n"
"// This is the double-free rule `in_container` encodes, one level out. A value\n"
"// stored into a field the type now releases has the struct's teardown as its\n"
"// release point, so its own binding is not one -- otherwise it is freed at the\n"
"// scope exit *and* again when the struct goes.\n"
"//\n"
"// Reachable for the same narrow reason the container case is: normally E-STORE\n"
"// has already raised the value's escape to the struct's, and the `E == scope`\n"
"// test in aif_frees_at_scope_node declines first. It is only when the struct and\n"
"// the field's value share a scope that both tests pass and this one has to say\n"
"// no.\n"
"//\n"
"// Computed once over every (type, field) rather than per site, because the\n"
"// answer depends on the type's fields and not on where the site sits.\n"
"static Bits in_released_field;\n"
"static int in_released_field_done;\n"
"\n"
"// Whether anything actually reclaims a value of this type.\n"
"//\n"
"// **A field is only a release point if its owner has one**, and that is not\n"
"// implied by the owner having a generated release function. A T0 struct lives in\n"
"// the frame: nothing frees it, so nothing runs its release, so its fields are\n"
"// reclaimed by nobody. Barring the field's own binding there does not move the\n"
"// release -- it deletes it.\n"
"//\n"
"// g5_asset_cache is the case, and it cost a 47 -> 2049 regression to find. Its\n"
"// `Scene` is four fields and does not escape `main`, so it takes the T0 clause;\n"
"// the `entities` list stored in it was being freed at main's exit, and barring\n"
"// that on the strength of `Scene`'s release function leaked all 2000 elements.\n"
"static int type_reclaimed_cache_valid;\n"
"static int* type_reclaimed;\n"
"\n"
"static int type_is_reclaimed(int nominal) {\n"
"    if (nominal < 0 || nominal >= nominal_count) return 0;\n"
"    if (!type_reclaimed_cache_valid) {\n"
"        type_reclaimed = (int*)xcalloc((size_t)nominal_count, sizeof(int),\n"
"                                       \"AIF reclaimed types\");\n"
"        for (int s = 0; s < site_count; s++) {\n"
"            if (elem_disposition_of(s, aif_tier_of(s)) == AIF_ELEM_NONE) continue;\n"
"            int id = nominal_find_id(base_type_id(sites[s].type));\n"
"            if (id >= 0) type_reclaimed[id] = 1;\n"
"        }\n"
"        type_reclaimed_cache_valid = 1;\n"
"    }\n"
"    return type_reclaimed[nominal];\n"
"}\n"
"\n"
"static void compute_released_fields(void) {\n"
"    if (in_released_field_done) return;\n"
"    in_released_field_done = 1;\n"
"    for (int n = 0; n < nominal_count; n++) {\n"
"        if (nominals[n].is_enum) continue;\n"
"        if (!type_is_reclaimed(n)) continue;\n"
"        Nominal* t = &nominals[n];\n"
"        for (int i = 0; i < t->nfields; i++) {\n"
"            if (field_release_of(t->name, t->field_name[i], field_declared_type(t, i))\n"
"                == AIF_ELEM_NONE) continue;\n"
"            int key = key_find(AIF_KEY_FIELD, t->name, t->field_name[i]);\n"
"            if (key < 0 || key >= pt_len) continue;\n"
"            bits_or(&in_released_field, &pt[key], \"AIF released fields\");\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"static int site_in_released_field(int s) {\n"
"    compute_released_fields();\n"
"    return bits_test(&in_released_field, s);\n"
"}\n"
"\n"
"// Whether codegen should allocate this node's value through rc_alloc.\n"
"//\n"
"// Keyed by node like every other codegen query, and it must agree with\n"
"// elem_disposition_of exactly: a container told its elements are counted will\n"
"// decrement every one of them, so a site that reached that container without a\n"
"// header is a write through a pointer into someone else's allocation. They read\n"
"// the same predicate for that reason.\n"
"int aif_rc_at_node(const void* node) {\n"
"    if (node == NULL) return 0;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node != node) continue;\n"
"        return site_is_rc(&sites[n->site], aif_tier_of(n->site));\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"// What the container allocated at this node should do with its elements.\n"
"int aif_elem_owner_at_node(const void* node) {\n"
"    if (node == NULL) return AIF_ELEM_NONE;\n"
"    int container = -1;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) { container = n->site; break; }\n"
"    }\n"
"    if (container < 0) return AIF_ELEM_NONE;\n"
"\n"
"    int agreed = AIF_ELEM_NONE;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&container_of[s], container)) continue;\n"
"        int d = elem_disposition_of(s, aif_tier_of(s));\n"
"        if (d == AIF_ELEM_NONE) return AIF_ELEM_NONE;\n"
"        if (agreed == AIF_ELEM_NONE) agreed = d;\n"
"        else if (agreed != d) return AIF_ELEM_NONE;\n"
"    }\n"
"    return agreed;\n"
"}\n"
"\n"
"// The element type of a container whose elements are released by type.\n"
"//\n"
"// Read from the sites rather than from the container's spelled type, for the\n"
"// same reason the element key is object-insensitive: `list_new()` types as\n"
"// `List<Invalid>`, so the annotation is not always there to read, and the sites\n"
"// that actually reached the container always are. \"\" when they disagree, which\n"
"// aif_elem_owner_at_node has already turned into NONE.\n"
"const char* aif_elem_type_at_node(const void* node) {\n"
"    if (node == NULL) return \"\";\n"
"    int container = -1;\n"
"    for (NodeSite* n = node_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) { container = n->site; break; }\n"
"    }\n"
"    if (container < 0) return \"\";\n"
"\n"
"    int agreed = -1;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&container_of[s], container)) continue;\n"
"        if (agreed < 0) agreed = sites[s].type;\n"
"        else if (agreed != sites[s].type) return \"\";\n"
"    }\n"
"    return agreed < 0 ? \"\" : aif_str(agreed);\n"
"}\n"
"\n"
"int aif_site_in_container(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return sites[id].in_container;\n"
"}\n"
"\n"
"// The manifest's half of aif_rc_at_node. SPEC 6.2's placement column has to say\n"
"// what was *built*, and \"rc\" for a T3 site nothing counts would be the manifest\n"
"// asserting a mechanism the binary does not contain.\n"
"int aif_site_is_rc(int id) {\n"
"    if (id < 0 || id >= site_count) return 0;\n"
"    return site_is_rc(&sites[id], aif_tier_of(id));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Ownership transfer across a return\n"
"//\n"
"// `let cmds = cull(scene, ...)` allocates in the callee and reclaims in the\n"
"// caller, and the escape lattice cannot say so: E is per site, a site belongs to\n"
"// one function, and Region(s) can only name a scope in that function. So a\n"
"// returned value is Caller and stays Caller no matter how briefly the caller\n"
"// keeps it. INFERENCE 6's ownership contexts are the specified fix -- instantiate\n"
"// the callee per call site so the return lands in the caller's scope -- and that\n"
"// is a project, not a clause.\n"
"//\n"
"// What is available without it: T2 already means \"unique, and the callee kept no\n"
"// other holder\", which is the whole of what the caller needs to know. The rest is\n"
"// asked of the syntax at the binding, the same way node_assigns_name is, because\n"
"// the two things that could still go wrong are both visible there.\n"
"//\n"
"//   * The callee returned something it did not allocate -- a pass-through of its\n"
"//     own argument. Then the caller frees a value it already owns elsewhere.\n"
"//     Excluded by requiring every site in the return set to belong to the callee.\n"
"//   * The caller returns it onward. Excluded in ir.psm by node_returns_name,\n"
"//     which is the guard the escape fact would otherwise have supplied.\n"
"//\n"
"// Restricted to a returned **container**, and the restriction is a soundness\n"
"// requirement rather than a conservative start. A value set records the sites an\n"
"// expression may denote, and a string literal or a static is not a site -- so for\n"
"// a function returning `String`, `return \"ptr\"` contributes nothing and the set\n"
"// looks exactly like one that always allocates. Freeing that is a free of\n"
"// `.rodata`, which is the defect Level 4 found in `str_substring` arriving by a\n"
"// different road. The same goes for a struct-returning function with a sentinel\n"
"// path.\n"
"//\n"
"// A `List` has no literal form: `list_new` and `list_new_with_capacity` are the\n"
"// only ways to make one and both always allocate. So the return set of a\n"
"// list-returning function is complete, which is the property this needs and the\n"
"// one the other two lack -- and it is a property to check when a third\n"
"// constructor is added, not a fact about the count. Recovering the other two\n"
"// needs the points-to lattice to carry \"may hold something untracked\", which is a\n"
"// real extension and not this item.\n"
"//\n"
"// Returns the deallocator the result needs: 0 none, 2 list.\n"
"// ============================================================================\n"
"\n"
"typedef struct NodeCall {\n"
"    struct NodeCall* next;\n"
"    const void* node;\n"
"    int vs;\n"
"    int fn;\n"
"} NodeCall;\n"
"\n"
"static NodeCall* call_buckets[AIF_NODE_BUCKETS];\n"
"static Bits query_scratch;\n"
"\n"
"void aif_note_call_result(const void* node, int vs, int fn) {\n"
"    if (node == NULL || fn < 0) return;\n"
"    unsigned b = node_hash(node);\n"
"    for (NodeCall* n = call_buckets[b]; n; n = n->next) {\n"
"        if (n->node == node) return;\n"
"    }\n"
"    NodeCall* n = (NodeCall*)xmalloc(sizeof(NodeCall), \"AIF call index\");\n"
"    n->node = node;\n"
"    n->vs = vs;\n"
"    n->fn = fn;\n"
"    n->next = call_buckets[b];\n"
"    call_buckets[b] = n;\n"
"}\n"
"\n"
"int aif_owns_call_result_at_node(const void* node) {\n"
"    if (node == NULL) return AIF_ELEM_NONE;\n"
"    NodeCall* c = NULL;\n"
"    for (NodeCall* n = call_buckets[node_hash(node)]; n; n = n->next) {\n"
"        if (n->node == node) { c = n; break; }\n"
"    }\n"
"    if (c == NULL) return AIF_ELEM_NONE;\n"
"\n"
"    resolve(c->vs, &query_scratch);\n"
"    int agreed = AIF_ELEM_NONE;\n"
"    int any = 0;\n"
"    for (int s = 0; s < site_count; s++) {\n"
"        if (!bits_test(&query_scratch, s)) continue;\n"
"        any = 1;\n"
"        // Allocated by the callee, not handed to it. A pass-through leaves the\n"
"        // value owned where it was created, and freeing it here is a double free\n"
"        // through whichever binding owns it there.\n"
"        if (sites[s].fn != c->fn) return AIF_ELEM_NONE;\n"
"        if (sites[s].in_container) return AIF_ELEM_NONE;\n"
"        // A field the type releases is already this value's release point, so\n"
"        // the caller must not become a second one. The same exclusion as\n"
"        // in_container above, and reachable the same way: a function that both\n"
"        // stores a value into a field and returns that field.\n"
"        if (site_in_released_field(s)) return AIF_ELEM_NONE;\n"
"        if (aif_tier_of(s) != AIF_T2) return AIF_ELEM_NONE;\n"
"        int d = elem_disposition_of(s, AIF_T2);\n"
"        // A struct that owns something joins `List` here, and for the same\n"
"        // reason the comment above gives: the value set has to be complete.\n"
"        // A `List` qualifies because it has no literal form. A struct qualifies\n"
"        // because it has no *sentinel* form -- there is no null, so every way to\n"
"        // produce one is either a literal (a site in this callee) or a value\n"
"        // that came from somewhere else (a site whose fn is not this one, which\n"
"        // the test above declines). **REQUIREMENTS 4 must not break that**: an\n"
"        // Option-typed return would be the first struct-shaped value that is not\n"
"        // a site, and this is the line it would make unsound.\n"
"        //\n"
"        // Restricted to structs that own something, which is a scope choice and\n"
"        // not a soundness one -- the completeness argument says nothing about\n"
"        // the fields. It is where the leak is (g4's `World`), and a plain struct\n"
"        // return has a much wider blast radius for no measured gain.\n"
"        if (d != AIF_ELEM_LIST && d != AIF_ELEM_TYPED) return AIF_ELEM_NONE;\n"
"        if (agreed != AIF_ELEM_NONE && agreed != d) return AIF_ELEM_NONE;\n"
"        agreed = d;\n"
"    }\n"
"    return any ? agreed : AIF_ELEM_NONE;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Manifest ordering\n"
"//\n"
"// SPEC 6.2 makes the record order normative -- byte-wise ascending by symbol --\n"
"// because an unstable order makes every diff useless. The frontend builds each\n"
"// record's symbol (it knows what a symbol means) and hands it here to be sorted\n"
"// (sorting is a container operation).\n"
"//\n"
"// Insertion-order-stable, so equal symbols keep the order they were added in.\n"
"// There should be no equal symbols; relying on that rather than asserting it\n"
"// would make a future collision reorder the manifest silently.\n"
"// ============================================================================\n"
"\n"
"typedef struct {\n"
"    int symbol;     // interned\n"
"    int site;\n"
"    int seq;\n"
"} Record;\n"
"\n"
"static Record* records;\n"
"static int record_count, record_cap;\n"
"\n"
"void aif_order_add(const char* symbol, int site) {\n"
"    if (record_count == record_cap) {\n"
"        record_cap = record_cap ? record_cap * 2 : 1024;\n"
"        records = (Record*)xrealloc(records, (size_t)record_cap * sizeof(Record),\n"
"                                    \"AIF manifest records\");\n"
"    }\n"
"    Record* r = &records[record_count];\n"
"    r->symbol = aif_intern(symbol);\n"
"    r->site = site;\n"
"    r->seq = record_count;\n"
"    record_count++;\n"
"}\n"
"\n"
"static int record_cmp(const void* a, const void* b) {\n"
"    const Record* x = (const Record*)a;\n"
"    const Record* y = (const Record*)b;\n"
"    int c = strcmp(aif_str(x->symbol), aif_str(y->symbol));\n"
"    if (c != 0) return c;\n"
"    return x->seq - y->seq;\n"
"}\n"
"\n"
"void aif_order_sort(void) {\n"
"    if (record_count > 1) qsort(records, (size_t)record_count, sizeof(Record), record_cmp);\n"
"}\n"
"\n"
"int aif_order_count(void) { return record_count; }\n"
"const char* aif_order_symbol(int i) { return (i < 0 || i >= record_count) ? \"\" : aif_str(records[i].symbol); }\n"
"int aif_order_site(int i) { return (i < 0 || i >= record_count) ? -1 : records[i].site; }\n"
"\n"
"// ============================================================================\n"
"// Reset\n"
"//\n"
"// A compiler run analyses one program, but the test harness and any future\n"
"// per-module invocation want a clean slate. Interned names are deliberately\n"
"// kept: they cost nothing and nothing outside this file holds an id across a\n"
"// reset.\n"
"// ============================================================================\n"
"\n"
"void aif_reset(void) {\n"
"    g_stmt = -1;\n"
"    free(scope_stmt);\n"
"    scope_stmt = NULL;\n"
"    scope_stmt_cap = 0;\n"
"    free(key_last_stmt);\n"
"    key_last_stmt = NULL;\n"
"    key_last_stmt_cap = 0;\n"
"    for (int i = 0; i < pt_len; i++) bits_free(&pt[i]);\n"
"    for (int i = 0; i < holders_len; i++) bits_free(&holders[i]);\n"
"    for (int i = 0; i < holders_len; i++) bits_free(&container_of[i]);\n"
"    if (key_views) { for (int i = 0; i < pt_len; i++) bits_free(&key_views[i]); }\n"
"    free(pt);\n"
"    free(holders);\n"
"    free(container_of);\n"
"    free(key_views);\n"
"    pt = NULL;\n"
"    holders = NULL;\n"
"    container_of = NULL;\n"
"    key_views = NULL;\n"
"    pt_len = 0;\n"
"    holders_len = 0;\n"
"\n"
"    // LAYOUT 5's traversal table, for exactly the reason the call graph below is\n"
"    // torn down: a declared `workload` runs the engine twice in one process, and\n"
"    // traversals that survived would be counted against a second set of loop ids\n"
"    // -- doubling every co-access set and, because the loop ids differ, doing it\n"
"    // as *extra traversals* rather than as bigger ones. The cost of a candidate\n"
"    // would then scale with how many times the engine had run.\n"
"    traversals_reset();\n"
"    candidates_clear();\n"
"\n"
"    // SPEC 5.2.1.1's call graph. It has to be torn down here like everything\n"
"    // else, and the reason is not hypothetical: a declared `workload` runs the\n"
"    // whole engine twice in one process (LAYOUT 3.2), so edges that survived a\n"
"    // reset would double every call-site count -- and regime (a) turns on\n"
"    // exactly that count, so every callee would report two call sites and no\n"
"    // function would ever be sole-regime. A wrong answer, silently, on the\n"
"    // programs that carry a profile and on no others.\n"
"    for (int i = 0; i < bracket_fn_cap; i++) {\n"
"        bits_free(&fn_callees[i]);\n"
"        bits_free(&fn_owner_fns[i]);\n"
"    }\n"
"    free(fn_callees);\n"
"    free(fn_owner_fns);\n"
"    free(fn_has_global);\n"
"    free(fn_has_drop);\n"
"    free(fn_calls_opaque);\n"
"    fn_callees = NULL;\n"
"    fn_owner_fns = NULL;\n"
"    fn_has_global = NULL;\n"
"    fn_has_drop = NULL;\n"
"    fn_calls_opaque = NULL;\n"
"    bracket_fn_cap = 0;\n"
"    bracket_ready = 0;\n"
"    free(call_edges);\n"
"    call_edges = NULL;\n"
"    call_edge_count = 0;\n"
"    call_edge_cap = 0;\n"
"    free(owner_uses);\n"
"    owner_uses = NULL;\n"
"    owner_use_count = 0;\n"
"    owner_use_cap = 0;\n"
"    bits_free(&bracket_closure);\n"
"    bits_free(&bracket_scratch);\n"
"\n"
"    // SPEC 5.2.1.1's placement, torn down for the same reason the call graph\n"
"    // above is: a declared `workload` runs the whole engine twice in one process,\n"
"    // and site_bracket indexed by a *previous* run's site ids would hand this\n"
"    // run's sites an arena chosen for someone else's program.\n"
"    free(site_bracket);\n"
"    site_bracket = NULL;\n"
"    free(brackets);\n"
"    brackets = NULL;\n"
"    bracket_count = 0;\n"
"    bracket_cap = 0;\n"
"    bracket_place_ready = 0;\n"
"    bits_free(&bracket_place_extent);\n"
"    bits_free(&bracket_place_confined);\n"
"    for (int i = 0; i < site_owner_len; i++) bits_free(&site_owner_sites[i]);\n"
"    free(site_owner_sites);\n"
"    site_owner_sites = NULL;\n"
"    site_owner_len = 0;\n"
"    bits_free(&owner_bits_val);\n"
"    bits_free(&owner_bits_own);\n"
"    free(owner_vec_val.v);\n"
"    free(owner_vec_own.v);\n"
"    owner_vec_val.v = NULL; owner_vec_val.len = 0; owner_vec_val.cap = 0;\n"
"    owner_vec_own.v = NULL; owner_vec_own.len = 0; owner_vec_own.cap = 0;\n"
"    free(key_by_id);\n"
"    key_by_id = NULL;\n"
"    key_by_id_len = 0;\n"
"\n"
"    bits_free(&in_released_field);\n"
"    in_released_field_done = 0;\n"
"    free(type_releases);\n"
"    type_releases = NULL;\n"
"    type_releases_cap = 0;\n"
"    free(type_reclaimed);\n"
"    type_reclaimed = NULL;\n"
"    type_reclaimed_cache_valid = 0;\n"
"\n"
"    free(deriv_e);\n"
"    free(deriv_a);\n"
"    deriv_e = NULL;\n"
"    deriv_a = NULL;\n"
"    cause_len = 0;\n"
"    cur_con = -1;\n"
"    synth_rule = -1;\n"
"    force_rule = -1;\n"
"\n"
"    for (int i = 0; i < vs_count; i++) { free(vsets[i].items); free(vsets[i].views); }\n"
"    vs_count = 0;\n"
"\n"
"    for (int i = 0; i < nominal_count; i++) {\n"
"        bits_free(&nominals[i].reaches);\n"
"        bits_free(&nominals[i].hot);\n"
"        free(nominals[i].field_name);\n"
"        free(nominals[i].field_type);\n"
"        free(nominals[i].field_bytes);\n"
"        free(nominals[i].field_acc);\n"
"        free(nominals[i].order);\n"
"        free(nominals[i].field_lo);\n"
"        free(nominals[i].field_hi);\n"
"        free(nominals[i].field_has_range);\n"
"    }\n"
"    nominal_count = 0;\n"
"\n"
"    // Cleared, and the ordering is the reason it is safe to clear. The profile\n"
"    // is loaded *into* the nominals table, so it can only be loaded after\n"
"    // aifDeclare has repopulated that table -- which is in the second pass,\n"
"    // after this reset. Keeping the old value across the reset would leave a\n"
"    // manifest claiming `workload:NAME` if the second pass's load then failed.\n"
"    g_profile_source = -1;\n"
"    g_profile_runs = 0;\n"
"    for (int i = 0; i < nominal_by_name_cap; i++) nominal_by_name[i] = -1;\n"
"\n"
"    for (int i = 0; i < fn_by_symbol_cap; i++) fn_by_symbol[i] = -1;\n"
"    fn_count = 0;\n"
"\n"
"    free(var_scope);\n"
"    var_scope = NULL;\n"
"    var_scope_cap = 0;\n"
"\n"
"    free(extern_contract);\n"
"    extern_contract = NULL;\n"
"    extern_contract_cap = 0;\n"
"\n"
"    for (int i = 0; i < AIF_NODE_BUCKETS; i++) {\n"
"        NodeSite* n = node_buckets[i];\n"
"        while (n) {\n"
"            NodeSite* next = n->next;\n"
"            free(n);\n"
"            n = next;\n"
"        }\n"
"        node_buckets[i] = NULL;\n"
"    }\n"
"\n"
"    for (int i = 0; i < AIF_NODE_BUCKETS; i++) {\n"
"        NodeCall* n = call_buckets[i];\n"
"        while (n) {\n"
"            NodeCall* next = n->next;\n"
"            free(n);\n"
"            n = next;\n"
"        }\n"
"        call_buckets[i] = NULL;\n"
"    }\n"
"\n"
"    site_count = 0;\n"
"    scope_count = 0;\n"
"    con_count = 0;\n"
"    record_count = 0;\n"
"    orphan_sites = 0;\n"
"    solve_rounds = 0;\n"
"    owned_collections = 0;\n"
"\n"
"    bits_free(&scratch_val);\n"
"    bits_free(&scratch_own);\n"
"    bits_free(&query_scratch);\n"
"    free(vec_val.v);\n"
"    free(vec_own.v);\n"
"    free(argv.v);\n"
"    vec_val.v = NULL; vec_val.len = 0; vec_val.cap = 0;\n"
"    vec_own.v = NULL; vec_own.len = 0; vec_own.cap = 0;\n"
"    argv.v = NULL; argv.len = 0; argv.cap = 0;\n"
"\n"
"    for (int i = 0; i < AIF_KEY_BUCKETS; i++) {\n"
"        KeyNode* n = key_buckets[i];\n"
"        while (n) {\n"
"            KeyNode* next = n->next;\n"
"            free(n);\n"
"            n = next;\n"
"        }\n"
"        key_buckets[i] = NULL;\n"
"    }\n"
"    key_count = 0;\n"
"}\n"
;

static const char prismio_embedded_diagnostics_c[] =
"// Source-level diagnostics: the file registry, span rendering and error\n"
"// accounting behind every message the compiler prints.\n"
"//\n"
"// Compiler-only (backend.lib). A compiled Prismio program never reports a\n"
"// diagnostic, so none of this belongs in runtime.lib.\n"
"//\n"
"// Why this lives in C rather than in Prismio: rendering a diagnostic needs the\n"
"// *original source text* of whichever file the node came from, long after the\n"
"// parser has thrown the text away and `resolve_imports` has flattened every\n"
"// module into one AST. A registry keyed by an integer id is the smallest thing\n"
"// that survives both. Prismio also has no varargs, so the frontend composes the\n"
"// message with str_concat and hands over a finished string.\n"
"//\n"
"// Output goes to stderr, unconditionally and without colour. stderr because a\n"
"// diagnostic is not program output; without colour because the compiler cannot\n"
"// know whether the receiving console decodes ANSI (Windows consoles do not\n"
"// enable VT processing for a plain console application by default), and a\n"
"// half-decoded escape is worse than none.\n"
"\n"
"// stdio/stdlib/string arrive through this; including them again here would only\n"
"// let the two lists drift.\n"
"#include \"prismio_platform.h\"\n"
"\n"
"#define DIAG_MAX_FILES 256\n"
"\n"
"// Past this many errors the compiler stops rather than continuing to recover.\n"
"// Beyond roughly this point the output is cascade, not information, and every\n"
"// further recovery step is another chance to walk a half-built AST.\n"
"#define DIAG_ERROR_LIMIT 25\n"
"\n"
"typedef struct {\n"
"    char* path;\n"
"    char* content;\n"
"} DiagFile;\n"
"\n"
"static DiagFile g_files[DIAG_MAX_FILES];\n"
"static int g_file_count = 0;\n"
"static int g_error_count = 0;\n"
"static int g_warning_count = 0;\n"
"static int g_json_mode = 0;\n"
"static int g_finished = 0;\n"
"\n"
"void diag_set_json_mode(int on) {\n"
"    g_json_mode = on != 0;\n"
"}\n"
"\n"
"static char* diag_strdup(const char* s) {\n"
"    if (!s) s = \"\";\n"
"    size_t n = strlen(s) + 1;\n"
"    char* out = (char*)malloc(n);\n"
"    if (!out) return NULL;\n"
"    memcpy(out, s, n);\n"
"    return out;\n"
"}\n"
"\n"
"// Registers a source file and returns the id to stamp onto every token and AST\n"
"// node produced from it. The content is copied: the caller's buffer belongs to\n"
"// the frontend, which is free to reuse or release it once parsing is done.\n"
"//\n"
"// Re-registering a path returns the existing id instead of a second entry, so\n"
"// the diamond-shaped import graph in src/ does not consume four slots for\n"
"// utils.psm.\n"
"int diag_add_file(const char* path, const char* content) {\n"
"    if (!path) path = \"<unknown>\";\n"
"\n"
"    for (int i = 0; i < g_file_count; i++) {\n"
"        if (strcmp(g_files[i].path, path) == 0) return i;\n"
"    }\n"
"\n"
"    if (g_file_count >= DIAG_MAX_FILES) return -1;\n"
"\n"
"    char* p = diag_strdup(path);\n"
"    char* c = diag_strdup(content);\n"
"    if (!p || !c) {\n"
"        free(p);\n"
"        free(c);\n"
"        return -1;\n"
"    }\n"
"\n"
"    g_files[g_file_count].path = p;\n"
"    g_files[g_file_count].content = c;\n"
"    return g_file_count++;\n"
"}\n"
"\n"
"const char* diag_file_path(int file) {\n"
"    if (file < 0 || file >= g_file_count) return \"<unknown>\";\n"
"    return g_files[file].path;\n"
"}\n"
"\n"
"// How many ids diag_add_file has handed out.\n"
"//\n"
"// Exists because \"<unknown>\" is a usable answer for a diagnostic and a wrong one\n"
"// for debug info: an out-of-range id would become a DIFile named \"<unknown>\" and\n"
"// a debugger would go looking for a file by that name. The DWARF emitter asks\n"
"// this first and emits no location at all for an id outside the registry.\n"
"int diag_file_count(void) { return g_file_count; }\n"
"\n"
"// Start of the 1-based `line` within `text`, or NULL if the file has fewer\n"
"// lines than that -- which happens whenever a span is stale or synthesised, and\n"
"// must degrade to \"no snippet\" rather than reading past the buffer.\n"
"static const char* diag_line_start(const char* text, int line) {\n"
"    if (!text || line <= 0) return NULL;\n"
"\n"
"    const char* p = text;\n"
"    int current = 1;\n"
"    while (current < line && *p) {\n"
"        if (*p == '\\n') current++;\n"
"        p++;\n"
"    }\n"
"    return (current == line) ? p : NULL;\n"
"}\n"
"\n"
"static int diag_line_length(const char* start) {\n"
"    const char* end = start;\n"
"    while (*end && *end != '\\n') end++;\n"
"    int len = (int)(end - start);\n"
"    // A CRLF file would otherwise put a stray carriage return in the middle of\n"
"    // the rendered snippet, pushing the caret line back to column zero.\n"
"    if (len > 0 && start[len - 1] == '\\r') len--;\n"
"    return len;\n"
"}\n"
"\n"
"static int diag_digits(int value) {\n"
"    int n = 1;\n"
"    while (value >= 10) {\n"
"        value /= 10;\n"
"        n++;\n"
"    }\n"
"    return n;\n"
"}\n"
"\n"
"static void diag_spaces(int n) {\n"
"    for (int i = 0; i < n; i++) fputc(' ', stderr);\n"
"}\n"
"\n"
"// JSON Lines is used instead of one enclosing array so an IDE can consume each\n"
"// diagnostic as soon as the compiler reports it. Strings are written directly:\n"
"// diagnostics are already complete UTF-8 messages, and allocating an escaped\n"
"// copy here would make error reporting itself another failure path.\n"
"static void diag_json_string(const char* text) {\n"
"    if (!text) text = \"\";\n"
"\n"
"    fputc('\"', stderr);\n"
"    for (const unsigned char* p = (const unsigned char*)text; *p; p++) {\n"
"        switch (*p) {\n"
"            case '\"': fputs(\"\\\\\\\"\", stderr); break;\n"
"            case '\\\\': fputs(\"\\\\\\\\\", stderr); break;\n"
"            case '\\b': fputs(\"\\\\b\", stderr); break;\n"
"            case '\\f': fputs(\"\\\\f\", stderr); break;\n"
"            case '\\n': fputs(\"\\\\n\", stderr); break;\n"
"            case '\\r': fputs(\"\\\\r\", stderr); break;\n"
"            case '\\t': fputs(\"\\\\t\", stderr); break;\n"
"            default:\n"
"                if (*p < 0x20) {\n"
"                    fprintf(stderr, \"\\\\u%04x\", (unsigned int)*p);\n"
"                } else {\n"
"                    fputc(*p, stderr);\n"
"                }\n"
"                break;\n"
"        }\n"
"    }\n"
"    fputc('\"', stderr);\n"
"}\n"
"\n"
"static void diag_emit_json(const char* severity, int file, int line, int col,\n"
"                           int len, const char* message) {\n"
"    fputs(\"{\\\"kind\\\":\\\"diagnostic\\\",\\\"schemaVersion\\\":1,\\\"severity\\\":\", stderr);\n"
"    diag_json_string(severity);\n"
"    fputs(\",\\\"file\\\":\", stderr);\n"
"    if (file >= 0 && file < g_file_count) {\n"
"        diag_json_string(g_files[file].path);\n"
"    } else {\n"
"        fputs(\"null\", stderr);\n"
"    }\n"
"    fprintf(stderr, \",\\\"line\\\":%d,\\\"column\\\":%d,\\\"length\\\":%d,\\\"message\\\":\",\n"
"            line, col, len);\n"
"    diag_json_string(message);\n"
"    fputs(\"}\\n\", stderr);\n"
"}\n"
"\n"
"static void diag_emit_json_summary(void) {\n"
"    fprintf(stderr,\n"
"            \"{\\\"kind\\\":\\\"summary\\\",\\\"schemaVersion\\\":1,\\\"errors\\\":%d,\\\"warnings\\\":%d}\\n\",\n"
"            g_error_count, g_warning_count);\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"// The snippet block, in the rustc shape:\n"
"//\n"
"//      --> src/foo.psm:12:5\n"
"//       |\n"
"//    12 |     x = 6\n"
"//       |     ^\n"
"//\n"
"// `gutter` is the width of the line number, so the vertical bars line up no\n"
"// matter how long the file is.\n"
"static void diag_render_span(int file, int line, int col, int len) {\n"
"    if (file < 0 || file >= g_file_count || line <= 0) return;\n"
"\n"
"    const char* path = g_files[file].path;\n"
"    const char* text = g_files[file].content;\n"
"    const char* start = diag_line_start(text, line);\n"
"\n"
"    if (col < 1) col = 1;\n"
"\n"
"    if (!start) {\n"
"        // No snippet available, but the location itself is still worth having.\n"
"        fprintf(stderr, \" --> %s:%d:%d\\n\", path, line, col);\n"
"        return;\n"
"    }\n"
"\n"
"    int line_len = diag_line_length(start);\n"
"    int gutter = diag_digits(line);\n"
"\n"
"    diag_spaces(gutter);\n"
"    fprintf(stderr, \"--> %s:%d:%d\\n\", path, line, col);\n"
"\n"
"    diag_spaces(gutter + 1);\n"
"    fprintf(stderr, \"|\\n\");\n"
"\n"
"    fprintf(stderr, \"%d | %.*s\\n\", line, line_len, start);\n"
"\n"
"    diag_spaces(gutter + 1);\n"
"    fprintf(stderr, \"| \");\n"
"\n"
"    // Pad with the source's own whitespace so a tab-indented line keeps the\n"
"    // caret under the right character instead of drifting by seven columns.\n"
"    int pad = col - 1;\n"
"    if (pad > line_len) pad = line_len;\n"
"    for (int i = 0; i < pad; i++) fputc(start[i] == '\\t' ? '\\t' : ' ', stderr);\n"
"\n"
"    int carets = len > 0 ? len : 1;\n"
"    if (pad + carets > line_len) carets = line_len - pad;\n"
"    if (carets < 1) carets = 1;\n"
"    for (int i = 0; i < carets; i++) fputc('^', stderr);\n"
"    fputc('\\n', stderr);\n"
"}\n"
"\n"
"static void diag_emit(const char* severity, int file, int line, int col, int len, const char* message) {\n"
"    if (g_json_mode) {\n"
"        diag_emit_json(severity, file, line, col, len, message);\n"
"        fflush(stderr);\n"
"        return;\n"
"    }\n"
"\n"
"    fprintf(stderr, \"%s: %s\\n\", severity, message ? message : \"\");\n"
"    diag_render_span(file, line, col, len);\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"void diag_error_at(int file, int line, int col, int len, const char* message) {\n"
"    g_finished = 0;\n"
"    g_error_count++;\n"
"\n"
"    if (g_error_count > DIAG_ERROR_LIMIT) {\n"
"        if (g_json_mode) {\n"
"            diag_emit_json(\"error\", -1, 0, 0, 0,\n"
"                           \"too many errors; stopping after 25\");\n"
"            diag_emit_json_summary();\n"
"            exit(1);\n"
"        }\n"
"        fprintf(stderr, \"error: too many errors; stopping after %d\\n\", DIAG_ERROR_LIMIT);\n"
"        fflush(stderr);\n"
"        exit(1);\n"
"    }\n"
"\n"
"    diag_emit(\"error\", file, line, col, len, message);\n"
"}\n"
"\n"
"void diag_error(const char* message) {\n"
"    diag_error_at(-1, 0, 0, 0, message);\n"
"}\n"
"\n"
"void diag_warning_at(int file, int line, int col, int len, const char* message) {\n"
"    g_finished = 0;\n"
"    g_warning_count++;\n"
"    diag_emit(\"warning\", file, line, col, len, message);\n"
"}\n"
"\n"
"// Unlocated, the counterpart of diag_error above and reached the same way -- a\n"
"// file of -1. LAYOUT 3.2's W2 is what needed it: a workload that fails to build\n"
"// or times out has to warn, and the thing that went wrong is a build step rather\n"
"// than a span of source, so there is no honest place to point a caret.\n"
"void diag_warning(const char* message) {\n"
"    diag_warning_at(-1, 0, 0, 0, message);\n"
"}\n"
"\n"
"// A secondary span belonging to the diagnostic just reported -- \"the first\n"
"// declaration is here\", \"the loop starts here\". Indented so it reads as\n"
"// subordinate rather than as a second, unrelated error.\n"
"void diag_note_at(int file, int line, int col, int len, const char* message) {\n"
"    if (g_json_mode) {\n"
"        diag_emit(\"note\", file, line, col, len, message);\n"
"        return;\n"
"    }\n"
"\n"
"    fprintf(stderr, \"  note: %s\\n\", message ? message : \"\");\n"
"    diag_render_span(file, line, col, len);\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"void diag_note(const char* message) {\n"
"    if (g_json_mode) {\n"
"        diag_emit(\"note\", -1, 0, 0, 0, message);\n"
"        return;\n"
"    }\n"
"\n"
"    fprintf(stderr, \"  note: %s\\n\", message ? message : \"\");\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"int diag_error_count(void) {\n"
"    return g_error_count;\n"
"}\n"
"\n"
"int diag_warning_count(void) {\n"
"    return g_warning_count;\n"
"}\n"
"\n"
"// The closing line, printed once when compilation gives up. Its wording is the\n"
"// contract the negative tests match on: a test passes because the compiler\n"
"// *rejected* the program, which a crash or a linker failure must not be able to\n"
"// impersonate.\n"
"void diag_finish(void) {\n"
"    if (g_finished) return;\n"
"    g_finished = 1;\n"
"\n"
"    if (g_json_mode) {\n"
"        diag_emit_json_summary();\n"
"        return;\n"
"    }\n"
"\n"
"    if (g_error_count <= 0) return;\n"
"\n"
"    if (g_error_count == 1) {\n"
"        fprintf(stderr, \"error: aborting due to 1 previous error\\n\");\n"
"    } else {\n"
"        fprintf(stderr, \"error: aborting due to %d previous errors\\n\", g_error_count);\n"
"    }\n"
"    fflush(stderr);\n"
"}\n"
"\n"
"void diag_reset(void) {\n"
"    for (int i = 0; i < g_file_count; i++) {\n"
"        free(g_files[i].path);\n"
"        free(g_files[i].content);\n"
"        g_files[i].path = NULL;\n"
"        g_files[i].content = NULL;\n"
"    }\n"
"    g_file_count = 0;\n"
"    g_error_count = 0;\n"
"    g_warning_count = 0;\n"
"    g_finished = 0;\n"
"}\n"
;

static const char prismio_embedded_llvm_api_backend_c[] =
"// ============================================================================\n"
"// Prismio backend built on the real LLVM C API.\n"
"//\n"
"// This is the replacement for llvm-bridge.c, which assembled LLVM IR as text in\n"
"// fixed-size buffers. Both implement the same ir_* surface declared in\n"
"// src/bridge.psm, so exactly one is linked into the compiler and the frontend\n"
"// does not know which. Select this one with:\n"
"//\n"
"//     clang -DPRISMIO_BACKEND_LLVM_API ...   (and link LLVM-C)\n"
"//\n"
"// Why this exists at all, beyond tidiness: the text emitter could only be\n"
"// checked by llc's parser after the fact, so a malformed instruction surfaced as\n"
"// a parse error pointing at generated IR rather than at the code that built it.\n"
"// Here LLVMVerifyModule runs before anything is written, the IRBuilder refuses\n"
"// to construct type-incorrect instructions in the first place, and constants are\n"
"// folded as they are built. It is also the prerequisite for a custom memory\n"
"// model: allocation is a policy hook here (see \"memory model\" below) instead of\n"
"// a hardcoded `call ptr @malloc` spelled out in the frontend.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// How values cross the FFI\n"
"//\n"
"// Prismio has no pointer type, so the frontend passes everything as String. The\n"
"// compiler already relies on this for AST nodes (ptr_to_node/node_to_ptr). Here\n"
"// a value is a *handle string*, and every function that accepts a value resolves\n"
"// it through resolve_value():\n"
"//\n"
"//     \"$$v12\"      -> g_values[12], an LLVMValueRef produced by an earlier call\n"
"//     \"%p_argc\"    -> a parameter of the function being built, looked up by name\n"
"//     \"%x\"         -> a named alloca in the current function\n"
"//     anything else -> a literal constant, parsed according to the type argument\n"
"//\n"
"// The literal case is what lets the existing frontend keep passing \"0\", \"42\",\n"
"// \"true\" and \"null\" straight through without being rewritten first. '$' cannot\n"
"// appear in a Prismio identifier, so a handle can never collide with user text.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// Status: this is the only backend. llvm-bridge.c has been deleted.\n"
"//\n"
"// The compiler self-hosts on this backend to a fixed point and passes the full\n"
"// test suite. src/ir.psm no longer emits any IR text -- struct literals, member\n"
"// access, array literals, indexing, string literals and struct type definitions\n"
"// all go through the typed builders below.\n"
"//\n"
"// ir_append() is kept as a loud failure rather than removed. Nothing calls it,\n"
"// and nothing should: it is the guard that stops raw text creeping back in,\n"
"// where it would silently produce a module with instructions missing.\n"
"// ============================================================================\n"
"\n"
"#include <stdio.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"#include \"prismio_llvm.h\"\n"
"\n"
"// ============================================================================\n"
"// Module state\n"
"// ============================================================================\n"
"\n"
"// The value and block tables are indexed by a counter that runs for the whole\n"
"// module, so their old fixed sizes were a ceiling on *program size* rather than\n"
"// on anything a single function could do: a 922 KB source stopped with\n"
"// `value table exhausted`, which is the first hard limit anyone has hit here.\n"
"// They grow now, the way every table in ir_symbols.c does and for the reason\n"
"// stated there. These two names are the initial capacity, not a maximum.\n"
"#define INITIAL_VALUES 65536\n"
"#define INITIAL_LABELS 16384\n"
"// Per *function*, unlike the two above -- ir_function_body_start() resets both\n"
"// counts -- so this one is a bound on how many locals or parameters one function\n"
"// may have, and 4096 of either is not a program anyone is writing.\n"
"#define MAX_NAMED 4096\n"
"#define MAX_CALL_DEPTH 64\n"
"#define MAX_CALL_ARGS 64\n"
"#define MAX_PENDING_PARAMS 64\n"
"#define NAME_LEN 128\n"
"\n"
"static LLVMContextRef g_ctx;\n"
"static LLVMModuleRef g_module;\n"
"static LLVMBuilderRef g_builder;\n"
"// Second builder, used only for allocas. They must land in the entry block no\n"
"// matter where codegen currently is, or a `let` inside a loop body would grow\n"
"// the stack on every iteration.\n"
"static LLVMBuilderRef g_alloca_builder;\n"
"static LLVMBasicBlockRef g_entry_block;\n"
"static int g_initialized;\n"
"\n"
"static LLVMValueRef *g_values;\n"
"static int g_value_count;\n"
"static int g_value_capacity;\n"
"\n"
"// Blocks are reserved before they are created: the frontend asks for a label\n"
"// number, branches to it, and only later says \"the block starts here\". So a slot\n"
"// is handed out immediately and the LLVMBasicBlockRef is materialised on first\n"
"// use.\n"
"static LLVMBasicBlockRef *g_blocks;\n"
"static int g_label_count;\n"
"static int g_label_capacity;\n"
"\n"
"typedef struct {\n"
"    char name[NAME_LEN];\n"
"    LLVMValueRef value;\n"
"    LLVMTypeRef type; // allocated type, for load/GEP\n"
"} NamedValue;\n"
"\n"
"static NamedValue g_allocas[MAX_NAMED];\n"
"static int g_alloca_count;\n"
"static NamedValue g_params[MAX_PENDING_PARAMS];\n"
"static int g_param_count;\n"
"\n"
"// Function currently being built.\n"
"static LLVMValueRef g_function;\n"
"static char g_pending_fn_name[NAME_LEN];\n"
"static LLVMTypeRef g_pending_ret;\n"
"static LLVMTypeRef g_pending_params[MAX_PENDING_PARAMS];\n"
"static char g_pending_param_names[MAX_PENDING_PARAMS][NAME_LEN];\n"
"static int g_pending_param_count;\n"
"static int g_declaring; // 1 while building a `declare`, 0 for a definition\n"
"\n"
"// Call being assembled.\n"
"typedef struct {\n"
"    LLVMValueRef args[MAX_CALL_ARGS];\n"
"    int count;\n"
"} CallFrame;\n"
"static CallFrame g_calls[MAX_CALL_DEPTH];\n"
"static int g_call_depth;\n"
"\n"
"static int g_has_returned;\n"
"\n"
"// ============================================================================\n"
"// Memory model policy\n"
"//\n"
"// Object allocation is deliberately indirect. The frontend asks for \"an object\n"
"// of this struct type\" and this layer decides what that means, so swapping\n"
"// malloc for an arena, a refcounting allocator, or anything else is a change\n"
"// here and not a change to codegen. Defaults keep today's behaviour exactly.\n"
"// ============================================================================\n"
"\n"
"static char g_alloc_fn[NAME_LEN] = \"malloc\";\n"
"static char g_free_fn[NAME_LEN] = \"free\";\n"
"\n"
"// Pointer-sized integer for the current target, in LLVM spelling. Set once per\n"
"// module from the front end's irPtrIntType(); i64 on every target so far.\n"
"// Determines the width of the size argument passed to the allocator.\n"
"static char g_ptr_int[16] = \"i64\";\n"
"\n"
"void ir_set_pointer_int_type(const char *t) {\n"
"    if (t && *t) {\n"
"        strncpy(g_ptr_int, t, sizeof(g_ptr_int) - 1);\n"
"        g_ptr_int[sizeof(g_ptr_int) - 1] = '\\0';\n"
"    }\n"
"}\n"
"\n"
"void ir_set_alloc_function(const char *name) {\n"
"    if (name && *name) {\n"
"        strncpy(g_alloc_fn, name, NAME_LEN - 1);\n"
"        g_alloc_fn[NAME_LEN - 1] = '\\0';\n"
"    }\n"
"}\n"
"\n"
"void ir_set_free_function(const char *name) {\n"
"    if (name && *name) {\n"
"        strncpy(g_free_fn, name, NAME_LEN - 1);\n"
"        g_free_fn[NAME_LEN - 1] = '\\0';\n"
"    }\n"
"}\n"
"\n"
"const char *ir_get_alloc_function(void) { return g_alloc_fn; }\n"
"const char *ir_get_free_function(void) { return g_free_fn; }\n"
"\n"
"// The LLVM actually loaded, for `prismio --version`. Reported rather than\n"
"// hardcoded so a version mismatch is visible without having to trigger it.\n"
"const char *ir_llvm_version(void) {\n"
"    static char buf[32];\n"
"    unsigned major = 0, minor = 0, patch = 0;\n"
"    LLVMGetVersion(&major, &minor, &patch);\n"
"    snprintf(buf, sizeof(buf), \"%u.%u.%u\", major, minor, patch);\n"
"    return buf;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Diagnostics\n"
"// ============================================================================\n"
"\n"
"static void backend_fail(const char *what, const char *detail) {\n"
"    fprintf(stderr, \"internal backend error: %s\", what);\n"
"    if (detail) fprintf(stderr, \" (%s)\", detail);\n"
"    fprintf(stderr, \"\\n\");\n"
"    exit(1);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Value table\n"
"// ============================================================================\n"
"\n"
"// Doubling, and the allocation is kept across ir_reset() -- a second module in\n"
"// one process is bootstrap, and it needs the same room the first one did.\n"
"static void grow_table(void **items, int *capacity, int wanted, size_t item_size,\n"
"                       int initial, const char *what) {\n"
"    if (wanted < *capacity) return;\n"
"    int next = *capacity ? *capacity * 2 : initial;\n"
"    while (next <= wanted) next *= 2;\n"
"    void *grown = realloc(*items, (size_t)next * item_size);\n"
"    if (!grown) backend_fail(\"out of memory growing\", what);\n"
"    // New slots are zeroed: block_for() reads a slot to decide whether the block\n"
"    // has been materialised, and ir_get_label() only clears the one it hands out.\n"
"    memset((char *)grown + (size_t)*capacity * item_size, 0,\n"
"           (size_t)(next - *capacity) * item_size);\n"
"    *items = grown;\n"
"    *capacity = next;\n"
"}\n"
"\n"
"static int intern_value(LLVMValueRef v) {\n"
"    grow_table((void **)&g_values, &g_value_capacity, g_value_count,\n"
"               sizeof(LLVMValueRef), INITIAL_VALUES, \"the value table\");\n"
"    g_values[g_value_count] = v;\n"
"    return g_value_count++;\n"
"}\n"
"\n"
"const char *ir_get_temp_name(int id) {\n"
"    char *out = (char *)malloc(32);\n"
"    snprintf(out, 32, \"$$v%d\", id);\n"
"    return out;\n"
"}\n"
"\n"
"const char *ir_get_label_name(int id) {\n"
"    char *out = (char *)malloc(32);\n"
"    snprintf(out, 32, \"label_%d\", id);\n"
"    return out;\n"
"}\n"
"\n"
"// Reserves a slot without an instruction behind it yet.\n"
"int ir_get_temp(void) { return intern_value(NULL); }\n"
"\n"
"// ============================================================================\n"
"// Types\n"
"// ============================================================================\n"
"\n"
"static LLVMTypeRef named_struct(const char *name);\n"
"\n"
"// Maps the frontend's type keys (\"i32\", \"double\", \"ptr\", \"struct:Foo\") onto\n"
"// LLVM types. Unknown keys are a hard error rather than a silent i32, which is\n"
"// what the text backend defaulted to.\n"
"static LLVMTypeRef type_from_key(const char *t) {\n"
"    if (!t || !*t) return LLVMVoidTypeInContext(g_ctx);\n"
"    if (strcmp(t, \"void\") == 0) return LLVMVoidTypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i1\") == 0) return LLVMInt1TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i8\") == 0) return LLVMInt8TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i16\") == 0) return LLVMInt16TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i32\") == 0) return LLVMInt32TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"i64\") == 0) return LLVMInt64TypeInContext(g_ctx);\n"
"    if (strcmp(t, \"double\") == 0) return LLVMDoubleTypeInContext(g_ctx);\n"
"    if (strcmp(t, \"ptr\") == 0 || strcmp(t, \"ptrptr\") == 0)\n"
"        return LLVMPointerTypeInContext(g_ctx, 0);\n"
"    if (strncmp(t, \"struct:\", 7) == 0) return named_struct(t + 7);\n"
"    if (t[0] == '%') return named_struct(t + 1);\n"
"    backend_fail(\"unknown type key\", t);\n"
"    return NULL;\n"
"}\n"
"\n"
"// --- named struct types -----------------------------------------------------\n"
"\n"
"// LAYOUT 6's hot/cold split lives entirely in this table.\n"
"//\n"
"// `hot_count` is 0 for every type the search left alone, and otherwise the number\n"
"// of fields the hot record keeps. The hot record then carries **one extra\n"
"// element**, a pointer at index `hot_count`, and `cold` is the separately\n"
"// allocated block it points at. That is LAYOUT 5.2.1's *linked* split: one\n"
"// pointer still reaches the whole object, which is exactly why this needs no\n"
"// handles and why it is emittable today.\n"
"//\n"
"// Codegen never learns any of it. The frontend emits fields in the order\n"
"// `aif_layout_field` hands it -- hot ones first -- and indexes them from 0, so a\n"
"// field index below `hot_count` is a GEP into the hot record and one at or above\n"
"// it is a load of the link followed by a GEP into `cold`. `ir_struct_field_ptr`\n"
"// is the single choke point for field access, which is what keeps the whole\n"
"// transform inside this file instead of in a pass over the IR.\n"
"typedef struct {\n"
"    char name[NAME_LEN];\n"
"    LLVMTypeRef type;\n"
"    LLVMTypeRef cold;   // NULL unless split\n"
"    int hot_count;      // 0 unless split\n"
"} StructType;\n"
"\n"
"static StructType g_structs[256];\n"
"static int g_struct_count;\n"
"\n"
"static StructType *struct_entry(const char *name) {\n"
"    for (int i = 0; i < g_struct_count; i++) {\n"
"        if (strcmp(g_structs[i].name, name) == 0) return &g_structs[i];\n"
"    }\n"
"    if (g_struct_count >= 256) backend_fail(\"too many struct types\", name);\n"
"    // Created opaque; the body is set by ir_struct_type_end().\n"
"    LLVMTypeRef ty = LLVMStructCreateNamed(g_ctx, name);\n"
"    strncpy(g_structs[g_struct_count].name, name, NAME_LEN - 1);\n"
"    g_structs[g_struct_count].name[NAME_LEN - 1] = '\\0';\n"
"    g_structs[g_struct_count].type = ty;\n"
"    g_structs[g_struct_count].cold = NULL;\n"
"    g_structs[g_struct_count].hot_count = 0;\n"
"    return &g_structs[g_struct_count++];\n"
"}\n"
"\n"
"static LLVMTypeRef named_struct(const char *name) { return struct_entry(name)->type; }\n"
"\n"
"static LLVMTypeRef g_struct_fields[64];\n"
"static int g_struct_field_count;\n"
"static char g_struct_building[NAME_LEN];\n"
"static int g_struct_split;\n"
"\n"
"void ir_struct_type_begin(const char *name) {\n"
"    strncpy(g_struct_building, name, NAME_LEN - 1);\n"
"    g_struct_building[NAME_LEN - 1] = '\\0';\n"
"    g_struct_field_count = 0;\n"
"    // Cleared here as well as in ir_struct_type_end, so a type emitted without a\n"
"    // split call cannot inherit the previous type's cut.\n"
"    g_struct_split = 0;\n"
"}\n"
"\n"
"void ir_struct_type_field(const char *field_type) {\n"
"    if (g_struct_field_count >= 64) backend_fail(\"too many struct fields\", g_struct_building);\n"
"    g_struct_fields[g_struct_field_count++] = type_from_key(field_type);\n"
"}\n"
"\n"
"// How many of the fields just declared stay in the hot record. 0, or a count\n"
"// covering the whole field list, means no split. Called between the last\n"
"// ir_struct_type_field and ir_struct_type_end.\n"
"void ir_struct_type_split(int hot_count) { g_struct_split = hot_count; }\n"
"\n"
"void ir_struct_type_end(void) {\n"
"    StructType *s = struct_entry(g_struct_building);\n"
"    int hc = g_struct_split;\n"
"    g_struct_split = 0;\n"
"\n"
"    if (hc <= 0 || hc >= g_struct_field_count) {\n"
"        s->hot_count = 0;\n"
"        s->cold = NULL;\n"
"        LLVMStructSetBody(s->type, g_struct_fields, (unsigned)g_struct_field_count, 0);\n"
"        return;\n"
"    }\n"
"\n"
"    char cold_name[NAME_LEN];\n"
"    snprintf(cold_name, sizeof(cold_name), \"%s.cold\", g_struct_building);\n"
"    LLVMTypeRef cold = LLVMStructCreateNamed(g_ctx, cold_name);\n"
"    LLVMStructSetBody(cold, &g_struct_fields[hc], (unsigned)(g_struct_field_count - hc), 0);\n"
"\n"
"    // The link word is **appended, not prepended**, so field 0 of the hot record\n"
"    // is still byte 0 of the object. tests/test_41_punned_slot_bytes.psm reads the\n"
"    // first byte of the pointed-to struct and this must not move it.\n"
"    LLVMTypeRef hot_fields[65];\n"
"    for (int i = 0; i < hc; i++) hot_fields[i] = g_struct_fields[i];\n"
"    hot_fields[hc] = LLVMPointerTypeInContext(g_ctx, 0);\n"
"    LLVMStructSetBody(s->type, hot_fields, (unsigned)(hc + 1), 0);\n"
"\n"
"    s->hot_count = hc;\n"
"    s->cold = cold;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Value resolution\n"
"// ============================================================================\n"
"\n"
"static LLVMValueRef lookup_named(NamedValue *table, int count, const char *name,\n"
"                                 LLVMTypeRef *out_type) {\n"
"    for (int i = 0; i < count; i++) {\n"
"        if (strcmp(table[i].name, name) == 0) {\n"
"            if (out_type) *out_type = table[i].type;\n"
"            return table[i].value;\n"
"        }\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"static LLVMValueRef const_from_text(const char *s, LLVMTypeRef ty) {\n"
"    if (!ty) backend_fail(\"constant with no type\", s);\n"
"    if (ty == LLVMDoubleTypeInContext(g_ctx)) return LLVMConstReal(ty, atof(s));\n"
"    if (ty == LLVMPointerTypeInContext(g_ctx, 0)) {\n"
"        if (strcmp(s, \"null\") == 0 || strcmp(s, \"0\") == 0) return LLVMConstPointerNull(ty);\n"
"        backend_fail(\"non-null pointer constant\", s);\n"
"    }\n"
"    if (strcmp(s, \"true\") == 0) return LLVMConstInt(ty, 1, 0);\n"
"    if (strcmp(s, \"false\") == 0) return LLVMConstInt(ty, 0, 0);\n"
"    return LLVMConstInt(ty, (unsigned long long)strtoll(s, NULL, 10), 1);\n"
"}\n"
"\n"
"// The single place that turns a frontend string into an LLVMValueRef.\n"
"static LLVMValueRef resolve_value(const char *s, const char *type_key) {\n"
"    if (!s) backend_fail(\"null value\", NULL);\n"
"\n"
"    if (s[0] == '$' && s[1] == '$' && s[2] == 'v') {\n"
"        int idx = atoi(s + 3);\n"
"        if (idx < 0 || idx >= g_value_count) backend_fail(\"value handle out of range\", s);\n"
"        LLVMValueRef v = g_values[idx];\n"
"        if (!v) backend_fail(\"value handle refers to an unset slot\", s);\n"
"        return v;\n"
"    }\n"
"\n"
"    if (s[0] == '%') {\n"
"        const char *name = s + 1;\n"
"        LLVMValueRef v = lookup_named(g_params, g_param_count, name, NULL);\n"
"        if (v) return v;\n"
"        v = lookup_named(g_allocas, g_alloca_count, name, NULL);\n"
"        if (v) return v;\n"
"        backend_fail(\"unknown local name\", s);\n"
"    }\n"
"\n"
"    return const_from_text(s, type_from_key(type_key));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Module lifecycle\n"
"// ============================================================================\n"
"\n"
"static void reset_state(void) {\n"
"    g_value_count = 0;\n"
"    g_label_count = 0;\n"
"    g_alloca_count = 0;\n"
"    g_param_count = 0;\n"
"    g_struct_count = 0;\n"
"    g_call_depth = 0;\n"
"    g_has_returned = 0;\n"
"    g_function = NULL;\n"
"    g_pending_param_count = 0;\n"
"}\n"
"\n"
"// Declared here because the debug section is further down the file and this is\n"
"// the one place outside it that has to know debug info exists: a DIBuilder holds\n"
"// metadata owned by the module it was created from, so it cannot outlive it.\n"
"static void debug_dispose(void);\n"
"static void debug_clear_location(void);\n"
"\n"
"void ir_reset(void) {\n"
"    debug_dispose();\n"
"    if (g_module) {\n"
"        LLVMDisposeModule(g_module);\n"
"        g_module = NULL;\n"
"    }\n"
"    reset_state();\n"
"}\n"
"\n"
"// Refuses to run against an LLVM whose major version is not the pinned one.\n"
"//\n"
"// Checked here rather than only at build time because the dangerous mismatch is\n"
"// between the headers this was compiled against and the LLVM-C library actually\n"
"// loaded: that links cleanly and then misbehaves in ways that look like compiler\n"
"// bugs. On Windows in particular, any LLVM-C.dll earlier on PATH wins.\n"
"static void check_llvm_version(void) {\n"
"    unsigned major = 0, minor = 0, patch = 0;\n"
"    LLVMGetVersion(&major, &minor, &patch);\n"
"    if ((int)major != PRISMIO_LLVM_EXPECTED_MAJOR) {\n"
"        fprintf(stderr,\n"
"                \"error: this Prismio was built for LLVM %d, but LLVM %u.%u.%u is loaded.\\n\"\n"
"                \"  The LLVM C API is only stable within a major version.\\n\"\n"
"                \"  Run: python tools/setup_llvm.py\\n\",\n"
"                PRISMIO_LLVM_EXPECTED_MAJOR, major, minor, patch);\n"
"        exit(1);\n"
"    }\n"
"}\n"
"\n"
"static void ensure_context(void) {\n"
"    if (g_initialized) return;\n"
"    check_llvm_version();\n"
"    g_ctx = LLVMContextCreate();\n"
"    g_builder = LLVMCreateBuilderInContext(g_ctx);\n"
"    g_alloca_builder = LLVMCreateBuilderInContext(g_ctx);\n"
"    g_initialized = 1;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Targets\n"
"//\n"
"// The compiler's whole notion of a target is three facts -- triple, pointer\n"
"// width, data layout -- and every one of them is answered by LLVM from the\n"
"// triple rather than by a table in this repo. A table would be a second copy of\n"
"// something LLVM already owns, and a wrong row here is a *miscompile*: an\n"
"// allocation sized for the wrong pointer, or member offsets four bytes out. The\n"
"// frontend reads all three back as one record (see src/ir/target.psm); this is\n"
"// the only place they are stored, so the two cannot drift.\n"
"//\n"
"// The host is resolved lazily, on the first question anyone asks, and is marked\n"
"// not-explicit: a build that never passed --target must emit exactly the module\n"
"// it emitted before targets existed, which means no triple and no layout stamped\n"
"// on it. Only an explicitly named target stamps.\n"
"//\n"
"// Without real headers (see prismio_llvm.h) nothing here can resolve anything.\n"
"// The host then falls back to 64-bit with no triple -- which is what the\n"
"// frontend hardcoded before this existed, so that path is unchanged -- and an\n"
"// explicit --target fails loudly rather than guessing.\n"
"// ============================================================================\n"
"\n"
"static char g_target_triple[256];\n"
"static char g_target_layout[1024];\n"
"static int  g_target_ptr_bits;\n"
"static int  g_target_explicit;\n"
"static int  g_target_selected;\n"
"\n"
"#ifdef PRISMIO_TARGETS\n"
"static void ensure_all_targets(void) {\n"
"    static int done = 0;\n"
"    if (done) return;\n"
"    LLVMInitializeAllTargetInfos();\n"
"    LLVMInitializeAllTargets();\n"
"    LLVMInitializeAllTargetMCs();\n"
"    done = 1;\n"
"}\n"
"#endif\n"
"\n"
"// triple == NULL or \"\" selects the host. Returns 0 if LLVM does not recognise\n"
"// the triple, in which case nothing is changed and the caller must stop.\n"
"int ir_target_select(const char *triple) {\n"
"    int want_host = !triple || !*triple;\n"
"#ifdef PRISMIO_TARGETS\n"
"    ensure_all_targets();\n"
"\n"
"    char *host = want_host ? LLVMGetDefaultTargetTriple() : NULL;\n"
"    const char *use = want_host ? host : triple;\n"
"\n"
"    LLVMTargetRef target = NULL;\n"
"    char *err = NULL;\n"
"    if (!use || LLVMGetTargetFromTriple(use, &target, &err)) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        if (host) LLVMDisposeMessage(host);\n"
"        if (want_host) {\n"
"            // The host is unresolvable only on a broken LLVM. Fall back to the\n"
"            // width the frontend assumed before targets existed rather than\n"
"            // failing a build that never asked for a target in the first place.\n"
"            g_target_triple[0] = '\\0';\n"
"            g_target_layout[0] = '\\0';\n"
"            g_target_ptr_bits = 64;\n"
"            g_target_explicit = 0;\n"
"            g_target_selected = 1;\n"
"            return 1;\n"
"        }\n"
"        return 0;\n"
"    }\n"
"\n"
"    LLVMTargetMachineRef tm = LLVMCreateTargetMachine(\n"
"        target, use, \"\", \"\", LLVMCodeGenLevelDefault, LLVMRelocDefault,\n"
"        LLVMCodeModelDefault);\n"
"    LLVMTargetDataRef td = LLVMCreateTargetDataLayout(tm);\n"
"    char *rep = LLVMCopyStringRepOfTargetData(td);\n"
"\n"
"    snprintf(g_target_triple, sizeof(g_target_triple), \"%s\", use);\n"
"    snprintf(g_target_layout, sizeof(g_target_layout), \"%s\", rep ? rep : \"\");\n"
"    g_target_ptr_bits = (int)LLVMPointerSize(td) * 8;\n"
"    g_target_explicit = want_host ? 0 : 1;\n"
"    g_target_selected = 1;\n"
"\n"
"    if (rep) LLVMDisposeMessage(rep);\n"
"    LLVMDisposeTargetData(td);\n"
"    LLVMDisposeTargetMachine(tm);\n"
"    if (host) LLVMDisposeMessage(host);\n"
"    return 1;\n"
"#else\n"
"    if (!want_host) return 0;\n"
"    g_target_triple[0] = '\\0';\n"
"    g_target_layout[0] = '\\0';\n"
"    g_target_ptr_bits = 64;\n"
"    g_target_explicit = 0;\n"
"    g_target_selected = 1;\n"
"    return 1;\n"
"#endif\n"
"}\n"
"\n"
"static void ensure_target(void) {\n"
"    if (!g_target_selected) ir_target_select(NULL);\n"
"}\n"
"\n"
"const char *ir_target_triple(void) { ensure_target(); return g_target_triple; }\n"
"const char *ir_target_data_layout(void) { ensure_target(); return g_target_layout; }\n"
"int ir_target_pointer_bits(void) { ensure_target(); return g_target_ptr_bits; }\n"
"int ir_target_is_explicit(void) { ensure_target(); return g_target_explicit; }\n"
"\n"
"// Stamps a named target onto the module being built, which is what makes -g and\n"
"// clang agree about it: pin_data_layout() below leaves an existing layout alone,\n"
"// so a cross build's member offsets come from the target rather than the host.\n"
"void ir_module_set_target(const char *triple, const char *layout) {\n"
"    if (!g_module) backend_fail(\"ir_module_set_target with no module\", triple);\n"
"    if (triple && *triple) LLVMSetTarget(g_module, triple);\n"
"    if (layout && *layout) LLVMSetDataLayout(g_module, layout);\n"
"}\n"
"\n"
"void ir_module_start(const char *module_name) {\n"
"    ensure_context();\n"
"    reset_state();\n"
"    g_module = LLVMModuleCreateWithNameInContext(module_name, g_ctx);\n"
"    LLVMSetSourceFileName(g_module, \"prismio_generated\", strlen(\"prismio_generated\"));\n"
"#ifdef _WIN32\n"
"    // Pinned only on Windows, where msvc and mingw are a real fork and msvc is\n"
"    // the configuration that is actually verified. Elsewhere LLVM's own host\n"
"    // triple is a better answer than a guess. Matches the text backend.\n"
"    //\n"
"    // Still a #ifdef and not a row in the target record above, because this is\n"
"    // the *implicit host* case and changing it would change the IR every\n"
"    // Windows build emits -- on the one platform none of this was tested on.\n"
"    // `--target x86_64-pc-windows-msvc` goes through the record like any other\n"
"    // named target; moving the default there is a job for someone with the box.\n"
"    LLVMSetTarget(g_module, \"x86_64-pc-windows-msvc\");\n"
"#endif\n"
"}\n"
"\n"
"void ir_module_end(void) { /* nothing to flush -- the module is already built */ }\n"
"\n"
"// ============================================================================\n"
"// Functions\n"
"// ============================================================================\n"
"\n"
"static int g_pending_param_noalias[MAX_PENDING_PARAMS];\n"
"\n"
"void ir_function_begin(const char *name, const char *ret_type) {\n"
"    strncpy(g_pending_fn_name, name, NAME_LEN - 1);\n"
"    g_pending_fn_name[NAME_LEN - 1] = '\\0';\n"
"    g_pending_ret = type_from_key(ret_type);\n"
"    g_pending_param_count = 0;\n"
"    memset(g_pending_param_noalias, 0, sizeof(g_pending_param_noalias));\n"
"    g_declaring = 0;\n"
"}\n"
"\n"
"void ir_declare_function_begin(const char *name, const char *ret_type) {\n"
"    ir_function_begin(name, ret_type);\n"
"    g_declaring = 1;\n"
"}\n"
"\n"
"void ir_function_param(const char *param_type, const char *param_name) {\n"
"    if (g_pending_param_count >= MAX_PENDING_PARAMS)\n"
"        backend_fail(\"too many parameters\", g_pending_fn_name);\n"
"    g_pending_params[g_pending_param_count] = type_from_key(param_type);\n"
"    strncpy(g_pending_param_names[g_pending_param_count], param_name ? param_name : \"\",\n"
"            NAME_LEN - 1);\n"
"    g_pending_param_names[g_pending_param_count][NAME_LEN - 1] = '\\0';\n"
"    g_pending_param_count++;\n"
"}\n"
"\n"
"void ir_declare_function_param(const char *param_type) {\n"
"    ir_function_param(param_type, \"\");\n"
"}\n"
"\n"
"// SPEC 5.1's `unique`, which already means \"exactly one reference exists, and it\n"
"// owns\". `noalias` is that fact spelled for LLVM, so this is a lowering of an\n"
"// existing annotation rather than a new one -- SPEC 11 item 7's four stay four.\n"
"//\n"
"// It is an axiom, not a proof: the solver takes A = Unique as given and the\n"
"// affine discipline discharges the local half, but nothing checks that a caller\n"
"// passes distinct pointers. semaCheckUniqueArgs rejects the reachable half of\n"
"// that -- the same name given to two `unique` parameters of one call.\n"
"void ir_function_param_unique(const char *param_type, const char *param_name) {\n"
"    int i = g_pending_param_count;\n"
"    ir_function_param(param_type, param_name);\n"
"    if (i < MAX_PENDING_PARAMS) g_pending_param_noalias[i] = 1;\n"
"}\n"
"\n"
"static void apply_param_attrs(LLVMValueRef fn) {\n"
"    unsigned kind = LLVMGetEnumAttributeKindForName(\"noalias\", 7);\n"
"    if (!kind) return;\n"
"    for (int i = 0; i < g_pending_param_count; i++) {\n"
"        if (!g_pending_param_noalias[i]) continue;\n"
"        LLVMAddAttributeAtIndex(fn, (unsigned)(i + 1),\n"
"                                LLVMCreateEnumAttribute(g_ctx, kind, 0));\n"
"    }\n"
"}\n"
"\n"
"static LLVMValueRef materialize_function(void) {\n"
"    LLVMTypeRef fnty = LLVMFunctionType(g_pending_ret, g_pending_params,\n"
"                                        (unsigned)g_pending_param_count, 0);\n"
"    LLVMValueRef existing = LLVMGetNamedFunction(g_module, g_pending_fn_name);\n"
"    if (existing) return existing; // a forward `declare` already created it\n"
"    return LLVMAddFunction(g_module, g_pending_fn_name, fnty);\n"
"}\n"
"\n"
"void ir_declare_function_end(void) { materialize_function(); }\n"
"\n"
"void ir_function_body_start(void) {\n"
"    g_function = materialize_function();\n"
"    apply_param_attrs(g_function);\n"
"    // Whatever the previous function left set belongs to the previous function's\n"
"    // subprogram. Attaching it to an instruction here is not a slightly wrong\n"
"    // line, it is a module the verifier rejects -- so it is cleared before the\n"
"    // first instruction rather than trusted to be cleared on the way out.\n"
"    debug_clear_location();\n"
"    g_alloca_count = 0;\n"
"    g_param_count = 0;\n"
"    g_has_returned = 0;\n"
"\n"
"    g_entry_block = LLVMAppendBasicBlockInContext(g_ctx, g_function, \"entry\");\n"
"    LLVMPositionBuilderAtEnd(g_builder, g_entry_block);\n"
"\n"
"    for (int i = 0; i < g_pending_param_count; i++) {\n"
"        if (!g_pending_param_names[i][0]) continue;\n"
"        strncpy(g_params[g_param_count].name, g_pending_param_names[i], NAME_LEN - 1);\n"
"        g_params[g_param_count].name[NAME_LEN - 1] = '\\0';\n"
"        g_params[g_param_count].value = LLVMGetParam(g_function, (unsigned)i);\n"
"        g_params[g_param_count].type = g_pending_params[i];\n"
"        g_param_count++;\n"
"    }\n"
"}\n"
"\n"
"void ir_function_end(void) {\n"
"    // A function whose last block has no terminator is invalid. The frontend is\n"
"    // responsible for the return, but guard anyway so the verifier reports\n"
"    // something more useful than a malformed block.\n"
"    LLVMBasicBlockRef bb = LLVMGetInsertBlock(g_builder);\n"
"    if (bb && !LLVMGetBasicBlockTerminator(bb)) LLVMBuildUnreachable(g_builder);\n"
"    g_function = NULL;\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Basic blocks\n"
"// ============================================================================\n"
"\n"
"int ir_get_label(void) {\n"
"    grow_table((void **)&g_blocks, &g_label_capacity, g_label_count,\n"
"               sizeof(LLVMBasicBlockRef), INITIAL_LABELS, \"the block table\");\n"
"    g_blocks[g_label_count] = NULL;\n"
"    return g_label_count++;\n"
"}\n"
"\n"
"static LLVMBasicBlockRef block_for(int id) {\n"
"    if (id < 0 || id >= g_label_count) backend_fail(\"label out of range\", NULL);\n"
"    if (!g_blocks[id]) {\n"
"        char name[32];\n"
"        snprintf(name, sizeof(name), \"label_%d\", id);\n"
"        g_blocks[id] = LLVMAppendBasicBlockInContext(g_ctx, g_function, name);\n"
"    }\n"
"    return g_blocks[id];\n"
"}\n"
"\n"
"// True when the block being written already ends in a terminator, meaning any\n"
"// further instruction would be unreachable. The text backend happily wrote past\n"
"// this point and produced invalid IR; here the write is dropped instead, so a\n"
"// stray statement after `return` cannot corrupt the module.\n"
"static int block_done(void) {\n"
"    LLVMBasicBlockRef bb = LLVMGetInsertBlock(g_builder);\n"
"    return !bb || LLVMGetBasicBlockTerminator(bb) != NULL;\n"
"}\n"
"\n"
"void ir_label_numbered(int id) { LLVMPositionBuilderAtEnd(g_builder, block_for(id)); }\n"
"\n"
"void ir_label(const char *name) { (void)name; /* numbered labels only */ }\n"
"\n"
"void ir_br_numbered(int target) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildBr(g_builder, block_for(target));\n"
"}\n"
"\n"
"void ir_cond_br_numbered(const char *cond, int t, int f) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildCondBr(g_builder, resolve_value(cond, \"i1\"), block_for(t), block_for(f));\n"
"}\n"
"\n"
"void ir_br(const char *label) { (void)label; backend_fail(\"named branches are not supported\", label); }\n"
"void ir_cond_br(const char *c, const char *t, const char *f) {\n"
"    (void)c; (void)t; (void)f;\n"
"    backend_fail(\"named branches are not supported\", NULL);\n"
"}\n"
"\n"
"void ir_ret(const char *type, const char *value) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildRet(g_builder, resolve_value(value, type));\n"
"}\n"
"\n"
"void ir_ret_void(void) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildRetVoid(g_builder);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Memory\n"
"// ============================================================================\n"
"\n"
"int ir_alloca(const char *type, const char *name) {\n"
"    for (int i = 0; i < g_alloca_count; i++) {\n"
"        if (strcmp(g_allocas[i].name, name) == 0) return -1; // already allocated\n"
"    }\n"
"    if (g_alloca_count >= MAX_NAMED) backend_fail(\"too many locals\", name);\n"
"\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"\n"
"    // Always emitted in the entry block, wherever codegen currently is. The\n"
"    // frontend now creates each local at its declaration, which for a `let`\n"
"    // inside a loop body would otherwise allocate again on every iteration.\n"
"    // Inserted before the entry block's terminator once it has one, so the\n"
"    // alloca cannot end up after a branch.\n"
"    LLVMValueRef entry_term = LLVMGetBasicBlockTerminator(g_entry_block);\n"
"    if (entry_term) {\n"
"        LLVMPositionBuilderBefore(g_alloca_builder, entry_term);\n"
"    } else {\n"
"        LLVMPositionBuilderAtEnd(g_alloca_builder, g_entry_block);\n"
"    }\n"
"    LLVMValueRef slot = LLVMBuildAlloca(g_alloca_builder, ty, name);\n"
"\n"
"    strncpy(g_allocas[g_alloca_count].name, name, NAME_LEN - 1);\n"
"    g_allocas[g_alloca_count].name[NAME_LEN - 1] = '\\0';\n"
"    g_allocas[g_alloca_count].value = slot;\n"
"    g_allocas[g_alloca_count].type = ty;\n"
"    g_alloca_count++;\n"
"    return intern_value(slot);\n"
"}\n"
"\n"
"int ir_load(const char *type, const char *ptr_name) {\n"
"    LLVMTypeRef ty = NULL;\n"
"    LLVMValueRef ptr = lookup_named(g_allocas, g_alloca_count, ptr_name, &ty);\n"
"    if (!ptr) {\n"
"        ptr = lookup_named(g_params, g_param_count, ptr_name, &ty);\n"
"    }\n"
"    if (!ptr) backend_fail(\"load from unknown local\", ptr_name);\n"
"    return intern_value(LLVMBuildLoad2(g_builder, type_from_key(type), ptr, \"\"));\n"
"}\n"
"\n"
"void ir_store(const char *type, const char *value, const char *ptr_name) {\n"
"    LLVMValueRef ptr = lookup_named(g_allocas, g_alloca_count, ptr_name, NULL);\n"
"    if (!ptr) ptr = lookup_named(g_params, g_param_count, ptr_name, NULL);\n"
"    if (!ptr) backend_fail(\"store to unknown local\", ptr_name);\n"
"    if (block_done()) return;\n"
"    LLVMBuildStore(g_builder, resolve_value(value, type), ptr);\n"
"}\n"
"\n"
"// Load/store through a pointer *value* rather than a named local. Struct fields\n"
"// and array elements are addresses produced by a GEP, so they have no name to\n"
"// look up -- the text backend reached them by emitting `store ... ptr %tN`\n"
"// directly, which is one of the things ir_append was being used for.\n"
"int ir_load_ptr(const char *type, const char *ptr_value) {\n"
"    return intern_value(\n"
"        LLVMBuildLoad2(g_builder, type_from_key(type), resolve_value(ptr_value, \"ptr\"), \"\"));\n"
"}\n"
"\n"
"void ir_store_ptr(const char *type, const char *value, const char *ptr_value) {\n"
"    if (block_done()) return;\n"
"    LLVMBuildStore(g_builder, resolve_value(value, type), resolve_value(ptr_value, \"ptr\"));\n"
"}\n"
"\n"
"// An inline struct field is storage, not a slot holding an address, so writing\n"
"// one copies bytes. The counterpart of ir_store_ptr for a field whose registered\n"
"// type is `struct:T` rather than `ptr`.\n"
"//\n"
"// The alignment is read back from the module's data layout rather than assumed,\n"
"// because it is the number LLVM placed the field at -- see the note on\n"
"// LLVMBuildMemCpy in prismio_llvm.h for the case that makes 8 wrong.\n"
"void ir_copy_struct(const char *struct_name, const char *dest, const char *src) {\n"
"    if (block_done()) return;\n"
"    // An inline struct field is the only caller, and `aif_layout_split_select`\n"
"    // vetoes every type that appears as one -- so this is unreachable rather than\n"
"    // guarded. It is spelled out because the failure it prevents is silent:\n"
"    // copying a split record copies its *link*, so two objects would share one\n"
"    // cold block and the second release would be a double free.\n"
"    if (struct_entry(struct_name)->hot_count > 0)\n"
"        backend_fail(\"byte-copy of a split struct\", struct_name);\n"
"    LLVMTypeRef sty = named_struct(struct_name);\n"
"    unsigned align = LLVMABIAlignmentOfType(LLVMGetModuleDataLayout(g_module), sty);\n"
"    LLVMBuildMemCpy(g_builder,\n"
"                    resolve_value(dest, \"ptr\"), align,\n"
"                    resolve_value(src, \"ptr\"), align,\n"
"                    LLVMSizeOf(sty));\n"
"}\n"
"\n"
"static LLVMValueRef global_named(const char *name, LLVMTypeRef ty) {\n"
"    LLVMValueRef g = LLVMGetNamedGlobal(g_module, name);\n"
"    if (!g) {\n"
"        g = LLVMAddGlobal(g_module, ty, name);\n"
"        LLVMSetInitializer(g, LLVMConstNull(ty));\n"
"    }\n"
"    return g;\n"
"}\n"
"\n"
"int ir_load_global(const char *type, const char *name) {\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"    return intern_value(LLVMBuildLoad2(g_builder, ty, global_named(name, ty), \"\"));\n"
"}\n"
"\n"
"void ir_store_global(const char *type, const char *value, const char *name) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"    LLVMBuildStore(g_builder, resolve_value(value, type), global_named(name, ty));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Object allocation -- the memory-model seam\n"
"// ============================================================================\n"
"\n"
"// Allocates one object of a struct type through the configured allocator.\n"
"// Replaces the hand-written getelementptr-null / ptrtoint / call malloc text\n"
"// the frontend used to emit, and is the single place a different memory model\n"
"// needs to change.\n"
"// AIF T0: the value does not outlive the activation record that creates it, so\n"
"// it needs a stack slot and no allocation call at all (SPEC 3, T0 row).\n"
"//\n"
"// Hoisted to the entry block, like every other alloca here, because a literal\n"
"// inside a loop would otherwise allocate a fresh slot per iteration and grow the\n"
"// frame without bound. That means **one slot per site, reused by every\n"
"// iteration** -- which is only correct because T0 requires the value's escape to\n"
"// bottom at its own defining scope, i.e. nothing from one iteration is still\n"
"// reachable in the next. The escape module has to be right about that; when it\n"
"// was not, this was a miscompile rather than a slowdown (see aif_var_scope in\n"
"// aif_support.c).\n"
"//\n"
"// Unnamed and never deduplicated, unlike ir_alloca: two struct literals of the\n"
"// same type in one function are two values and need two slots.\n"
"int ir_alloc_stack(const char *struct_name) {\n"
"    StructType *s = struct_entry(struct_name);\n"
"    LLVMTypeRef sty = s->type;\n"
"\n"
"    LLVMValueRef entry_term = LLVMGetBasicBlockTerminator(g_entry_block);\n"
"    if (entry_term) {\n"
"        LLVMPositionBuilderBefore(g_alloca_builder, entry_term);\n"
"    } else {\n"
"        LLVMPositionBuilderAtEnd(g_alloca_builder, g_entry_block);\n"
"    }\n"
"\n"
"    LLVMValueRef hot = LLVMBuildAlloca(g_alloca_builder, sty, \"\");\n"
"    // A split T0 object is two slots and a link, not two allocations: nothing is\n"
"    // reclaimed at either one, so this is the one allocator hook the release path\n"
"    // has nothing to say about. Both slots are hoisted to the entry block for the\n"
"    // reason above, and the link store goes with them -- it must run before any\n"
"    // field access, and every field access is after the entry block by\n"
"    // construction.\n"
"    if (s->hot_count > 0) {\n"
"        LLVMValueRef cold = LLVMBuildAlloca(g_alloca_builder, s->cold, \"\");\n"
"        LLVMValueRef slot = LLVMBuildStructGEP2(g_alloca_builder, sty, hot,\n"
"                                                (unsigned)s->hot_count, \"\");\n"
"        LLVMBuildStore(g_alloca_builder, cold, slot);\n"
"    }\n"
"    return intern_value(hot);\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// The second half of a split object.\n"
"//\n"
"// Allocated through the **same allocator the hot record came from**, and that is\n"
"// the whole of the accounting argument. A verify build swaps `g_alloc_fn` and\n"
"// `g_free_fn` together, so both halves land in one ledger and a leaked cold block\n"
"// reads as a leak rather than as a number nobody compares. An arena build routes\n"
"// both to `arena_alloc`, so the region reclaims both in bulk and neither is ever\n"
"// handed to a deallocator.\n"
"//\n"
"// Emitted immediately after the hot allocation and before any field initialiser,\n"
"// because a struct literal's first cold field write is the next instruction.\n"
"// ---------------------------------------------------------------------------\n"
"static void attach_cold(const StructType *s, LLVMValueRef hot, const char *alloc_fn,\n"
"                        LLVMTypeRef size_ty) {\n"
"    if (!s || s->hot_count <= 0) return;\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(s->cold);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, alloc_fn);\n"
"    if (!fn) fn = LLVMAddFunction(g_module, alloc_fn, alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    LLVMValueRef cold = LLVMBuildCall2(g_builder, alloc_ty, fn, args, 1, \"\");\n"
"    LLVMValueRef slot = LLVMBuildStructGEP2(g_builder, s->type, hot,\n"
"                                            (unsigned)s->hot_count, \"\");\n"
"    LLVMBuildStore(g_builder, cold, slot);\n"
"}\n"
"\n"
"int ir_alloc_object(const char *struct_name) {\n"
"    StructType *s = struct_entry(struct_name);\n"
"    LLVMTypeRef sty = s->type;\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    // LLVMSizeOf yields an i64; narrow it when the target's size argument is\n"
"    // smaller, so the call matches the allocator's declared signature.\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, g_alloc_fn);\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, g_alloc_fn, alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    LLVMValueRef hot = LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\");\n"
"    attach_cold(s, hot, g_alloc_fn, size_ty);\n"
"    return intern_value(hot);\n"
"}\n"
"\n"
"// The third hook COMPILER-AUDIT 3 asked for. It expected `fn(arena, size) -> ptr`\n"
"// with the handle threaded from the enclosing region; the arena is dynamically\n"
"// scoped instead (see runtime/lang_runtime.c), so the signature stays\n"
"// `fn(size) -> ptr` and no frontend plumbing is needed to reach it.\n"
"//\n"
"// Unlike ir_alloc_object this does not read g_alloc_fn: a region allocation is a\n"
"// different obligation, not a different allocator, and routing it through the\n"
"// name swap would mean a verify build tried to account for memory the arena\n"
"// releases in bulk.\n"
"int ir_alloc_region(const char *struct_name) {\n"
"    StructType *s = struct_entry(struct_name);\n"
"    LLVMTypeRef sty = s->type;\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, \"arena_alloc\");\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, \"arena_alloc\", alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    LLVMValueRef hot = LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\");\n"
"    // Both halves from the arena, so the region's pop reclaims both and neither\n"
"    // is ever handed to a deallocator -- which is also why an arena-served split\n"
"    // site needs nothing at all from the release path.\n"
"    attach_cold(s, hot, \"arena_alloc\", size_ty);\n"
"    return intern_value(hot);\n"
"}\n"
"\n"
"// AIF Level 5, and the fourth hook. COMPILER-AUDIT 3 rated T3 only \"partly\"\n"
"// expressible through the seam because a count word changes struct layout, which\n"
"// named_struct and every ir_struct_field_ptr index would have to account for. A\n"
"// *prefix* header avoids that entirely -- the count sits in front of the pointer,\n"
"// the LLVM struct type is untouched, and what is left really is just a name.\n"
"//\n"
"// Like ir_alloc_region, this does not read g_alloc_fn. rc_alloc reaches the verify\n"
"// shim through the runtime's own rt_base_alloc, so both ends of the pairing swap\n"
"// together when the runtime is compiled -- the same arrangement Level 4 needed for\n"
"// strings, and for the same reason.\n"
"// **T3 is where a split cracks, and the fix has room already.** `rc_release`\n"
"// frees one block and cannot name the type -- a counted value's last holder is a\n"
"// container's teardown, which reaches `rc_release(e)` holding a bare pointer. The\n"
"// generated release is not on that path, so forcing `aif_type_releases` does not\n"
"// reach it either.\n"
"//\n"
"// The answer is the one `cyc_set_type` already uses: tell the object at\n"
"// construction. `RC_HDR` is 16 bytes with 8 in use, so the **byte offset of the\n"
"// link word fits in the spare word** -- no function pointer, no per-type table,\n"
"// and no extra call beyond the one allocating the cold block. `rc_release` then\n"
"// loads the cold pointer at that offset and frees it before the base.\n"
"//\n"
"// Offset 0 is the sentinel for \"not split\", and it is a sound one rather than a\n"
"// convenient one: field 0 is pinned hot and placed first, so a link word can\n"
"// never sit at byte 0 of any hot record.\n"
"static void attach_cold_rc(const StructType *s, LLVMValueRef hot, LLVMTypeRef size_ty) {\n"
"    if (!s || s->hot_count <= 0) return;\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    unsigned long long off = LLVMOffsetOfElement(LLVMGetModuleDataLayout(g_module),\n"
"                                                 s->type, (unsigned)s->hot_count);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(s->cold);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef params[3] = {ptr, size_ty, size_ty};\n"
"    LLVMTypeRef fn_ty = LLVMFunctionType(voidty, params, 3, 0);\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, \"rc_attach_cold\");\n"
"    if (!fn) fn = LLVMAddFunction(g_module, \"rc_attach_cold\", fn_ty);\n"
"\n"
"    LLVMValueRef args[3] = {hot, size, LLVMConstInt(size_ty, off, 0)};\n"
"    LLVMBuildCall2(g_builder, fn_ty, fn, args, 3, \"\");\n"
"}\n"
"\n"
"int ir_alloc_rc(const char *struct_name) {\n"
"    StructType *s = struct_entry(struct_name);\n"
"    LLVMTypeRef sty = s->type;\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, \"rc_alloc\");\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, \"rc_alloc\", alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    LLVMValueRef hot = LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\");\n"
"    attach_cold_rc(s, hot, size_ty);\n"
"    return intern_value(hot);\n"
"}\n"
"\n"
"// Region entry and exit. Emitted at every exit from the block, like the drops --\n"
"// a `return` out of a region that did not pop would leave the arena live for the\n"
"// rest of the program.\n"
"static void ir_arena_call(const char *name) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef fn_ty = LLVMFunctionType(voidty, NULL, 0, 0);\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, name);\n"
"    if (!fn) fn = LLVMAddFunction(g_module, name, fn_ty);\n"
"    LLVMBuildCall2(g_builder, fn_ty, fn, NULL, 0, \"\");\n"
"}\n"
"\n"
"void ir_region_begin(void) { ir_arena_call(\"arena_push\"); }\n"
"void ir_region_end(void)   { ir_arena_call(\"arena_pop\"); }\n"
"\n"
"// AIF Level 4. A string or a list is allocated inside the runtime, not through\n"
"// ir_alloc_region, so the site cannot pick the arena for itself. Bracketing the\n"
"// producing call says \"the allocation this one makes belongs to the region\", and\n"
"// the runtime bumps rather than calling malloc. Emitted around the call only;\n"
"// the arguments are already evaluated by then.\n"
"void ir_arena_hint_begin(void) { ir_arena_call(\"rt_arena_hint_push\"); }\n"
"void ir_arena_hint_end(void)   { ir_arena_call(\"rt_arena_hint_pop\"); }\n"
"\n"
"static void ir_release_call(const char *value, const char *fn_name) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMTypeRef free_ty = LLVMFunctionType(voidty, &ptr, 1, 0);\n"
"    LLVMValueRef free_fn = LLVMGetNamedFunction(g_module, fn_name);\n"
"    if (!free_fn) free_fn = LLVMAddFunction(g_module, fn_name, free_ty);\n"
"\n"
"    LLVMValueRef args[1] = {resolve_value(value, \"ptr\")};\n"
"    LLVMBuildCall2(g_builder, free_ty, free_fn, args, 1, \"\");\n"
"}\n"
"\n"
"void ir_free_object(const char *value) { ir_release_call(value, g_free_fn); }\n"
"\n"
"// LAYOUT 6's hot/cold split, the release half.\n"
"//\n"
"// A split object is two allocations and `ir_free_object` above frees one block\n"
"// while knowing nothing about its type -- so this is emitted immediately before\n"
"// it, from inside the generated `__aif_release_T`, which is the one place in the\n"
"// program where the pointer and the type are both in hand. `aif_type_releases` is\n"
"// forced true for every split type precisely so that this is on every path a\n"
"// split object can die by.\n"
"//\n"
"// A no-op for an unsplit type, which is what lets generateReleaseFn call it\n"
"// unconditionally: the frontend does not have to know which types were split, and\n"
"// therefore cannot get it wrong for one of them.\n"
"//\n"
"// Ordering is not cosmetic. The cold pointer lives *inside* the hot record, so\n"
"// reading it after the base has been freed is a use-after-free -- and in a verify\n"
"// build, a read of poisoned bytes handed straight to the deallocator.\n"
"void ir_free_cold(const char *struct_name, const char *value) {\n"
"    StructType *s = struct_entry(struct_name);\n"
"    if (s->hot_count <= 0) return;\n"
"    if (block_done()) return;\n"
"\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef obj = resolve_value(value, \"ptr\");\n"
"    LLVMValueRef slot = LLVMBuildStructGEP2(g_builder, s->type, obj,\n"
"                                            (unsigned)s->hot_count, \"\");\n"
"    LLVMValueRef cold = LLVMBuildLoad2(g_builder, ptr, slot, \"\");\n"
"\n"
"    LLVMTypeRef free_ty = LLVMFunctionType(voidty, &ptr, 1, 0);\n"
"    LLVMValueRef free_fn = LLVMGetNamedFunction(g_module, g_free_fn);\n"
"    if (!free_fn) free_fn = LLVMAddFunction(g_module, g_free_fn, free_ty);\n"
"\n"
"    LLVMValueRef args[1] = {cold};\n"
"    LLVMBuildCall2(g_builder, free_ty, free_fn, args, 1, \"\");\n"
"}\n"
"\n"
"// AIF Level 4. A list is a handle plus an element block, so the one-pointer\n"
"// deallocator the seam names cannot reclaim it. `list_release` is the runtime's\n"
"// own -- it frees both through the same allocator the list came from, which is\n"
"// what keeps a verify build's accounting balanced.\n"
"void ir_free_list(const char *value) { ir_release_call(value, \"list_release\"); }\n"
"\n"
"// Struct-field ownership. A struct that owns its fields is reclaimed by a\n"
"// function generated for its type, so the callee is named by the caller rather\n"
"// than fixed. It is still behind the seam: what that generated function frees,\n"
"// it frees through ir_free_object and its siblings.\n"
"void ir_free_typed(const char *value, const char *fn_name) { ir_release_call(value, fn_name); }\n"
"\n"
"// AIF Level 5. The decrement half, for a counted value held in a struct field.\n"
"void ir_free_rc(const char *value) { ir_release_call(value, \"rc_release\"); }\n"
"\n"
"// AIF T4a. The same release through the atomic entry point.\n"
"//\n"
"// A distinct symbol chosen at compile time rather than a flag tested at run\n"
"// time, which is the point of inferring thread affinity at all: SPEC 11\n"
"// item 10 keeps atomics off the common path, and a value proved never to cross\n"
"// a thread boundary should not pay even a predictable branch to establish that.\n"
"void ir_free_rc_atomic(const char *value) { ir_release_call(value, \"rc_release_atomic\"); }\n"
"\n"
"// AIF T4b. The fifth allocator hook, and a `fn(size) -> ptr` like the other\n"
"// four: the colour and the per-type descriptor go in front of the pointer, so\n"
"// the LLVM struct type is untouched and cyc_set_type fills them in afterwards --\n"
"// the same shape as list_set_elem_owner, and for the same reason.\n"
"int ir_alloc_cycle(const char *struct_name) {\n"
"    StructType *s = struct_entry(struct_name);\n"
"    // Not a fallback: `aif_layout_split_select` vetoes every type in a non-trivial\n"
"    // SCC, and a T4b site's type is in one by the tier's definition, so the two\n"
"    // sets are disjoint by construction. This is the assertion that says so out\n"
"    // loud -- if the veto is ever loosened, `cyc_free_object` calls the generated\n"
"    // release on the payload while the base is `payload - CYC_HDR`, and a split\n"
"    // would put a second block behind that asymmetry.\n"
"    if (s->hot_count > 0) backend_fail(\"split type reached the cycle allocator\", struct_name);\n"
"    LLVMTypeRef sty = s->type;\n"
"    LLVMTypeRef size_ty = type_from_key(g_ptr_int);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"\n"
"    LLVMValueRef size = LLVMSizeOf(sty);\n"
"    if (size_ty != LLVMInt64TypeInContext(g_ctx)) {\n"
"        size = LLVMBuildTrunc(g_builder, size, size_ty, \"\");\n"
"    }\n"
"\n"
"    LLVMTypeRef alloc_ty = LLVMFunctionType(ptr, &size_ty, 1, 0);\n"
"    LLVMValueRef alloc_fn = LLVMGetNamedFunction(g_module, \"cyc_alloc\");\n"
"    if (!alloc_fn) alloc_fn = LLVMAddFunction(g_module, \"cyc_alloc\", alloc_ty);\n"
"\n"
"    LLVMValueRef args[1] = {size};\n"
"    return intern_value(LLVMBuildCall2(g_builder, alloc_ty, alloc_fn, args, 1, \"\"));\n"
"}\n"
"\n"
"// An indirect call to a `fn(ptr) -> void` through a function pointer.\n"
"//\n"
"// The collector's visitor is a value rather than a name: the children function\n"
"// is generated per type, and the visitor differs per traversal phase, so the\n"
"// callee cannot be baked into the call.\n"
"void ir_call_indirect_ptr(const char *fn_value, const char *arg) {\n"
"    if (block_done()) return;\n"
"    LLVMTypeRef voidty = LLVMVoidTypeInContext(g_ctx);\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"    LLVMTypeRef fn_ty = LLVMFunctionType(voidty, &ptr, 1, 0);\n"
"    LLVMValueRef args[1] = {resolve_value(arg, \"ptr\")};\n"
"    LLVMBuildCall2(g_builder, fn_ty, resolve_value(fn_value, \"ptr\"), args, 1, \"\");\n"
"}\n"
"\n"
"// The address of a named function, as a value.\n"
"//\n"
"// Needed because a container of structs-with-owned-fields cannot be told its\n"
"// disposition with an int: the release differs per element *type*, and the\n"
"// runtime has no way to name a type. So it is told the function instead, which\n"
"// is the same \"the container is told, it cannot ask\" rule the int modes follow.\n"
"int ir_func_addr(const char *name) {\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, name);\n"
"    if (!fn) backend_fail(\"address of unknown function\", name);\n"
"    return intern_value(fn);\n"
"}\n"
"\n"
"// Field address within a struct object. Replaces emitted getelementptr text.\n"
"//\n"
"// **The single choke point for field access, and therefore the whole of the\n"
"// hot/cold redirection.** Codegen indexes fields 0..n-1 in the order\n"
"// `aif_layout_field` chose; when the type is split that order is hot fields\n"
"// first, so an index at or above `hot_count` is a cold field and is reached by\n"
"// loading the link and GEPing into the cold block instead. One dependent load,\n"
"// which is exactly what LAYOUT 5.2.1 prices a linked split at.\n"
"int ir_struct_field_ptr(const char *struct_name, const char *object, int field_index) {\n"
"    StructType *s = struct_entry(struct_name);\n"
"    LLVMValueRef obj = resolve_value(object, \"ptr\");\n"
"    if (field_index < 0) backend_fail(\"negative struct field index\", struct_name);\n"
"\n"
"    if (s->hot_count > 0 && field_index >= s->hot_count) {\n"
"        LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"        LLVMValueRef link = LLVMBuildStructGEP2(g_builder, s->type, obj,\n"
"                                                (unsigned)s->hot_count, \"\");\n"
"        LLVMValueRef cold = LLVMBuildLoad2(g_builder, ptr, link, \"\");\n"
"        return intern_value(LLVMBuildStructGEP2(g_builder, s->cold, cold,\n"
"                                                (unsigned)(field_index - s->hot_count), \"\"));\n"
"    }\n"
"\n"
"    return intern_value(\n"
"        LLVMBuildStructGEP2(g_builder, s->type, obj, (unsigned)field_index, \"\"));\n"
"}\n"
"\n"
"// Address of element `index` in a flat array of `elem_type`.\n"
"int ir_elem_ptr(const char *elem_type, const char *base, const char *index) {\n"
"    LLVMTypeRef ety = type_from_key(elem_type);\n"
"    LLVMValueRef idx[1] = {resolve_value(index, \"i32\")};\n"
"    return intern_value(\n"
"        LLVMBuildInBoundsGEP2(g_builder, ety, resolve_value(base, \"ptr\"), idx, 1, \"\"));\n"
"}\n"
"\n"
"// Stack array of `count` elements, yielding a pointer to the first element.\n"
"int ir_array_alloca(const char *elem_type, int count) {\n"
"    LLVMTypeRef ety = type_from_key(elem_type);\n"
"    LLVMTypeRef arr = LLVMArrayType2(ety, (uint64_t)count);\n"
"    LLVMValueRef slot = LLVMBuildAlloca(g_builder, arr, \"\");\n"
"    LLVMTypeRef i32 = LLVMInt32TypeInContext(g_ctx);\n"
"    LLVMValueRef idx[2] = {LLVMConstInt(i32, 0, 0), LLVMConstInt(i32, 0, 0)};\n"
"    return intern_value(LLVMBuildInBoundsGEP2(g_builder, arr, slot, idx, 2, \"\"));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Arithmetic, comparison, conversion\n"
"// ============================================================================\n"
"\n"
"#define BINOP(fn_name, builder_call)                                                   \\\n"
"    int fn_name(const char *type, const char *lhs, const char *rhs) {                  \\\n"
"        LLVMValueRef l = resolve_value(lhs, type);                                     \\\n"
"        LLVMValueRef r = resolve_value(rhs, type);                                     \\\n"
"        return intern_value(builder_call(g_builder, l, r, \"\"));                        \\\n"
"    }\n"
"\n"
"BINOP(ir_add, LLVMBuildAdd)\n"
"BINOP(ir_sub, LLVMBuildSub)\n"
"BINOP(ir_mul, LLVMBuildMul)\n"
"BINOP(ir_sdiv, LLVMBuildSDiv)\n"
"BINOP(ir_udiv, LLVMBuildUDiv)\n"
"BINOP(ir_srem, LLVMBuildSRem)\n"
"BINOP(ir_urem, LLVMBuildURem)\n"
"BINOP(ir_fadd, LLVMBuildFAdd)\n"
"BINOP(ir_fsub, LLVMBuildFSub)\n"
"BINOP(ir_fmul, LLVMBuildFMul)\n"
"BINOP(ir_fdiv, LLVMBuildFDiv)\n"
"BINOP(ir_and, LLVMBuildAnd)\n"
"BINOP(ir_or, LLVMBuildOr)\n"
"BINOP(ir_xor, LLVMBuildXor)\n"
"BINOP(ir_shl, LLVMBuildShl)\n"
"BINOP(ir_lshr, LLVMBuildLShr)\n"
"BINOP(ir_ashr, LLVMBuildAShr)\n"
"\n"
"int ir_neg(const char *type, const char *value) {\n"
"    return intern_value(LLVMBuildNeg(g_builder, resolve_value(value, type), \"\"));\n"
"}\n"
"\n"
"int ir_fneg(const char *type, const char *value) {\n"
"    return intern_value(LLVMBuildFNeg(g_builder, resolve_value(value, type), \"\"));\n"
"}\n"
"\n"
"int ir_not(const char *type, const char *value) {\n"
"    return intern_value(LLVMBuildNot(g_builder, resolve_value(value, type), \"\"));\n"
"}\n"
"\n"
"#define ICMP(fn_name, pred)                                                            \\\n"
"    int fn_name(const char *type, const char *lhs, const char *rhs) {                  \\\n"
"        LLVMValueRef l = resolve_value(lhs, type);                                     \\\n"
"        LLVMValueRef r = resolve_value(rhs, type);                                     \\\n"
"        return intern_value(LLVMBuildICmp(g_builder, pred, l, r, \"\"));                 \\\n"
"    }\n"
"\n"
"ICMP(ir_icmp_eq, LLVMIntEQ)\n"
"ICMP(ir_icmp_ne, LLVMIntNE)\n"
"ICMP(ir_icmp_slt, LLVMIntSLT)\n"
"ICMP(ir_icmp_sle, LLVMIntSLE)\n"
"ICMP(ir_icmp_sgt, LLVMIntSGT)\n"
"ICMP(ir_icmp_sge, LLVMIntSGE)\n"
"ICMP(ir_icmp_ult, LLVMIntULT)\n"
"ICMP(ir_icmp_ule, LLVMIntULE)\n"
"ICMP(ir_icmp_ugt, LLVMIntUGT)\n"
"ICMP(ir_icmp_uge, LLVMIntUGE)\n"
"\n"
"#define FCMP(fn_name, pred)                                                            \\\n"
"    int fn_name(const char *type, const char *lhs, const char *rhs) {                  \\\n"
"        LLVMValueRef l = resolve_value(lhs, type);                                     \\\n"
"        LLVMValueRef r = resolve_value(rhs, type);                                     \\\n"
"        return intern_value(LLVMBuildFCmp(g_builder, pred, l, r, \"\"));                 \\\n"
"    }\n"
"\n"
"FCMP(ir_fcmp_oeq, LLVMRealOEQ)\n"
"FCMP(ir_fcmp_one, LLVMRealONE)\n"
"FCMP(ir_fcmp_olt, LLVMRealOLT)\n"
"FCMP(ir_fcmp_ole, LLVMRealOLE)\n"
"FCMP(ir_fcmp_ogt, LLVMRealOGT)\n"
"FCMP(ir_fcmp_oge, LLVMRealOGE)\n"
"\n"
"int ir_zext(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildZExt(g_builder, resolve_value(value, from_type),\n"
"                                      type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_sext(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildSExt(g_builder, resolve_value(value, from_type),\n"
"                                      type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_trunc(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildTrunc(g_builder, resolve_value(value, from_type),\n"
"                                       type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// REQUIREMENTS 20. A `List<T>` stores pointer-sized slots, so a scalar element\n"
"// rides in one rather than being boxed. Boxing would cost an allocation per\n"
"// element *and* give the container something to own, which is the opposite of\n"
"// what a scalar element is: nothing allocates, so there is no site and nothing\n"
"// to release.\n"
"int ir_int_to_ptr(const char *from_type, const char *value) {\n"
"    LLVMTypeRef ptr = LLVMPointerTypeInContext(g_ctx, 0);\n"
"    return intern_value(LLVMBuildIntToPtr(g_builder, resolve_value(value, from_type),\n"
"                                          ptr, \"\"));\n"
"}\n"
"\n"
"int ir_ptr_to_int(const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildPtrToInt(g_builder, resolve_value(value, \"ptr\"),\n"
"                                          type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// The float half of the same round trip: a double is 64 bits of payload, not a\n"
"// number to convert, so this reinterprets rather than rounding.\n"
"int ir_bitcast(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildBitCast(g_builder, resolve_value(value, from_type),\n"
"                                         type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// Integer <-> floating point. Needed by `as`; the signed and unsigned forms are\n"
"// distinct instructions, so the frontend picks based on the source/target type.\n"
"int ir_sitofp(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildSIToFP(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_uitofp(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildUIToFP(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_fptosi(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildFPToSI(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"int ir_fptoui(const char *from_type, const char *value, const char *to_type) {\n"
"    return intern_value(LLVMBuildFPToUI(g_builder, resolve_value(value, from_type),\n"
"                                        type_from_key(to_type), \"\"));\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Calls\n"
"// ============================================================================\n"
"\n"
"void ir_call_begin(void) {\n"
"    if (g_call_depth >= MAX_CALL_DEPTH) backend_fail(\"call nesting too deep\", NULL);\n"
"    g_calls[g_call_depth].count = 0;\n"
"    g_call_depth++;\n"
"}\n"
"\n"
"void ir_call_arg(const char *arg_type, const char *arg_value) {\n"
"    if (g_call_depth <= 0) backend_fail(\"call argument outside a call\", arg_value);\n"
"    CallFrame *f = &g_calls[g_call_depth - 1];\n"
"    if (f->count >= MAX_CALL_ARGS) backend_fail(\"too many call arguments\", NULL);\n"
"    f->args[f->count++] = resolve_value(arg_value, arg_type);\n"
"}\n"
"\n"
"int ir_call_end(const char *ret_type, const char *func_name) {\n"
"    if (g_call_depth <= 0) backend_fail(\"call end without begin\", func_name);\n"
"    CallFrame *f = &g_calls[--g_call_depth];\n"
"\n"
"    int is_void = (!ret_type || !*ret_type || strcmp(ret_type, \"void\") == 0);\n"
"\n"
"    LLVMValueRef fn = LLVMGetNamedFunction(g_module, func_name);\n"
"    if (!fn) {\n"
"        // Forward reference. Functions are emitted in a second pass, so a call\n"
"        // can precede its definition, and generate_module deliberately skips\n"
"        // the `declare` for any function the module also defines -- that is the\n"
"        // forward-declaration idiom the compiler's own sources rely on\n"
"        // (parser.psm, sema.psm and ir.psm all `extern fn` something they then\n"
"        // define). The text backend never noticed because it wrote the call as\n"
"        // text and left resolution to the assembler.\n"
"        //\n"
"        // Synthesise the declaration from the call site. The frontend has\n"
"        // already type-checked the call, so the argument types are the\n"
"        // definition's parameter types, and materialize_function() reuses this\n"
"        // same LLVMValueRef when the definition is finally built.\n"
"        LLVMTypeRef param_types[MAX_CALL_ARGS];\n"
"        for (int i = 0; i < f->count; i++) param_types[i] = LLVMTypeOf(f->args[i]);\n"
"        LLVMTypeRef rty = is_void ? LLVMVoidTypeInContext(g_ctx) : type_from_key(ret_type);\n"
"        LLVMTypeRef synth = LLVMFunctionType(rty, param_types, (unsigned)f->count, 0);\n"
"        fn = LLVMAddFunction(g_module, func_name, synth);\n"
"    }\n"
"\n"
"    LLVMTypeRef fnty = LLVMGlobalGetValueType(fn);\n"
"    LLVMValueRef call = LLVMBuildCall2(g_builder, fnty, fn, f->args, (unsigned)f->count, \"\");\n"
"\n"
"    return is_void ? -1 : intern_value(call);\n"
"}\n"
"\n"
"// ============================================================================\n"
"// Globals and string constants\n"
"// ============================================================================\n"
"\n"
"void ir_global_var(const char *name, const char *type, const char *init_value,\n"
"                   int is_const) {\n"
"    LLVMTypeRef ty = type_from_key(type);\n"
"    LLVMValueRef g = LLVMGetNamedGlobal(g_module, name);\n"
"    if (!g) g = LLVMAddGlobal(g_module, ty, name);\n"
"\n"
"    // An initializer naming another global (a string constant) arrives as \"@name\".\n"
"    if (init_value && init_value[0] == '@') {\n"
"        LLVMValueRef target = LLVMGetNamedGlobal(g_module, init_value + 1);\n"
"        if (!target) backend_fail(\"global initializer names an unknown global\", init_value);\n"
"        LLVMSetInitializer(g, target);\n"
"    } else if (init_value && *init_value) {\n"
"        LLVMSetInitializer(g, const_from_text(init_value, ty));\n"
"    } else {\n"
"        LLVMSetInitializer(g, LLVMConstNull(ty));\n"
"    }\n"
"    if (is_const) LLVMSetGlobalConstant(g, 1);\n"
"}\n"
"\n"
"void ir_global_string(const char *name, const char *content) {\n"
"    unsigned len = (unsigned)strlen(content);\n"
"    LLVMValueRef str = LLVMConstStringInContext(g_ctx, content, len, 0); // NUL-terminated\n"
"    LLVMTypeRef arr = LLVMArrayType2(LLVMInt8TypeInContext(g_ctx), (uint64_t)len + 1);\n"
"    LLVMValueRef g = LLVMAddGlobal(g_module, arr, name);\n"
"    LLVMSetInitializer(g, str);\n"
"    LLVMSetLinkage(g, LLVMPrivateLinkage);\n"
"    LLVMSetGlobalConstant(g, 1);\n"
"    LLVMSetUnnamedAddr(g, 1);\n"
"}\n"
"\n"
"// LAYOUT 2. A constant C string created on demand, for the type and field names\n"
"// the profile instrumentation passes to rt_profile_field.\n"
"//\n"
"// Every other string in a generated module is named by the collect_strings\n"
"// pre-pass, which walks the AST and gives each *source* literal a global. These\n"
"// strings are not in the source -- they are the names of the things being\n"
"// measured -- so there is nothing for that pre-pass to find, and adding a second\n"
"// pre-pass for them would mean two walks that have to agree on a name.\n"
"//\n"
"// Interned by content, so a type touched at four hundred sites has one global.\n"
"// The name is derived from the content rather than from a counter for the reason\n"
"// every other generated name here is: a counter makes the IR depend on emission\n"
"// order, and two builds of one program have to produce byte-identical output.\n"
"int ir_const_cstring(const char *text) {\n"
"    // FNV-1a of the content. A collision would alias two distinct names onto one\n"
"    // global and mislabel a counter, so the name carries the length as well --\n"
"    // two strings colliding in both are not something this compiler will meet.\n"
"    unsigned h = 2166136261u;\n"
"    for (const char *p = text; *p; p++) { h ^= (unsigned char)*p; h *= 16777619u; }\n"
"\n"
"    char name[64];\n"
"    snprintf(name, sizeof(name), \".aifprof.%08x.%u\", h, (unsigned)strlen(text));\n"
"\n"
"    LLVMValueRef g = LLVMGetNamedGlobal(g_module, name);\n"
"    if (!g) {\n"
"        ir_global_string(name, text);\n"
"        g = LLVMGetNamedGlobal(g_module, name);\n"
"        if (!g) backend_fail(\"could not create profile string\", text);\n"
"    }\n"
"    return intern_value(g);\n"
"}\n"
"\n"
"// Pointer to the first byte of a previously created string global.\n"
"int ir_string_ptr(const char *global_name) {\n"
"    LLVMValueRef g = LLVMGetNamedGlobal(g_module, global_name);\n"
"    if (!g) backend_fail(\"unknown string global\", global_name);\n"
"    // With opaque pointers the global's address already is the pointer we want.\n"
"    return intern_value(g);\n"
"}\n"
"\n"
"// Return tracking, the struct/enum/global registries, var types and move/borrow\n"
"// state all live in ir_symbols.c -- they are compiler bookkeeping shared by both\n"
"// backends, not emission state.\n"
"\n"
"// ============================================================================\n"
"// Raw text: deliberately unsupported\n"
"// ============================================================================\n"
"\n"
"// The text backend let the frontend splice arbitrary IR text into the output,\n"
"// which is how struct literals, GEPs and array indexing were emitted. There is\n"
"// no way to honour that here, and quietly ignoring it would produce a module\n"
"// missing whole instructions. Fail loudly instead: every remaining caller is a\n"
"// site that still needs migrating to a typed builder above.\n"
"void ir_append(const char *text) {\n"
"    backend_fail(\"ir_append() has no meaning in the LLVM API backend; \"\n"
"                 \"migrate this call site to a typed builder\",\n"
"                 text);\n"
"}\n"
"\n"
"void ir_append_line(const char *text) { ir_append(text); }\n"
"\n"
"void ir_comment(const char *text) { (void)text; /* comments have no IR representation */ }\n"
"void ir_blank_line(void) { /* formatting only */ }\n"
"\n"
"// ============================================================================\n"
"// Debug information (DWARF)\n"
"//\n"
"// `prismio build <src> -g` puts a DICompileUnit, a DISubprogram per source\n"
"// function, a line table, and a DILocalVariable per binding into the module.\n"
"// clang then emits DWARF from them; no `-g` is passed to clang, because for an\n"
"// LLVM IR input the module's own metadata is what drives emission.\n"
"//\n"
"// Everything here is off unless the frontend calls ir_debug_begin(). A release\n"
"// build takes not one branch differently, which is why -g could land without\n"
"// moving a byte of anyone's output.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// The rule this section is written around: **never emit a location that is\n"
"// wrong.** A debugger that says \"no location for x\" sends the reader to a print\n"
"// statement. A debugger that says \"x is at frame offset 12\" when x is at 16\n"
"// sends the reader after a bug that does not exist. So every entry point below\n"
"// has an \"I cannot answer that\" path, and takes it:\n"
"//\n"
"//   - an unregistered file id, or a line of 0 (a node the parser synthesised\n"
"//     rather than read), emits no location and leaves the previous one standing;\n"
"//   - a function whose declaration has no readable span gets no DISubprogram at\n"
"//     all, so nothing inside it claims a line;\n"
"//   - a local whose alloca this layer cannot name gets no variable entry;\n"
"//   - a struct is described only when its exact byte layout is known, and a\n"
"//     field the hot/cold split moved out of the record is described where it\n"
"//     really is (behind the link pointer) rather than at a made-up offset.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// Three things Prismio makes harder than C does, and what is done about each.\n"
"//\n"
"// **1. AIF's T0 hoists an allocation into an alloca in the entry block**, and\n"
"// one slot serves every iteration of the loop that declares it. The DWARF is\n"
"// still true: the variable's storage *is* that slot, and its DILexicalBlock\n"
"// bounds it to the block that declares it, exactly as a C loop-body local is\n"
"// bounded. What DWARF cannot say -- and what this does not pretend to say -- is\n"
"// that a pointer to a T0 object read in iteration 1 names iteration 2's object\n"
"// afterwards. That is a property of the promotion, not of the location, and\n"
"// docs/DEBUGGING.md is where it is written down.\n"
"//\n"
"// **2. An arena-placed value has no individual lifetime.** Its slot is a\n"
"// pointer, and the pointer is right for as long as the binding is in scope; the\n"
"// storage behind it dies with the enclosing region, all at once. Scoping covers\n"
"// the binding. It does not cover a pointer copied out of the region, and DWARF\n"
"// has no way to express \"valid until this other PC\" for a heap object. Again\n"
"// documented rather than approximated.\n"
"//\n"
"// **3. A field may not be where the source says it is.** LAYOUT 7.2 permutes\n"
"// field order and LAYOUT 6 can move the tail of a record into a separate cold\n"
"// block. Member offsets here are therefore never computed from the declaration\n"
"// -- they come from LLVMOffsetOfElement over the struct LLVM actually built, so\n"
"// a permutation is described rather than papered over, and a split type is\n"
"// described as what it is: a hot record with a `__cold` pointer, and a second\n"
"// composite behind it.\n"
"//\n"
"// ---------------------------------------------------------------------------\n"
"// Why a -g build pins the module's data layout\n"
"//\n"
"// A module with no `target datalayout` is laid out by LLVM's *default*\n"
"// specification, in which i64 has a 4-byte ABI alignment. `{ i32, i64 }` is 12\n"
"// bytes there and 16 on every target this compiler supports, so member offsets\n"
"// read from the default would be four bytes out on the first 64-bit field of\n"
"// every struct that has one. clang would then lay the object out its own way and\n"
"// the DWARF would point into the middle of a field. So -g asks the host target\n"
"// machine for its layout and writes it onto the module, which is what clang does\n"
"// for a C translation unit and for the same reason. A module that already has a\n"
"// layout keeps it -- nothing sets one today, but a cross-target build would.\n"
"// ============================================================================\n"
"\n"
"#ifdef PRISMIO_DWARF\n"
"\n"
"// From diagnostics.c. A file id on an AST node indexes that registry; the path\n"
"// is what a DIFile needs. diag_file_count() is the difference between \"file 7\"\n"
"// and \"there is no file 7\" -- without it an out-of-range id renders as\n"
"// \"<unknown>\", which is a filename a debugger would go looking for.\n"
"int diag_file_count(void);\n"
"const char *diag_file_path(int file);\n"
"\n"
"// From program_support.c, for DW_AT_comp_dir. A source path reaches the\n"
"// compiler as the user typed it, so it is usually relative, and a debugger\n"
"// resolves a relative DW_AT_name against the compilation directory.\n"
"char *current_directory(void);\n"
"\n"
"// From ir_symbols.c. The field *names* of a registered struct, in the order they\n"
"// were registered -- which generateStructDecl guarantees is the physical order\n"
"// the layout search chose, not the declaration order.\n"
"int ir_get_struct_field_count(const char *struct_name);\n"
"const char *ir_get_struct_field_name_at(const char *struct_name, int index);\n"
"const char *ir_get_struct_field_type_at(const char *struct_name, int index);\n"
"int ir_is_struct_type_name(const char *name);\n"
"\n"
"// Same file. `ir_named_type_kind` is how a struct is told from an enum: guessing\n"
"// from the name is wrong, because `TokenType` is an enum and does not look like\n"
"// one. 1 = struct, 2 = enum, 0 = not a declared type.\n"
"int ir_named_type_kind(const char *name);\n"
"int ir_get_enum_variant_count(const char *enum_name);\n"
"const char *ir_get_enum_variant_name_at(const char *enum_name, int index);\n"
"int ir_get_enum_variant_value_at(const char *enum_name, int index);\n"
"\n"
"// DWARF base-type encodings. llvm-c/DebugInfo.h types LLVMDWARFTypeEncoding as a\n"
"// bare `unsigned` and defines no constants for it, so these are DWARF 5 table\n"
"// 7.11 verbatim rather than something LLVM would check.\n"
"#define PRISMIO_DW_ATE_boolean 0x02\n"
"#define PRISMIO_DW_ATE_float 0x04\n"
"#define PRISMIO_DW_ATE_signed 0x05\n"
"#define PRISMIO_DW_ATE_signed_char 0x06\n"
"#define PRISMIO_DW_TAG_structure_type 0x13\n"
"\n"
"#define MAX_DI_FILES 256\n"
"#define MAX_DI_SCOPES 64\n"
"#define MAX_DI_TYPES 512\n"
"#define MAX_DI_SCOPE_FILES 128\n"
"\n"
"static LLVMDIBuilderRef g_di;\n"
"static LLVMMetadataRef g_di_cu;\n"
"static LLVMMetadataRef g_di_files[MAX_DI_FILES];\n"
"static LLVMTargetDataRef g_di_layout;\n"
"static LLVMMetadataRef g_di_empty_expr;\n"
"static char g_di_dir[1024];\n"
"\n"
"// The open scope chain: [0] is the subprogram, the rest are lexical blocks. A\n"
"// depth of 0 means no function with debug info is open, and every entry point\n"
"// below is a no-op in that state -- which is how a generated function\n"
"// (__aif_release_T, an extern stub, the workload driver) ends up with no line\n"
"// information rather than with a made-up one.\n"
"typedef struct {\n"
"    LLVMMetadataRef scope;\n"
"    int file; // the frontend file id this scope's DIFile came from\n"
"} DIScope;\n"
"static DIScope g_di_scopes[MAX_DI_SCOPES];\n"
"static int g_di_depth;\n"
"\n"
"// A DILocation carries no file of its own: it inherits the file of its scope.\n"
"// So a statement whose file differs from the function around it would be\n"
"// attributed to the function's file -- a wrong answer rather than a missing one.\n"
"// DILexicalBlockFile is the mechanism for exactly that (it is what `#line`\n"
"// lowers to); these are the ones already built.\n"
"//\n"
"// **Nothing in the tree reaches this today**, and that was checked rather than\n"
"// assumed: no program in tests/ or aif/corpus/ emits a DILexicalBlockFile,\n"
"// because resolveImports flattens files without moving nodes between them and a\n"
"// monomorphised clone keeps its template's file on both the body and the\n"
"// function. It is kept because the alternative is not \"no code\" but \"a silently\n"
"// wrong file\", and the first pass that copies an AST node across a file boundary\n"
"// would introduce that without failing anything.\n"
"typedef struct {\n"
"    LLVMMetadataRef scope;\n"
"    int file;\n"
"    LLVMMetadataRef derived;\n"
"} DIScopeFile;\n"
"static DIScopeFile g_di_scope_files[MAX_DI_SCOPE_FILES];\n"
"static int g_di_scope_file_count;\n"
"\n"
"typedef struct {\n"
"    char key[NAME_LEN];\n"
"    LLVMMetadataRef type;\n"
"} DITypeEntry;\n"
"static DITypeEntry g_di_types[MAX_DI_TYPES];\n"
"static int g_di_type_count;\n"
"\n"
"// Where each struct was declared. Kept here rather than derived, because the\n"
"// backend's struct table holds a layout and no provenance -- and a composite\n"
"// attributed to the wrong file is the same class of wrong answer as a member at\n"
"// the wrong offset. A type nobody registered gets no DW_AT_decl_file at all.\n"
"typedef struct {\n"
"    char name[NAME_LEN];\n"
"    int file;\n"
"    int line;\n"
"} DIStructSite;\n"
"static DIStructSite g_di_struct_sites[256];\n"
"static int g_di_struct_site_count;\n"
"\n"
"// The same, for enums. A separate table rather than a shared one keyed by kind:\n"
"// the two are looked up by different code and a name can only be one of them,\n"
"// so sharing would buy nothing and cost a kind check on every lookup.\n"
"static DIStructSite g_di_enum_sites[256];\n"
"static int g_di_enum_site_count;\n"
"\n"
"// The source-level type name of one field, for the same reason a local has one:\n"
"// ir_symbols.c stores the *storage* key, and String, List<T>, [T], `T?` and every\n"
"// struct are all `ptr` there. Without this a struct's String field reads as an\n"
"// anonymous address instead of printing its characters.\n"
"//\n"
"// Its own table rather than a fourth argument to ir_register_struct_field: that\n"
"// function is called by the committed seed's IR, and changing its arity would\n"
"// mean the seed could no longer link.\n"
"typedef struct {\n"
"    char owner[NAME_LEN];\n"
"    char field[NAME_LEN];\n"
"    char type[NAME_LEN];\n"
"} DIFieldType;\n"
"static DIFieldType g_di_field_types[1024];\n"
"static int g_di_field_type_count;\n"
"\n"
"static const char *di_field_type_name(const char *owner, const char *field) {\n"
"    for (int i = 0; i < g_di_field_type_count; i++) {\n"
"        if (strcmp(g_di_field_types[i].owner, owner) == 0\n"
"            && strcmp(g_di_field_types[i].field, field) == 0) {\n"
"            return g_di_field_types[i].type;\n"
"        }\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"void ir_debug_field_type(const char *owner, const char *field, const char *type_name) {\n"
"    if (!g_di || g_di_field_type_count >= 1024) return;\n"
"    snprintf(g_di_field_types[g_di_field_type_count].owner, NAME_LEN, \"%s\", owner);\n"
"    snprintf(g_di_field_types[g_di_field_type_count].field, NAME_LEN, \"%s\", field);\n"
"    snprintf(g_di_field_types[g_di_field_type_count].type, NAME_LEN, \"%s\", type_name);\n"
"    g_di_field_type_count++;\n"
"}\n"
"\n"
"int ir_debug_enabled(void) { return g_di != NULL; }\n"
"\n"
"void ir_debug_location(int file_id, int line, int col);\n"
"\n"
"// The declared signature, buffered between ir_function_begin and\n"
"// ir_function_body_start.\n"
"//\n"
"// It exists because the LLVM function type is not enough. Everything with an\n"
"// address is `ptr` there -- a String, a List, a Point, an opaque extern return --\n"
"// so a signature read off it says `void *` five times where the source said five\n"
"// different things. The frontend knows which is which and says so here; slot 0\n"
"// is the return.\n"
"//\n"
"// Only used when the count matches what LLVM built. It will not match for main,\n"
"// whose real argc/argv are prepended by codegen, and a mismatch means the two\n"
"// have gone out of step -- in which case the storage types are still true, just\n"
"// coarser, and that is what gets emitted.\n"
"static char g_di_sig_key[MAX_PENDING_PARAMS + 1][NAME_LEN];\n"
"static char g_di_sig_name[MAX_PENDING_PARAMS + 1][NAME_LEN];\n"
"static int g_di_sig_count;\n"
"\n"
"static void sig_push(const char *key, const char *name) {\n"
"    if (g_di_sig_count > MAX_PENDING_PARAMS) return;\n"
"    snprintf(g_di_sig_key[g_di_sig_count], NAME_LEN, \"%s\", key ? key : \"\");\n"
"    snprintf(g_di_sig_name[g_di_sig_count], NAME_LEN, \"%s\", name ? name : \"\");\n"
"    g_di_sig_count++;\n"
"}\n"
"\n"
"void ir_debug_signature(const char *ret_key, const char *ret_name) {\n"
"    if (!g_di) return;\n"
"    g_di_sig_count = 0;\n"
"    sig_push(ret_key, ret_name);\n"
"}\n"
"\n"
"void ir_debug_signature_param(const char *key, const char *name) {\n"
"    if (!g_di || g_di_sig_count == 0) return;\n"
"    sig_push(key, name);\n"
"}\n"
"\n"
"static LLVMMetadataRef di_file(int file_id) {\n"
"    if (!g_di) return NULL;\n"
"    if (file_id < 0 || file_id >= MAX_DI_FILES) return NULL;\n"
"    if (file_id >= diag_file_count()) return NULL;\n"
"    if (g_di_files[file_id]) return g_di_files[file_id];\n"
"\n"
"    const char *path = diag_file_path(file_id);\n"
"    g_di_files[file_id] = LLVMDIBuilderCreateFile(g_di, path, strlen(path),\n"
"                                                  g_di_dir, strlen(g_di_dir));\n"
"    return g_di_files[file_id];\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Types\n"
"//\n"
"// Two facts are needed per binding and the frontend has one of each: the\n"
"// *storage* key it already passes to every builder here (\"i32\", \"ptr\",\n"
"// \"struct:Foo\"), which is authoritative about size, and the source-level type\n"
"// name sema recorded (\"Int\", \"String\", \"Point\"), which is what the reader typed.\n"
"// The key decides the shape; the name only refines a pointer, and only when the\n"
"// two agree about there being a pointer.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"static LLVMMetadataRef di_cached(const char *key) {\n"
"    for (int i = 0; i < g_di_type_count; i++) {\n"
"        if (strcmp(g_di_types[i].key, key) == 0) return g_di_types[i].type;\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"static LLVMMetadataRef di_cache(const char *key, LLVMMetadataRef type) {\n"
"    if (g_di_type_count >= MAX_DI_TYPES) return type;\n"
"    strncpy(g_di_types[g_di_type_count].key, key, NAME_LEN - 1);\n"
"    g_di_types[g_di_type_count].key[NAME_LEN - 1] = '\\0';\n"
"    g_di_types[g_di_type_count].type = type;\n"
"    g_di_type_count++;\n"
"    return type;\n"
"}\n"
"\n"
"static LLVMMetadataRef di_basic(const char *name, uint64_t bits, unsigned encoding) {\n"
"    LLVMMetadataRef hit = di_cached(name);\n"
"    if (hit) return hit;\n"
"    return di_cache(name, LLVMDIBuilderCreateBasicType(g_di, name, strlen(name),\n"
"                                                       bits, encoding, LLVMDIFlagZero));\n"
"}\n"
"\n"
"// An address whose pointee this layer will not claim to know. Not a lie and not\n"
"// nothing: the reader still gets the address, which is what a `ptr` is.\n"
"static LLVMMetadataRef di_opaque_ptr(void) {\n"
"    LLVMMetadataRef hit = di_cached(\"$ptr\");\n"
"    if (hit) return hit;\n"
"    return di_cache(\"$ptr\", LLVMDIBuilderCreatePointerType(g_di, NULL, 64, 0, 0, \"\", 0));\n"
"}\n"
"\n"
"static LLVMMetadataRef di_struct_type(const char *name);\n"
"static LLVMMetadataRef di_enum_type(const char *name);\n"
"\n"
"// `struct:Foo` in a local's slot means a *pointer* to Foo -- storageType()\n"
"// collapses it before the alloca is made -- so the pointee is looked up and the\n"
"// pointer built around it.\n"
"static LLVMMetadataRef di_pointer_to(const char *pointee_key, LLVMMetadataRef pointee) {\n"
"    char key[NAME_LEN];\n"
"    snprintf(key, sizeof(key), \"$p:%s\", pointee_key);\n"
"    LLVMMetadataRef hit = di_cached(key);\n"
"    if (hit) return hit;\n"
"    if (!pointee) return di_opaque_ptr();\n"
"    return di_cache(key, LLVMDIBuilderCreatePointerType(g_di, pointee, 64, 0, 0, \"\", 0));\n"
"}\n"
"\n"
"// The storage key alone. `name` refines only the pointer case, and only towards\n"
"// something this layer can show to be true.\n"
"static LLVMMetadataRef di_type_for(const char *key, const char *name) {\n"
"    if (!key || !*key) return NULL;\n"
"    if (strcmp(key, \"void\") == 0) return NULL;\n"
"    if (strcmp(key, \"i1\") == 0) return di_basic(\"Bool\", 8, PRISMIO_DW_ATE_boolean);\n"
"    if (strcmp(key, \"i8\") == 0) return di_basic(\"Char\", 8, PRISMIO_DW_ATE_signed_char);\n"
"    if (strcmp(key, \"i16\") == 0) return di_basic(\"I16\", 16, PRISMIO_DW_ATE_signed);\n"
"    if (strcmp(key, \"i32\") == 0) {\n"
"        // Every Prismio enum lowers to i32, so the storage key alone cannot tell\n"
"        // `NodeKind` from `Int` -- only the source-level name can, and only when\n"
"        // the frontend had one to send. With it, `p kind` prints STRUCT_DECL\n"
"        // instead of 12, which on a compiler written around NodeKind, TypeKind\n"
"        // and TokenType is most of what a debugger is for.\n"
"        if (name && *name && ir_named_type_kind(name) == 2) {\n"
"            LLVMMetadataRef e = di_enum_type(name);\n"
"            if (e) return e;\n"
"        }\n"
"        return di_basic(\"Int\", 32, PRISMIO_DW_ATE_signed);\n"
"    }\n"
"    if (strcmp(key, \"i64\") == 0) return di_basic(\"I64\", 64, PRISMIO_DW_ATE_signed);\n"
"    if (strcmp(key, \"double\") == 0) return di_basic(\"Float\", 64, PRISMIO_DW_ATE_float);\n"
"\n"
"    if (strncmp(key, \"struct:\", 7) == 0) {\n"
"        return di_pointer_to(key + 7, di_struct_type(key + 7));\n"
"    }\n"
"    if (strcmp(key, \"ptrptr\") == 0) return di_pointer_to(\"$ptr\", di_opaque_ptr());\n"
"\n"
"    if (strcmp(key, \"ptr\") == 0) {\n"
"        // A Prismio String is a NUL-terminated char* -- str_concat, str_equals\n"
"        // and every runtime string function treat it as one -- so saying `char *`\n"
"        // is a statement of fact, and it is what makes a debugger print the\n"
"        // contents instead of the address.\n"
"        if (name && strcmp(name, \"String\") == 0) {\n"
"            // Lowercase `char`, and the case is load-bearing rather than a\n"
"            // style choice. lldb auto-prints a `char *` as its characters and\n"
"            // prints a `signed char *` as an address, and it decides which by\n"
"            // the base type's *name*: with \"Char\" here, `frame variable s`\n"
"            // rendered `(signed char *) 0x1000042fc` and docs/DEBUGGING.md's\n"
"            // promise that a String prints its contents was false. Measured\n"
"            // both ways on lldb 22.1.8.\n"
"            //\n"
"            // Only the String pointee. An `i8` binding is Prismio's `Char` and\n"
"            // keeps that name below, because it is a Char and not a C char.\n"
"            return di_pointer_to(\"$char\", di_basic(\"char\", 8, PRISMIO_DW_ATE_signed_char));\n"
"        }\n"
"        // A struct-typed binding whose key was already collapsed to `ptr`.\n"
"        if (name && *name && ir_is_struct_type_name(name)) {\n"
"            return di_pointer_to(name, di_struct_type(name));\n"
"        }\n"
"        // A List, an Optional, an array, an opaque extern return. Each is an\n"
"        // address of something this layer has no layout for.\n"
"        return di_opaque_ptr();\n"
"    }\n"
"    return NULL;\n"
"}\n"
"\n"
"// The same mapping driven by what LLVM built rather than by what the frontend\n"
"// said. Used for a function's signature, where the storage types are all this\n"
"// layer has and all a DWARF consumer needs.\n"
"static LLVMMetadataRef di_type_for_llvm(LLVMTypeRef ty) {\n"
"    switch (LLVMGetTypeKind(ty)) {\n"
"    case LLVMVoidTypeKind: return NULL;\n"
"    case LLVMDoubleTypeKind: return di_type_for(\"double\", NULL);\n"
"    case LLVMPointerTypeKind: return di_opaque_ptr();\n"
"    case LLVMIntegerTypeKind: {\n"
"        unsigned w = LLVMGetIntTypeWidth(ty);\n"
"        if (w == 1) return di_type_for(\"i1\", NULL);\n"
"        if (w <= 8) return di_type_for(\"i8\", NULL);\n"
"        if (w <= 16) return di_type_for(\"i16\", NULL);\n"
"        if (w <= 32) return di_type_for(\"i32\", NULL);\n"
"        return di_type_for(\"i64\", NULL);\n"
"    }\n"
"    default: return NULL;\n"
"    }\n"
"}\n"
"\n"
"// The composite for a registered struct, built from the type LLVM really\n"
"// created rather than from the declaration.\n"
"//\n"
"// The field *names* come from ir_symbols.c in registration order, and\n"
"// generateStructDecl registers them in the physical order aif_layout_field\n"
"// chose -- so index i is the same field in both, and a permuted layout is\n"
"// described correctly without this having to know a search ran.\n"
"//\n"
"// A split type is the case worth reading. The hot record is `hot_count` fields\n"
"// plus a link pointer; the rest live in a separate `Foo.cold` allocation. There\n"
"// is no offset in the hot record that names a cold field, so none is invented:\n"
"// the composite gets its hot members, a `__cold` member for the link, and a\n"
"// second composite for what the link points at. `p obj->__cold->field` is a\n"
"// longer thing to type than `p obj->field`, and it is the truth.\n"
"// DW_TAG_enumeration_type: the name, and every enumerator with its value.\n"
"//\n"
"// Enums lower to i32 and every variant's value is one, so the size is fixed and\n"
"// there is no layout to read -- which is why this needs none of the machinery\n"
"// di_struct_type does, and no replaceable placeholder either: an enumerator\n"
"// cannot refer back to its own type.\n"
"//\n"
"// An enum with no registered variants gets no type rather than an empty one. A\n"
"// DW_TAG_enumeration_type with no enumerators tells a debugger the value has a\n"
"// name it cannot find, which reads worse than plain `Int`.\n"
"static LLVMMetadataRef di_enum_type(const char *name) {\n"
"    char key[NAME_LEN];\n"
"    snprintf(key, sizeof(key), \"$e:%s\", name);\n"
"    LLVMMetadataRef hit = di_cached(key);\n"
"    if (hit) return hit;\n"
"\n"
"    int total = ir_get_enum_variant_count(name);\n"
"    if (total <= 0) return NULL;\n"
"    if (total > 512) total = 512;\n"
"\n"
"    LLVMMetadataRef site_file = NULL;\n"
"    unsigned site_line = 0;\n"
"    for (int i = 0; i < g_di_enum_site_count; i++) {\n"
"        if (strcmp(g_di_enum_sites[i].name, name) != 0) continue;\n"
"        site_file = di_file(g_di_enum_sites[i].file);\n"
"        if (g_di_enum_sites[i].line > 0) site_line = (unsigned)g_di_enum_sites[i].line;\n"
"        break;\n"
"    }\n"
"\n"
"    LLVMMetadataRef *values =\n"
"        (LLVMMetadataRef *)malloc(sizeof(LLVMMetadataRef) * (size_t)total);\n"
"    if (!values) return NULL;\n"
"    unsigned count = 0;\n"
"    for (int i = 0; i < total; i++) {\n"
"        const char *vname = ir_get_enum_variant_name_at(name, i);\n"
"        if (!vname || !*vname) continue;\n"
"        values[count++] = LLVMDIBuilderCreateEnumerator(\n"
"            g_di, vname, strlen(vname),\n"
"            (int64_t)ir_get_enum_variant_value_at(name, i), 0);\n"
"    }\n"
"\n"
"    LLVMMetadataRef type = NULL;\n"
"    if (count > 0) {\n"
"        type = LLVMDIBuilderCreateEnumerationType(\n"
"            g_di, g_di_cu, name, strlen(name), site_file, site_line,\n"
"            32, 32, values, count,\n"
"            di_basic(\"Int\", 32, PRISMIO_DW_ATE_signed));\n"
"    }\n"
"    free(values);\n"
"    if (!type) return NULL;\n"
"    return di_cache(key, type);\n"
"}\n"
"\n"
"static LLVMMetadataRef di_struct_type(const char *name) {\n"
"    char key[NAME_LEN];\n"
"    snprintf(key, sizeof(key), \"$s:%s\", name);\n"
"    LLVMMetadataRef hit = di_cached(key);\n"
"    if (hit) return hit;\n"
"\n"
"    StructType *s = NULL;\n"
"    for (int i = 0; i < g_struct_count; i++) {\n"
"        if (strcmp(g_structs[i].name, name) == 0) { s = &g_structs[i]; break; }\n"
"    }\n"
"    if (!s || !g_di_layout || LLVMIsOpaqueStruct(s->type)) return NULL;\n"
"\n"
"    LLVMMetadataRef site_file = NULL;\n"
"    unsigned site_line = 0;\n"
"    for (int i = 0; i < g_di_struct_site_count; i++) {\n"
"        if (strcmp(g_di_struct_sites[i].name, name) != 0) continue;\n"
"        site_file = di_file(g_di_struct_sites[i].file);\n"
"        if (g_di_struct_sites[i].line > 0) site_line = (unsigned)g_di_struct_sites[i].line;\n"
"        break;\n"
"    }\n"
"\n"
"    // Cached before the members are built: a struct that contains a pointer to\n"
"    // its own type would otherwise recurse forever.\n"
"    LLVMMetadataRef placeholder = LLVMDIBuilderCreateReplaceableCompositeType(\n"
"        g_di, PRISMIO_DW_TAG_structure_type, name, strlen(name), g_di_cu,\n"
"        site_file, site_line, 0, 0, 0, LLVMDIFlagZero, \"\", 0);\n"
"    di_cache(key, placeholder);\n"
"\n"
"    int total = ir_get_struct_field_count(name);\n"
"    int hot = s->hot_count > 0 ? s->hot_count : total;\n"
"\n"
"    LLVMMetadataRef members[66];\n"
"    unsigned count = 0;\n"
"    for (int i = 0; i < hot && i < total && count < 64; i++) {\n"
"        const char *fname = ir_get_struct_field_name_at(name, i);\n"
"        const char *ftype = ir_get_struct_field_type_at(name, i);\n"
"        LLVMMetadataRef fty = di_type_for(ftype, di_field_type_name(name, fname));\n"
"        if (!fty) continue;\n"
"        LLVMTypeRef llvm_field = LLVMStructGetTypeAtIndex(s->type, (unsigned)i);\n"
"        members[count++] = LLVMDIBuilderCreateMemberType(\n"
"            g_di, placeholder, fname, strlen(fname), site_file, 0,\n"
"            LLVMABISizeOfType(g_di_layout, llvm_field) * 8,\n"
"            LLVMABIAlignmentOfType(g_di_layout, llvm_field) * 8,\n"
"            LLVMOffsetOfElement(g_di_layout, s->type, (unsigned)i) * 8,\n"
"            LLVMDIFlagZero, fty);\n"
"    }\n"
"\n"
"    if (s->hot_count > 0 && s->cold && count < 65) {\n"
"        char cold_name[NAME_LEN];\n"
"        snprintf(cold_name, sizeof(cold_name), \"%s.cold\", name);\n"
"        LLVMMetadataRef cold_members[64];\n"
"        unsigned cold_count = 0;\n"
"        for (int i = hot; i < total && cold_count < 64; i++) {\n"
"            const char *fname = ir_get_struct_field_name_at(name, i);\n"
"            const char *ftype = ir_get_struct_field_type_at(name, i);\n"
"            LLVMMetadataRef fty = di_type_for(ftype, di_field_type_name(name, fname));\n"
"            if (!fty) continue;\n"
"            LLVMTypeRef llvm_field = LLVMStructGetTypeAtIndex(s->cold, (unsigned)(i - hot));\n"
"            cold_members[cold_count++] = LLVMDIBuilderCreateMemberType(\n"
"                g_di, g_di_cu, fname, strlen(fname), site_file, 0,\n"
"                LLVMABISizeOfType(g_di_layout, llvm_field) * 8,\n"
"                LLVMABIAlignmentOfType(g_di_layout, llvm_field) * 8,\n"
"                LLVMOffsetOfElement(g_di_layout, s->cold, (unsigned)(i - hot)) * 8,\n"
"                LLVMDIFlagZero, fty);\n"
"        }\n"
"        LLVMMetadataRef cold_ty = LLVMDIBuilderCreateStructType(\n"
"            g_di, g_di_cu, cold_name, strlen(cold_name), site_file, site_line,\n"
"            LLVMABISizeOfType(g_di_layout, s->cold) * 8,\n"
"            LLVMABIAlignmentOfType(g_di_layout, s->cold) * 8,\n"
"            LLVMDIFlagZero, NULL, cold_members, cold_count, 0, NULL, \"\", 0);\n"
"\n"
"        LLVMTypeRef link = LLVMStructGetTypeAtIndex(s->type, (unsigned)hot);\n"
"        members[count++] = LLVMDIBuilderCreateMemberType(\n"
"            g_di, placeholder, \"__cold\", 6, site_file, 0,\n"
"            LLVMABISizeOfType(g_di_layout, link) * 8,\n"
"            LLVMABIAlignmentOfType(g_di_layout, link) * 8,\n"
"            LLVMOffsetOfElement(g_di_layout, s->type, (unsigned)hot) * 8,\n"
"            LLVMDIFlagZero, LLVMDIBuilderCreatePointerType(g_di, cold_ty, 64, 0, 0, \"\", 0));\n"
"    }\n"
"\n"
"    LLVMMetadataRef real = LLVMDIBuilderCreateStructType(\n"
"        g_di, g_di_cu, name, strlen(name), site_file, site_line,\n"
"        LLVMABISizeOfType(g_di_layout, s->type) * 8,\n"
"        LLVMABIAlignmentOfType(g_di_layout, s->type) * 8,\n"
"        LLVMDIFlagZero, NULL, members, count, 0, NULL, \"\", 0);\n"
"    LLVMMetadataReplaceAllUsesWith(placeholder, real);\n"
"\n"
"    for (int i = 0; i < g_di_type_count; i++) {\n"
"        if (strcmp(g_di_types[i].key, key) == 0) g_di_types[i].type = real;\n"
"    }\n"
"    return real;\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Lifecycle\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"// Asks the target machine for the layout the object file will be built with, and\n"
"// writes it onto the module. See the section header for why a -g build cannot\n"
"// use LLVM's default specification.\n"
"//\n"
"// **A named target has already stamped its own layout** (ir_module_set_target,\n"
"// in the \"Targets\" section above), and the early return below is what makes a\n"
"// cross-compiled -g build read member offsets from the *target* rather than from\n"
"// this host -- which is precisely the bug this layer exists to prevent. Verified:\n"
"// a struct { Int, String, I64 } reports its String member at offset 64 on a\n"
"// 64-bit host and at offset 32 for wasm32-unknown-unknown.\n"
"//\n"
"// The host default is reached only when nothing was named, and only then is\n"
"// LLVMGetDefaultTargetTriple() the right question to ask.\n"
"static void pin_data_layout(void) {\n"
"    const char *existing = LLVMGetDataLayoutStr(g_module);\n"
"    if (existing && *existing) {\n"
"        g_di_layout = LLVMGetModuleDataLayout(g_module);\n"
"        return;\n"
"    }\n"
"\n"
"    LLVMInitializeNativeTarget();\n"
"    LLVMInitializeNativeAsmPrinter();\n"
"\n"
"    char *triple = LLVMGetDefaultTargetTriple();\n"
"    LLVMTargetRef target = NULL;\n"
"    char *err = NULL;\n"
"    if (LLVMGetTargetFromTriple(triple, &target, &err)) {\n"
"        // No layout means no member offsets, and the composites are skipped\n"
"        // rather than guessed. Line tables and scalar locals are unaffected.\n"
"        fprintf(stderr, \"warning: -g could not resolve the host target (%s); \"\n"
"                        \"struct layouts will be omitted from the debug info\\n\",\n"
"                err ? err : \"?\");\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        LLVMDisposeMessage(triple);\n"
"        return;\n"
"    }\n"
"\n"
"    LLVMTargetMachineRef tm = LLVMCreateTargetMachine(\n"
"        target, triple, \"\", \"\", LLVMCodeGenLevelDefault, LLVMRelocDefault,\n"
"        LLVMCodeModelDefault);\n"
"    LLVMTargetDataRef td = LLVMCreateTargetDataLayout(tm);\n"
"    char *rep = LLVMCopyStringRepOfTargetData(td);\n"
"    LLVMSetDataLayout(g_module, rep);\n"
"    const char *triple_now = LLVMGetTarget(g_module);\n"
"    if (!triple_now || !*triple_now) LLVMSetTarget(g_module, triple);\n"
"    LLVMDisposeMessage(rep);\n"
"    LLVMDisposeTargetMachine(tm);\n"
"    LLVMDisposeMessage(triple);\n"
"\n"
"    g_di_layout = LLVMGetModuleDataLayout(g_module);\n"
"}\n"
"\n"
"void ir_debug_begin(const char *producer, const char *main_path, int is_optimized) {\n"
"    if (!g_module) backend_fail(\"-g: no module to attach debug info to\", NULL);\n"
"    if (g_di) return;\n"
"\n"
"    memset(g_di_files, 0, sizeof(g_di_files));\n"
"    g_di_type_count = 0;\n"
"    g_di_scope_file_count = 0;\n"
"    g_di_struct_site_count = 0;\n"
"    g_di_enum_site_count = 0;\n"
"    g_di_field_type_count = 0;\n"
"    g_di_sig_count = 0;\n"
"    g_di_depth = 0;\n"
"\n"
"    char *cwd = current_directory();\n"
"    snprintf(g_di_dir, sizeof(g_di_dir), \"%s\", cwd ? cwd : \".\");\n"
"    if (cwd) free(cwd);\n"
"\n"
"    g_di = LLVMCreateDIBuilder(g_module);\n"
"    pin_data_layout();\n"
"\n"
"    LLVMMetadataRef file = LLVMDIBuilderCreateFile(g_di, main_path, strlen(main_path),\n"
"                                                   g_di_dir, strlen(g_di_dir));\n"
"    // DW_LANG_C99 rather than a Prismio of our own. DWARF's language codes are\n"
"    // registered, Prismio has none, and the code is not decoration: lldb and gdb\n"
"    // pick an expression parser and a formatter from it. C99 is the one whose\n"
"    // value model -- machine integers, NUL-terminated char*, flat structs -- is\n"
"    // what a Prismio binary actually contains.\n"
"    g_di_cu = LLVMDIBuilderCreateCompileUnit(\n"
"        g_di, LLVMDWARFSourceLanguageC99, file, producer, strlen(producer),\n"
"        is_optimized ? 1 : 0, \"\", 0, 0, \"\", 0, LLVMDWARFEmissionFull, 0, 0, 0, \"\", 0, \"\", 0);\n"
"\n"
"    g_di_empty_expr = LLVMDIBuilderCreateExpression(g_di, NULL, 0);\n"
"\n"
"    // \"Debug Info Version\" is what makes the backend read any of this; without\n"
"    // it every !dbg node is dropped on the way to the object. The DWARF version\n"
"    // is pinned at 4 rather than left to the target's default so that two hosts\n"
"    // produce the same thing, and at 4 rather than 5 because every lldb, gdb and\n"
"    // dsymutil in service reads 4. Raise it when something needs a 5-only form.\n"
"    LLVMTypeRef i32 = LLVMInt32TypeInContext(g_ctx);\n"
"    LLVMAddModuleFlag(g_module, LLVMModuleFlagBehaviorWarning, \"Dwarf Version\", 13,\n"
"                      LLVMValueAsMetadata(LLVMConstInt(i32, 4, 0)));\n"
"    LLVMAddModuleFlag(g_module, LLVMModuleFlagBehaviorWarning, \"Debug Info Version\", 18,\n"
"                      LLVMValueAsMetadata(LLVMConstInt(i32, 3, 0)));\n"
"}\n"
"\n"
"void ir_debug_end(void) {\n"
"    if (!g_di) return;\n"
"    LLVMDIBuilderFinalize(g_di);\n"
"}\n"
"\n"
"static void debug_dispose(void) {\n"
"    if (!g_di) return;\n"
"    LLVMDisposeDIBuilder(g_di);\n"
"    g_di = NULL;\n"
"    g_di_cu = NULL;\n"
"    g_di_layout = NULL;\n"
"    g_di_depth = 0;\n"
"}\n"
"\n"
"static void debug_clear_location(void) {\n"
"    if (!g_di) return;\n"
"    LLVMSetCurrentDebugLocation2(g_builder, NULL);\n"
"    LLVMSetCurrentDebugLocation2(g_alloca_builder, NULL);\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Scopes and locations\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"// The scope a location in `file` should hang from. Same file as the enclosing\n"
"// scope: the scope itself. A different one: a DILexicalBlockFile over it, so the\n"
"// line is attributed to the file it was written in.\n"
"static LLVMMetadataRef scope_in_file(int file) {\n"
"    LLVMMetadataRef scope = g_di_scopes[g_di_depth - 1].scope;\n"
"    if (file == g_di_scopes[g_di_depth - 1].file) return scope;\n"
"\n"
"    LLVMMetadataRef f = di_file(file);\n"
"    if (!f) return scope;\n"
"\n"
"    for (int i = 0; i < g_di_scope_file_count; i++) {\n"
"        if (g_di_scope_files[i].scope == scope && g_di_scope_files[i].file == file) {\n"
"            return g_di_scope_files[i].derived;\n"
"        }\n"
"    }\n"
"    LLVMMetadataRef derived = LLVMDIBuilderCreateLexicalBlockFile(g_di, scope, f, 0);\n"
"    if (g_di_scope_file_count < MAX_DI_SCOPE_FILES) {\n"
"        g_di_scope_files[g_di_scope_file_count].scope = scope;\n"
"        g_di_scope_files[g_di_scope_file_count].file = file;\n"
"        g_di_scope_files[g_di_scope_file_count].derived = derived;\n"
"        g_di_scope_file_count++;\n"
"    }\n"
"    return derived;\n"
"}\n"
"\n"
"void ir_debug_function_begin(const char *name, const char *linkage_name,\n"
"                             int file_id, int line) {\n"
"    if (!g_di || !g_function) return;\n"
"    g_di_depth = 0;\n"
"\n"
"    LLVMMetadataRef file = di_file(file_id);\n"
"    if (!file || line <= 0) return; // no span to point at: no subprogram\n"
"\n"
"    LLVMTypeRef fn_ty = LLVMGlobalGetValueType(g_function);\n"
"    LLVMMetadataRef types[MAX_PENDING_PARAMS + 1];\n"
"    unsigned n = 0;\n"
"    unsigned pc = LLVMCountParamTypes(fn_ty);\n"
"    if (pc > MAX_PENDING_PARAMS) pc = MAX_PENDING_PARAMS;\n"
"\n"
"    if (g_di_sig_count == (int)pc + 1) {\n"
"        // The declared signature. Preferred because it distinguishes the five\n"
"        // different things that are all `ptr` in the LLVM type.\n"
"        for (int i = 0; i < g_di_sig_count; i++) {\n"
"            types[n++] = di_type_for(g_di_sig_key[i], g_di_sig_name[i]);\n"
"        }\n"
"    } else {\n"
"        // Storage-level, from the function LLVM built. Coarser and still true.\n"
"        LLVMTypeRef ret = LLVMGetReturnType(fn_ty);\n"
"        types[n++] = LLVMGetTypeKind(ret) == LLVMVoidTypeKind ? NULL : di_type_for_llvm(ret);\n"
"        LLVMTypeRef params[MAX_PENDING_PARAMS];\n"
"        LLVMGetParamTypes(fn_ty, params);\n"
"        for (unsigned i = 0; i < pc; i++) types[n++] = di_type_for_llvm(params[i]);\n"
"    }\n"
"\n"
"    // NULL means void, and void is only meaningful at index 0. A parameter this\n"
"    // layer could not map would be read as \"nothing\" in the middle of a\n"
"    // signature, so the whole signature is dropped rather than half-stated -- the\n"
"    // subprogram, the line table and the locals all survive without it.\n"
"    for (unsigned i = 1; i < n; i++) {\n"
"        if (!types[i]) { n = 0; break; }\n"
"    }\n"
"\n"
"    LLVMMetadataRef sub_ty = LLVMDIBuilderCreateSubroutineType(\n"
"        g_di, file, n > 0 ? types : NULL, n, LLVMDIFlagZero);\n"
"\n"
"    LLVMMetadataRef sp = LLVMDIBuilderCreateFunction(\n"
"        g_di, file, name, strlen(name), linkage_name, strlen(linkage_name), file,\n"
"        (unsigned)line, sub_ty, 0, 1, (unsigned)line, LLVMDIFlagZero, 0);\n"
"    LLVMSetSubprogram(g_function, sp);\n"
"\n"
"    g_di_scopes[0].scope = sp;\n"
"    g_di_scopes[0].file = file_id;\n"
"    g_di_depth = 1;\n"
"    ir_debug_location(file_id, line, 1);\n"
"}\n"
"\n"
"void ir_debug_function_end(void) {\n"
"    if (!g_di) return;\n"
"    g_di_depth = 0;\n"
"    // Cleared, and this is not tidiness. A stale location outlives the function\n"
"    // it belongs to, and the next instruction built would carry a !dbg whose\n"
"    // scope is another function's subprogram -- which the verifier rejects, and\n"
"    // which would otherwise be a build failure whose cause is three functions\n"
"    // back.\n"
"    LLVMSetCurrentDebugLocation2(g_builder, NULL);\n"
"    LLVMSetCurrentDebugLocation2(g_alloca_builder, NULL);\n"
"}\n"
"\n"
"void ir_debug_scope_push(int file_id, int line, int col) {\n"
"    if (!g_di || g_di_depth == 0 || g_di_depth >= MAX_DI_SCOPES) return;\n"
"    LLVMMetadataRef file = di_file(file_id);\n"
"    if (!file) file = LLVMDIScopeGetFile(g_di_scopes[g_di_depth - 1].scope);\n"
"\n"
"    LLVMMetadataRef block = LLVMDIBuilderCreateLexicalBlock(\n"
"        g_di, g_di_scopes[g_di_depth - 1].scope, file,\n"
"        (unsigned)(line > 0 ? line : 0), (unsigned)(col > 0 ? col : 0));\n"
"    g_di_scopes[g_di_depth].scope = block;\n"
"    g_di_scopes[g_di_depth].file = file_id;\n"
"    g_di_depth++;\n"
"}\n"
"\n"
"void ir_debug_scope_pop(void) {\n"
"    // Never below the subprogram: generateFunction pops the parameter scope\n"
"    // after generateBlock has popped the body's, and one unbalanced pop would\n"
"    // leave every later location hanging off nothing.\n"
"    if (!g_di || g_di_depth <= 1) return;\n"
"    g_di_depth--;\n"
"}\n"
"\n"
"void ir_debug_location(int file_id, int line, int col) {\n"
"    if (!g_di || g_di_depth == 0) return;\n"
"    // A synthesised node -- a desugared `x += 1`, an inserted drop, anything\n"
"    // createNode() made without a token -- carries line 0. Claiming line 0 puts\n"
"    // the debugger at the top of the file; leaving the previous location\n"
"    // standing attributes the instruction to the statement that caused it, which\n"
"    // is where it came from.\n"
"    if (line <= 0) return;\n"
"    if (di_file(file_id) == NULL) return;\n"
"\n"
"    LLVMMetadataRef loc = LLVMDIBuilderCreateDebugLocation(\n"
"        g_ctx, (unsigned)line, (unsigned)(col > 0 ? col : 0), scope_in_file(file_id), NULL);\n"
"    LLVMSetCurrentDebugLocation2(g_builder, loc);\n"
"    LLVMSetCurrentDebugLocation2(g_alloca_builder, loc);\n"
"}\n"
"\n"
"// ---------------------------------------------------------------------------\n"
"// Variables\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"// `slot` is the alloca's name, the same one ir_alloca() was given and every\n"
"// load and store since has resolved through. arg_no is 0 for a local and the\n"
"// 1-based parameter position otherwise.\n"
"void ir_debug_local(const char *name, const char *slot, const char *type_key,\n"
"                    const char *type_name, int file_id, int line, int arg_no) {\n"
"    if (!g_di || g_di_depth == 0) return;\n"
"    if (line <= 0) return;\n"
"\n"
"    LLVMTypeRef stored = NULL;\n"
"    LLVMValueRef storage = lookup_named(g_allocas, g_alloca_count, slot, &stored);\n"
"    if (!storage) return; // nothing this layer can name: no entry, no guess\n"
"\n"
"    LLVMMetadataRef file = di_file(file_id);\n"
"    if (!file) return;\n"
"\n"
"    LLVMMetadataRef ty = di_type_for(type_key, type_name);\n"
"    if (!ty) return;\n"
"\n"
"    LLVMMetadataRef scope = g_di_scopes[g_di_depth - 1].scope;\n"
"    LLVMMetadataRef var =\n"
"        arg_no > 0\n"
"            ? LLVMDIBuilderCreateParameterVariable(g_di, scope, name, strlen(name),\n"
"                                                   (unsigned)arg_no, file, (unsigned)line,\n"
"                                                   ty, 1, LLVMDIFlagZero)\n"
"            : LLVMDIBuilderCreateAutoVariable(g_di, scope, name, strlen(name), file,\n"
"                                              (unsigned)line, ty, 1, LLVMDIFlagZero, 0);\n"
"\n"
"    LLVMMetadataRef loc = LLVMDIBuilderCreateDebugLocation(\n"
"        g_ctx, (unsigned)line, 0, scope, NULL);\n"
"    LLVMBasicBlockRef bb = LLVMGetInsertBlock(g_builder);\n"
"    if (!bb) return;\n"
"    LLVMDIBuilderInsertDeclareRecordAtEnd(g_di, storage, var, g_di_empty_expr, loc, bb);\n"
"}\n"
"\n"
"// A module-level global.\n"
"//\n"
"// Unlike a local there is no alloca and no insert point: the description hangs\n"
"// off the global's own LLVMValueRef as a `!dbg` attachment, and the compile unit\n"
"// collects it when the DIBuilder is finalized. So this runs during the module's\n"
"// global loop, before any function exists and with no scope stack to read.\n"
"//\n"
"// Scope is the compile unit rather than a file. `resolveImports` merges every\n"
"// module into one unit here, and a Prismio global is visible across that whole\n"
"// unit, so LocalToUnit is 0 -- which is also what ir_global_var's linkage says.\n"
"void ir_debug_global(const char *name, const char *type_key, const char *type_name,\n"
"                     int file_id, int line) {\n"
"    if (!g_di) return;\n"
"    if (line <= 0) return;\n"
"\n"
"    // Compiler-internal globals (prismio_argc, string literals) never reach this\n"
"    // -- only the frontend's VARIABLE_DECL loop calls it -- but a name that does\n"
"    // not resolve is still an \"I cannot answer that\" rather than a guess.\n"
"    LLVMValueRef global = LLVMGetNamedGlobal(g_module, name);\n"
"    if (!global) return;\n"
"\n"
"    LLVMMetadataRef file = di_file(file_id);\n"
"    if (!file) return;\n"
"\n"
"    LLVMMetadataRef ty = di_type_for(type_key, type_name);\n"
"    if (!ty) return; // a type this layer has no description for: no entry\n"
"\n"
"    LLVMMetadataRef gve = LLVMDIBuilderCreateGlobalVariableExpression(\n"
"        g_di, g_di_cu, name, strlen(name), name, strlen(name), file,\n"
"        (unsigned)line, ty, 0, g_di_empty_expr, NULL, 0);\n"
"    LLVMGlobalSetMetadata(global, LLVMGetMDKindIDInContext(g_ctx, \"dbg\", 3), gve);\n"
"}\n"
"\n"
"// One enumeration per declared enum, for the same reason ir_debug_struct emits\n"
"// one composite per struct: a type a program only passes around is still a type\n"
"// `p` should be able to name. The site is recorded first, because di_enum_type\n"
"// reads it.\n"
"void ir_debug_enum(const char *name, int file_id, int line) {\n"
"    if (!g_di) return;\n"
"    if (g_di_enum_site_count < 256) {\n"
"        strncpy(g_di_enum_sites[g_di_enum_site_count].name, name, NAME_LEN - 1);\n"
"        g_di_enum_sites[g_di_enum_site_count].name[NAME_LEN - 1] = '\\0';\n"
"        g_di_enum_sites[g_di_enum_site_count].file = file_id;\n"
"        g_di_enum_sites[g_di_enum_site_count].line = line;\n"
"        g_di_enum_site_count++;\n"
"    }\n"
"    di_enum_type(name);\n"
"}\n"
"\n"
"// One composite per struct, emitted after generateStructDecl has registered\n"
"// every type. Nothing references them until a variable does, so this exists to\n"
"// make a type visible to `p` even in a program that only passes it around.\n"
"void ir_debug_struct(const char *name, int file_id, int line) {\n"
"    if (!g_di) return;\n"
"    if (g_di_struct_site_count < 256) {\n"
"        strncpy(g_di_struct_sites[g_di_struct_site_count].name, name, NAME_LEN - 1);\n"
"        g_di_struct_sites[g_di_struct_site_count].name[NAME_LEN - 1] = '\\0';\n"
"        g_di_struct_sites[g_di_struct_site_count].file = file_id;\n"
"        g_di_struct_sites[g_di_struct_site_count].line = line;\n"
"        g_di_struct_site_count++;\n"
"    }\n"
"    di_struct_type(name);\n"
"}\n"
"\n"
"#else // !PRISMIO_DWARF\n"
"\n"
"int ir_debug_enabled(void) { return 0; }\n"
"\n"
"void ir_debug_begin(const char *producer, const char *main_path, int is_optimized) {\n"
"    (void)producer; (void)main_path; (void)is_optimized;\n"
"    fprintf(stderr,\n"
"            \"error: -g is not available in this build of the compiler.\\n\"\n"
"            \"  Debug info needs the LLVM DebugInfo C API, which is only compiled in\\n\"\n"
"            \"  when the backend is built against real llvm-c headers.\\n\"\n"
"            \"  Run: python3 tools/setup_llvm.py\\n\");\n"
"    exit(1);\n"
"}\n"
"\n"
"void ir_debug_end(void) {}\n"
"void ir_debug_signature(const char *k, const char *n) { (void)k; (void)n; }\n"
"void ir_debug_signature_param(const char *k, const char *n) { (void)k; (void)n; }\n"
"static void debug_dispose(void) {}\n"
"static void debug_clear_location(void) {}\n"
"void ir_debug_function_begin(const char *n, const char *l, int f, int line) {\n"
"    (void)n; (void)l; (void)f; (void)line;\n"
"}\n"
"void ir_debug_function_end(void) {}\n"
"void ir_debug_scope_push(int f, int l, int c) { (void)f; (void)l; (void)c; }\n"
"void ir_debug_scope_pop(void) {}\n"
"void ir_debug_location(int f, int l, int c) { (void)f; (void)l; (void)c; }\n"
"void ir_debug_local(const char *n, const char *s, const char *k, const char *t,\n"
"                    int f, int l, int a) {\n"
"    (void)n; (void)s; (void)k; (void)t; (void)f; (void)l; (void)a;\n"
"}\n"
"void ir_debug_global(const char *n, const char *k, const char *t, int f, int l) {\n"
"    (void)n; (void)k; (void)t; (void)f; (void)l;\n"
"}\n"
"void ir_debug_enum(const char *name, int f, int l) { (void)name; (void)f; (void)l; }\n"
"void ir_debug_struct(const char *name, int f, int l) { (void)name; (void)f; (void)l; }\n"
"void ir_debug_field_type(const char *o, const char *f, const char *t) {\n"
"    (void)o; (void)f; (void)t;\n"
"}\n"
"\n"
"#endif // PRISMIO_DWARF\n"
"\n"
"// ============================================================================\n"
"// Output\n"
"// ============================================================================\n"
"\n"
"// Verifies before writing. This is the check the text backend never had: a\n"
"// malformed module is reported here, against the code that built it, instead of\n"
"// surfacing later as an llc parse error pointing at generated text.\n"
"// -O level, 0 by default -- unoptimized, which is what shipped before this\n"
"// existed: no pass pipeline was ever run over the generated module.\n"
"static int g_opt_level = 0;\n"
"\n"
"void ir_set_opt_level(int level) {\n"
"    if (level < 0) level = 0;\n"
"    if (level > 3) level = 3;\n"
"    g_opt_level = level;\n"
"}\n"
"\n"
"// Runs LLVM's standard pipeline over the module before it is written.\n"
"//\n"
"// The frontend emits a load/store through a stack slot for every binding, so\n"
"// even -O1 (which includes mem2reg/SROA) is a large improvement over the raw\n"
"// output. No TargetMachine is passed: these are the target-independent passes,\n"
"// and llc still does target-specific work afterwards.\n"
"static int run_optimization(void) {\n"
"    if (g_opt_level == 0) return 0;\n"
"\n"
"    char pipeline[32];\n"
"    snprintf(pipeline, sizeof(pipeline), \"default<O%d>\", g_opt_level);\n"
"\n"
"    LLVMPassBuilderOptionsRef options = LLVMCreatePassBuilderOptions();\n"
"    LLVMErrorRef err = LLVMRunPasses(g_module, pipeline, NULL, options);\n"
"    LLVMDisposePassBuilderOptions(options);\n"
"\n"
"    if (err) {\n"
"        char *msg = LLVMGetErrorMessage(err);\n"
"        fprintf(stderr, \"error: optimization pipeline failed: %s\\n\", msg ? msg : \"?\");\n"
"        return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"int ir_write_file(const char *filename) {\n"
"    char *err = NULL;\n"
"\n"
"    // Verify first: optimizing an already-invalid module produces far worse\n"
"    // diagnostics than reporting the original problem.\n"
"    if (LLVMVerifyModule(g_module, LLVMReturnStatusAction, &err)) {\n"
"        fprintf(stderr, \"error: generated module failed verification\\n\");\n"
"        if (err) fprintf(stderr, \"%s\\n\", err);\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        return 1;\n"
"    }\n"
"    if (err) { LLVMDisposeMessage(err); err = NULL; }\n"
"\n"
"    if (run_optimization() != 0) return 1;\n"
"    if (LLVMVerifyModule(g_module, LLVMReturnStatusAction, &err)) {\n"
"        fprintf(stderr, \"error: generated module failed verification\\n\");\n"
"        if (err) fprintf(stderr, \"%s\\n\", err);\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        return 1;\n"
"    }\n"
"    if (err) LLVMDisposeMessage(err);\n"
"\n"
"    char *werr = NULL;\n"
"    if (LLVMPrintModuleToFile(g_module, filename, &werr)) {\n"
"        fprintf(stderr, \"error: could not write %s: %s\\n\", filename, werr ? werr : \"?\");\n"
"        if (werr) LLVMDisposeMessage(werr);\n"
"        return 1;\n"
"    }\n"
"    return 0;\n"
"}\n"
"\n"
"void ir_print(void) {\n"
"    char *s = LLVMPrintModuleToString(g_module);\n"
"    if (s) {\n"
"        printf(\"%s\", s);\n"
"        LLVMDisposeMessage(s);\n"
"    }\n"
"}\n"
"\n"
"// ============================================\n"
"// `prismio run --jit`\n"
"//\n"
"// `run` otherwise pays a full clang compile plus a link on every invocation to\n"
"// produce an executable it deletes moments later. The module is already in\n"
"// memory by the time compileSource asks for a build, so this hands it to LLJIT\n"
"// instead and calls `main` in this process.\n"
"//\n"
"// **Off by default and behind its own flag, deliberately.** Nothing here is on\n"
"// the emission path: codegen produces the same module either way, and a build\n"
"// that writes an object is untouched. This adds an execution path, not an\n"
"// emission one, which is why it cannot move any program's IR.\n"
"//\n"
"// Compiled in only on the real-headers path, for the reason given over the\n"
"// DIBuilder block in prismio_llvm.h: the linker checks names and not\n"
"// signatures, and this API is opaque handles passed by pointer.\n"
"// ============================================\n"
"\n"
"#ifdef PRISMIO_LLVM_REAL_HEADERS\n"
"\n"
"// Defined by generated code -- see the note in program_support.c. Referenced,\n"
"// never defined, so this stays a backend-only symbol reference and nothing\n"
"// changes about what a user binary links.\n"
"extern int prismio_argc;\n"
"extern char **prismio_argv;\n"
"\n"
"// Reports an LLVMErrorRef and consumes it. Always returns 1 so callers can\n"
"// `return jit_failed(...)`.\n"
"static int jit_failed(const char *what, LLVMErrorRef err) {\n"
"    char *message = LLVMGetErrorMessage(err);   // consumes err\n"
"    fprintf(stderr, \"ERROR: --jit: %s: %s\\n\", what, message ? message : \"(no detail)\");\n"
"    if (message) LLVMDisposeErrorMessage(message);\n"
"    return 1;\n"
"}\n"
"\n"
"// ============================================\n"
"// M1.1 -- the curated inlinable module, in process\n"
"//\n"
"// build_driver.c owns the decision to merge and the caching; this file owns the\n"
"// LLVM. That split is the same one everywhere else here: the driver drives\n"
"// clang, the backend touches the C API.\n"
"//\n"
"// **Why this is not a shell-out to llvm-extract and llvm-link.** Both ship with\n"
"// LLVM and both were used to develop this, but prismio_llvm.h exists because the\n"
"// official Windows installer ships LLVM-C.lib and the DLL and very little else,\n"
"// and CI runs three platforms. A feature that silently does nothing on one of\n"
"// them is worse than a feature that is off. The C API is already a hard\n"
"// dependency of this binary, so doing it here adds nothing to install.\n"
"//\n"
"// The output is byte-identical to `llvm-extract --func=... | sed 's/^define/&\n"
"// available_externally/'` on this runtime, which is how the port was checked.\n"
"\n"
"// Empty a function without disturbing anything that referred to it.\n"
"//\n"
"// The C API has no Function::deleteBody, and the obvious loop -- erase basic\n"
"// blocks front to back -- breaks on any loop in the CFG: a back edge is a\n"
"// terminator in a later block naming an earlier one, so the earlier block still\n"
"// has a use when it is erased. Doing it in three passes avoids needing to know\n"
"// the CFG at all: drop the values first, then the instructions (which is what\n"
"// removes the block-to-block references, since a terminator *is* an\n"
"// instruction), and only then the now-unreferenced blocks.\n"
"static void ir_delete_function_body(LLVMValueRef fn) {\n"
"    for (LLVMBasicBlockRef bb = LLVMGetFirstBasicBlock(fn); bb;\n"
"         bb = LLVMGetNextBasicBlock(bb)) {\n"
"        for (LLVMValueRef inst = LLVMGetFirstInstruction(bb); inst;\n"
"             inst = LLVMGetNextInstruction(inst)) {\n"
"            LLVMTypeRef ty = LLVMTypeOf(inst);\n"
"            if (LLVMGetTypeKind(ty) != LLVMVoidTypeKind) {\n"
"                LLVMReplaceAllUsesWith(inst, LLVMGetUndef(ty));\n"
"            }\n"
"        }\n"
"    }\n"
"    for (LLVMBasicBlockRef bb = LLVMGetFirstBasicBlock(fn); bb;\n"
"         bb = LLVMGetNextBasicBlock(bb)) {\n"
"        LLVMValueRef inst = LLVMGetFirstInstruction(bb);\n"
"        while (inst) {\n"
"            LLVMValueRef next = LLVMGetNextInstruction(inst);\n"
"            LLVMInstructionEraseFromParent(inst);\n"
"            inst = next;\n"
"        }\n"
"    }\n"
"    while (LLVMGetFirstBasicBlock(fn)) {\n"
"        LLVMDeleteBasicBlock(LLVMGetFirstBasicBlock(fn));\n"
"    }\n"
"}\n"
"\n"
"// Read `runtime_ir`, keep the named functions as `available_externally` bodies,\n"
"// reduce everything else to a declaration, drop what nothing refers to, and\n"
"// write the result to `out_path`. Returns 0 on success.\n"
"//\n"
"// `available_externally` is the whole point: the body is there for the inliner\n"
"// and emits no code, so a call the inliner declines still resolves to the\n"
"// runtime archive and nothing is defined twice.\n"
"int ir_curate_module(const char *runtime_ir, const char *const *names, int count,\n"
"                     const char *out_path) {\n"
"    LLVMContextRef ctx = LLVMContextCreate();\n"
"    LLVMMemoryBufferRef buf = NULL;\n"
"    char *err = NULL;\n"
"\n"
"    if (LLVMCreateMemoryBufferWithContentsOfFile(runtime_ir, &buf, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        LLVMContextDispose(ctx);\n"
"        return 1;\n"
"    }\n"
"\n"
"    LLVMModuleRef m = NULL;\n"
"    // Takes the buffer either way, so it must not be disposed here -- the same\n"
"    // ownership rule the JIT path documents.\n"
"    if (LLVMParseIRInContext(ctx, buf, &m, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        LLVMContextDispose(ctx);\n"
"        return 1;\n"
"    }\n"
"\n"
"    for (LLVMValueRef fn = LLVMGetFirstFunction(m); fn; fn = LLVMGetNextFunction(fn)) {\n"
"        if (!LLVMGetFirstBasicBlock(fn)) continue;  // already a declaration\n"
"        size_t len = 0;\n"
"        const char *name = LLVMGetValueName2(fn, &len);\n"
"        int curated = 0;\n"
"        for (int i = 0; i < count; i++) {\n"
"            if (strcmp(name, names[i]) == 0) { curated = 1; break; }\n"
"        }\n"
"        if (curated) {\n"
"            LLVMSetLinkage(fn, LLVMAvailableExternallyLinkage);\n"
"        } else {\n"
"            ir_delete_function_body(fn);\n"
"            LLVMSetLinkage(fn, LLVMExternalLinkage);\n"
"        }\n"
"    }\n"
"\n"
"    // A `static` in C is `internal` here, and an internal *declaration* is not\n"
"    // valid IR. These become external declarations, which is sound only because\n"
"    // nothing curated references them -- run_curated_closure_test is what\n"
"    // asserts that, and the dead-declaration sweep below removes them anyway\n"
"    // whenever it holds.\n"
"    for (LLVMValueRef g = LLVMGetFirstGlobal(m); g; g = LLVMGetNextGlobal(g)) {\n"
"        if (LLVMGetInitializer(g)) {\n"
"            LLVMSetInitializer(g, NULL);\n"
"            LLVMSetLinkage(g, LLVMExternalLinkage);\n"
"        }\n"
"    }\n"
"\n"
"    // What llvm-extract gets from GlobalDCE. Without it the module carries every\n"
"    // declaration in the runtime -- valid, but roughly four times the bytes for\n"
"    // the merge to parse on every build. A fixpoint because deleting one\n"
"    // declaration can be what makes the next one unreferenced.\n"
"    int removed = 1;\n"
"    while (removed) {\n"
"        removed = 0;\n"
"        for (LLVMValueRef fn = LLVMGetFirstFunction(m); fn; ) {\n"
"            LLVMValueRef next = LLVMGetNextFunction(fn);\n"
"            if (!LLVMGetFirstBasicBlock(fn) && !LLVMGetFirstUse(fn)) {\n"
"                size_t len = 0;\n"
"                const char *name = LLVMGetValueName2(fn, &len);\n"
"                int curated = 0;\n"
"                for (int i = 0; i < count; i++) {\n"
"                    if (strcmp(name, names[i]) == 0) { curated = 1; break; }\n"
"                }\n"
"                if (!curated) { LLVMDeleteFunction(fn); removed = 1; }\n"
"            }\n"
"            fn = next;\n"
"        }\n"
"        for (LLVMValueRef g = LLVMGetFirstGlobal(m); g; ) {\n"
"            LLVMValueRef next = LLVMGetNextGlobal(g);\n"
"            if (!LLVMGetInitializer(g) && !LLVMGetFirstUse(g)) {\n"
"                LLVMDeleteGlobal(g);\n"
"                removed = 1;\n"
"            }\n"
"            g = next;\n"
"        }\n"
"    }\n"
"\n"
"    int failed = 0;\n"
"    if (LLVMVerifyModule(m, LLVMReturnStatusAction, &err) != 0) {\n"
"        fprintf(stderr, \"ERROR: curated module failed verification: %s\\n\",\n"
"                err ? err : \"(no detail)\");\n"
"        failed = 1;\n"
"    }\n"
"    if (err) { LLVMDisposeMessage(err); err = NULL; }\n"
"\n"
"    if (!failed && LLVMPrintModuleToFile(m, out_path, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        failed = 1;\n"
"    }\n"
"\n"
"    LLVMDisposeModule(m);\n"
"    LLVMContextDispose(ctx);\n"
"    return failed;\n"
"}\n"
"\n"
"// Link `src_ir` into `dest_ir` and write the result. Returns 0 on success.\n"
"//\n"
"// LLVMLinkModules2 consumes the source module, so it must not be disposed here\n"
"// on success -- the same ownership shape as LLVMParseIRInContext above.\n"
"int ir_link_modules(const char *dest_ir, const char *src_ir, const char *out_path) {\n"
"    LLVMContextRef ctx = LLVMContextCreate();\n"
"    LLVMMemoryBufferRef dbuf = NULL, sbuf = NULL;\n"
"    LLVMModuleRef dm = NULL, sm = NULL;\n"
"    char *err = NULL;\n"
"\n"
"    if (LLVMCreateMemoryBufferWithContentsOfFile(dest_ir, &dbuf, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        LLVMContextDispose(ctx);\n"
"        return 1;\n"
"    }\n"
"    if (LLVMParseIRInContext(ctx, dbuf, &dm, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        LLVMContextDispose(ctx);\n"
"        return 1;\n"
"    }\n"
"    if (LLVMCreateMemoryBufferWithContentsOfFile(src_ir, &sbuf, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        LLVMDisposeModule(dm);\n"
"        LLVMContextDispose(ctx);\n"
"        return 1;\n"
"    }\n"
"    if (LLVMParseIRInContext(ctx, sbuf, &sm, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        LLVMDisposeModule(dm);\n"
"        LLVMContextDispose(ctx);\n"
"        return 1;\n"
"    }\n"
"\n"
"    int failed = 0;\n"
"    if (LLVMLinkModules2(dm, sm) != 0) {\n"
"        fprintf(stderr, \"ERROR: could not merge the curated runtime module\\n\");\n"
"        failed = 1;  // sm is consumed even on failure\n"
"    }\n"
"\n"
"    if (!failed && LLVMPrintModuleToFile(dm, out_path, &err) != 0) {\n"
"        if (err) LLVMDisposeMessage(err);\n"
"        failed = 1;\n"
"    }\n"
"\n"
"    LLVMDisposeModule(dm);\n"
"    LLVMContextDispose(ctx);\n"
"    return failed;\n"
"}\n"
"\n"
"int ir_jit_run_main(const char *program_name) {\n"
"    if (!g_module) {\n"
"        fprintf(stderr, \"ERROR: --jit: no module was generated\\n\");\n"
"        return 1;\n"
"    }\n"
"\n"
"    // The JIT emits code for this process, so the *native* target and its\n"
"    // assembly printer are what it needs. ensure_all_targets() registers target\n"
"    // infos and MCs for cross-compilation and deliberately no printers, so\n"
"    // calling it is not enough here.\n"
"    LLVMInitializeNativeTarget();\n"
"    LLVMInitializeNativeAsmPrinter();\n"
"\n"
"    LLVMOrcLLJITRef jit = NULL;\n"
"    LLVMErrorRef err = LLVMOrcCreateLLJIT(&jit, NULL);\n"
"    if (err) return jit_failed(\"could not create an LLJIT\", err);\n"
"\n"
"    // **The module cannot be handed over directly.** LLJIT requires a module\n"
"    // owned by the LLVMContext inside the ThreadSafeContext it is given, and\n"
"    // this one was built in the backend's own context long before any of this\n"
"    // existed. Round-tripping through an in-memory bitcode buffer is how the two\n"
"    // are reconciled without codegen having to know the JIT exists -- which is\n"
"    // the property that keeps `--jit` off the emission path. It costs one\n"
"    // serialise and one parse of a module already in memory, against the clang\n"
"    // compile and link this replaces.\n"
"    LLVMMemoryBufferRef bitcode = LLVMWriteBitcodeToMemoryBuffer(g_module);\n"
"    if (!bitcode) {\n"
"        fprintf(stderr, \"ERROR: --jit: could not serialise the module\\n\");\n"
"        LLVMOrcDisposeLLJIT(jit);\n"
"        return 1;\n"
"    }\n"
"\n"
"    // Into a context of its own, which the ThreadSafeContext then adopts.\n"
"    // `LLVMOrcCreateNewThreadSafeContextFromLLVMContext` *takes ownership* of\n"
"    // what it is given, so handing it the backend's `g_ctx` would leave the\n"
"    // module teardown at shutdown disposing a context the JIT already owns.\n"
"    // There is no way back from a ThreadSafeContext to its LLVMContext in LLVM\n"
"    // 22 -- `LLVMOrcThreadSafeContextGetContext` is gone -- so this is also the\n"
"    // only order that works: make the context, parse into it, then wrap it.\n"
"    LLVMContextRef jit_ctx = LLVMContextCreate();\n"
"    LLVMModuleRef jitted = NULL;\n"
"    char *parse_error = NULL;\n"
"    // Takes the buffer either way, so it must not be disposed here.\n"
"    if (LLVMParseIRInContext(jit_ctx, bitcode, &jitted, &parse_error) != 0) {\n"
"        fprintf(stderr, \"ERROR: --jit: could not re-read the module: %s\\n\",\n"
"                parse_error ? parse_error : \"(no detail)\");\n"
"        if (parse_error) LLVMDisposeMessage(parse_error);\n"
"        LLVMContextDispose(jit_ctx);\n"
"        LLVMOrcDisposeLLJIT(jit);\n"
"        return 1;\n"
"    }\n"
"\n"
"    LLVMOrcThreadSafeContextRef tsc =\n"
"        LLVMOrcCreateNewThreadSafeContextFromLLVMContext(jit_ctx);\n"
"    LLVMOrcThreadSafeModuleRef tsm = LLVMOrcCreateNewThreadSafeModule(jitted, tsc);\n"
"    LLVMOrcDisposeThreadSafeContext(tsc);\n"
"\n"
"    // Every `extern` the module names -- the string helpers, the allocator, the\n"
"    // list shims -- is already in this process, because the compiler links the\n"
"    // runtime it also hands to user programs. The generator resolves against\n"
"    // the process rather than a table of names and addresses maintained here: a\n"
"    // second copy of the runtime's surface would drift from the first, and the\n"
"    // failure of a drifted entry is an unresolved symbol at lookup time, which\n"
"    // is exactly what the generator reports anyway.\n"
"    LLVMOrcJITDylibRef jd = LLVMOrcLLJITGetMainJITDylib(jit);\n"
"    LLVMOrcDefinitionGeneratorRef generator = NULL;\n"
"    err = LLVMOrcCreateDynamicLibrarySearchGeneratorForProcess(\n"
"        &generator, LLVMOrcLLJITGetGlobalPrefix(jit), NULL, NULL);\n"
"    if (err) {\n"
"        LLVMOrcDisposeThreadSafeModule(tsm);\n"
"        LLVMOrcDisposeLLJIT(jit);\n"
"        return jit_failed(\"could not resolve this process's symbols\", err);\n"
"    }\n"
"    LLVMOrcJITDylibAddGenerator(jd, generator);\n"
"\n"
"    err = LLVMOrcLLJITAddLLVMIRModule(jit, jd, tsm);\n"
"    if (err) {\n"
"        // The module is consumed even on failure; disposing it here would be a\n"
"        // double free.\n"
"        LLVMOrcDisposeLLJIT(jit);\n"
"        return jit_failed(\"could not add the module to the JIT\", err);\n"
"    }\n"
"\n"
"    LLVMOrcExecutorAddress entry_address = 0;\n"
"    err = LLVMOrcLLJITLookup(jit, &entry_address, \"main\");\n"
"    if (err) {\n"
"        LLVMOrcDisposeLLJIT(jit);\n"
"        return jit_failed(\"could not find `main` in the jitted module\", err);\n"
"    }\n"
"\n"
"    // **The two prismio_argc are not the same variable, and this is the bug this\n"
"    // line exists to prevent.** Generated code *defines* `@prismio_argc`, so the\n"
"    // jitted module gets its own copy and its `main` fills that one. The runtime\n"
"    // shims behind `cli_arg_count()` are the compiler's own, already linked into\n"
"    // this process, and they read the *compiler's* copy -- which holds the\n"
"    // compiler's argv. Without this a jitted program asking for its arguments is\n"
"    // told about `prismio run --jit prog.psm`, quietly and with a straight face.\n"
"    //\n"
"    // One argument, the program's own name: `compiler_run_executable` runs the\n"
"    // built binary with no arguments, and `--jit` is a way of running the same\n"
"    // program, not a different calling convention.\n"
"    char *jit_argv[2];\n"
"    jit_argv[0] = (char *)(program_name ? program_name : \"prismio\");\n"
"    jit_argv[1] = NULL;\n"
"\n"
"    int saved_argc = prismio_argc;\n"
"    char **saved_argv = prismio_argv;\n"
"    prismio_argc = 1;\n"
"    prismio_argv = jit_argv;\n"
"\n"
"    int (*entry)(int, char **) = (int (*)(int, char **))(uintptr_t)entry_address;\n"
"    int status = entry(1, jit_argv);\n"
"\n"
"    // Restored rather than left pointing at a stack array that is about to go\n"
"    // away: the compiler keeps running after this returns.\n"
"    prismio_argc = saved_argc;\n"
"    prismio_argv = saved_argv;\n"
"\n"
"    LLVMOrcDisposeLLJIT(jit);\n"
"    return status;\n"
"}\n"
"\n"
"#else\n"
"\n"
"int ir_jit_run_main(const char *program_name) {\n"
"    (void)program_name;\n"
"    fprintf(stderr,\n"
"            \"ERROR: --jit needs an LLVM with the C headers installed.\\n\"\n"
"            \"       This build was compiled against the fallback declarations in\\n\"\n"
"            \"       runtime/prismio_llvm.h, which deliberately do not cover Orc or\\n\"\n"
"            \"       LLJIT. Build without --jit, or install LLVM's llvm-c headers\\n\"\n"
"            \"       (tools/setup_llvm.py checks for them).\\n\");\n"
"    return 1;\n"
"}\n"
"\n"
"#endif\n"
;

#endif
